/* Past-year questions for Rank mode · JEE Mains · Rotational Motion, grouped by topic and sub-topic.
   Sources: JEE Main, JEE Advanced, IIT-JEE and AIEEE papers. Wording as in the paper; solutions written for this site.
   MCQ: o + c (index or array of indices). Numerical: n. Multi-part: a. s = worked solution. y = exam and year. fig = diagram (PhysicaFig spec). */
window.PhysicaRankPyqRot=[
{"y":"JEE Main 2025 · 7 Apr · Shift 1","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"A rod of length 5L is bent right angle keeping one side length as 2L. The position of the centre of mass of the system (Consider L = 10 cm)","fig":{"w":340,"h":190,"alt":"A bent rod with a vertical arm of length 3L on the y-axis and a horizontal arm of length 2L along the x-axis, meeting at the origin.","d":[["l",90,160,90,15,"a"],["l",90,160,300,160,"a"],["t",96,18,"y"],["t",304,164,"x"],["l",90,160,90,70,"B"],["l",90,160,150,160,"B"],["t",82,118,"3L","e"],["t",120,178,"2L","m"],["t",82,174,"O","e"]]},"o":["4î+9ĵ","5î+8ĵ","3î+7ĵ","2î+3ĵ"],"c":0,"s":"The rod has two straight parts: a vertical part of length 3L = 30 cm and a horizontal part of length 2L = 20 cm, meeting at the origin.\nMass is proportional to length. Horizontal part: mass 2 units, centre at (10, 0). Vertical part: mass 3 units, centre at (0, 15).\nx = (2 × 10 + 3 × 0)/5 = 4 cm.\ny = (2 × 0 + 3 × 15)/5 = 9 cm.\nCentre of mass = 4î + 9ĵ, option (a)."},
{"y":"JEE Main 2025 · 23 Jan · Shift 1","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"Consider a circular disc of radius 20 cm with centre located at the origin. A circular hole of radius 5 cm is cut from this disc in such a way that the edge of the hole touches the edge of the disc. The distance of centre of mass of residual or remaining disc from the origin will be","o":["0.5 cm","2.0 cm","1.5 cm","1.0 cm"],"c":3,"s":"The hole touches the edge, so its centre is 20 − 5 = 15 cm from the origin.\nTreat the hole as negative mass. Mass is proportional to area, so the hole has 5² = 25 units and the full disc has 20² = 400 units.\nx = −(25 × 15)/(400 − 25) = −375/375 = −1 cm.\nThe centre of mass is 1.0 cm from the origin, on the side away from the hole. Option (d)."},
{"y":"JEE Main 2025 · 28 Jan · Shift 1","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"The center of mass of a thin rectangular plate (Fig - x) with sides of length a and b, whose mass per unit area (σ) varies as σ = {σ₀x;ab} (where σ₀ is a constant), would be ______.","fig":{"w":340,"h":190,"alt":"A rectangular plate of width a along the x-axis and height b along the y-axis with its corner at the origin O.","d":[["l",70,160,70,15,"a"],["l",70,160,290,160,"a"],["t",76,18,"y"],["t",294,164,"x"],["r",70,40,180,120],["t",62,176,"O","e"],["t",160,178,"a","m"],["t",258,104,"b"]]},"o":["({2;3}a, {b;2})","({1;3}a, {b;2})","({a;2}, {b;2})","({2;3}a, {2;3}b)"],"c":0,"s":"The density depends only on x, so y_cm = b/2 by symmetry.\nTake a strip of width dx: its mass is proportional to x dx (because σ ∝ x, and the strip height b is constant).\nx_cm = ∫x·x dx / ∫x dx = (a³/3)/(a²/2) = 2a/3.\nCentre of mass = (2a/3, b/2), option (a)."},
{"y":"JEE Advanced 2025","tp":"prc","st":"Motion of the centre of mass and collisions","q":"In a scattering experiment, a particle of mass 2m collides with another particle of mass m, which is initially at rest. Assuming the collision to be perfectly elastic, the maximum angular deviation θ of the heavier particle, as shown in the figure, in radians is:","fig":{"w":340,"h":190,"alt":"A particle of mass 2m moves right and strikes a stationary mass m. After the collision the 2m particle goes up-right at angle theta to the original direction (dashed) and m goes down-right.","d":[["l",30,100,150,100,"a"],["t",20,92,"2m","m"],["c",150,100,5,"F"],["t",150,120,"m","m"],["l",150,100,310,100,"d"],["l",150,100,260,38,"a"],["t",266,36,"2m"],["l",150,100,240,165,"a"],["t",244,176,"m"],["p","M200 100 A50 50 0 0 0 194 74"],["t",206,90,"θ","s"]]},"o":["π","tan⁻¹({1;2})","{π;3}","{π;6}"],"c":3,"s":"In an elastic collision the heavier particle (mass M = 2m) hits a lighter one (mass m) at rest.\nThe maximum deviation of the heavier particle satisfies sin θ_max = (mass of target)/(mass of projectile) = m/2m = 1/2.\nSo θ_max = π/6.\nOption (d)."},
{"y":"JEE Main 2022 · 29 Jul · Shift 1","tp":"prc","st":"Centre of mass of systems","q":"Two bodies of mass 1 kg and 3 kg have position vectors î + 2ĵ + k̂ and −3î − 2ĵ + k̂ respectively. The magnitude of position vector of centre of mass of this system will be similar to the magnitude of vector","o":["î+2ĵ+k̂","−3î−2ĵ+k̂","−2î+2k̂","−2î−ĵ+2k̂"],"c":0,"s":"r_cm = (1·(î + 2ĵ + k̂) + 3·(−3î − 2ĵ + k̂))/4 = (−8î − 4ĵ + 4k̂)/4 = −2î − ĵ + k̂.\nMagnitude of r_cm = √(4 + 1 + 1) = √6.\nMagnitudes of the options: (a) √(1+4+1) = √6, (b) √14, (c) √8, (d) 3.\nOnly option (a) has magnitude √6."},
{"y":"JEE Main 2022 · 27 Jun · Shift 1","tp":"prc","st":"Centre of mass of systems","q":"Two blocks of masses 10 kg and 30 kg are placed on the same straight line with coordinates (0, 0) cm and (x, 0) cm respectively. The block of 10 kg is moved on the same line through a distance of 6 cm towards the other block. The distance through which the block of 30 kg must be moved to keep the position of centre of mass of the system unchanged is","o":["4 cm towards the 10 kg block","2 cm away from the 10 kg block","2 cm towards the 10 kg block","4 cm away from the 10 kg block"],"c":2,"s":"For the centre of mass to stay fixed, the total mass-weighted displacement must be zero: m₁Δx₁ + m₂Δx₂ = 0.\nTake the direction from the 10 kg block towards the 30 kg block as positive. Then Δx₁ = +6 cm.\n10 × 6 + 30 × Δx₂ = 0, so Δx₂ = −2 cm.\nNegative means the 30 kg block moves 2 cm in the direction towards the 10 kg block.\nOption (c)."},
{"y":"JEE Main 2021 · 24 Feb · Shift 2","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"A circular hole of radius ({a;2}) is cut out of a circular disc of radius 'a' as shown in figure. The centroid of the remaining circular portion with respect to point 'O' will be","fig":{"w":340,"h":200,"alt":"A disc of radius a with its left edge at the origin O on the x-axis, and a hole of radius a/2 touching the right edge of the disc.","d":[["l",80,100,80,12,"a"],["t",86,14,"Y-axis"],["l",80,100,310,100,"a"],["t",250,118,"X-axis"],["c",150,100,70],["c",185,100,35,"f"],["t",72,114,"O","e"],["l",82,92,148,92,"b"],["t",115,86,"a","m"],["t",185,62,"a/2","ms"]]},"o":["{1;6}a","{10;11}a","{2;3}a","{5;6}a"],"c":3,"s":"The disc has radius a and its centre is a from O. The hole (radius a/2) touches the right edge, so its centre is a + a/2 = 3a/2 from O.\nMass is proportional to area: disc πa² (call it 4 units), hole π(a/2)² (1 unit).\nx = (4·a − 1·(3a/2))/(4 − 1) = (4a − 1.5a)/3 = 2.5a/3 = 5a/6.\nOption (d)."},
{"y":"JEE Main 2020 · 7 Jan · Shift 1","tp":"prc","st":"Centre of mass of systems","q":"Three point particles of masses 1.0 kg, 1.5 kg and 2.5 kg are placed at three corners of a right angle triangle of sides 4.0 cm, 3.0 cm and 5.0 cm as shown in the figure. The center of mass of the system is at a point","fig":{"w":340,"h":200,"alt":"A right triangle with 1.0 kg at the right-angle corner, 1.5 kg at the end of the 3 cm base and 2.5 kg at the top of the 4 cm vertical side.","d":[["p","M70 150 L160 150 L70 30 Z"],["c",70,150,4,"F"],["c",160,150,4,"F"],["c",70,30,4,"F"],["t",70,172,"1.0 kg","m"],["t",160,172,"1.5 kg","m"],["t",78,28,"2.5 kg"],["t",62,95,"4 cm","e"],["t",115,172,"3 cm","m"],["t",126,84,"5 cm"]]},"o":["2.0 cm right and 0.9 cm above 1 kg mass","0.9 cm right and 2.0 cm above 1 kg mass","0.6 cm right and 2.0 cm above 1 kg mass","1.5 cm right and 1.2 cm above 1 kg mass"],"c":1,"s":"Put the 1.0 kg mass at the origin, with the 1.5 kg mass 3 cm along the base and the 2.5 kg mass 4 cm up the vertical side.\nTotal mass = 1.0 + 1.5 + 2.5 = 5 kg.\nx = (1.5 × 3)/5 = 0.9 cm to the right of the 1 kg mass.\ny = (2.5 × 4)/5 = 2.0 cm above the 1 kg mass.\nOption (b)."},
{"y":"JEE Main 2020 · 7 Jan · Shift 2","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"A rod of length L has non-uniform linear mass density given by ρ(x) = a + b({x;L})², where a and b are constants and 0 ≤ x ≤ L. The value of x for the centre of mass of the rod is at","o":["{3;2}({2a+b;3a+b})L","{3;2}({a+b;2a+b})L","{3;4}({2a+b;3a+b})L","{4;3}({a+b;2a+3b})L"],"c":2,"s":"x_cm = ∫xρ dx / ∫ρ dx.\nNumerator = ∫₀ᴸ (ax + b x³/L²) dx = aL²/2 + bL²/4 = L²(2a + b)/4.\nDenominator = ∫₀ᴸ (a + b x²/L²) dx = aL + bL/3 = L(3a + b)/3.\nx_cm = [L²(2a + b)/4] × [3/(L(3a + b))] = {3;4}({2a+b;3a+b})L.\nOption (c)."},
{"y":"JEE Main 2020 · 8 Jan · Shift 1","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"The coordinates of centre of mass of a uniform flag shaped lamina (thin flat plate) of mass 4 kg (the coordinates of the same are shown in figure) are","fig":{"w":340,"h":210,"alt":"A flag shaped plate with corners at (0,0), (1,0), (1,2), (2,2), (2,3) and (0,3).","d":[["p","M70 185 H125 V75 H180 V20 H70 Z","f"],["t",70,200,"(0,0)","e"],["t",125,200,"(1,0)","m"],["t",64,18,"(0,3)","e"],["t",186,18,"(2,3)"],["t",186,80,"(2,2)"],["t",131,92,"(1,2)"]]},"o":["(1.25 m, 1.50 m)","(0.75 m, 0.75 m)","(0.75 m, 1.75 m)","(1 m, 1.75 m)"],"c":2,"s":"Split the flag into two rectangles of equal area: the stem x from 0 to 1, y from 0 to 2 (area 2, centre (0.5, 1)), and the top bar x from 0 to 2, y from 2 to 3 (area 2, centre (1, 2.5)).\nx = (2 × 0.5 + 2 × 1)/4 = 0.75 m.\ny = (2 × 1 + 2 × 2.5)/4 = 1.75 m.\nThe mass does not matter for a uniform plate.\nOption (c)."},
{"y":"JEE Main 2020 · 8 Jan · Shift 2","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"As shown in figure when a spherical cavity (centred at O) of radius 1 is cut out of a uniform sphere of radius R (centred at C), the centre of mass of remaining (shaded) part of sphere is at G, i.e., on the surface of the cavity. R can be determined by the equation","fig":{"w":340,"h":200,"alt":"A large sphere of radius R with centre C and a smaller cavity of radius 1 centred at O touching the right surface; G on the cavity surface is near C.","d":[["c",190,100,80],["c",227,100,43,"f"],["c",183,100,2.5,"F"],["c",190,100,2.5,"F"],["c",227,100,2.5,"F"],["t",172,116,"G","m"],["t",192,132,"C","m"],["t",228,116,"O","m"],["l",190,100,134,43],["t",150,66,"R","m"],["l",227,100,270,100],["t",250,94,"1","m"]]},"o":["(R²+R+1)(2−R) = 1","(R²+R−1)(2−R) = 1","(R²−R−1)(2−R) = 1","(R²−R+1)(2−R) = 1"],"c":0,"s":"Take C as the origin. The cavity touches the surface of the sphere, so O is at distance R − 1 from C, and G (the left end of the cavity) is at R − 2 from C.\nMass is proportional to volume: sphere R³, cavity 1. The cavity acts as negative mass.\nx_cm = −(1 × (R − 1))/(R³ − 1) = −1/(R² + R + 1), using R³ − 1 = (R − 1)(R² + R + 1).\nSetting x_cm = R − 2: (R − 2)(R² + R + 1) = −1, that is (R² + R + 1)(2 − R) = 1.\nOption (a)."},
{"y":"JEE Main 2019 · 8 Apr · Shift 1","tp":"prc","st":"Centre of mass of systems","q":"Four particles A, B, C and D with masses m_A = m, m_B = 2m, m_C = 3m and m_D = 4m are at the corners of a square. They have accelerations of equal magnitude with directions as shown. The acceleration of the centre of mass of the particles is","fig":{"w":340,"h":200,"alt":"A square ABCD with A bottom left, B top left, C top right, D bottom right. Acceleration a points left at A, up at B, right at C and down at D.","d":[["r",110,70,80,80],["l",110,150,72,150,"a"],["t",64,168,"a"],["l",110,70,110,32,"a"],["t",116,30,"a"],["l",190,70,228,70,"a"],["t",232,66,"a"],["l",190,150,190,188,"a"],["t",198,186,"a"],["t",112,164,"A"],["t",96,66,"B","e"],["t",196,64,"C"],["t",196,166,"D"],["l",150,110,150,40,"a"],["t",154,36,"Y"],["l",150,110,250,110,"a"],["t",254,114,"X"]]},"o":["{a;5}(î + ĵ)","a(î + ĵ)","zero","{a;5}(î − ĵ)"],"c":3,"s":"From the figure: A accelerates in −x, B in +y, C in +x and D in −y, each with magnitude a.\na_cm = Σ m·a / Σ m = [m(−aî) + 2m(aĵ) + 3m(aî) + 4m(−aĵ)]/(10m).\nx part: (−1 + 3)a/10 = 2a/10. y part: (2 − 4)a/10 = −2a/10.\na_cm = {a;5}(î − ĵ).\nOption (d)."},
{"y":"JEE Main 2019 · 8 Apr · Shift 2","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"A uniform rectangular thin sheet ABCD of mass M has length a and breadth b, as shown in the figure. If the shaded portion HBGO is cut-off, the coordinates of the centre of mass of the remaining portion will be","fig":{"w":340,"h":200,"alt":"A rectangle ABCD with A top left, B top right, C bottom right, D bottom left. The top right quarter HBGO is shaded, where H and G are midpoints of the top and right sides and O is the centre.","d":[["r",60,40,200,130],["r",160,40,100,65,"f"],["l",60,105,260,105,"d"],["l",160,40,160,170,"d"],["t",56,34,"A (0,b)","e"],["t",264,34,"B (a,b)"],["t",264,182,"C (a,0)"],["t",56,182,"D (0,0)","e"],["t",160,34,"H","m"],["t",54,109,"E","e"],["t",266,109,"G"],["t",160,184,"F","m"],["t",154,122,"O","e"]]},"o":["({5a;3}, {5b;3})","({2a;3}, {2b;3})","({3a;4}, {3b;4})","({5a;12}, {5b;12})"],"c":3,"s":"The rectangle has corners D(0, 0), C(a, 0), B(a, b), A(0, b). O is its centre (a/2, b/2); H and G are the midpoints of AB and BC.\nThe cut piece HBGO is a quarter of the sheet: mass M/4, centre (3a/4, 3b/4). The full sheet has mass M and centre (a/2, b/2).\nx = (M·a/2 − (M/4)(3a/4))/(3M/4) = (5a/16)/(3/4) = 5a/12.\nBy the same working y = 5b/12.\nOption (d)."},
{"y":"JEE Main 2019 · 12 Apr · Shift 1","tp":"pra","st":"Conservation of angular momentum","q":"A person of mass M is sitting on a swing of length L and swinging with an angular amplitude θ₀. If the person stands up when the swing passes through its lowest point, the work done by him, assuming that his centre of mass moves by a distance l (l << L), is close to","o":["Mgl(1 − θ₀²)","Mgl","Mgl(1 + θ₀²)","Mgl(1 + {θ₀²;2})"],"c":2,"s":"At the lowest point the speed is v, with v² = 2gL(1 − cos θ₀) ≈ gLθ₀² (small angle).\nStanding up is done by internal forces, so angular momentum about the pivot is conserved: Mv L = Mv′(L − l), so v′ = vL/(L − l) ≈ v(1 + l/L).\nWork done = gain in kinetic energy + gain in potential energy = ½M(v′² − v²) + Mgl.\n½M(v′² − v²) ≈ ½Mv²(2l/L) = Mv²l/L = Mgθ₀²l.\nW = Mgl + Mglθ₀² = Mgl(1 + θ₀²). Option (c)."},
{"y":"JEE Main 2019 · 12 Apr · Shift 2","tp":"prc","st":"Centre of mass of systems","q":"Three particles of masses 50 g, 100 g and 150 g are placed at the vertices of an equilateral triangle of side 1 m (as shown in the figure). The (x, y) coordinates of the centre of mass will be","fig":{"w":340,"h":206,"alt":"An equilateral triangle on the x-axis with m1 = 50 g at the origin, m2 = 100 g at x = 1.0 m and m3 = 150 g at the apex above x = 0.5 m.","d":[["l",90,180,90,15,"a"],["l",90,180,300,180,"a"],["t",94,14,"Y"],["t",304,184,"X"],["p","M90 180 L250 180 L170 42 Z"],["l",170,42,170,180,"d"],["l",90,42,170,42,"d"],["c",90,180,3,"F"],["c",250,180,3,"F"],["c",170,42,3,"F"],["t",84,172,"50 g = m₁","e"],["t",254,172,"m₂ = 100 g"],["t",176,38,"m₃ = 150 g"],["t",110,172,"60°","s"],["t",170,198,"0.5 m","m"],["t",250,198,"1.0 m","m"],["t",84,196,"O","e"]]},"o":["({7;12}m, {√3;8}m)","({7;12}m, {√3;4}m)","({√3;8}m, {7;12}m)","({√3;4}m, {5;12}m)"],"c":1,"s":"Coordinates: m₁ = 50 g at (0, 0), m₂ = 100 g at (1, 0), m₃ = 150 g at (0.5, √3/2) (height of the equilateral triangle).\nTotal mass = 300 g.\nx = (50·0 + 100·1 + 150·0.5)/300 = 175/300 = 7/12 m.\ny = (150 × √3/2)/300 = √3/4 m.\nOption (b)."},
{"y":"JEE Main 2019 · 12 Jan · Shift 1","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"The position vector of the centre of mass r⃗ cm of an asymmetric uniform bar of negligible area of cross-section as shown in figure is","fig":{"w":340,"h":200,"alt":"Axes with an L-shaped step bar: a horizontal bar at height L from x=0 to 2L, a vertical bar down from it at x=2L, and a horizontal bar on the x-axis from 2L to 3L.","d":[["l",50,170,50,15,"a"],["l",50,170,290,170,"a"],["t",56,18,"y"],["t",294,174,"x"],["l",50,110,170,110,"B"],["l",170,110,170,170,"B"],["l",170,170,230,170,"B"],["t",44,114,"L","e"],["l",110,170,110,175],["l",170,170,170,175],["l",230,170,230,175],["t",110,190,"L","m"],["t",170,190,"2L","m"],["t",230,190,"3L","m"]]},"o":["r⃗ cm = {11;8}L x̂ + {3;8}L ŷ","r⃗ cm = {13;8}L x̂ + {5;8}L ŷ","r⃗ cm = {3;8}L x̂ + {11;8}L ŷ","r⃗ cm = {5;8}L x̂ + {13;8}L ŷ"],"c":1,"s":"The bar has four parts, each of the same material, so mass is proportional to length:\n1. Horizontal, length 2L at y = L, from x = 0 to 2L: centre (L, L).\n2. Vertical, length L at x = 2L: centre (2L, L/2).\n3. Horizontal, length L on the x-axis from 2L to 3L: centre (2.5L, 0).\nTotal length = 2L + L + L = 4L.\nx = (2L·L + L·2L + L·2.5L)/4L = 6.5L/4 = 13L/8.\ny = (2L·L + L·L/2 + 0)/4L = 2.5L/4 = 5L/8.\nr⃗ cm = {13;8}L x̂ + {5;8}L ŷ. Option (b)."},
{"y":"JEE Main 2016 · Online","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"In the figure shown ABC is a uniform wire. If centre of mass of wire lies vertically below point A, then {BC;AB} is close to","fig":{"w":340,"h":190,"alt":"A wire ABC: segment BA rises from B at 60 degrees above the horizontal segment BC.","d":[["l",60,150,110,63.4],["l",60,150,230,150],["t",54,154,"B","e"],["t",236,154,"C"],["t",112,58,"A"],["t",84,146,"60°","s"],["p","M80 150 A20 20 0 0 0 70 133"]]},"o":["1.85","1.5","1.37","3"],"c":2,"s":"Let AB = l₁ and BC = l₂, with B at the origin and BC along the x-axis. The angle at B is 60°.\nA is at x = l₁cos 60° = l₁/2. The centre of AB is at x = l₁/4, and the centre of BC is at x = l₂/2.\nCM is below A, so x_cm = l₁/2: (l₁·l₁/4 + l₂·l₂/2)/(l₁ + l₂) = l₁/2.\nThis gives 2l₂² − 2l₁l₂ − l₁² = 0. With r = l₂/l₁: 2r² − 2r − 1 = 0, so r = (1 + √3)/2 ≈ 1.37.\nOption (c)."},
{"y":"JEE Main 2015","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"Distance of the centre of mass of a solid uniform cone from its vertex is z₀. If the radius of its base is R and its height is h then z₀ is equal to","o":["{5h;8}","{3h²;8R}","{h²;4R}","{3h;4}"],"c":3,"s":"For a solid uniform cone the centre of mass lies on the axis, at 1/4 of the height from the base.\nSo from the vertex the distance is h − h/4 = 3h/4.\n(Check by integration: slice at distance z from the vertex has area ∝ z², so z₀ = ∫z³dz/∫z²dz = (h⁴/4)/(h³/3) = 3h/4. It does not depend on R.)\nOption (d)."},
{"y":"JEE Main 2015 · Online","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"A uniform thin rod AB of length L has linear mass density μ(x) = a + {bx;L}, where x is measured from A. If the CM of the rod lies at a distance of ({7;12}L) from A, then a and b are related as","o":["a = b","a = 2b","2a = b","3a = 2b"],"c":2,"s":"x_cm = ∫xμ dx / ∫μ dx.\nNumerator = ∫₀ᴸ (ax + bx²/L) dx = aL²/2 + bL²/3.\nDenominator = ∫₀ᴸ (a + bx/L) dx = aL + bL/2.\nx_cm = L(a/2 + b/3)/(a + b/2) = 7L/12.\nCross-multiply: 12(a/2 + b/3) = 7(a + b/2), so 6a + 4b = 7a + 3.5b, giving 0.5b = a, that is b = 2a.\nSo 2a = b. Option (c)."},
{"y":"JEE Main 2014 · Online","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"A thin bar of length L has a mass per unit length λ, that increases linearly with distance from one end. If its total mass is M and its mass per unit length at the lighter end is λ₀, then the distance of the centre of mass from the lighter end is","o":["{L;2} − {λ₀L²;4M}","{L;3} + {λ₀L²;8M}","{L;3} + {λ₀L²;4M}","{2L;3} − {λ₀L²;6M}"],"c":3,"s":"Let the lighter end be x = 0 and λ = λ₀ + kx.\nTotal mass M = λ₀L + kL²/2, so k = 2(M − λ₀L)/L².\nM x_cm = ∫xλ dx = λ₀L²/2 + kL³/3 = λ₀L²/2 + 2L(M − λ₀L)/3.\nx_cm = λ₀L²/(2M) + 2L/3 − 2λ₀L²/(3M) = 2L/3 − λ₀L²/(6M).\nOption (d)."},
{"y":"JEE Main 2013 · Online","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A projectile of mass M is fired so that the horizontal range is 4 km. At the highest point, the projectile explodes in two parts of masses {M;4} and {3M;4} respectively and the heavier part starts falling down vertically with zero initial speed. The horizontal range (distance from point of firing) of the lighter part is","o":["16 km","1 km","10 km","2 km"],"c":2,"s":"At the highest point the projectile has only horizontal speed u, and it is 2 km (half the range) from the firing point.\nThe heavy part has zero horizontal speed, so momentum conservation gives M·u = (M/4)·v, so v = 4u.\nThe remaining fall time is the same as the time of the original flight to the top, in which the projectile moved 2 km at speed u. At speed 4u it moves 4 × 2 = 8 km.\nRange of the lighter part = 2 + 8 = 10 km.\nOption (c)."},
{"y":"AIEEE 2012 · Online","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A projectile moving vertically upwards with a velocity of 200 m s⁻¹ breaks into two equal parts at a height of 490 m. One part starts moving vertically upwards with a velocity of 400 m s⁻¹. How much time after the break up will the other part hit the ground?","o":["2√10 s","5 s","10 s","√10 s"],"c":2,"s":"The velocity of 200 m/s is the velocity of the projectile at the instant it breaks, at 490 m.\nMomentum is conserved: 2m × 200 = m × 400 + m × v₂, so v₂ = 0.\nThe other part starts from rest at height 490 m and falls freely (g = 9.8 m/s²): 490 = ½ × 9.8 × t².\nt² = 100, so t = 10 s.\nOption (c)."},
{"y":"IIT-JEE 2011","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A ball of mass 0.2 kg rests on a vertical post of height 5 m. A bullet of mass 0.01 kg, travelling with a velocity V m/s in a horizontal direction, hits the centre of the ball. After the collision, the ball and bullet travel independently. The ball hits the ground at a distance of 20 m and the bullet at a distance of 100 m from the foot of the post. The initial velocity V of the bullet is","o":["250 m/s","250√2 m/s","400 m/s","500 m/s"],"c":3,"s":"Both leave the post horizontally from height 5 m, so both fall for t = √(2h/g) = √(2 × 5/10) = 1 s.\nBall speed = 20 m/s, bullet speed after collision = 100 m/s.\nHorizontal momentum is conserved: 0.01 × V = 0.2 × 20 + 0.01 × 100 = 4 + 1 = 5.\nV = 500 m/s.\nOption (d)."},
{"y":"IIT-JEE 2009","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"Look at the drawing given in the figure which has been drawn with ink of uniform line-thickness. The mass of ink used to draw each of the two inner circles, and each of the two line segments is m. The mass of the ink used to draw the outer circle is 6m. The coordinates of the centres of the different parts are: outer circle (0, 0), left inner circle (−a, a), right inner circle (a, a), vertical line (0, 0) and horizontal line (0, −a). The y-coordinate of the centre of mass of the ink in this drawing is","fig":{"w":340,"h":200,"alt":"A face drawing: a large outer circle, two small circles for eyes, a short vertical line for the nose and a short horizontal line for the mouth, with dashed x and y axes through the centre.","d":[["c",140,100,75],["c",112,72,14],["c",168,72,14],["l",140,85,140,115],["l",120,128,160,128],["l",140,100,240,100,"da"],["l",140,100,140,10,"da"],["t",244,104,"x"],["t",146,14,"y"]]},"o":["{a;10}","{a;8}","{a;12}","{a;3}"],"c":0,"s":"Total mass = 6m + m + m + m + m = 10m.\nThe y-coordinates of the centres: outer circle 0, two inner circles a and a, vertical line 0, horizontal line −a.\ny_cm = (6m·0 + m·a + m·a + m·0 + m·(−a))/10m = a/10.\nOption (a)."},
{"y":"AIEEE 2008","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"A thin rod of length L is lying along the x-axis with its ends at x = 0 and x = L. Its linear density (mass/length) varies with x as k(x/L)ⁿ where n can be zero or any positive number. If the position x_CM of the centre of mass of the rod is plotted against n, which of the following graphs best approximates the dependence of x_CM on n?","fig":{"w":340,"h":200,"alt":"Four graphs of x_CM against n: (a) flat at L/2 then S-shaped rise to L; (b) rising from L/2 with decreasing slope towards L; (c) horizontal line at L/2; (d) falling from L to L/2.","d":[["t",99,12,"(a)","m"],["l",44,92,44,22,"a"],["l",44,92,154,92,"a"],["l",44,34,144,34,"d"],["l",44,63,144,63,"d"],["t",40,38,"L","es"],["t",40,67,"L/2","es"],["t",40,96,"O","es"],["t",158,96,"n","s"],["t",48,22,"xCM","s"],["p","M44 63 H64 C84 63 84 34 104 34 H144"],["t",269,12,"(b)","m"],["l",214,92,214,22,"a"],["l",214,92,324,92,"a"],["l",214,34,314,34,"d"],["l",214,63,314,63,"d"],["t",210,38,"L","es"],["t",210,67,"L/2","es"],["t",210,96,"O","es"],["t",328,96,"n","s"],["t",218,22,"xCM","s"],["p","M214 63 C222 42 239 36 314 34"],["t",99,112,"(c)","m"],["l",44,192,44,122,"a"],["l",44,192,154,192,"a"],["l",44,134,144,134,"d"],["l",44,163,144,163,"d"],["t",40,138,"L","es"],["t",40,167,"L/2","es"],["t",40,196,"O","es"],["t",158,196,"n","s"],["t",48,122,"xCM","s"],["l",44,163,144,163],["t",269,112,"(d)","m"],["l",214,192,214,122,"a"],["l",214,192,324,192,"a"],["l",214,134,314,134,"d"],["l",214,163,314,163,"d"],["t",210,138,"L","es"],["t",210,167,"L/2","es"],["t",210,196,"O","es"],["t",328,196,"n","s"],["t",218,122,"xCM","s"],["p","M214 134 C239 155 269 162 314 163"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":1,"s":"Linear density λ = k(x/L)ⁿ.\nx_cm = ∫₀ᴸ xⁿ⁺¹ dx / ∫₀ᴸ xⁿ dx = [Lⁿ⁺²/(n + 2)] / [Lⁿ⁺¹/(n + 1)] = L(n + 1)/(n + 2).\nFor n = 0 this gives L/2 (uniform rod). As n increases the value rises quickly at first and approaches L but never exceeds it.\nSo the graph starts at L/2 and rises with decreasing slope towards L. That is graph (b)."},
{"y":"AIEEE 2006","tp":"prc","st":"Centre of mass of systems","q":"Consider a two particle system with particles having masses m₁ and m₂. If the first particle is pushed towards the centre of mass through a distance d, by what distance should the second particle be moved, so as to keep the centre of mass at the same position?","o":["d","{m₂;m₁}d","{m₁;m₁+m₂}d","{m₁;m₂}d"],"c":3,"s":"The centre of mass stays fixed if the mass-weighted displacements cancel: m₁Δx₁ + m₂Δx₂ = 0.\nThe first particle moves d towards the centre of mass. Then the second must also move towards the centre of mass (it lies on the other side), by Δx₂ with m₂Δx₂ = m₁d.\nΔx₂ = (m₁/m₂)d.\nOption (d)."},
{"y":"AIEEE 2005","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"A T shaped object with dimensions shown in the figure, is lying on a smooth floor. A force F⃗ is applied at the point P parallel to AB, such that the object has only the translational motion without rotation. Find the location of P with respect to C.","fig":{"w":340,"h":250,"alt":"A T shaped object: a horizontal bar AB of length l on top of a vertical bar of length 2l ending at C. A force F acts to the right at a point P on the vertical bar.","d":[["r",100,25,100,8,"F"],["r",146,33,8,196,"F"],["t",92,32,"A","e"],["t",206,32,"B"],["t",150,246,"C","m"],["l",100,12,200,12,"b"],["t",150,9,"l","m"],["l",240,29,240,229,"b"],["t",246,130,"2l"],["l",96,139,146,139,"a"],["t",92,134,"F","e"],["t",160,143,"P"]]},"o":["{4;3}l","l","{3;4}l","{3;2}l"],"c":0,"s":"For pure translation, the line of the force must pass through the centre of mass.\nTake the two rods uniform and of the same material, so mass is proportional to length: AB (length l) has mass m, and CD (length 2l) has mass 2m.\nMeasure distance from C along the stem. The stem's centre is at l, and the bar AB sits at the top, at 2l.\ny_cm = (2m·l + m·2l)/3m = 4l/3.\nSo P is at 4l/3 from C. Option (a)."},
{"y":"AIEEE 2005","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A body A of mass M while falling vertically downwards under gravity breaks into two parts; a body B of mass {1;3}M and body C of mass {2;3}M. The center of mass of bodies B and C taken together shifts compared to that of body A towards","o":["body C","body B","depends on height of breaking","does not shift"],"c":3,"s":"Breaking is caused by internal forces only. The only external force on the system is gravity, the same as before the break.\nSo the centre of mass of B and C moves exactly as the centre of mass of A would have moved (same acceleration g, same initial velocity).\nThe centre of mass therefore does not shift.\nOption (d)."},
{"y":"AIEEE 2002","tp":"prc","st":"Centre of mass of systems","q":"Two identical particles move towards each other with velocity 2v and v respectively. The velocity of centre of mass is","o":["v","v/3","v/2","zero"],"c":2,"s":"For identical masses, v_cm = (m·2v + m·(−v))/(2m).\nTake the direction of the first particle as positive; the second moves in the opposite direction, so its velocity is −v.\nv_cm = (2v − v)/2 = v/2.\nOption (c)."},
{"y":"IIT-JEE 2002","tp":"prc","st":"Motion of the centre of mass and collisions","q":"Two blocks of masses 10 kg and 4 kg are connected by a spring of negligible mass and placed on a frictionless horizontal surface. An impulse gives a velocity of 14 m/s to the heavier block in the direction of the lighter block. The velocity of the centre of mass is","o":["30 m/s","20 m/s","10 m/s","5 m/s"],"c":2,"s":"Right after the impulse the heavier block moves at 14 m/s and the lighter one is at rest.\nv_cm = (10 × 14 + 4 × 0)/(10 + 4) = 140/14 = 10 m/s.\nNo external horizontal force acts afterwards, so v_cm stays 10 m/s.\nOption (c)."},
{"y":"IIT-JEE 2001","tp":"prc","st":"Motion of the centre of mass and collisions","q":"Two particles of masses m₁ and m₂, in projectile motion, have velocities v⃗₁ and v⃗₂ respectively at time t = 0. They collide at time t₀. Their velocities become v⃗₁′ and v⃗₂′ at time 2t₀ while moving in air. The value of impulse is","o":["zero","(m₁ + m₂)gt₀","2(m₁ + m₂)gt₀","{1;2}(m₁ + m₂)gt₀"],"c":2,"s":"Treat the two particles as one system. The collision forces are internal, so only gravity changes the total momentum.\nOver the time interval from 0 to 2t₀, the total impulse of gravity is (m₁ + m₂)g × 2t₀.\nSo |(m₁v⃗₁′ + m₂v⃗₂′) − (m₁v⃗₁ + m₂v⃗₂)| = 2(m₁ + m₂)gt₀.\nOption (c)."},
{"y":"IIT-JEE 1997","tp":"prc","st":"Motion of the centre of mass and collisions","q":"An isolated particle of mass m is moving in horizontal plane (x-y) along the x-axis, at a certain height above the ground. It suddenly explodes into two fragments of masses {m;4} and {3m;4}. An instant later, the smaller fragment is at y = +15 cm. The larger fragment at this instant is at","o":["y = −5 cm","y = +20 cm","y = +5 cm","y = −20 cm"],"c":0,"s":"The particle moves along the x-axis, so its centre of mass has y = 0, and the explosion is by internal forces only, so the centre of mass keeps y = 0.\n(m/4)(15) + (3m/4)y = 0.\n3y/4 = −15/4, so y = −5 cm.\nOption (a)."},
{"y":"IIT-JEE 1982","tp":"prc","st":"Motion of the centre of mass and collisions","q":"Two particles A and B, initially at rest, move towards each other under mutual force of attraction. At the instant when the speed of A is v and the speed of B is 2v, the speed of the centre of mass of the system is","o":["3v","v","1.5v","zero"],"c":3,"s":"The only forces are the mutual (internal) forces, so the total momentum stays at its initial value, zero.\nHence v_cm = 0 at all times, whatever the speeds of A and B.\n(Check: m_A·v = m_B·2v in magnitude and opposite in direction.)\nOption (d)."},
{"y":"JEE Advanced 2017","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A block of mass M has a circular cut with a frictionless surface as shown. The block rests on the horizontal frictionless surface of a fixed table. Initially the right edge of the block is at x = 0, in a co-ordinate system fixed to the table. A point mass m is released from rest at the topmost point of the path as shown and it slides down. When the mass loses contact with the block, its position is x and the velocity is v. At that instant, which of the following options is/are correct?","fig":{"w":340,"h":200,"alt":"A block of mass M with a quarter circular cut of radius R at its top right corner, resting on a table. The point mass m is at the top left end of the cut. The right edge of the block is at x = 0.","d":[["l",40,168,40,45,"a"],["t",46,48,"y"],["l",40,168,90,168,"a"],["t",76,158,"x"],["l",60,170,300,170,"B"],["p","M100 165 V70 H190 A60 60 0 0 0 250 130 V165 Z","f"],["c",190,70,3.5,"F"],["t",180,64,"m","e"],["t",140,125,"M","m"],["l",190,54,250,54,"b"],["t",220,48,"R","m"],["l",270,70,270,130,"b"],["t",276,104,"R"],["l",250,56,250,180,"d"],["t",250,194,"x = 0","m"]]},"o":["The velocity of the point mass m is v = √{2gR;1 + m/M}","The x component of displacement of the center of mass of the block M is −{mR;M+m}","The position of the point mass is x = −√2 {mR;M+m}","The velocity of the block M is V = −{m;M}√(2gR)"],"c":[0,1],"s":"No horizontal external force acts on the block and mass together, so the horizontal momentum stays zero: mv = MV (opposite directions), and the horizontal CM stays fixed.\nEnergy: mgR = ½mv² + ½MV². Put V = mv/M: mgR = ½mv²(1 + m/M), so v = √(2gR/(1 + m/M)). (a) is correct.\nThe mass moves a horizontal distance R relative to the block. If the block moves X, the mass moves R + X relative to the table (X is negative), and mR + (m + M)X = 0, so X = −mR/(M + m). (b) is correct.\nThe mass ends at the block's right edge, which is at x = −mR/(M + m), not −√2 mR/(M + m). (c) is wrong.\nV = (m/M)v = (m/M)√(2gR/(1 + m/M)), which is not (m/M)√(2gR). (d) is wrong.\nAnswer: (a) and (b)."},
{"y":"IIT-JEE 2011","tp":"pra","st":"Collisions with rotating bodies","q":"A thin ring of mass 2 kg and radius 0.5 m is rolling without slipping on a horizontal plane with velocity 1 m/s. A small ball of mass 0.1 kg, moving with velocity 20 m/s in the opposite direction, hits the ring at a height of 0.75 m and goes vertically up with velocity 10 m/s. Immediately after the collision","fig":{"w":340,"h":190,"alt":"A ring rolling on the ground with velocity 1 m/s to the left. A ball moving at 20 m/s to the right hits the ring at a height of 0.75 m and then moves vertically up at 10 m/s.","d":[["l",20,170,330,170,"B"],["c",200,110,60],["c",200,110,2,"F"],["l",210,110,185,110,"a"],["t",196,132,"1 m/s","m"],["l",60,80,148,80,"a"],["t",56,72,"20 m/s","e"],["l",148,80,148,20,"a"],["t",154,26,"10 m/s"],["l",40,80,40,170,"b"],["t",34,128,"0.75 m","e"]]},"o":["the ring has pure rotation about its stationary CM.","the ring comes to a complete stop.","friction between the ring and the ground is to the left.","there is no friction between the ring and the ground."],"c":[0,2],"s":"Take right as positive. The ring moves left at 1 m/s (momentum −2 kg m/s), the ball moves right (+0.1 × 20 = +2 kg m/s).\nAfter the collision the ball has no horizontal velocity. If ground friction impulse is small, horizontal momentum conserved: −2 + 2 = 0 = 2 × v_ring + 0, so the ring's CM stops (v = 0).\nAngular momentum about the ring's centre: before = Iω = (2 × 0.5²)(1/0.5) = 1.0 kg m²/s (anticlockwise, for leftward rolling). The ball hit 0.25 m above the centre with impulse 2 N s to the right, giving −2 × 0.25 = −0.5 (clockwise). Now L = 0.5, so ω = 0.5/0.5 = 1 rad/s (anticlockwise).\nSo the ring only spins about its stationary centre, and the contact point moves right at ωR = 0.5 m/s. (a) is true, (b) is false.\nThe contact point slides to the right, so kinetic friction on the ring acts to the left. (c) is true, (d) is false.\nAnswer: (a) and (c)."},
{"y":"IIT-JEE 2009","tp":"prc","st":"Motion of the centre of mass and collisions","q":"If the resultant of all the external forces acting on a system of particles is zero, then from an inertial frame, one can surely say that","o":["linear momentum of the system does not change in time","kinetic energy of the system does not change in time","angular momentum of the system does not change in time","potential energy of the system does not change in time"],"c":0,"s":"Net external force = rate of change of total linear momentum. If it is zero, linear momentum does not change with time. (a) is true.\nThe net external torque can still be non-zero (a couple), so angular momentum can change. (c) is not sure.\nExternal forces can still do work (for example two equal and opposite forces on a rod) so kinetic and potential energy can change. (b) and (d) are not sure.\nOption (a)."},
{"y":"IIT-JEE 2008","tp":"prc","st":"Motion of the centre of mass and collisions","q":"Two balls, having linear momenta p⃗₁ = pî and p⃗₂ = −pî, undergo a collision in free space. There is no external force acting on the balls. Let p⃗₁′ and p⃗₂′ be their final momenta. The following option(s) is/are NOT ALLOWED for any non-zero value of p, a₁, a₂, b₁, b₂, c₁ and c₂.","o":["p⃗₁′ = a₁î + b₁ĵ + c₁k̂ and p⃗₂′ = a₂î + b₂ĵ","p⃗₁′ = c₁k̂ and p⃗₂′ = c₂k̂","p⃗₁′ = a₁î + b₁ĵ + c₁k̂ and p⃗₂′ = a₂î + b₂ĵ − c₁k̂","p⃗₁′ = a₁î + b₁ĵ and p⃗₂′ = a₂î + b₁ĵ"],"c":[0,3],"s":"There is no external force, so total momentum is conserved: p⃗₁′ + p⃗₂′ = p⃗₁ + p⃗₂ = 0.\nSo every component of the final momenta must cancel in pairs.\n(a) The z component is c₁ + 0 = c₁ ≠ 0, so this is not allowed.\n(b) c₁ + c₂ = 0 is possible with c₂ = −c₁, so this is allowed.\n(c) The z components cancel (c₁ − c₁ = 0), and the others can cancel with a₂ = −a₁, b₂ = −b₁. Allowed.\n(d) The y component is b₁ + b₁ = 2b₁ ≠ 0 for non-zero b₁, so this is not allowed.\nNot allowed: (a) and (d)."},
{"y":"IIT-JEE 1993","tp":"prc","st":"Motion of the centre of mass and collisions","q":"Two blocks A and B, each of mass m, are connected by a massless spring of natural length L and spring constant K. The blocks are initially resting on a smooth horizontal floor with the spring at its natural length, as shown in figure. A third identical block C, also of mass m, moves on the floor with a speed v along the line joining A and B, and collides elastically with A. Then","fig":{"w":340,"h":150,"alt":"Three blocks on a smooth floor: C moving right with speed v towards A; A and B are joined by a spring of natural length L.","d":[["l",20,122,320,122,"B"],["r",30,72,50,50],["t",55,102,"C","m"],["r",140,72,50,50],["t",165,102,"A","m"],["r",270,72,50,50],["t",295,102,"B","m"],["p","M190 97 H198 L203 85 L213 109 L223 85 L233 109 L243 85 L253 109 L258 97 H270"],["l",35,58,75,58,"a"],["t",55,50,"v","m"],["l",190,62,270,62,"b"],["t",230,56,"L","m"]]},"o":["the kinetic energy of the A-B system, at maximum compression of the spring, is zero.","the kinetic energy of the A-B system, at maximum compression of the spring, is mv²/4.","the maximum compression of the spring is v√(m/K).","the maximum compression of the spring is v√(m/2K)."],"c":[1,3],"s":"C and A are identical and the collision is elastic, so they exchange velocities: C stops and A moves with v.\nThen A and B (spring between them) have momentum mv. At maximum compression they move with the same velocity v/2.\nKE of A-B system at maximum compression = ½(2m)(v/2)² = mv²/4. So (a) is false and (b) is true.\nEnergy: ½mv² = mv²/4 + ½Kx², so ½Kx² = mv²/4 and x = v√(m/2K). (c) is false and (d) is true.\nAnswer: (b) and (d)."},
{"y":"IIT-JEE 1986","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A ball hits the floor and rebounds after an inelastic collision. In this case","o":["the momentum of the ball just after the collision is the same as that just before the collision","the mechanical energy of the ball remains the same in the collision","the total momentum of the ball and the earth is conserved","the total energy of the ball and the earth is conserved."],"c":[2,3],"s":"In an inelastic collision the ball's speed after the collision is less than before, so its momentum and its mechanical energy both change. (a) and (b) are false.\nThe floor (Earth) takes the lost momentum; momentum of the ball + Earth system is conserved because the only forces are internal. (c) is true.\nEnergy is never destroyed: the lost mechanical energy becomes heat, sound and deformation, so total energy of ball and Earth is conserved. (d) is true.\nAnswer: (c) and (d)."},
{"y":"IIT-JEE 1986","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A shell is fired from a cannon with a velocity v (m/sec.) at an angle θ with the horizontal. At the highest point in its path it explodes into two pieces of equal mass. One of the pieces retraces its path to the cannon and the speed (in m/sec) of the other piece immediately after the explosion is","o":["3v cos θ","2v cos θ","{3;2}v cos θ","√{3;2} v cos θ"],"c":0,"s":"At the highest point only the horizontal velocity v cos θ remains.\nTo retrace its path, one piece must move with velocity −v cos θ (same speed, backward).\nMomentum conservation (horizontal): 2m × v cos θ = m(−v cos θ) + m·u.\nu = 2v cos θ + v cos θ = 3v cos θ.\nOption (a)."},
{"y":"JEE Main 2025 · 29 Jan · Shift 1","tp":"prt","st":"Torque and its direction","q":"The coordinates of a particle with respect to origin in a given reference frame is (1, 1, 1) meters. If a force of F⃗ = î − ĵ + k̂ acts on the particle, then the magnitude of torque (with respect to origin) in z-direction is ______.","n":2,"s":"Torque τ⃗ = r⃗ × F⃗ with r⃗ = î + ĵ + k̂ and F⃗ = î − ĵ + k̂.\nThe z component of the torque is τ_z = x·F_y − y·F_x = (1)(−1) − (1)(1) = −2.\n(Full vector: τ⃗ = 2î − 2k̂, from the determinant.)\nThe magnitude of the z component is 2 N m."},
{"y":"JEE Main 2024 · 4 Apr · Shift 2","tp":"prc","st":"Centre of mass of systems","q":"In a system two particles of masses m₁ = 3 kg and m₂ = 2 kg are placed at certain distance from each other. The particle of mass m₁ is moved towards the centre of mass of the system through a distance 2 cm. In order to keep the centre of mass of the system at the original position, the particle of mass m₂ should move towards the centre of mass by the distance ______ cm.","n":3,"s":"The centre of mass stays fixed if m₁Δx₁ = m₂Δx₂ (both moved towards the centre of mass).\n3 × 2 = 2 × Δx₂.\nΔx₂ = 3 cm."},
{"y":"JEE Main 2024 · 8 Apr · Shift 1","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"A uniform thin metal plate of mass 10 kg with dimensions is shown. The ratio of x and y coordinates of center of mass of plate is {n;9}. The value of n is ______.","fig":{"w":340,"h":180,"alt":"A plate of overall size 3 by 2 with a square notch 1 by 1 removed from the middle of the top edge; corners (0,0), (3,0), (3,2), (2,2), (2,1), (1,1), (1,2), (0,2).","d":[["p","M50 150 H230 V30 H170 V90 H110 V30 H50 Z","f"],["l",50,150,50,10,"a"],["l",50,150,260,150,"a"],["t",44,28,"(0,2)","e"],["t",110,24,"(1,2)","m"],["t",170,24,"(2,2)","m"],["t",236,28,"(3,2)"],["t",114,108,"(1,1)"],["t",174,108,"(2,1)"],["t",44,166,"(0,0)","e"],["t",230,166,"(3,0)","m"]]},"n":15,"s":"The plate is the full rectangle 3 × 2 (area 6, centre (1.5, 1)) with a 1 × 1 piece removed from the top middle (x from 1 to 2, y from 1 to 2: area 1, centre (1.5, 1.5)).\nx_cm = 1.5 by symmetry.\ny_cm = (6 × 1 − 1 × 1.5)/(6 − 1) = 4.5/5 = 0.9.\nx/y = 1.5/0.9 = 5/3 = 15/9, so n = 15."},
{"y":"JEE Main 2024 · 1 Feb · Shift 1","tp":"prc","st":"Centre of mass of systems","q":"Three identical spheres each of mass 2M are placed at the corners of a right angled triangle with mutually perpendicular sides equal to 4 m each. Taking point of intersection of these two sides as origin, the magnitude of position vector of the centre of mass of the system is {4√2;x}, where the value of x is ______.","n":3,"s":"The masses are equal, so the centre of mass is the average of the positions.\nTake the corners at (0, 0), (4, 0) and (0, 4).\nx_cm = (0 + 4 + 0)/3 = 4/3 and y_cm = 4/3.\n|r| = √((4/3)² + (4/3)²) = 4√2/3.\nComparing with 4√2/x gives x = 3."},
{"y":"JEE Main 2023 · 21 Jan · Shift 1","tp":"prr","st":"Rolling and its energy","q":"A solid sphere of mass 2 kg is making pure rolling on a horizontal surface with kinetic energy 2240 J. The velocity of centre of mass of the sphere will be ______ m s⁻¹.","n":40,"s":"For pure rolling, total KE = ½mv² + ½Iω² with I = (2/5)mR² and ω = v/R.\nSo KE = ½mv²(1 + 2/5) = (7/10)mv².\n2240 = 0.7 × 2 × v², so v² = 1600.\nv = 40 m/s."},
{"y":"JEE Main 2022 · 25 Jul · Shift 2","tp":"prc","st":"Centre of mass of systems","q":"Three identical spheres each of mass M are placed at the corners of a right angled triangle with mutually perpendicular sides equal to 3 m each. Taking point of intersection of mutually perpendicular sides as origin, the magnitude of position vector of centre of mass of the system will be √x m. The value of x is ______.","n":2,"s":"Take the corners at (0, 0), (3, 0) and (0, 3) with equal masses.\nx_cm = (0 + 3 + 0)/3 = 1 and y_cm = 1.\n|r| = √(1² + 1²) = √2 m.\nSo x = 2."},
{"y":"JEE Main 2022 · 28 Jul · Shift 2","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"The distance of centre of mass from end A of a one dimensional rod (AB) having mass density ρ = ρ₀(1 − {x²;L²}) kg/m and length L (in meter) is {3L;α} m. The value of α is ______. (where x is the distance from end A)","n":8,"s":"Mass element dm = ρ dx, with x from 0 to L.\nTotal mass = ρ₀∫(1 − x²/L²)dx = ρ₀(L − L/3) = 2ρ₀L/3.\nMoment = ρ₀∫(x − x³/L²)dx = ρ₀(L²/2 − L²/4) = ρ₀L²/4.\nx_cm = (ρ₀L²/4)/(2ρ₀L/3) = 3L/8.\nComparing with 3L/α gives α = 8."},
{"y":"JEE Main 2021 · 22 Jul · Shift 2","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"The position of the centre of mass of a uniform semi-circular wire of radius R placed in x-y plane with its centre at the origin and the line joining its ends as x-axis is given by (0, {xR;π}). Then the value of |x| is ______.","n":2,"s":"For a semicircular wire the centre of mass lies on the axis of symmetry at a distance 2R/π from the centre.\nThis comes from y_cm = (1/πR)∫R sinθ · R dθ = 2R/π.\nComparing with xR/π gives x = 2, so |x| = 2."},
{"y":"JEE Main 2021 · 25 Jul · Shift 1","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A body of mass 2 kg moving with a speed of 4 m/s makes an elastic collision with another body at rest and continues to move in the original direction but with one fourth of its initial speed. The speed of the two body centre of mass is {x;10} m/s. Then the value of x is ______.","n":25,"s":"Let the second mass be m₂. For an elastic collision the first body's final speed is v₁' = {(m₁−m₂);(m₁+m₂)}·4.\nIt equals 4/4 = 1 m/s: 4(2 − m₂) = 2 + m₂, so m₂ = 1.2 kg.\nThe speed of the centre of mass stays constant: v_cm = (2 × 4)/(2 + 1.2) = 2.5 m/s.\n2.5 = x/10, so x = 25."},
{"y":"JEE Main 2021 · 17 Mar · Shift 2","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"A disc of mass M with uniform surface mass density σ is shown in the figure. The centre of mass of the quarter disc (the shaded area) is at the position {xa;3π}, where x is ______. (Round off to the nearest integer)\n[a is as shown in the figure]","fig":{"w":340,"h":200,"alt":"A circle of radius a centred at the origin with the quarter between the positive y-axis and positive x-axis shaded, and a radial line at angle θ above the x-axis","d":[["p","M170 100 L240 100 A70 70 0 0 0 170 30 Z","f"],["c",170,100,70],["l",95,100,170,100,"d"],["l",170,100,170,175,"d"],["l",170,100,300,100,"a"],["l",170,100,170,12,"a"],["l",170,100,231,65],["p","M200 100 A30 30 0 0 0 196 85"],["t",206,96,"θ","s"],["t",190,72,"a"],["t",304,104,"X"],["t",176,16,"Y"]]},"n":4,"s":"For a quarter disc of radius a (the radius is the length a in the figure), the centre of mass lies on the diagonal by symmetry.\nIntegrating thin strips gives x_cm = y_cm = 4a/(3π), measured from the centre O.\nCompare with xa/(3π): x = 4."},
{"y":"JEE Advanced 2021","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A projectile is thrown from a point O on the ground at an angle 45° from the vertical and with a speed 5√2 m s⁻¹. The projectile at the highest point of its trajectory splits into two equal parts. One part falls vertically down to the ground, 0.5 s after the splitting. The other part, t seconds after the splitting, falls to the ground at a distance x meters from the point O. The acceleration due to gravity g = 10 m s⁻².\nThe value of t is ______.","n":0.5,"s":"Launch speed components: vₓ = 5√2 sin45° = 5 m/s and v_y = 5√2 cos45° = 5 m/s.\nAt the top, height H = v_y²/2g = 1.25 m, time to the top = 0.5 s, and horizontal distance = 5 × 0.5 = 2.5 m.\nThe first part falls vertically from H = 1.25 m in 0.5 s (½ × 10 × 0.25 = 1.25), so it starts with zero vertical speed.\nThe second part also has zero vertical speed just after the split, so it falls the same height in the same time.\nt = 0.5 s."},
{"y":"JEE Advanced 2021","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A projectile is thrown from a point O on the ground at an angle 45° from the vertical and with a speed 5√2 m s⁻¹. The projectile at the highest point of its trajectory splits into two equal parts. One part falls vertically down to the ground, 0.5 s after the splitting. The other part, t seconds after the splitting, falls to the ground at a distance x meters from the point O. The acceleration due to gravity g = 10 m s⁻².\nThe value of x is ______.","n":7.5,"s":"At the top the speed is 5 m/s horizontal, at x = 2.5 m, height 1.25 m.\nMomentum conservation: 2m × 5 = m × 0 + m × u, so u = 10 m/s (horizontal) for the second part.\nIt takes t = 0.5 s to fall 1.25 m.\nAdditional distance = 10 × 0.5 = 5 m.\nx = 2.5 + 5 = 7.5 m."},
{"y":"JEE Main 2020 · 2 Sep · Shift 2","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"A square shaped hole of side l = {a;2} is carved out at a distance d = {a;2} from the centre 'O' of a uniform circular disk of radius a. If the distance of the centre of mass of the remaining portion from O is −{a;X}, value of X (to the nearest integer) is ______.","fig":{"w":340,"h":210,"alt":"A circular disc of radius a with centre O and a small square hole of side a/2 whose centre is a distance a/2 to the right of O","d":[["c",150,110,80],["l",150,25,150,198,"d"],["l",150,110,270,110,"d"],["r",170,90,40,40],["l",150,110,100,56,"a"],["t",112,76,"a"],["t",144,106,"O","e"],["l",150,110,189,110,"a"],["t",160,128,"d","s"],["t",190,152,"l = a/2","m"]]},"n":23,"s":"Treat the hole as a negative mass. Mass ∝ area.\nDisc area = πa², hole area = (a/2)² = a²/4, hole centre at distance a/2 from O.\nx_cm = −(a²/4 × a/2)/(πa² − a²/4) = −(a/8)/(π − 1/4) = −a/(8π − 2).\n8π − 2 ≈ 23.1, so X ≈ 23."},
{"y":"JEE Main 2020 · 6 Sep · Shift 2","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"The centre of mass of a solid hemisphere of radius 8 cm is x cm from the centre of the flat surface. Then value of x is ______.","n":3,"s":"For a solid hemisphere the centre of mass lies on the axis at 3R/8 from the centre of the flat face.\nx = (3/8) × 8 = 3 cm."},
{"y":"JEE Advanced 2018","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A solid horizontal surface is covered with a thin layer of oil. A rectangular block of mass m = 0.4 kg is at rest on this surface. An impulse of 1.0 N s is applied to the block at time t = 0 so that it starts moving along the x-axis with a velocity v(t) = v₀e^(−t/τ), where v₀ is a constant and τ = 4 s. The displacement of the block, in metres, at t = τ is ______. Take e⁻¹ = 0.37.","n":6.3,"s":"Impulse = change in momentum: 1.0 = 0.4 × v₀, so v₀ = 2.5 m/s.\nDisplacement = ∫₀^τ v₀e^(−t/τ) dt = v₀τ(1 − e⁻¹).\n= 2.5 × 4 × (1 − 0.37) = 10 × 0.63 = 6.3 m."},
{"y":"IIT-JEE 2003","tp":"prc","st":"Statements, matching and subjective","q":"Two masses m₁ and m₂ are connected by a light spring of natural length l₀ which is compressed completely and tied by a string. This system while moving with a velocity v₀ along +ve x-axis passes through the origin at t = 0. At this position the string snaps. Position of the particle m₁ at time t is given by the equation x₁(t) = v₀t − A(1 − cos ωt). Calculate\n(a) position of the particle m₂ as a function of time\n(b) l₀ in terms of A.","a":"(a) x₂ = v₀t + (m₁A/m₂)(1 − cos ωt)   (b) l₀ = (m₁/m₂ + 1)A","s":"No external horizontal force acts, so the centre of mass keeps moving at v₀: x_cm = v₀t (both masses start at the origin).\nm₁x₁ + m₂x₂ = (m₁ + m₂)v₀t gives m₂x₂ = (m₁ + m₂)v₀t − m₁v₀t + m₁A(1 − cos ωt).\nSo x₂ = v₀t + (m₁A/m₂)(1 − cos ωt).\nSpring length = x₂ − x₁ = A(1 + m₁/m₂)(1 − cos ωt).\nIt starts at zero (fully compressed) and oscillates about l₀ with amplitude l₀, so the length is l₀(1 − cos ωt).\nComparing: l₀ = (m₁/m₂ + 1)A."},
{"y":"IIT-JEE 2001","tp":"prc","st":"Statements, matching and subjective","q":"A car P is moving with a uniform speed of 5√3 m/s towards a carriage of mass 9 kg at rest kept on the rails at a point B as shown in figure. The height AC is 120 m. Cannon balls of 1 kg are fired from the car with an initial velocity 100 m/s at an angle 30° with the horizontal. The first cannon ball hits the stationary carriage after a time t₀ and sticks to it. Determine t₀. At t₀, the second cannon ball is fired. Assume that the resistive force between the rails and the carriage is constant and ignore the vertical motion of the carriage throughout. If the second ball also hits and sticks to the carriage, what will be the horizontal velocity of the carriage just after the second impact?","fig":{"w":340,"h":185,"alt":"A car P on a high platform fires a cannon ball upward to the right; below the platform edge C, point A is 120 m lower, where a carriage B stands on the rails","d":[["l",25,60,175,60],["r",50,42,34,16,"f"],["l",72,40,92,24,"a"],["t",58,76,"P"],["t",180,58,"C"],["l",175,60,175,142],["t",169,142,"A","e"],["l",175,142,320,142],["r",250,126,34,14,"f"],["t",267,158,"B","m"],["t",168,104,"120 m","es"]]},"a":"t₀ = 12 s;  v = 15.75 m/s","s":"Ball: vertical launch speed = 100 sin30° = 50 m/s up, and it must land 120 m below.\n−120 = 50t − 5t², so t² − 10t − 24 = 0 and t₀ = 12 s.\nHorizontal speed of the ball = 100 cos30° = 50√3 m/s (the 100 m/s is taken as the ground-frame speed).\nFirst impact: 1 × 50√3 = 10 v₁, so v₁ = 5√3 m/s. This equals the car's speed, so the gap stays the same and the second ball also needs 12 s.\nThe carriage keeps v₁ (constant resistive force assumed to be balanced).\nSecond impact: 50√3 + 10 × 5√3 = 11 v, so v = 100√3/11 ≈ 15.75 m/s."},
{"y":"IIT-JEE 1999","tp":"prc","st":"Statements, matching and subjective","q":"Two blocks of mass 2 kg and M are at rest on an inclined plane and are separated by a distance of 6.0 m as shown in figure. The co-efficient of friction between each of the blocks and the inclined plane is 0.25. The 2 kg block is given a velocity of 10.0 m/s up the inclined plane. It collides with M, comes back and has a velocity of 1.0 m/s when it reaches its initial position. The other block M after the collision moves 0.5 m up and comes to rest. Calculate the co-efficient of restitution between the blocks and the mass of the block M.\n[Take sinθ ≈ tanθ = 0.05 and g = 10 m/s²]","fig":{"w":340,"h":175,"alt":"An incline of angle θ with a 2 kg block low on the slope and block M higher up, 6.0 m apart along the slope","d":[["l",40,150,310,150],["l",40,150,300,60],["p","M87.3 133.7 L129.8 119 L118 85 L75.5 99.7 Z","f"],["p","M219.6 87.9 L266.8 71.5 L255 37.5 L207.8 53.9 Z","f"],["t",98,112,"2 kg","ms"],["t",232,64,"M","m"],["l",126,102,212,71,"bd"],["t",134,84,"6.0 m","s"],["p","M70 150 A30 30 0 0 0 68.4 140.2"],["t",78,146,"θ","s"]]},"a":"e = 0.84, M = 15.02 kg","s":"Take sinθ ≈ 0.05, cosθ ≈ 1. Going up: deceleration = g(sinθ + μcosθ) = 0.5 + 2.5 = 3 m/s².\nSpeed before hitting M: v² = 10² − 2 × 3 × 6 = 64, so v = 8 m/s.\nComing back down, friction (2.5) beats gravity (0.5), deceleration = 2 m/s². After the collision speed u: 1² = u² − 2 × 2 × 6, so u = 5 m/s (down).\nBlock M goes 0.5 m up and stops: V² = 2 × 3 × 0.5 = 3, so V = √3 m/s.\nMomentum: 2 × 8 = −2 × 5 + M√3, so M = 26/√3 ≈ 15.0 kg (book: 15.02).\ne = (V + 5)/8 = (1.73 + 5)/8 ≈ 0.84."},
{"y":"IIT-JEE 1998","tp":"prc","st":"Statements, matching and subjective","q":"A wedge of mass m and triangular cross-section (AB = BC = CA = 2R) is moving with a constant velocity v î towards a sphere of radius R fixed on a smooth horizontal table, as shown in the figure. The wedge makes an elastic collision with the fixed sphere and returns along the same path, without any rotation. Neglect all friction and suppose that the wedge remains in contact with the sphere for a very short time Δt during which the sphere exerts a constant force F⃗ on the wedge.\n(a) Find the force F⃗ and also the normal force N⃗ exerted by the table on the wedge during the time Δt.\n(b) Let h denote the perpendicular distance between the centre of mass of the wedge and the line of action of F⃗. Find the magnitude of the torque due to the normal force N⃗ about the centre of the wedge during the interval Δt.","fig":{"w":340,"h":185,"alt":"A fixed sphere of radius R on a table at left and an equilateral triangular wedge ABC on the table moving left toward it with speed v; x axis along the table and z axis vertical","d":[["l",30,150,320,150,"a"],["l",30,150,30,20,"a"],["t",22,24,"z","e"],["t",324,154,"x"],["c",110,115,35],["l",110,115,110,80],["t",98,100,"R","e"],["p","M185 150 L280 150 L232 68 Z"],["l",205,112,165,112,"a"],["t",184,104,"v","m"],["t",232,60,"A","m"],["t",185,168,"B","m"],["t",282,168,"C","m"]]},"a":"(a) F⃗ = (2mv/(√3 Δt))(√3 î − k̂), N⃗ = (2mv/(√3 Δt) + mg) k̂   (b) |τ| = 4mvh/(√3 Δt)","s":"The face AB makes 60° with the table, so the contact force of the sphere is normal to it, at 30° to the horizontal, pushing the wedge back and downward: direction (√3/2) î − (1/2) k̂.\nAn elastic collision reverses the wedge's horizontal velocity, so the horizontal impulse is 2mv: F cos30° × Δt = 2mv, giving F = 4mv/(√3 Δt).\nSo F⃗ = (2mv/(√3 Δt))(√3 î − k̂). Its downward part is 2mv/(√3 Δt).\nVertical balance (no vertical motion): N = mg + 2mv/(√3 Δt), along +k̂.\n(b) The wedge does not rotate, so the torque of N about the centre of mass cancels the torque of F, which is F × h.\n|τ| = (4mv/(√3 Δt)) h = 4mvh/(√3 Δt)."},
{"y":"IIT-JEE 1997","tp":"prc","st":"Statements, matching and subjective","q":"A cart is moving along + x direction with a velocity of 4 m/s. A person on the cart throws a stone with a velocity of 6 m/s relative to himself. In the frame of reference of the cart, the stone is thrown in y-z plane making an angle of 30° with vertical z-axis. At the highest point of its trajectory, the stone hits an object of equal mass hung vertically from the branch of a tree by means of a string of length L. A completely inelastic collision occurs, in which the stone gets embedded in the object. Determine:\n(i) The speed of the combined mass immediately after the collision with respect to an observer on the ground.\n(ii) The length L of the string such that the tension in the string becomes zero when the string becomes horizontal during the subsequent motion of the combined mass.","a":"(i) 2.5 m/s   (ii) L = 0.318 m","s":"Stone relative to cart: y-component = 6 sin30° = 3 m/s, z-component = 6 cos30° = 3√3 m/s.\nIn the ground frame the x-component is the cart's 4 m/s. At the highest point the z-component is zero, so the velocity is (4, 3, 0), speed = 5 m/s.\n(i) Equal masses stick: v = 5/2 = 2.5 m/s.\n(ii) When the string is horizontal the tension is mv²/L (gravity is perpendicular to the string), so T = 0 needs speed zero there.\nEnergy: ½v² = gL, so L = v²/2g = 6.25/19.6 ≈ 0.32 m (book: 0.318 m with g = 9.8)."},
{"y":"IIT-JEE 1996","tp":"prc","st":"Centre of mass of systems","q":"A small sphere of radius R is held against the inner surface of a larger sphere of radius 6R. The masses of the large and small spheres are 4M and M respectively. This arrangement is placed on a horizontal table. There is no friction between any surfaces of contact. The small sphere is now released. Find the coordinates of the centre of the larger sphere when the smaller sphere reaches the other extreme position.","fig":{"w":340,"h":200,"alt":"A large circle of radius 6R, mass 4M, centred at (L, 0) on the x-axis with a small circle of radius R and mass M touching its inner surface on the right","d":[["l",40,105,320,105,"a"],["l",40,190,40,15,"a"],["t",46,20,"y","s"],["t",324,108,"x"],["t",30,118,"0","e"],["c",170,105,72],["c",230,105,12],["l",170,105,119,54,"a"],["t",134,70,"6R"],["l",230,105,222,96,"a"],["t",236,92,"R","s"],["t",230,122,"M","ms"],["t",170,122,"(L, 0)","ms"],["t",170,152,"4M","m"]]},"a":"(L + 2R, 0)","s":"There is no external horizontal force, so the centre of mass of the system does not move horizontally.\nInitially the small sphere is 6R − R = 5R to the right of the large centre; at the other extreme it is 5R to the left. Relative shift = 10R to the left.\nLet the large sphere move by Δ to the right. Then the small one moves Δ − 10R.\n4M × Δ + M(Δ − 10R) = 0, so 5Δ = 10R and Δ = 2R.\nThe centre of the large sphere is at (L + 2R, 0)."},
{"y":"IIT-JEE 1993","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A cylindrical solid of mass 10⁻² kg and cross-sectional area 10⁻⁴ m² is moving parallel to its axis (the x-axis) with a uniform speed of 10³ m/s in the positive direction. At t = 0, its front face passes the plane x = 0. The region to the right of this plane is filled with dust particles of uniform density 10⁻³ kg/m³. When a dust particle collides with the face of the cylinder, it sticks to its surface. Assuming that the dimensions of the cylinder remain practically unchanged and that the dust sticks only to the front face, find the x-coordinate of the front of the cylinder at t = 150 s.","a":"10⁵ m","s":"When the front is at x, dust mass collected = ρAx, with ρA = 10⁻³ × 10⁻⁴ = 10⁻⁷ kg/m.\nMomentum conservation (dust initially at rest): M v₀ = (M + ρAx) v, with v = dx/dt.\nSo (M + ρAx) dx = M v₀ dt. Integrating: Mx + ρAx²/2 = M v₀ t.\n10⁻²x + 0.5 × 10⁻⁷x² = 10⁻² × 10³ × 150 = 1500.\nx² + 2 × 10⁵x − 3 × 10¹⁰ = 0, so x = (−2×10⁵ + 4×10⁵)/2 = 10⁵ m."},
{"y":"IIT-JEE 1993","tp":"prc","st":"Statements, matching and subjective","q":"A uniform thin rod of mass M and length L is standing vertically along the y-axis, on a smooth horizontal surface, with its lower end at the origin (0, 0). A slight disturbance at t = 0 causes the lower end to slip on the smooth surface along the positive x-axis and the rod starts falling.\n(i) What is the path, followed by the centre of mass of the rod, during its fall?\n(ii) Find the equation of the trajectory of a point on the rod, located at a distance r from the lower end. What is the shape of the path of this point?","a":"(i) a vertical straight line (the y-axis)   (ii) x²/(L/2 − r)² + y²/r² = 1, an ellipse","s":"(i) No horizontal external force acts and the centre of mass starts at rest, so its x-coordinate never changes. It falls straight down along the y-axis.\n(ii) Let the rod make angle θ with the vertical. The centre of mass stays at x = 0, so the lower end is at x = (L/2) sinθ.\nA point at distance r from the lower end is at x = (L/2) sinθ − r sinθ = (L/2 − r) sinθ and y = r cosθ.\nUsing sin²θ + cos²θ = 1: x²/(L/2 − r)² + y²/r² = 1.\nThis is an ellipse (a straight line for r = L/2, the centre of mass)."},
{"y":"IIT-JEE 1991","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A block A of mass 2m is placed on another block B of mass 4m which in turn is placed on a fixed table. The two blocks have same length 4d and they are placed as shown in figure. The coefficient of friction (both static and kinetic) between the block B and table is μ. There is no friction between the two blocks. A small object of mass m moving horizontally along a line passing through the centre of mass (COM) of the block B and perpendicular to its face with a speed v collides elastically with the block B at a height d above the table.\n(a) What is the minimum value of v (call it v₀) required to make the block A topple?\n(b) If v = 2v₀, find the distance (from the point P in the figure) at which the mass m falls on the table after collision. (Ignore the role of friction during the collision).","fig":{"w":340,"h":190,"alt":"Block A of mass 2m resting on block B of mass 4m on a table, each 4d long and 2d tall, with a small mass m approaching block B at height d above the table","d":[["l",30,150,320,150],["r",110,10,140,70],["r",110,80,140,70],["t",180,50,"A   2m","m"],["t",180,102,"B   4m","m"],["c",65,115,8],["l",73,115,180,115,"d"],["l",78,106,100,106,"a"],["t",90,100,"v","ms"],["l",100,115,100,150,"b"],["t",94,136,"d","es"],["l",268,80,268,150,"b"],["t",274,119,"2d","s"],["t",110,166,"P","m"],["l",110,178,250,178,"b"],["t",180,172,"4d","m"]]},"a":"(a) v₀ = (5/2)√(6μgd)   (b) 6d√(3μ) from P","s":"Collision (m with 4m, elastic): speed of B after = 2mv/(m + 4m) = 2v/5; m rebounds with speed 3v/5.\nA has no friction with B, so it stays at rest while B slides under it. A topples when its centre of mass passes B's edge, that is when B has moved 2d.\nFriction on B: μ(6m)g, so deceleration = 1.5μg. For B to travel 2d: (2v₀/5)² = 2 × 1.5μg × 2d = 6μgd.\nv₀ = (5/2)√(6μgd).\n(b) For v = 2v₀ = 5√(6μgd), the mass m rebounds with 3v/5 = 3√(6μgd), from height d.\nFall time = √(2d/g). Distance = 3√(6μgd) × √(2d/g) = 3d√(12μ) = 6d√(3μ) from P."},
{"y":"IIT-JEE 1988","tp":"prc","st":"Statements, matching and subjective","q":"A bullet of mass M is fired with a velocity 50 m/s at an angle θ with the horizontal. At the highest point of its trajectory, it collides head-on with a bob of mass 3M suspended by a massless string of length (10/3) metre and gets embedded in the bob. After the collision, the string moves through an angle of 120°. Find\n(i) the angle θ;\n(ii) the vertical and horizontal coordinates of the initial position of the bob with respect to the point of firing of the bullet. Take g = 9.8 m/s².","a":"(i) 37°   (ii) horizontal 122.6 m, vertical 46 m","s":"At the top the bullet's speed is 50 cosθ (horizontal). Collision: M × 50 cosθ = 4M V, so V = 12.5 cosθ.\nThe string turns through 120°, so the bob rises L(1 − cos120°) = 1.5 × 10/3 = 5 m: V² = 2g × 5 = 98, V ≈ 9.9 m/s.\ncosθ = 9.9/12.5 ≈ 0.79, so θ ≈ 37° (cos37° = 0.8).\n(ii) Vertical speed = 50 sin37° = 30 m/s; time to top = 30/9.8 ≈ 3.06 s; height = 30²/(2 × 9.8) ≈ 46 m.\nHorizontal distance = 50 cos37° × 3.06 ≈ 122 m (book: 122.6 m)."},
{"y":"IIT-JEE 1987","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A simple pendulum is suspended from a peg on a vertical wall. The pendulum is pulled away from the wall to a horizontal position (see figure) and released. The ball hits the wall, the co-efficient of restitution being {2;√5}. What is the minimum number of collisions after which the amplitude of oscillations becomes less than 60 degrees?","fig":{"w":340,"h":215,"alt":"A pendulum of length L hanging from a peg on a vertical wall at left, with the ball pulled out to the horizontal position and a dotted arc down to the wall","d":[["l",60,15,60,195],["l",60,30,220,30],["c",220,30,5,"F"],["p","M220 30 A160 160 0 0 1 60 190","d"],["t",140,22,"L","m"],["l",60,15,48,27],["l",60,27,48,39],["l",60,39,48,51],["l",60,51,48,63],["l",60,63,48,75],["l",60,75,48,87],["l",60,87,48,99],["l",60,99,48,111],["l",60,111,48,123],["l",60,123,48,135],["l",60,135,48,147],["l",60,147,48,159],["l",60,159,48,171],["l",60,171,48,183],["l",60,183,48,195]]},"a":"4","s":"The ball is released from the horizontal, so it swings down to the wall at the lowest point with speed √(2gL).\nEach hit multiplies the speed by e, so the height reached after n hits is h = L e^(2n).\nAmplitude < 60° means h < L(1 − cos60°) = L/2.\ne² = 4/5: (4/5)ⁿ < 1/2. For n = 3: 0.512 (not enough). For n = 4: 0.41 (enough).\nMinimum number of collisions = 4."},
{"y":"IIT-JEE 1985","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A ball of mass 100 g is projected vertically upwards from the ground with a velocity of 49 m/sec. At the same time another identical ball is dropped from a height of 98 m to fall freely along the same path as that followed by the first ball. After some time the two balls collide and stick together and finally fall to the ground. Find the time of flight of the masses.","a":"6.53 s","s":"Both balls have the same acceleration, so their relative speed is constant: 49 m/s. They meet when 49t = 98, so t = 2 s.\nAt t = 2 s: first ball v = 49 − 19.6 = 29.4 m/s up; second ball v = 19.6 m/s down; height = 98 − 19.6 = 78.4 m.\nEqual masses stick: V = (29.4 − 19.6)/2 = 4.9 m/s upward.\nFor the combined mass: −78.4 = 4.9t − 4.9t², so t² − t − 16 = 0 and t = (1 + √65)/2 ≈ 4.53 s.\nTotal time = 2 + 4.53 ≈ 6.53 s."},
{"y":"IIT-JEE 1984","tp":"prc","st":"Motion of the centre of mass and collisions","q":"Two bodies A and B of masses m and 2m respectively are placed on a smooth floor. They are connected by a spring. A third body C of mass m moves with velocity v₀ along the line joining A and B as shown in fig and collides elastically with A. At a certain instant of time t₀ after collision, it is found that the instantaneous velocities of A and B are the same. Further at this instant the compression of the spring is found to be x₀. Determine (i) the common velocity of A and B at time t₀ and (ii) the spring constant.","fig":{"w":340,"h":130,"alt":"Body C of mass m moving right with velocity v0 toward body A, which is joined by a spring to the larger body B, all on a smooth floor","d":[["l",20,100,320,100],["r",30,60,50,40,"f"],["t",55,52,"C","m"],["l",82,78,106,78,"a"],["t",94,70,"v₀","ms"],["r",110,60,50,40,"f"],["t",135,52,"A","m"],["p","M160 80 L168 80 L172 70 L180 90 L188 70 L196 90 L204 70 L212 90 L220 80 L230 80"],["r",230,40,60,60,"f"],["t",260,32,"B","m"]]},"a":"(i) v₀/3   (ii) k = 2mv₀²/(3x₀²)","s":"C and A have equal masses and collide elastically, so they exchange velocities: C stops and A moves with v₀.\nWhen A and B have the same velocity V the spring is most compressed. Momentum: m v₀ = (m + 2m)V, so V = v₀/3.\nEnergy: ½mv₀² = ½(3m)(v₀/3)² + ½kx₀².\n½kx₀² = ½mv₀²(1 − 1/3) = mv₀²/3, so k = 2mv₀²/(3x₀²)."},
{"y":"IIT-JEE 1983","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A block of mass M, with a semicircular track of radius R, rests on a horizontal frictionless surface. A uniform cylinder of radius r and mass m is released from rest at the top point A, as shown in figure. The cylinder slips on the semicircular frictionless track. How far has the block moved when the cylinder reaches the bottom (point B) of the track? How fast is the block moving when the cylinder reaches the bottom of the track?","fig":{"w":340,"h":215,"alt":"A block of mass M with a semicircular track of radius R cut in its top, on a frictionless floor; a cylinder of radius r and mass m sits at the top left end A of the track and B is the lowest point","d":[["l",30,190,320,190],["p","M50 60 L100 60 A70 70 0 0 0 240 60 L290 60 L290 190 L50 190 Z"],["l",100,60,240,60,"d"],["c",118,60,18],["l",118,60,127,44],["t",129,54,"r","s"],["t",90,52,"A","e"],["c",170,130,3,"F"],["t",170,152,"B","m"],["l",170,60,219,109,"a"],["t",200,84,"R"],["t",118,90,"m","m"],["t",262,100,"M","m"]]},"a":"x = m(R − r)/(M + m);  v = m√(2g(R − r)/(M(M + m)))","s":"No horizontal external force: the centre of mass of cylinder + block stays fixed horizontally.\nThe cylinder's centre moves a horizontal distance (R − r) relative to the block, and the block moves x the other way: M x = m(R − r − x).\nSo x = m(R − r)/(M + m).\nAt B (no friction, no rotation): momentum m v₁ = M v₂ and energy mg(R − r) = ½mv₁² + ½Mv₂².\nSubstituting v₁ = Mv₂/m: ½Mv₂²(M + m)/m = mg(R − r), so v₂ = m√(2g(R − r)/(M(M + m)))."},
{"y":"IIT-JEE 1982","tp":"prc","st":"Centre of mass of systems","q":"Three particles A, B and C of equal mass move with equal speed v along the medians of an equilateral triangle as shown in figure. They collide at the centroid of the triangle. After the collision, A comes to rest, B retraces its path with the speed v. What is the velocity of C?","fig":{"w":340,"h":190,"alt":"Equilateral triangle ABC with centroid G; particles A, B and C move toward G along the medians","d":[["p","M170 21 L90 160 L250 160 Z"],["l",170,21,170,114],["l",90,160,170,114],["l",250,160,170,114],["l",170,48,170,88,"a"],["l",116,145,148,127,"a"],["l",224,145,192,127,"a"],["t",170,14,"A","m"],["t",82,174,"B","m"],["t",258,174,"C","m"],["t",178,130,"G","s"]]},"a":"v (same speed as before), directed along the original direction of motion of B, that is from B towards G","s":"The three initial velocities have equal size and are 120° apart, so the total momentum is zero.\nMomentum is conserved, so it is zero after the collision as well.\nAfter the collision: A is at rest (momentum 0) and B moves back with velocity equal and opposite to its initial velocity.\nSo C must cancel B: m v⃗_C + m(−v⃗_B,initial) = 0, giving v⃗_C = v⃗_B,initial.\nC moves with speed v, parallel to the original direction of B's motion (from B towards G)."},
{"y":"IIT-JEE 1981","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A body of mass 1 kg, initially at rest, explodes and breaks into three fragments of masses in the ratio 1 : 1 : 3. The two pieces of equal masses fly off perpendicular to each other with a speed of 30 m/sec each. What is the velocity of the heavier fragment?","a":"10√2 m/s","s":"Masses of the fragments: 0.2 kg, 0.2 kg and 0.6 kg.\nThe body starts at rest, so the total momentum after the explosion is zero.\nThe two light pieces are perpendicular: resultant momentum = 0.2 × 30 × √2 = 6√2 kg m/s.\nThe heavy piece must have equal and opposite momentum: 0.6 v = 6√2.\nv = 10√2 m/s (about 14.1 m/s), opposite to the resultant of the two light pieces."},
{"y":"IIT-JEE 1980","tp":"prc","st":"Centre of mass of bodies and cut-outs","q":"A circular plate of uniform thickness has a diameter of 56 cm. A circular portion of diameter 42 cm is removed from one edge of the plate as shown in the figure. Find the position of the centre of mass of the remaining portion.","fig":{"w":340,"h":230,"alt":"A circular plate of diameter 56 cm with a circular part of diameter 42 cm removed from its right edge, with the two diameters marked below","d":[["c",150,95,84],["c",171,95,63],["t",171,99,"removed","ms"],["l",66,95,66,210,"d"],["l",108,95,108,198,"d"],["l",234,95,234,210,"d"],["l",108,184,234,184,"b"],["t",171,180,"42 cm","m"],["l",66,206,234,206,"b"],["t",150,222,"56 cm","m"]]},"a":"9 cm from the centre of the plate, on the side opposite to the removed part","s":"Radii: plate 28 cm, removed disc 21 cm. The removed disc touches the edge, so its centre is 28 − 21 = 7 cm from the plate centre.\nMass is proportional to area, so ∝ r²: plate 28² = 784, removed disc 21² = 441.\nTreat the removed part as negative mass: x_cm = (784 × 0 − 441 × 7)/(784 − 441) = −3087/343 = −9 cm.\nThe centre of mass of the remaining part is 9 cm from the centre of the plate, away from the hole."},
{"y":"IIT-JEE 1979","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A 20 g bullet pierces through a plate of mass M₁ = 1 kg and then comes to rest inside a second plate of mass M₂ = 2.98 kg as shown in figure. It is found that the two plates initially at rest, now move with equal velocities. Find the percentage loss in the initial velocity of the bullet when it is between M₁ and M₂. Neglect any loss of material of the plates due to the action of bullet.","fig":{"w":340,"h":185,"alt":"A bullet moving right passes through plate M1 and is about to embed in plate M2; both plates move to the right","d":[["r",95,40,30,110],["r",225,40,30,110],["l",95,28,125,28,"a"],["l",225,28,255,28,"a"],["l",30,95,222,95,"da"],["c",230,95,6,"F"],["t",110,168,"M₁","m"],["t",240,168,"M₂","m"]]},"a":"25%","s":"Let the bullet's initial speed be u and the common final speed of both plates be V.\nTotal momentum: 0.02u = 1 × V + (2.98 + 0.02)V = 4V, so V = u/200.\nWhen the bullet is between the plates, M₁ already moves at V = u/200 and M₂ is still at rest.\nMomentum then: 0.02u = 0.02u' + 1 × (u/200), so 0.02u' = 0.02u − 0.005u and u' = 0.75u.\nLoss in the bullet's velocity = 25%."},
{"y":"IIT-JEE 1979","tp":"prc","st":"Statements, matching and subjective","q":"When a ball is thrown up, the magnitude of its momentum decreases and then increases. Does this violate the conservation of momentum principle?","a":"No","s":"Momentum of a system is conserved only when no external force acts on it.\nThe ball alone is acted on by gravity (the pull of the Earth), an external force, so its momentum changes.\nThe ball also pulls the Earth with an equal and opposite force, so the Earth's momentum changes by the opposite amount.\nFor the system ball + Earth, the total momentum stays constant, so the principle is not violated."},
{"y":"IIT-JEE 1978","tp":"prc","st":"Statements, matching and subjective","q":"A body of mass m moving with a velocity v in the x-direction collides with another body of mass M moving in the y-direction with a velocity V. They coalesce into one body during collision. Find\n(a) the direction and magnitude of the momentum of the composite body.\n(b) the fraction of the initial kinetic energy transformed into heat during the collision.","a":"(a) p = √(m²v² + M²V²), at angle tan⁻¹(MV/mv) from the x-axis   (b) mM(v² + V²) / [(m + M)(mv² + MV²)]","s":"(a) Momentum is conserved along each axis: pₓ = mv and p_y = MV.\nMagnitude p = √(m²v² + M²V²), direction tanφ = MV/(mv) from the x-axis.\n(b) Initial KE = ½mv² + ½MV². Final KE = p²/(2(m + M)) = (m²v² + M²V²)/(2(m + M)).\nHeat = initial − final. Combine over 2(m + M): numerator = (m + M)(mv² + MV²) − (m²v² + M²V²) = mM(v² + V²).\nFraction = mM(v² + V²) / [(m + M)(mv² + MV²)]."},
{"y":"IIT-JEE 1989","tp":"prc","st":"Statements, matching and subjective","q":"Two particles of mass 1 kg and 3 kg move towards each other under their mutual force of attraction. No other force acts on them. When the relative velocity of approach of the two particles is 2 m/s, their centre of mass has a velocity of 0.5 m/s. When the relative velocity of approach becomes 3 m/s, the velocity of the centre of mass is 0.75 m/s.","o":["True","False"],"c":1,"s":"Only the internal force of attraction acts on the two particles.\nWith no external force, the velocity of the centre of mass cannot change.\nIt stays at 0.5 m/s whatever the relative speed of approach, so it cannot become 0.75 m/s.\nThe statement is false."},
{"y":"IIT-JEE 1987","tp":"prc","st":"Motion of the centre of mass and collisions","q":"A particle of mass 4m which is at rest explodes into three fragments. Two of the fragments each of mass m are found to move with a speed v each in mutually perpendicular directions. The total energy released in the process of explosion is ______.","a":"(3/2) m v²","s":"The third fragment has mass 4m − 2m = 2m.\nMomentum conservation: the two perpendicular pieces give a resultant mv√2, so 2m × v₃ = √2 mv and v₃ = v/√2.\nEnergy released = total KE = ½mv² + ½mv² + ½(2m)(v²/2) = mv² + mv²/2.\nEnergy = (3/2) m v²."},
{"y":"JEE Main 2025 · 2 Apr · Shift 1","tp":"prt","st":"Equilibrium of rigid bodies","q":"A square Lamina OABC of length 10 cm is pivoted at 'O'. Forces act on Lamina as shown in figure. If lamina remains stationary, then the magnitude of F is","fig":{"w":340,"h":225,"alt":"Square lamina OABC of side 10 cm pivoted at O (bottom left). Forces: F to the left and 10 N up at C (top left); 10 N up and 10 N to the right at B (top right); 10 N to the right and 10 N down at A (bottom right)","d":[["r",80,50,120,120],["c",80,170,3,"F"],["l",80,50,80,15,"a"],["t",88,24,"10 N","s"],["l",80,50,45,50,"a"],["t",40,54,"F","e"],["l",200,50,200,15,"a"],["t",206,24,"10 N","s"],["l",200,50,245,50,"a"],["t",250,54,"10 N","s"],["l",200,170,245,170,"a"],["t",250,174,"10 N","s"],["l",200,170,200,205,"a"],["t",206,215,"10 N","s"],["t",86,66,"C"],["t",194,66,"B","e"],["t",194,164,"A","e"],["t",74,186,"O","e"],["t",208,115,"10 cm","s"]]},"o":["10√2 N","20 N","10 N","0 (zero)"],"c":2,"s":"Take torques about the pivot O. Side = 10 cm. Anticlockwise is positive.\nF at C pulls left (C is 10 cm above O): torque = +10F (N·cm). The 10 N up at C has zero arm.\nAt B: 10 N up gives +100 and 10 N right gives −100, so they cancel.\nAt A: 10 N right has zero arm; 10 N down gives −100.\nEquilibrium: 10F − 100 = 0, so F = 10 N."},
{"y":"JEE Main 2025 · 4 Apr · Shift 1","tp":"prt","st":"Torque and its direction","q":"Which of the following are correct expression for torque acting on a body?\nA. τ⃗ = r⃗ × L⃗\nB. τ⃗ = {d;dt}(r⃗ × p⃗)\nC. τ⃗ = r⃗ × {dp⃗;dt}\nD. τ⃗ = I α⃗\nE. τ⃗ = r⃗ × F⃗\n(r⃗ = position vector; p⃗ = linear momentum; L⃗ = angular momentum; α⃗ = angular acceleration; I = moment of inertia; F⃗ = force; t = time)\nChoose the correct answer from the options given below.","o":["B, C, D and E Only","A, B, D and E Only","C and D Only","B, D and E Only"],"c":0,"s":"Torque is r × F = r × dp/dt, so C and E are correct.\nAlso L = r × p and τ = dL/dt = d(r × p)/dt, so B is correct.\nFor a rigid body about a fixed axis τ = Iα, so D is correct.\nA is wrong: r × L has no meaning as torque (torque is the rate of change of L, not r × L).\nCorrect: B, C, D and E."},
{"y":"JEE Main 2025 · 22 Jan · Shift 2","tp":"prt","st":"Torque and its direction","q":"The torque due to the force (2î + ĵ + 2k̂) about the origin, acting on a particle whose position vector is (î + ĵ + k̂), would be","o":["î − ĵ + k̂","ĵ + k̂","î − k̂","î + k̂"],"c":2,"s":"τ = r × F with r = (1, 1, 1) and F = (2, 1, 2).\nx-component: (1)(2) − (1)(1) = 1.\ny-component: −[(1)(2) − (1)(2)] = 0.\nz-component: (1)(1) − (1)(2) = −1.\nτ = î − k̂."},
{"y":"JEE Main 2025 · 28 Jan · Shift 2","tp":"prt","st":"Equilibrium of rigid bodies","q":"A uniform rod of mass 250 g having length 100 cm is balanced on a sharp edge at 40 cm mark. A mass of 400 g is suspended at 10 cm mark. To maintain the balance of the rod, the mass to be suspended at 90 cm mark, is","o":["290 g","200 g","300 g","190 g"],"c":3,"s":"Take torques about the pivot at the 40 cm mark.\nThe rod's weight acts at 50 cm: arm 10 cm to the right, 250 g gives 250 × 10 = 2500.\nThe 400 g at 10 cm: arm 30 cm to the left, gives 400 × 30 = 12000.\nThe unknown m at 90 cm: arm 50 cm to the right, gives 50m.\nBalance: 50m + 2500 = 12000, so m = 190 g."},
{"y":"JEE Main 2024 · 9 Apr · Shift 1","tp":"prt","st":"Ladder, beams and hinges","q":"A heavy iron bar of weight W is having its one end on the ground and the other on the shoulder of a person. The bar makes an angle θ with the horizontal. The weight experienced by the person is","o":["{W;2}","W sinθ","W","W cosθ"],"c":0,"s":"The weight W acts at the middle of the uniform bar. The ground end and the shoulder end carry vertical forces.\nTorque about the ground end: N × (L cosθ) = W × ({L;2} cosθ).\nThe cosθ cancels, so N = W/2.\nThe person feels W/2, whatever the angle."},
{"y":"JEE Main 2024 · 27 Jan · Shift 2","tp":"prt","st":"Ladder, beams and hinges","q":"A heavy iron bar of weight 12 kg is having its one end on the ground and the other on the shoulder of a man. The rod makes an angle 60° with the horizontal, the weight experienced by the man is","o":["12 kg","6√3 kg","3 kg","6 kg"],"c":3,"s":"The weight acts at the centre of the uniform rod. Take torques about the ground end.\nN × (L cos60°) = 12 × ({L;2} cos60°).\nThe angle cancels, so N = 12/2 = 6 kg."},
{"y":"JEE Main 2022 · 29 Jul · Shift 2","tp":"prt","st":"Torque and its direction","q":"The torque of a force 5î + 3ĵ − 7k̂ about the origin is τ. If the force acts on a particle whose position vector is 2î + 2ĵ + k̂, then the value of τ will be","o":["11î + 19ĵ − 4k̂","−11î + 9ĵ − 16k̂","−17î + 19ĵ − 4k̂","17î + 9ĵ + 16k̂"],"c":2,"s":"τ = r × F with r = (2, 2, 1) and F = (5, 3, −7).\nx: (2)(−7) − (1)(3) = −17.\ny: −[(2)(−7) − (1)(5)] = +19.\nz: (2)(3) − (2)(5) = −4.\nτ = −17î + 19ĵ − 4k̂."},
{"y":"JEE Main 2022 · 25 Jun · Shift 1","tp":"prt","st":"Torque and its direction","q":"If force F⃗ = 3î + 4ĵ − 2k̂ acts on a particle having position vector 2î + ĵ + 2k̂ then, the torque about the origin will be","o":["3î + 4ĵ − 2k̂","−10î + 10ĵ + 5k̂","10î + 5ĵ − 10k̂","10î + ĵ − 5k̂"],"c":1,"s":"τ = r × F with r = (2, 1, 2) and F = (3, 4, −2).\nx: (1)(−2) − (2)(4) = −10.\ny: −[(2)(−2) − (2)(3)] = +10.\nz: (2)(4) − (1)(3) = 5.\nτ = −10î + 10ĵ + 5k̂."},
{"y":"JEE Main 2021 · 17 Mar · Shift 1","tp":"prt","st":"Torque and its direction","q":"A triangular plate is shown. A force F⃗ = 4î − 3ĵ is applied at point P. The torque at point P with respect to point O and Q are","fig":{"w":340,"h":235,"alt":"Triangle OPQ with O at the origin, Q on the x-axis 10 cm from O, sides OP and PQ both 10 cm and both base angles 60 degrees; force F acts at the apex P","d":[["l",40,200,40,10,"a"],["l",40,200,310,200,"a"],["l",40,200,140,27],["l",140,27,240,200],["t",30,14,"Y","e"],["t",314,204,"X"],["t",132,20,"P","e"],["t",246,216,"Q"],["t",30,216,"O","e"],["t",58,120,"10 cm","s"],["t",192,120,"10 cm","s"],["t",62,192,"60°","s"],["t",200,192,"60°","s"],["l",40,224,240,224,"b"],["t",140,220,"10 cm","ms"],["l",140,27,168,48,"a"],["t",172,44,"F⃗"]]},"o":["−15 + 20√3, 15 + 20√3","−15 − 20√3, 15 − 20√3","15 + 20√3, 15 − 20√3","15 − 20√3, 15 + 20√3"],"c":1,"s":"The triangle is equilateral with side 10 cm. P = (5, 5√3) cm, Q = (10, 0).\nAbout O: r = (5, 5√3), τ = xF_y − yF_x = 5(−3) − 5√3(4) = −15 − 20√3.\nAbout Q: r = P − Q = (−5, 5√3), τ = (−5)(−3) − 5√3(4) = 15 − 20√3.\nAnswer: (−15 − 20√3, 15 − 20√3)."},
{"y":"JEE Main 2020 · 3 Sep · Shift 1","tp":"pra","st":"Conservation of angular momentum","q":"A block of mass m = 1 kg slides with velocity v = 6 m/s on a frictionless horizontal surface and collides with a uniform vertical rod and sticks to it as shown. The rod is pivoted about O and swings as a result of the collision making angle θ before momentarily coming to rest. If the rod has mass M = 2 kg and length l = 1 m, the value of θ is approximately (take g = 10 m/s²)","fig":{"w":340,"h":215,"alt":"A block of mass m sliding right with speed v on a frictionless floor toward the lower end of a vertical rod of mass M and length l pivoted at O at the top; the rod swings out to angle θ with the vertical carrying the block","d":[["l",20,190,320,190],["l",150,25,150,190,"d"],["l",150,25,248,142,"B"],["c",248,142,7,"F"],["t",260,148,"m","s"],["r",40,150,36,40,"f"],["t",58,174,"m","m"],["l",80,170,115,170,"a"],["t",98,164,"v","m"],["r",138,166,24,24,"d"],["c",150,25,3,"F"],["t",142,22,"O","e"],["t",160,20,"M, l","s"],["p","M150 85 A60 60 0 0 0 188.6 71"],["t",162,98,"θ","s"]]},"o":["63°","55°","69°","49°"],"c":0,"s":"The pivot force is impulsive, so angular momentum about O is conserved in the collision: m v l = I ω.\nI = Ml²/3 + ml² = 2/3 + 1 = 5/3 kg m², so ω = 6/(5/3) = 3.6 rad/s.\nKE just after = ½ × (5/3) × 3.6² = 10.8 J.\nTo reach angle θ the rod's centre rises (l/2)(1 − cosθ) and the block rises l(1 − cosθ): PE gain = (Mg/2 + mg) l(1 − cosθ) = 20(1 − cosθ).\n20(1 − cosθ) = 10.8, so cosθ = 0.46 and θ ≈ 63°."},
{"y":"JEE Main 2019 · 10 Apr · Shift 1","tp":"prt","st":"Torque and its direction","q":"A particle of mass m is moving along a trajectory given by x = x₀ + a cos ω₁t ; y = y₀ + b sin ω₂t\nThe torque, acting on the particle about the origin, at t = 0 is","o":["m(−x₀b + y₀a)ω₁² k̂","−m(x₀bω₂² − y₀aω₁²) k̂","+m y₀ a ω₁² k̂","Zero"],"c":2,"s":"Torque about the origin: τ = m(x·aᵧ − y·aₓ) k̂.\nAt t = 0: x = x₀ + a, y = y₀.\naₓ = −aω₁² cos ω₁t = −aω₁², aᵧ = −bω₂² sin ω₂t = 0.\nτ = m[(x₀+a)(0) − y₀(−aω₁²)] k̂ = m y₀ a ω₁² k̂.\nAnswer: (c)."},
{"y":"JEE Main 2019 · 9 Jan · Shift 1","tp":"prt","st":"Equilibrium of rigid bodies","q":"An L-shaped object, made of thin rods of uniform mass density, is suspended with a string as shown in figure. If AB = BC, and the angle made by AB with downward vertical is θ, then","fig":{"w":340,"h":180,"alt":"L-shaped rod ABC hung from a string at A, with AB making angle θ with the downward vertical and a right angle at B","d":[["l",215,12,265,12,"B"],["l",240,12,240,20],["l",240,20,205,124,"B"],["l",205,124,309,159,"B"],["l",240,20,240,150,"d"],["t",248,24,"A"],["t",196,132,"B","e"],["t",313,170,"C"],["t",246,66,"θ"],["t",210,146,"90°","s"]]},"o":["tanθ = {2;√3}","tanθ = {1;2}","tanθ = {1;2√3}","tanθ = {1;3}"],"c":3,"s":"In equilibrium the centre of mass lies on the vertical line through the suspension point A.\nLet AB = BC = 2 units. Mid-point of AB: (−sinθ, −cosθ) from A. Mid-point of BC: (−2sinθ + cosθ, −2cosθ − sinθ).\nBoth rods have equal mass, so x(cm) = ½(−3 sinθ + cosθ) = 0.\nSo tanθ = 1/3.\nAnswer: (d)."},
{"y":"JEE Main 2019 · 10 Jan · Shift 1","tp":"prt","st":"Torque and its direction","q":"To mop-clean a floor, a cleaning machine presses a circular mop of radius R vertically down with a total force F and rotates it with a constant angular speed about its axis. If the force F is distributed uniformly over the mop and if coefficient of friction between the mop and the floor is μ, the torque, applied by the machine on the mop is","o":["{μFR;2}","{μFR;6}","{μFR;3}","{2;3}μFR"],"c":3,"s":"Pressure on the mop = F/(πR²).\nTake a ring of radius r and width dr: normal force = (F/πR²)(2πr dr), friction = μ times this.\nTorque of the ring = r × friction = (2μF/R²) r² dr.\nTotal torque = (2μF/R²)(R³/3) = (2/3) μFR.\nAnswer: (d)."},
{"y":"JEE Main 2019 · 11 Jan · Shift 1","tp":"prt","st":"Torque and its direction","q":"A slab is subjected to two forces F⃗₁ and F⃗₂ of same magnitude F as shown in the figure. Force F⃗₂ is in xy-plane while force F⃗₁ acts along z-axis at the point (2î + 3ĵ). The moment of these forces about point O will be","fig":{"w":340,"h":200,"alt":"Slab in the xy-plane, 6 m along y and 4 m along x, with F1 up along z at a point on the slab and F2 at the far corner of the y-axis at 30 degrees to the y-axis","d":[["l",110,50,110,12,"a"],["t",116,16,"z"],["l",110,50,330,50,"a"],["t",322,44,"y"],["l",110,50,35,160,"a"],["t",24,168,"x"],["p","M110 50 H270 L210 140 H50 Z"],["t",104,44,"O","e"],["c",160,95,2.5,"F"],["l",160,95,160,52,"a"],["t",166,62,"F₁"],["l",270,50,305,30,"a"],["t",300,22,"F₂"],["t",296,62,"30°","s"],["t",252,112,"4 m","s"],["t",130,158,"6 m","m"]]},"o":["(3î − 2ĵ − 3k̂)F","(3î + 2ĵ + 3k̂)F","(3î − 2ĵ + 3k̂)F","(3î + 2ĵ − 3k̂)F"],"c":2,"s":"Torque of F⃗₁ = (2î + 3ĵ) × Fk̂ = F(2(−ĵ) + 3î) = F(3î − 2ĵ).\nF⃗₂ acts at the corner (0, 6 m) on the y-axis, in the xy-plane, tilted 30° from the y-axis (away from the viewer). Its x-component is −F/2.\nThe z-torque of F⃗₂ = x·Fᵧ − y·Fₓ = 0 − 6(−F/2) = 3F, along k̂.\nTotal = (3î − 2ĵ + 3k̂)F.\nAnswer: (c)."},
{"y":"JEE Main 2019 · 11 Jan · Shift 2","tp":"prt","st":"Torque and its direction","q":"The magnitude of torque on a particle of mass 1 kg is 2.5 N m about the origin. If the force acting on it is 1 N, and the distance of the particle from the origin is 5 m, the angle between the force and the position vector is (in radians)","o":["{π;3}","{π;8}","{π;4}","{π;6}"],"c":3,"s":"τ = rF sinθ.\n2.5 = 5 × 1 × sinθ, so sinθ = 1/2.\nθ = π/6.\nAnswer: (d)."},
{"y":"JEE Main 2018 · Online","tp":"prt","st":"Torque and its direction","q":"A force of 40 N acts on a point B at the end of an L-shaped object, as shown in the figure. The angle θ that will produce maximum moment of the force about point A is given by","fig":{"w":340,"h":215,"alt":"L-shaped object with a 4 m vertical arm ending at A and a 2 m horizontal arm ending at B, where a 40 N force acts at angle θ above the horizontal","d":[["p","M90 20 H110 V140 H165 V160 H90 Z"],["t",116,28,"A"],["l",65,20,65,150,"b"],["t",58,90,"4 m","e"],["l",100,188,165,188,"b"],["t",132,204,"2 m","m"],["l",165,150,225,150,"d"],["l",165,150,215,112,"a"],["t",220,106,"F"],["t",206,146,"θ","s"],["t",160,172,"B","e"]]},"o":["tanθ = {1;2}","tanθ = 4","tanθ = 2","tanθ = {1;4}"],"c":0,"s":"Take A as origin. B is 2 m to the right and 4 m below A: r = (2, −4).\nForce at angle θ above the horizontal: F = 40(cosθ, sinθ).\nτ = x·Fᵧ − y·Fₓ = 80 sinθ + 160 cosθ.\nThis is maximum when dτ/dθ = 0: 80 cosθ − 160 sinθ = 0, so tanθ = 1/2.\nAnswer: (a)."},
{"y":"JEE Main 2018 · Online","tp":"prt","st":"Equilibrium of rigid bodies","q":"A uniform rod AB is suspended from a point X, at a variable distance x from A, as shown. To make the rod horizontal, a mass m is suspended from its end A. A set of (m, x) values is recorded. The appropriate variables that give a straight line, when plotted, are","fig":{"w":340,"h":170,"alt":"Horizontal rod AB hung from a ceiling string at X, distance x from end A, with a mass m hanging from A","d":[["l",150,10,210,10],["l",160,10,155,4],["l",180,10,175,4],["l",200,10,195,4],["l",180,10,180,70],["r",60,70,240,8,"f"],["t",54,62,"A","e"],["t",186,64,"X"],["t",296,62,"B"],["l",60,78,60,128],["c",60,138,10,"F"],["t",76,142,"m"],["l",60,104,180,104,"b"],["t",120,100,"x","m"]]},"o":["m, {1;x²}","m, x²","m, x","m, {1;x}"],"c":3,"s":"Let the rod have mass M and length L; its centre is at L/2 from A.\nTorque balance about X: m g x = M g (L/2 − x).\nSo x(m + M) = ML/2, which gives 1/x = 2(m + M)/(ML) = 2/L + 2m/(ML).\nThis is linear in m: 1/x versus m is a straight line.\nAnswer: (d)."},
{"y":"JEE Main 2017 · Online","tp":"prt","st":"Equilibrium of rigid bodies","q":"In a physical balance working on the principle of moments, when 5 mg weight is placed on the left pan, the beam becomes horizontal. Both the empty pans of the balance are of equal mass. Which of the following statements is correct?","o":["Left arm is shorter than the right arm.","Left arm is longer than the right arm.","Every object that is weighed using this balance appears lighter than its actual weight","Both the arms are of same length"],"c":0,"s":"Let each pan have weight p, left arm l₁ and right arm l₂.\nThe beam is horizontal with 5 mg on the left pan only, so torques balance: (p + 5 mg) l₁ = p l₂.\nTherefore l₂ > l₁: the left arm is shorter than the right arm.\nAnswer: (a)."},
{"y":"JEE Advanced 2016","tp":"prt","st":"Ladder, beams and hinges","q":"A uniform wooden stick of mass 1.6 kg and length l rests in an inclined manner on a smooth, vertical wall of height h(< l) such that a small portion of the stick extends beyond the wall. The reaction force of the wall on the stick is perpendicular to the stick. The stick makes an angle of 30° with the wall and the bottom of the stick is on a rough floor. The reaction of the wall on the stick is equal in magnitude to the reaction of the floor on the stick. The ratio h/l and the frictional force f at the bottom of the stick are (g = 10 m s⁻²)","o":["{h;l} = {√3;16}, f = {16√3;3} N","{h;l} = {3;16}, f = {16√3;3} N","{h;l} = {3√3;16}, f = {8√3;3} N","{h;l} = {3√3;16}, f = {16√3;3} N"],"c":3,"s":"Weight = 16 N. The wall reaction N is perpendicular to the stick, so it makes 30° with the horizontal: horizontal part N cos30°, vertical part N sin30°. Floor reaction R = N.\nVertical: R + N sin30° = 16, so 1.5N = 16 and N = 32/3 N.\nHorizontal: f = N cos30° = (32/3)(√3/2) = 16√3/3 N.\nTorque about the bottom: N·d = 16·(l/2) sin30°, where d is the length along the stick up to the wall contact. So d = 3l/8.\nh = d cos30° = (3l/8)(√3/2) = 3√3 l/16.\nAnswer: (d)."},
{"y":"AIEEE 2006","tp":"prt","st":"Torque and its direction","q":"A force of −Fk̂ acts on O, the origin of the coordinate system. The torque about the point (1, −1) is","fig":{"w":200,"h":120,"alt":"Right-handed axes: z up, y to the right, x toward the viewer, with origin O","d":[["l",80,70,80,15,"a"],["t",86,18,"z"],["l",80,70,170,70,"a"],["t",166,64,"y"],["l",80,70,40,105,"a"],["t",30,112,"x"],["t",72,84,"O","e"]]},"o":["−F(î − ĵ)","F(î − ĵ)","−F(î + ĵ)","F(î + ĵ)"],"c":2,"s":"Torque = r × F, where r is the vector from the reference point (1, −1) to the point where the force acts (the origin).\nr = (0 − 1)î + (0 + 1)ĵ = −î + ĵ.\nτ = (−î + ĵ) × (−Fk̂) = F(î×k̂) − F(ĵ×k̂) = −Fĵ − Fî.\nτ = −F(î + ĵ).\nAnswer: (c). (The printed key says (d), which has the opposite sign.)"},
{"y":"AIEEE 2003","tp":"prt","st":"Torque and its direction","q":"Let F⃗ be the force acting on a particle having position vector r⃗ and τ⃗ be the torque of this force about the origin. Then","o":["r⃗·τ⃗ = 0 and F⃗·τ⃗ ≠ 0","r⃗·τ⃗ ≠ 0 and F⃗·τ⃗ = 0","r⃗·τ⃗ ≠ 0 and F⃗·τ⃗ ≠ 0","r⃗·τ⃗ = 0 and F⃗·τ⃗ = 0"],"c":3,"s":"τ⃗ = r⃗ × F⃗.\nThe cross product is perpendicular to both r⃗ and F⃗.\nSo r⃗·τ⃗ = 0 and F⃗·τ⃗ = 0.\nAnswer: (d)."},
{"y":"JEE Advanced 2021","tp":"prt","st":"Ladder, beams and hinges","q":"One end of a horizontal uniform beam of weight W and length L is hinged on a vertical wall at point O and its other end is supported by a light inextensible rope. The other end of the rope is fixed at point Q, at a height L above the hinge at point O. A block of weight αW is attached at the point P of the beam, as shown in the figure (not to scale). The rope can sustain a maximum tension of (2√2)W.\nWhich of the following statement(s) is(are) correct?","fig":{"w":340,"h":190,"alt":"Horizontal beam OP hinged to a vertical wall at O, a rope from P to Q on the wall a height L above O, and a block of weight alpha W hanging at P","d":[["r",52,20,8,160,"f"],["t",48,24,"Q","e"],["t",48,146,"O","e"],["l",35,20,35,140,"b"],["t",30,84,"L","e"],["r",60,137,120,6,"f"],["l",60,20,180,140],["t",120,130,"W","m"],["t",120,160,"L","m"],["t",188,134,"P"],["l",180,143,180,150],["r",170,150,20,24,"F"],["t",196,166,"αW"]]},"o":["The vertical component of reaction force at O does not depend on α.","The horizontal component of reaction force at O is equal to W for α = 0.5.","The tension in the rope is 2W for α = 0.5.","The rope breaks if α > 1.5."],"c":[0,1,3],"s":"The rope PQ makes 45° with the beam (OQ = OP = L).\nTorque about O: T sin45°·L = W(L/2) + αW·L, so T = √2 W(½ + α).\nHorizontal reaction = T cos45° = W(½ + α). For α = 0.5 this is W, so (b) is true.\nVertical: V + T sin45° = W + αW, so V = W/2, independent of α, so (a) is true.\nFor α = 0.5, T = √2 W, not 2W, so (c) is false.\nT > 2√2 W when ½ + α > 2, that is α > 1.5, so (d) is true.\nAnswer: (a), (b), (d)."},
{"y":"JEE Advanced 2021","tp":"pra","st":"Angular momentum of particles and bodies","q":"A particle of mass M = 0.2 kg is initially at rest in the xy-plane at a point (x = −l, y = −h), where l = 10 m and h = 1 m. The particle is accelerated at time t = 0 with a constant acceleration a = 10 m s⁻² along the positive x-direction. Its angular momentum and torque with respect to the origin, in SI units, are represented by L⃗ and τ⃗, respectively. î, ĵ and k̂ are unit vectors along the positive x, y and z-directions. If k̂ = î × ĵ then which of the following statement(s) is(are) correct?","o":["The particle arrives at the point (x = l, y = −h) at time t = 2 s.","τ⃗ = 2k̂ when the particle passes through the point (x = l, y = −h).","L⃗ = 4k̂ when the particle passes through the point (x = l, y = −h).","τ⃗ = k̂ when the particle passes through the point (x = 0, y = −h)."],"c":[0,1,2],"s":"Distance to x = l is 2l = 20 m: 20 = ½(10)t², so t = 2 s. (a) true.\nForce F = Ma = 2 N along x. Torque τ = x·Fᵧ − y·Fₓ = 0 − (−1)(2) = 2 k̂ N m at x = l (and also at x = 0, since it depends only on y). (b) true, (d) false.\nAt x = l: v = at = 20 m/s, p = 0.2 × 20 = 4 kg m/s.\nL = x·pᵧ − y·pₓ = −(−1)(4) = 4 k̂. (c) true.\nAnswer: (a), (b), (c)."},
{"y":"JEE Advanced 2021","tp":"prr","st":"Rolling bodies with forces and plates","q":"A horizontal force F is applied at the center of mass of a cylindrical object of mass m and radius R, perpendicular to its axis as shown in the figure. The coefficient of friction between the object and the ground is μ. The center of mass of the object has an acceleration a. The acceleration due to gravity is g. Given that the object rolls without slipping, which of the following statement(s) is(are) correct?","fig":{"w":340,"h":170,"alt":"Cylinder resting on the ground with a horizontal force F applied at its centre, pointing right","d":[["c",150,90,50],["c",150,90,2,"F"],["l",150,90,250,90,"a"],["t",256,86,"F"],["l",150,90,185,125,"d"],["t",172,104,"R","s"],["l",60,140,290,140]]},"o":["For the same F, the value of a does not depend on whether the cylinder is solid or hollow.","For a solid cylinder, the maximum possible value of a is 2μg.","The magnitude of the frictional force on the object due to the ground is always μmg.","For a thin-walled hollow cylinder, a = F/2m."],"c":[1,3],"s":"Let I = kmR². Rolling: F − f = ma and fR = I(a/R), so f = kma.\nThen a = F/(m(1 + k)), which depends on k, so (a) is false.\nSolid cylinder (k = ½): f = F/3 ≤ μmg, so F ≤ 3μmg and a = 2F/3m ≤ 2μg. (b) true.\nFriction f = kma is not always μmg (only at the limit), so (c) is false.\nThin hollow cylinder (k = 1): a = F/2m. (d) true.\nAnswer: (b), (d)."},
{"y":"JEE Advanced 2019","tp":"prd","st":"Torque and angular acceleration","q":"A thin and uniform rod of mass M and length L is held vertical on a floor with large friction. The rod is released from rest so that it falls by rotating about its contact-point with the floor without slipping. Which of the following statement(s) is/are correct, when the rod makes an angle 60° with vertical?\n[g is the acceleration due to gravity]","o":["The angular acceleration of the rod will be {2g;L}.","The normal reaction force from the floor on the rod will be {Mg;16}.","The radial acceleration of the rod’s center of mass will be {3g;4}.","The angular speed of the rod will be √{3g;2L}."],"c":[1,2,3],"s":"About the contact point I = ML²/3. Torque = Mg(L/2) sinθ, so α = (3g/2L) sinθ = 3√3g/4L at 60°. (a) is false.\nEnergy: ½Iω² = Mg(L/2)(1 − cos60°), so ω² = 3g/2L and ω = √(3g/2L). (d) true.\nRadial acceleration of centre = ω²(L/2) = 3g/4. (c) true.\nTangential acceleration = α(L/2) = 3√3g/8. Vertical downward acceleration of centre = (3g/4)cos60° + (3√3g/8)sin60° = 3g/8 + 9g/16 = 15g/16.\nMg − N = M(15g/16), so N = Mg/16. (b) true.\nAnswer: (b), (c), (d)."},
{"y":"JEE Advanced 2018","tp":"prt","st":"Torque and its direction","q":"Consider a body of mass 1.0 kg at rest at the origin at time t = 0. A force F⃗ = (αtî + βĵ) is applied on the body, where α = 1.0 N s⁻¹ and β = 1.0 N. The torque acting on the body about the origin at time t = 1.0 s is τ⃗. Which of the following statements is (are) true?","o":["|τ⃗| = {1;3} N m.","The torque τ⃗ is in the direction of the unit vector +k̂.","The velocity of the body at t = 1 s is v⃗ = {1;2}(î + 2ĵ) m s⁻¹.","The magnitude of displacement of the body at t = 1 s is {1;6} m."],"c":[0,2],"s":"a = F/m = (t, 1). Integrating: v = (t²/2, t), r = (t³/6, t²/2).\nAt t = 1 s: v = ½(î + 2ĵ) m/s, so (c) is true. r = (1/6, 1/2), |r| = √10/6 m, so (d) is false.\nτ = x·Fᵧ − y·Fₓ = (1/6)(1) − (1/2)(1) = −1/3 N m.\nMagnitude 1/3 N m, so (a) true; direction is −k̂, so (b) false.\nAnswer: (a), (c)."},
{"y":"JEE Advanced 2017","tp":"prd","st":"Torque and angular acceleration","q":"A rigid uniform bar AB of length L is slipping from its vertical position on a frictionless floor (as shown in the figure). At some instant of time, the angle made by the bar with the vertical is θ. Which of the following statements about its motion is/are correct?","fig":{"w":340,"h":185,"alt":"Uniform bar AB slipping on a frictionless floor with its lower end B on the floor and the upper end A to the left of the original vertical line, angle theta with the vertical","d":[["r",20,150,300,8,"f"],["l",150,150,150,30,"d"],["l",116,52,184,150,"B"],["t",104,50,"A","e"],["t",190,146,"B"],["t",158,88,"θ"],["t",150,178,"O","m"],["l",60,30,60,150,"b"],["t",54,95,"L","e"]]},"o":["When the bar makes an angle θ with the vertical, the displacement of its midpoint from the initial position is proportional to (1 − cos θ).","The midpoint of the bar will fall vertically downward.","Instantaneous torque about the point in contact with the floor is proportional to sin θ.","The trajectory of the point A is a parabola."],"c":[0,1,2],"s":"No horizontal force acts on the bar (smooth floor), so its centre of mass moves only vertically. (b) true.\nCentre height = (L/2)cosθ, so its fall from the start = (L/2)(1 − cosθ). (a) true.\nWeight acts at the centre, at horizontal distance (L/2)sinθ from the floor contact point, so the torque is mg(L/2) sinθ, proportional to sinθ. (c) true.\nPoint A has x = −(L/2)sinθ relative to the fixed centre line and height L cosθ: x²/(L/2)² + y²/L² = 1, an ellipse, not a parabola. (d) false.\nAnswer: (a), (b), (c)."},
{"y":"JEE Advanced 2014","tp":"prt","st":"Ladder, beams and hinges","q":"In the figure, a ladder of mass m is shown leaning against a wall. It is in static equilibrium making an angle θ with the horizontal floor. The coefficient of friction between the wall and the ladder is μ₁ and that between the floor and the ladder is μ₂. The normal reaction of the wall on the ladder is N₁ and that of the floor is N₂. If the ladder is about to slip, then","fig":{"w":340,"h":205,"alt":"Ladder leaning against a wall on the right at angle theta with the floor; wall friction coefficient mu1 and floor friction coefficient mu2","d":[["r",290,20,8,155,"f"],["r",60,170,238,6,"f"],["l",130,170,290,40],["t",150,164,"θ"],["t",262,34,"μ₁"],["t",190,196,"μ₂","m"]]},"o":["μ₁ = 0, μ₂ ≠ 0 and N₂tanθ = {mg;2}","μ₁ ≠ 0, μ₂ = 0 and N₁tanθ = {mg;2}","μ₁ ≠ 0, μ₂ ≠ 0 and N₂ = {mg;1+μ₁μ₂}","μ₁ = 0, μ₂ ≠ 0 and N₁tanθ = {mg;2}"],"c":[2,3],"s":"Forces: N₁ (horizontal, wall), μ₁N₁ (up, wall), N₂ (up, floor), μ₂N₂ (horizontal, floor).\nHorizontal: N₁ = μ₂N₂. Vertical: N₂ + μ₁N₁ = mg, so N₂(1 + μ₁μ₂) = mg and N₂ = mg/(1 + μ₁μ₂). (c) is true.\nIf μ₁ = 0: N₂ = mg, N₁ = μ₂mg. Torque about the foot: N₁ L sinθ = mg (L/2) cosθ, so N₁ tanθ = mg/2. (d) true; (a) is false since then N₂ tanθ = mg tanθ.\nIf μ₂ = 0, then N₁ = 0 and the ladder cannot be in equilibrium on the wall, so (b) is false.\nAnswer: (c), (d)."},
{"y":"JEE Main 2023 · 10 Apr · Shift 2","tp":"prt","st":"Torque and its direction","q":"A force of −Pk̂ acts on the origin of the coordinate system. The torque about the point (2, −3) is P(aî + bĵ), the ratio of a/b is x/2. Find the value of x.","n":3,"s":"Position of the force's point (origin) relative to (2, −3): r = −2î + 3ĵ.\nτ = r × F = (−2î + 3ĵ) × (−Pk̂) = 2P(î×k̂) − 3P(ĵ×k̂) = −2Pĵ − 3Pî.\nSo a = −3, b = −2, and a/b = 3/2 = x/2.\nx = 3."},
{"y":"JEE Main 2021 · 16 Mar · Shift 2","tp":"prt","st":"Torque and its direction","q":"A force F⃗ = 4î + 3ĵ + 4k̂ is applied on an intersection point of x = 2 plane and x-axis. The magnitude of torque of this force about a point (2, 3, 4) is ______. (Round off to the nearest integer)","n":20,"s":"The plane x = 2 meets the x-axis at (2, 0, 0).\nr = (2,0,0) − (2,3,4) = (0, −3, −4).\nτ = r × F with F = (4, 3, 4): x-part = (−3)(4) − (−4)(3) = 0; y-part = (−4)(4) − 0 = −16; z-part = 0 − (−3)(4) = 12.\n|τ| = √(16² + 12²) = 20."},
{"y":"JEE Main 2020 · 5 Sep · Shift 1","tp":"prt","st":"Torque and its direction","q":"A force F⃗ = (î + 2ĵ + 3k̂) N acts at a point (4î + 3ĵ − k̂) m. Then the magnitude of torque about the point (î + 2ĵ + k̂) m will be √x N m. The value of x is ______.","n":195,"s":"r = (4,3,−1) − (1,2,1) = (3, 1, −2); F = (1, 2, 3).\nτ = r × F = (1·3 − (−2)·2, (−2)·1 − 3·3, 3·2 − 1·1) = (7, −11, 5).\n|τ|² = 49 + 121 + 25 = 195.\nSo x = 195."},
{"y":"JEE Main 2020 · 7 Jan · Shift 2","tp":"prt","st":"Equilibrium of rigid bodies","q":"Consider a uniform cubical box of side a on a rough floor that is to be moved by applying minimum possible force F at a point b above its centre of mass (see figure). If the coefficient of friction is μ = 0.4, the maximum possible value of 100 × b/a for box not to topple before moving is ______.","fig":{"w":340,"h":215,"alt":"Cube of side a with a horizontal force F applied on its left face at height b above the centre of mass","d":[["r",100,50,120,120],["c",160,110,2.5,"F"],["l",70,110,160,110,"d"],["l",46,86,100,86,"a"],["t",52,78,"F"],["l",78,86,78,110,"b"],["t",72,104,"b","e"],["l",100,188,220,188,"b"],["t",160,204,"a","m"],["l",60,170,260,170]]},"n":75,"s":"The box starts to move when F = μmg = 0.4 mg (friction is limiting, f = F, N = mg).\nIf the box is about to topple, the normal force acts at the front bottom edge, at a/2 from the centre line.\nTorque about the centre of mass: F·b + f·(a/2) = N·(a/2).\n0.4mg(b + a/2) = mg(a/2), so b + a/2 = 1.25a and b = 0.75a.\nTo move without toppling, b ≤ 0.75a, so the maximum of 100b/a is 75."},
{"y":"IIT-JEE 2007","tp":"prc","st":"Statements, matching and subjective","q":"Statement-1 : If there is no external torque on a body about its centre of mass, then the velocity of the centre of mass remains constant.\nStatement-2 : The linear momentum of an isolated system remains constant.","o":["Statements-1 and 2 are true and statement-2 is a correct explanation for statement-1","Statements-1 and 2 are true and statement-2 is not a correct explanation for statement-1","Statement-1 is true, statement-2 is false","Statement-1 is false, statement-2 is true."],"c":3,"s":"Statement-2 is true: with no external force on an isolated system, its total linear momentum is constant.\nStatement-1 is false: zero external torque about the centre of mass only keeps the angular momentum constant. The velocity of the centre of mass is fixed only if the net external force is zero. Example: a single force acting through the centre of mass gives zero torque about it, yet the centre of mass accelerates.\nAnswer: (d)."},
{"y":"IIT-JEE 2006","tp":"prt","st":"Statements, matching and subjective","q":"There is a rectangular plate of mass M kg, of dimensions (a × b). The plate is held in the horizontal position by striking n small balls, each of mass m, per unit area per unit time. These are striking in the dotted half region of the plate. The balls are colliding elastically with velocity v. What is v?\nIt is given: n = 100, M = 3 kg, m = 0.01 kg, b = 2 m, a = 1 m, g = 10 m/s².","fig":{"w":340,"h":200,"alt":"Rectangular plate seen in perspective with width b and side a, hinged along its left edge; the right half is dotted where balls strike from below","d":[["p","M80 40 H300 L260 140 H40 Z"],["l",80,40,40,140,"B"],["l",80,24,300,24,"b"],["t",190,18,"b","m"],["t",298,104,"a"],["c",196.4,54,1.6,"F"],["c",216.4,54,1.6,"F"],["c",236.4,54,1.6,"F"],["c",256.4,54,1.6,"F"],["c",276.4,54,1.6,"F"],["c",189.2,72,1.6,"F"],["c",209.2,72,1.6,"F"],["c",229.2,72,1.6,"F"],["c",249.2,72,1.6,"F"],["c",269.2,72,1.6,"F"],["c",182,90,1.6,"F"],["c",202,90,1.6,"F"],["c",222,90,1.6,"F"],["c",242,90,1.6,"F"],["c",262,90,1.6,"F"],["c",174.8,108,1.6,"F"],["c",194.8,108,1.6,"F"],["c",214.8,108,1.6,"F"],["c",234.8,108,1.6,"F"],["c",254.8,108,1.6,"F"],["c",167.6,126,1.6,"F"],["c",187.6,126,1.6,"F"],["c",207.6,126,1.6,"F"],["c",227.6,126,1.6,"F"],["c",247.6,126,1.6,"F"],["l",205,178,205,152,"a"],["l",225,178,225,152,"a"],["l",245,178,245,152,"a"],["t",50,160,"hinge","s"]]},"a":"v = 10 m/s","s":"The plate is hinged along its left edge (the line drawn through the left side); it is held horizontal by the torque of the ball impacts.\nElastic collision: each ball changes momentum by 2mv. Area hit = a·b/2, so force F = n(ab/2)(2mv) = nabmv. It acts at the middle of the dotted half, at 3b/4 from the hinge.\nTorque balance about the hinge: F(3b/4) = Mg(b/2), so F = 2Mg/3.\nnabmv = 2Mg/3, so v = 2Mg/(3nabm) = (2×3×10)/(3×100×1×2×0.01) = 10 m/s."},
{"y":"IIT-JEE 2002","tp":"prd","st":"Statements, matching and subjective","q":"Three particles A, B and C, each of mass m, are connected to each other by three massless rigid rods to form a rigid, equilateral triangular body of side l. This body is placed on a horizontal frictionless table (x-y plane) and is hinged to it at the point A so that it can move without friction about the vertical axis through A (see figure). The body is set into rotational motion on the table about A with a constant angular velocity ω.\n(a) Find the magnitude of the horizontal force exerted by the hinge on the body.\n(b) At time T, when the side BC is parallel to the x-axis, a force F is applied on B along BC (as shown). Obtain the x-component and the y-component of the force exerted by the hinge on the body, immediately after time T.","fig":{"w":340,"h":200,"alt":"Equilateral triangle ABC with A at the top hinged and axes x to the right and y up at A; BC horizontal at the bottom with side l and force F applied at B pointing toward C","d":[["c",170,40,5],["l",170,34,170,10,"a"],["t",176,14,"y"],["l",176,40,230,40,"a"],["t",234,44,"x"],["t",196,34,"ω","s"],["l",170,45,110,144],["l",170,45,230,144],["l",115,144,225,144],["c",110,144,5],["c",230,144,5],["t",154,34,"A","e"],["t",102,160,"B","e"],["t",236,160,"C"],["l",116,170,224,170,"b"],["t",170,186,"l","m"],["l",50,144,103,144,"a"],["t",56,136,"F"]]},"a":"(a) √3 m l ω²   (b) x-component −F/4, y-component √3 m l ω²","s":"(a) B and C each move in a circle of radius l about A, so each needs a centripetal force mω²l toward A. These two forces are 30° from the bisector, so the resultant = 2·mω²l·cos30° = √3 mω²l. The hinge supplies it.\n(b) Take A as origin, B = (−l/2, −√3l/2), C = (l/2, −√3l/2), F = (F, 0) at B. I about A = 2ml².\nTorque about A = −y·F = (√3 l/2)F, so α = √3F/(4ml).\nSum of m·a over B and C: x-part = mα(√3 l) = 3F/4 (tangential), y-part = √3 mω²l (centripetal).\nHinge + F = Σma: Hₓ = 3F/4 − F = −F/4, Hᵧ = √3 mlω²."},
{"y":"IIT-JEE 1985","tp":"prd","st":"Statements, matching and subjective","q":"A triangular plate of uniform thickness and density is made to rotate about an axis perpendicular to the plane of the paper and (a) passing through A, (b) passing through B, by the application of the same force, F, at C (midpoint of AB) as shown in the figure. The angular acceleration in both the cases will be the same.","fig":{"w":340,"h":200,"alt":"Right-angled triangular plate with base AB, vertical side at B, and a force F applied upward at the midpoint C of AB","d":[["p","M30 150 H270 V30 Z","f"],["t",22,168,"A","e"],["t",276,168,"B"],["t",146,142,"C","e"],["l",150,185,150,153,"a"],["t",156,184,"F"]]},"o":["True","False"],"c":1,"s":"The torque of F about A and about B is the same in size: F × (AB/2).\nBut α = τ/I, and the moment of inertia is not the same about A and B. The mass of the triangle is concentrated near the vertical side at B, so I about B is smaller than I about A.\nSo the angular accelerations are different.\nAnswer: False."},
{"y":"IIT-JEE 1997","tp":"prt","st":"Equilibrium of rigid bodies","q":"A rod of weight W is supported by two parallel knife edges A and B and is in equilibrium in a horizontal position. The knives are at a distance d from each other. The centre of mass of the rod is at distance x from A. The normal reaction on A is ______ and on B is ______.","fig":{"w":340,"h":160,"alt":"Horizontal rod resting on knife edges A and B a distance d apart, with its centre of mass at distance x from A","d":[["r",40,50,260,10,"f"],["p","M90 60 L82 85 H98 Z"],["p","M230 60 L222 85 H238 Z"],["t",90,102,"A","m"],["t",230,102,"B","m"],["c",150,55,3,"F"],["l",150,60,150,98,"a"],["t",156,98,"W"],["l",90,120,150,120,"b"],["t",120,116,"x","m"],["l",90,142,230,142,"b"],["t",160,138,"d","m"]]},"a":"On A: (d − x)W/d, on B: xW/d","s":"Let N_A and N_B be the reactions. Vertical balance: N_A + N_B = W.\nTorque about A: N_B·d = W·x, so N_B = xW/d.\nThen N_A = W − xW/d = (d − x)W/d."},
{"y":"IIT-JEE 1988","tp":"prd","st":"Statements, matching and subjective","q":"A cylinder of mass M and radius R is resting on a horizontal platform (which is parallel to the x-y plane) with its axis fixed along the y-axis and free to rotate about its axis. The platform is given a motion in the x-direction given by x = Acos(ωt). There is no slipping between the cylinder and platform. The maximum torque acting on the cylinder during its motion is ______.","a":"MRAω²/2","s":"The axis is fixed, so the cylinder only spins. With no slipping, the surface speed Rω_c equals the platform speed, so Rα = a_platform.\na_platform = −Aω² cos ωt, maximum Aω².\nTorque = Iα = (MR²/2)(Aω²/R) for a solid cylinder = MRAω²/2 (maximum).\n(The printed key shows MRAω²/3, which does not follow from this working; see notes.)"},
{"y":"IIT-JEE 1984","tp":"prt","st":"Equilibrium of rigid bodies","q":"A uniform cube of side a and mass m rests on a rough horizontal table. A horizontal force F is applied normal to one of the faces at a point that is directly above the centre of the face, at a height 3a/4 above the base. The minimum value of F for which the cube begins to tip about the edge is ______. (Assume that the cube does not slide).","a":"(2/3) mg","s":"At the point of tipping, the cube turns about the lower far edge; the table reaction and friction act at that edge and have no torque about it.\nTorque of F about the edge = F(3a/4). Torque of weight = mg(a/2) in the opposite sense.\nF(3a/4) = mg(a/2), so F = (2/3)mg."},
{"y":"JEE Main 2025 · 2 Apr · Shift 1","tp":"pri","st":"Radius of gyration and composite bodies","q":"Moment of inertia of a rod of mass ‘M’ and length ‘L’ about an axis passing through its center and normal to its length is ‘α’. Now the rod is cut into two equal parts and these parts are joined symmetrically to form a cross shape. Moment of inertia of cross about an axis passing through its center and normal to plane containing cross is","o":["α/2","α/8","α/4","α"],"c":2,"s":"α = ML²/12.\nEach half has mass M/2 and length L/2. About the cross centre (its own centre) I = (M/2)(L/2)²/12 = ML²/96.\nThe two halves cross at their centres, so both axes pass through their centres: I = 2 × ML²/96 = ML²/48.\nThis is α/4.\nAnswer: (c)."},
{"y":"JEE Main 2025 · 2 Apr · Shift 2","tp":"pri","st":"Parallel and perpendicular axes","q":"The moment of inertia of a circular ring of mass M and diameter r about a tangential axis lying in the plane of the ring is","o":["{1;2}Mr²","{3;8}Mr²","2Mr²","{3;2}Mr²"],"c":1,"s":"Radius R = r/2.\nAbout a diameter: I = ½MR².\nTangent in the plane (parallel axis): I = ½MR² + MR² = (3/2)MR².\nSubstituting R² = r²/4: I = (3/2)M(r²/4) = (3/8)Mr².\nAnswer: (b)."},
{"y":"JEE Main 2025 · 8 Apr · Shift 2","tp":"pri","st":"Moment of inertia of bodies","q":"A rod of linear mass density ‘λ’ and length ‘L’ is bent to form a ring of radius ‘R’. Moment of inertia of ring about any of its diameter is","o":["{λL³;16π²}","{λL³;4π²}","{λL³;8π²}","{λL³;12}"],"c":2,"s":"Mass M = λL. The length is the circumference: L = 2πR, so R = L/2π.\nAbout a diameter, I = ½MR² = ½(λL)(L²/4π²) = λL³/(8π²).\nAnswer: (c)."},
{"y":"JEE Main 2025 · 22 Jan · Shift 1","tp":"pri","st":"Radius of gyration and composite bodies","q":"A uniform circular disc of radius ‘R’ and mass ‘M’ is rotating about an axis perpendicular to its plane and passing through its centre. A small circular part of radius R/2 is removed from the original disc as shown in the figure. Find the moment of inertia of the remaining part of the original disc about the axis as given above.","fig":{"w":340,"h":200,"alt":"Circular disc of radius R with a smaller circular hole of radius R/2 touching the centre and the right edge, dashed diameter shown","d":[["c",170,100,80],["c",210,100,40],["c",170,100,2,"F"],["l",90,100,250,100,"d"],["t",130,94,"R","m"],["t",210,94,"R","m"]]},"o":["{9;32}MR²","{13;32}MR²","{17;32}MR²","{7;32}MR²"],"c":1,"s":"Full disc: I = ½MR².\nThe removed disc has radius R/2, so mass M/4 (area ratio 1/4). Its centre is R/2 from the axis.\nI(removed) = ½(M/4)(R/2)² + (M/4)(R/2)² = (3/2)(M/4)(R²/4) = 3MR²/32.\nRemaining: ½MR² − 3MR²/32 = 16MR²/32 − 3MR²/32 = 13MR²/32.\nAnswer: (b)."},
{"y":"JEE Main 2024 · 5 Apr · Shift 1","tp":"pri","st":"Radius of gyration and composite bodies","q":"Ratio of radius of gyration of a hollow sphere to that of a solid cylinder of equal mass, for moment of Inertia about their diameter axis AB as shown in figure is √{8;x}. The value of x is","fig":{"w":340,"h":200,"alt":"Hollow sphere with vertical diameter axis AB, and a cylinder of diameter 2R and length 4R with axis AB perpendicular to it through its left end","d":[["c",70,100,45],["l",70,40,70,160,"d"],["t",70,34,"A","m"],["t",70,178,"B","m"],["t",108,60,"M","s"],["t",70,196,"hollow sphere","ms"],["l",190,80,310,80],["l",190,120,310,120],["p","M190 80 A8 20 0 0 0 190 120"],["p","M310 80 A8 20 0 0 1 310 120"],["l",190,40,190,160,"d"],["t",190,34,"A","m"],["t",190,178,"B","m"],["l",168,80,168,120,"b"],["t",162,104,"2R","e"],["l",190,138,310,138,"b"],["t",250,154,"4R","m"]]},"o":["17","51","34","67"],"c":3,"s":"Radius of the sphere = radius of the cylinder = R; cylinder length L = 4R, and axis AB is perpendicular to the cylinder axis through one end (as drawn).\nHollow sphere: I = (2/3)MR², so k₁² = 2R²/3.\nCylinder: I = M(R²/4 + L²/12) + M(L/2)² = MR²(1/4 + 4/3 + 4) = (67/12)MR², so k₂² = 67R²/12.\n(k₁/k₂)² = (2/3)(12/67) = 8/67, so x = 67.\nAnswer: (d)."},
{"y":"JEE Main 2021 · 26 Aug · Shift 2","tp":"pri","st":"Parallel and perpendicular axes","q":"The solid cylinder of length 80 cm and mass M has a radius of 20 cm. Calculate the density of the material used if the moment of inertia of the cylinder about an axis CD parallel to AB as shown in figure is 2.7 kg m².","fig":{"w":340,"h":195,"alt":"Solid cylinder of length L with axis AB through its centre and a parallel axis CD at distance L/2 from AB","d":[["l",110,40,110,150],["l",190,40,190,150],["p","M110 40 A40 10 0 0 1 190 40"],["p","M110 40 A40 10 0 0 0 190 40"],["p","M110 150 A40 10 0 0 0 190 150"],["l",150,28,150,162,"d"],["t",150,22,"A","m"],["t",150,178,"B","m"],["l",260,28,260,162,"d"],["t",260,22,"C","m"],["t",260,178,"D","m"],["l",150,95,260,95,"b"],["t",205,89,"L/2","m"],["l",70,40,70,150,"b"],["t",62,98,"L","e"],["t",124,100,"M","s"]]},"o":["1.49 × 10² kg/m³","7.5 × 10¹ kg/m³","14.9 kg/m³","7.5 × 10² kg/m³"],"c":0,"s":"AB is the axis of the cylinder; CD is parallel to it at a distance L/2 = 0.4 m (from the figure).\nI = ½MR² + M(L/2)² = M(0.02 + 0.16) = 0.18M.\n0.18M = 2.7, so M = 15 kg.\nVolume = πR²L = π(0.2)²(0.8) = 0.1005 m³.\nDensity = 15/0.1005 ≈ 149 kg/m³ = 1.49 × 10² kg/m³.\nAnswer: (a)."},
{"y":"JEE Main 2021 · 27 Aug · Shift 1","tp":"pri","st":"Parallel and perpendicular axes","q":"Moment of inertia of a square plate of side l about the axis passing through one of the corner and perpendicular to the plane of square plate is given by","o":["{Ml²;6}","{2;3}Ml²","Ml²","{Ml²;12}"],"c":1,"s":"About the centre, perpendicular to the plate: I = Ml²/12 + Ml²/12 = Ml²/6.\nThe corner is at distance l/√2 from the centre, so shift by M(l²/2).\nI = Ml²/6 + Ml²/2 = (2/3)Ml².\nAnswer: (b)."},
{"y":"JEE Main 2021 · 31 Aug · Shift 2","tp":"pri","st":"Parallel and perpendicular axes","q":"A system consists of two identical spheres each of mass 1.5 kg and radius 50 cm at the ends of a light rod. The distance between the centres of the two spheres is 5 m. What will be the moment of inertia of the system about an axis perpendicular to the rod passing through its midpoint?","o":["1.905 × 10⁵ kg m²","18.75 kg m²","19.05 kg m²","1.875 × 10⁵ kg m²"],"c":2,"s":"Each sphere: I = (2/5)mr² + m d², with r = 0.5 m and d = 2.5 m.\n(2/5)(1.5)(0.25) = 0.15 and 1.5 × 6.25 = 9.375, so I = 9.525 kg m².\nTwo spheres: 2 × 9.525 = 19.05 kg m².\nAnswer: (c)."},
{"y":"JEE Main 2021 · 27 Jul · Shift 1","tp":"pri","st":"Moment of inertia of bodies","q":"The figure shows two solid discs with radius R and r respectively. If mass per unit area is same for both, what is the ratio of MI of bigger disc around axis AB (which is perpendicular to the plane of the disc and passing through its centre) to MI of smaller disc around one of its diameters lying on its plane ? Given M is the mass of the larger disc. (MI stands for moment of inertia)","fig":{"w":340,"h":205,"alt":"Large disc of radius R with a smaller concentric disc of radius r, vertical axis AB through the centre and horizontal line CD","d":[["c",170,100,80],["c",170,100,35],["l",170,15,170,185,"d"],["t",170,10,"A","m"],["t",170,200,"B","m"],["l",60,100,285,100,"a"],["t",54,104,"C","e"],["t",290,104,"D"],["t",148,128,"M","s"],["t",212,130,"R"],["t",182,88,"r","s"]]},"o":["2r⁴ : R⁴","2R² : r²","2R⁴ : r⁴","R² : r²"],"c":2,"s":"Mass per unit area σ is the same: M = σπR² and m = σπr².\nBigger disc about AB (perpendicular, through centre): I₁ = ½MR² = ½σπR⁴.\nSmaller disc about a diameter: I₂ = ¼mr² = ¼σπr⁴.\nI₁ : I₂ = (½R⁴) : (¼r⁴) = 2R⁴ : r⁴.\nAnswer: (c)."},
{"y":"JEE Main 2021 · 16 Mar · Shift 1","tp":"pri","st":"Parallel and perpendicular axes","q":"For equal masses, m each are placed at the corners of a square of length (l) as shown in the figure. The moment of inertia of the system about an axis passing through A and parallel to DB would be","fig":{"w":340,"h":215,"alt":"Square ABCD of side l with a mass m at each corner, A bottom left, B bottom right, C top right, D top left, with dashed diagonals and a dashed axis through A parallel to DB","d":[["r",90,50,100,100],["l",90,50,190,150,"d"],["l",190,50,90,150,"d"],["l",40,100,140,200,"d"],["t",82,46,"D","e"],["t",196,46,"C"],["t",82,164,"A","e"],["t",196,164,"B"],["l",90,176,190,176,"b"],["t",140,192,"l","m"],["t",146,206,"axis","s"]]},"o":["2 ml²","√3 ml²","ml²","3 ml²"],"c":3,"s":"Place A at the origin, B = (l, 0), D = (0, l), C = (l, l). DB has direction (1, −1), so the distance of (x, y) from the axis through A is |x + y|/√2.\nB: l/√2, D: l/√2, C: 2l/√2 = √2 l, A: 0.\nI = m(l²/2) + m(l²/2) + m(2l²) + 0 = 3ml².\nAnswer: (d)."},
{"y":"JEE Main 2021 · 18 Mar · Shift 2","tp":"pri","st":"Moment of inertia of bodies","q":"Consider a uniform wire of mass M and length L. It is bent into a semicircle. Its moment of inertia about a line perpendicular to the plane of the wire passing through the centre is","o":["{2;5}{ML²;π²}","{1;2}{ML²;π²}","{1;4}{ML²;π²}","{ML²;π²}"],"c":3,"s":"The length of the semicircle is L = πR, so R = L/π.\nEvery part of the wire is at distance R from the axis through the centre, so I = MR².\nI = M L²/π².\nAnswer: (d)."},
{"y":"JEE Main 2021 · 24 Feb · Shift 1","tp":"pri","st":"Moment of inertia of bodies","q":"Moment of inertia (M.I.) of four bodies, having same mass and radius, are reported as\nI₁ = M.I. of thin circular ring about its diameter,\nI₂ = M.I. of circular disc about an axis perpendicular to disc and going through the centre,\nI₃ = M.I. of solid cylinder about its axis and\nI₄ = M.I. of solid sphere about its diameter.\nThen","o":["I₁ = I₂ = I₃ < I₄","I₁ + I₂ = I₃ = {5;2}I₄","I₁ + I₃ < I₂ + I₄","I₁ = I₂ = I₃ > I₄"],"c":3,"s":"I₁ = ½MR² (ring about a diameter).\nI₂ = ½MR² (disc about its central perpendicular axis).\nI₃ = ½MR² (solid cylinder about its axis).\nI₄ = (2/5)MR² (solid sphere about a diameter).\nSo I₁ = I₂ = I₃ > I₄.\nAnswer: (d)."},
{"y":"JEE Main 2021 · 26 Feb · Shift 1","tp":"pri","st":"Parallel and perpendicular axes","q":"Four identical solid spheres each of mass ‘m’ and radius ‘a’ are placed with their centres on the four corners of a square of side ‘b’. The moment of inertia of the system about one side of square where the axis of rotation is parallel to the plane of the square is","o":["{8;5}ma² + mb²","{4;5}ma² + 2mb²","{4;5}ma²","{8;5}ma² + 2mb²"],"c":3,"s":"The axis is along one side. Two spheres have centres on the axis: each I = (2/5)ma².\nThe other two are at distance b: each I = (2/5)ma² + mb².\nTotal = 4 × (2/5)ma² + 2mb² = (8/5)ma² + 2mb².\nAnswer: (d)."},
{"y":"JEE Main 2020 · 2 Sep · Shift 1","tp":"prt","st":"Equilibrium of rigid bodies","q":"A uniform cylinder of mass M and radius R is to be pulled over a step of height a (a < R) by applying a force F at its centre ‘O’ perpendicular to the plane through the axes of the cylinder on the edge of the step (see figure). The minimum value of F required is","fig":{"w":340,"h":185,"alt":"Cylinder of radius R with centre O resting against a step of height a, with force F at O perpendicular to the line from O to the step edge","d":[["c",130,100,50],["c",130,100,2,"F"],["r",170,130,130,20,"f"],["l",40,150,170,150],["l",130,100,170,130,"d"],["t",150,106,"R","s"],["l",130,100,172,44,"a"],["t",178,44,"F"],["t",118,98,"O","e"],["l",312,130,312,150,"b"],["t",318,144,"a"]]},"o":["Mg√{1 − ({R−a;R})²}","Mg√{({R;R−a})² − 1}","Mg{a;R}","Mg√{1 − {a²;R²}}"],"c":0,"s":"The cylinder just lifts off the ground when it is about to turn about the step edge P. Take torques about P.\nF acts at O perpendicular to OP, so its arm is OP = R: torque = FR.\nWeight acts at O; its horizontal arm is √(R² − (R − a)²): torque = Mg√(R² − (R − a)²).\nFR = Mg√(R² − (R − a)²), so F = Mg√(1 − ((R − a)/R)²).\nAnswer: (a)."},
{"y":"JEE Main 2020 · 3 Sep · Shift 1","tp":"pri","st":"Moment of inertia of bodies","q":"Moment of inertia of a cylinder of mass M, length L and radius R about an axis passing through its centre and perpendicular to the axis of the cylinder is I = M(R²/4 + L²/12). If such a cylinder is to be made for a given mass of a material, the ratio L/R for it to have minimum possible I is","o":["{2;3}","{3;2}","√{3;2}","√{2;3}"],"c":2,"s":"Same mass and same material means fixed volume V = πR²L, so R² = V/(πL).\nI/M = V/(4πL) + L²/12.\nSet d(I)/dL = 0: −V/(4πL²) + L/6 = 0, so L³ = 3V/(2π).\nPut V = πR²L: L² = 3R²/2, so L/R = √(3/2).\nAnswer: (c)."},
{"y":"JEE Main 2020 · 4 Sep · Shift 2","tp":"pri","st":"Moment of inertia of bodies","q":"Consider two uniform discs of the same thickness and different radii R₁ = R and R₂ = αR made of the same material. If the ratio of their moments of inertia I₁ and I₂ respectively, about their axes is I₁ : I₂ = 1 : 16 then the value of α is","o":["4","2","2√2","√2"],"c":1,"s":"Same thickness and material means mass is proportional to R².\nI = ½MR² is therefore proportional to R⁴.\nI₁/I₂ = 1/α⁴ = 1/16, so α⁴ = 16.\nα = 2."},
{"y":"JEE Main 2020 · 4 Sep · Shift 2","tp":"pri","st":"Parallel and perpendicular axes","q":"For a uniform rectangular sheet shown in the figure, the ratio of moments of inertia about the axes perpendicular to the sheet and passing through O (the centre of mass) and O′ (corner point) is","fig":{"w":300,"h":205,"alt":"Rectangular sheet 60 cm wide and 80 cm tall with its centre O and the top right corner O′, x and y axes along the bottom and left edges","d":[["l",100,175,100,5,"a"],["l",100,175,290,175,"a"],["r",100,15,120,160],["c",160,95,2.5,"F"],["t",150,92,"O","e"],["c",220,15,2.5,"F"],["t",226,12,"O′"],["t",225,96,"80 cm","s"],["l",230,15,230,175,"b"],["l",100,186,220,186,"b"],["t",160,200,"60 cm","ms"],["t",104,10,"y"],["t",284,168,"x","e"]]},"o":["2/3","1/2","1/8","1/4"],"c":3,"s":"Sheet of sides a = 60 cm and b = 80 cm.\nAbout the centre: I_O = M(a² + b²)/12.\nThe corner is a distance √(a² + b²)/2 from O, so I_O′ = I_O + M(a² + b²)/4 = M(a² + b²)/3.\nRatio I_O : I_O′ = (1/12) : (1/3) = 1/4."},
{"y":"JEE Main 2020 · 6 Sep · Shift 1","tp":"pri","st":"Moment of inertia of bodies","q":"Shown in the figure is a hollow ice cream cone (it is open at the top). If its mass is M, radius of its top, R and height, H, then its moment of inertia about its axis is","fig":{"w":300,"h":200,"alt":"Hollow cone with its apex down and open top of radius R, vertical dashed axis and height H marked","d":[["p","M80 35 A60 12 0 0 1 200 35 A60 12 0 0 1 80 35"],["l",80,35,140,180],["l",200,35,140,180],["l",140,10,140,190,"d"],["l",140,26,200,26,"a"],["t",170,20,"R","m"],["l",240,35,240,180,"b"],["t",248,112,"H"]]},"o":["{MR²;2}","{M(R²+H²);4}","{MH²;3}","{MR²;3}"],"c":0,"s":"The cone is a thin shell, so every bit of mass is at a different distance from the axis.\nTake a thin ring of the shell at radius r. Its distance from the axis is r.\nI = ∫r² dm, and the mass is spread uniformly over the surface area, with dm proportional to r dr.\nI = ∫r² · (2M r dr/R²) over r = 0 to R = 2M/R² · R⁴/4 = {MR²;2}.\nThe height H does not appear."},
{"y":"JEE Main 2020 · 6 Sep · Shift 2","tp":"pri","st":"Moment of inertia of bodies","q":"The linear mass density of a thin rod AB of length L varies from A to B as λ(x) = λ₀(1 + {x;L}), where x is the distance from A. If M is the mass of the rod, then its moment of inertia about an axis passing through A and perpendicular to the rod is","o":["{5;12}ML²","{7;18}ML²","{2;5}ML²","{3;7}ML²"],"c":1,"s":"Mass: M = ∫λ dx = λ₀(L + L/2) = {3;2}λ₀L.\nI about A = ∫λ x² dx = λ₀(L³/3 + L³/4) = {7;12}λ₀L³.\nPut λ₀ = 2M/(3L): I = {7;12} · {2M;3L} · L³ = {7;18}ML²."},
{"y":"JEE Main 2020 · 7 Jan · Shift 1","tp":"pri","st":"Radius of gyration and composite bodies","q":"The radius of gyration of a uniform rod of length l, about an axis passing through a point {l;4} away from the centre of the rod, and perpendicular to it, is","o":["{1;8}l","√{7;48}l","√{3;8}l","{1;4}l"],"c":1,"s":"I about the centre = ml²/12.\nParallel axis theorem with d = l/4: I = ml²/12 + m(l/4)² = ml²(1/12 + 1/16) = {7;48}ml².\nI = mk², so k = √{7;48} l."},
{"y":"JEE Main 2020 · 7 Jan · Shift 2","tp":"pri","st":"Moment of inertia of bodies","q":"Mass per unit area of a circular disc of radius a depends on the distance r from its centre as σ(r) = A + Br. The moment of inertia of the disc about the axis, perpendicular to the plane and passing through its centre is","o":["2πa⁴({aA;4} + {B;5})","2πa⁴({A;4} + {B;5})","2πa⁴({A;4} + {aB;5})","πa⁴({A;4} + {aB;5})"],"c":2,"s":"Take a ring of radius r and width dr. Its mass is dm = σ · 2πr dr.\nI = ∫r² dm = 2π∫(A + Br) r³ dr from 0 to a.\nI = 2π(A a⁴/4 + B a⁵/5) = 2πa⁴({A;4} + {aB;5})."},
{"y":"JEE Main 2020 · 9 Jan · Shift 1","tp":"pri","st":"Radius of gyration and composite bodies","q":"Three solid spheres each of mass m and diameter d are stuck together such that the lines connecting the centres form an equilateral triangle of side of length d. The ratio I₀/I_A of moment of inertia I₀ of the system about an axis passing the centroid and about center of any of the spheres I_A and perpendicular to the plane of the triangle is","fig":{"w":300,"h":150,"alt":"Three equal touching spheres A, B and C whose centres form an equilateral triangle of side d, with the centroid O and the diameter d marked","d":[["c",145,48,28],["c",201,48,28],["c",173,96.5,28],["t",145,52,"B","ms"],["t",201,52,"A","ms"],["t",173,100,"C","ms"],["l",145,48,201,48,"d"],["l",145,48,173,96.5,"d"],["l",201,48,173,96.5,"d"],["c",173,64,2,"F"],["t",178,68,"O","s"],["l",252,20,252,76,"b"],["t",258,52,"d"]]},"o":["{15;13}","{13;15}","{13;23}","{23;13}"],"c":2,"s":"Radius r = d/2 and a solid sphere has I = ²⁄₅mr² = {1;10}md² about its centre.\nCentroid O is at distance d/√3 from each centre.\nI₀ = 3[{1;10}md² + m(d²/3)] = {13;10}md².\nI_A (about the centre of A): sphere A gives {1;10}md², spheres B and C are each d away: 2[{1;10}md² + md²].\nI_A = {1;10}md² + {22;10}md² = {23;10}md².\nI₀/I_A = 13/23."},
{"y":"JEE Main 2019 · 8 Apr · Shift 1","tp":"pri","st":"Parallel and perpendicular axes","q":"A thin circular plate of mass M and radius R has its density varying as ρ(r) = ρ₀r with ρ₀ as constant and r is the distance from its center. The moment of inertia of the circular plate about an axis perpendicular to the plate and passing through its edge is I = aMR². The value of the coefficient a is","o":["{3;5}","{3;2}","{1;2}","{8;5}"],"c":3,"s":"Mass: M = ∫ρ₀r · 2πr dr = {2πρ₀R³;3}.\nI about the centre: ∫ρ₀r · 2πr · r² dr = {2πρ₀R⁵;5} = {3;5}MR².\nParallel axis theorem for an axis through the edge: I = {3;5}MR² + MR² = {8;5}MR².\nSo a = 8/5."},
{"y":"JEE Main 2019 · 10 Apr · Shift 1","tp":"pri","st":"Moment of inertia of bodies","q":"A thin disc M and radius R has mass per unit area σ(r) = kr² where r is the distance from its centre. Its moment of inertia about an axis going through its centre of mass and perpendicular to its plane is","o":["{MR²;6}","{2MR²;3}","{MR²;3}","{MR²;2}"],"c":1,"s":"Mass: M = ∫kr² · 2πr dr = {πkR⁴;2}.\nI = ∫kr² · 2πr · r² dr = {πkR⁶;3}.\nDivide: I/M = {2R²;3}.\nI = {2MR²;3}."},
{"y":"JEE Main 2019 · 10 Apr · Shift 2","tp":"pri","st":"Radius of gyration and composite bodies","q":"A solid sphere of mass M and radius R is divided into two unequal parts. The first part has a mass of {7M;8} and is converted into a uniform disc of radius 2R. The second part is converted into a uniform solid sphere. Let I₁ be the moment of inertia of the disc about its axis and I₂ the moment of inertia of the new sphere about its axis. The ratio I₁/I₂ is given by","o":["185","140","65","285"],"c":1,"s":"Disc: I₁ = ½ · {7M;8} · (2R)² = {7MR²;4}.\nThe second part has mass M/8, so its volume is 1/8 of the original sphere. Its radius is R/2.\nI₂ = {2;5} · {M;8} · (R/2)² = {MR²;80}.\nI₁/I₂ = {7;4} × 80 = 140."},
{"y":"JEE Main 2019 · 12 Apr · Shift 1","tp":"pri","st":"Radius of gyration and composite bodies","q":"A circular disc of radius b has a hole of radius a at its centre (see figure). If the mass per unit area of the disc varies as ({σ₀;r}), then the radius of gyration of the disc about its axis passing through the centre is","fig":{"w":260,"h":180,"alt":"Disc of outer radius b with a concentric hole of radius a","d":[["c",130,90,75],["c",130,90,30],["c",130,90,2,"F"],["l",130,90,205,90],["l",130,90,160,90,"B"],["t",182,84,"b","m"],["t",148,84,"a","m"]]},"o":["{a+b;3}","{a+b;2}","√{a²+b²+ab;2}","√{a²+b²+ab;3}"],"c":3,"s":"Mass: M = ∫(σ₀/r) · 2πr dr from a to b = 2πσ₀(b − a).\nI = ∫(σ₀/r) · 2πr · r² dr = 2πσ₀ (b³ − a³)/3.\nk² = I/M = (b³ − a³)/(3(b − a)) = (a² + ab + b²)/3.\nk = √{a²+b²+ab;3}."},
{"y":"JEE Main 2019 · 10 Jan · Shift 2","tp":"pri","st":"Radius of gyration and composite bodies","q":"Two identical spherical balls of mass M and radius R each are stuck on two ends of a rod of length 2R and mass M (see figure). The moment of inertia of the system about the axis passing perpendicularly through the centre of the rod is","fig":{"w":300,"h":150,"alt":"Two spheres of radius R joined by a rod of length 2R with a dashed vertical axis through the middle of the rod","d":[["c",110,80,30],["c",230,80,30],["l",140,75,200,75],["l",140,85,200,85],["l",170,35,170,135,"d"],["l",140,28,200,28,"b"],["t",170,22,"2R","ms"],["l",110,80,82,80],["t",96,74,"R","ms"],["l",230,80,258,80],["t",244,74,"R","ms"]]},"o":["{209;15}MR²","{137;15}MR²","{152;15}MR²","{17;15}MR²"],"c":1,"s":"Rod about its centre: {M(2R)²;12} = {MR²;3}.\nEach sphere has its centre at R + R = 2R from the axis.\nEach sphere: {2;5}MR² + M(2R)² = {22;5}MR².\nTotal: {MR²;3} + 2 · {22MR²;5} = ({5 + 132;15})MR² = {137;15}MR²."},
{"y":"JEE Main 2019 · 11 Jan · Shift 1","tp":"pri","st":"Radius of gyration and composite bodies","q":"An equilateral triangle ABC is cut from a thin solid sheet of wood. (See figure) D, E and F are the mid-points of its sides as shown and G is the centre of the triangle. The moment of inertia of the triangle about an axis passing through G and perpendicular to the plane of the triangle is I₀. If the smaller triangle DEF is removed from ABC, the moment of inertia of the remaining figure about the same axis is I. Then","fig":{"w":300,"h":195,"alt":"Equilateral triangle ABC with D, E, F the mid-points of AB, AC and BC joined by dashed lines and G the centre","d":[["p","M170 14 L80 170 L260 170 Z"],["p","M125 92 L215 92 L170 170 Z","d"],["c",170,118,2,"F"],["t",176,114,"G","s"],["t",170,10,"A","m"],["t",70,178,"B"],["t",262,178,"C"],["t",112,92,"D","e"],["t",220,92,"E"],["t",170,186,"F","m"]]},"o":["I = {15;16}I₀","I = {9;16}I₀","I = {3;4}I₀","I = {I₀;4}"],"c":0,"s":"For a triangle of mass m and side a, I about its centre is proportional to m a².\nThe small triangle DEF has side a/2 and mass M/4 (area is 1/4), and its centre is also G.\nI_DEF = {1;4} · {1;4} I₀ = {I₀;16}.\nRemaining part: I = I₀ − {I₀;16} = {15;16}I₀."},
{"y":"JEE Main 2019 · 11 Jan · Shift 2","tp":"pri","st":"Radius of gyration and composite bodies","q":"A circular disc D₁ of mass M and radius R has two identical discs D₂ and D₃ of the same mass M and radius R attached rigidly at its opposite ends (see figure). The moment of inertia of the system about the axis OO′, passing through the centre of D₁, as shown in the figure, will be","fig":{"w":300,"h":150,"alt":"Disc D1 lying flat with discs D2 and D3 standing at its two ends and a vertical axis OO′ through the centre of D1","d":[["p","M90 100 A60 13 0 0 1 210 100 A60 13 0 0 1 90 100"],["p","M81 100 A9 26 0 0 1 99 100 A9 26 0 0 1 81 100"],["p","M201 100 A9 26 0 0 1 219 100 A9 26 0 0 1 201 100"],["l",150,100,150,25,"a"],["t",156,22,"O′"],["c",150,100,2,"F"],["t",156,114,"O","s"],["t",150,138,"D₁","m"],["t",68,100,"D₂","e"],["t",224,100,"D₃"]]},"o":["3MR²","{4;5}MR²","{2;3}MR²","MR²"],"c":0,"s":"D₁ about OO′ (through its centre, perpendicular to its plane): ½MR².\nD₂ and D₃ stand upright with their centres at distance R from the axis. The axis is parallel to a diameter of each.\nEach: {MR²;4} + MR² = {5;4}MR².\nTotal: ½MR² + 2 · {5;4}MR² = 3MR²."},
{"y":"JEE Main 2019 · 12 Jan · Shift 1","tp":"pri","st":"Radius of gyration and composite bodies","q":"Let the moment of inertia of a hollow cylinder of length 30 cm (inner radius 10 cm and outer radius 20 cm), about its axis be I. The radius of a thin cylinder of the same mass such that its moment of inertia about its axis is also I, is","o":["14 cm","16 cm","12 cm","18 cm"],"c":1,"s":"Hollow cylinder: I = ½M(R₁² + R₂²) = ½M(100 + 400) = 250M (cm²).\nThin cylinder of the same mass: I = MR².\nMR² = 250M, so R = √250 ≈ 15.8 cm.\nThe closest option is 16 cm."},
{"y":"JEE Main 2019 · 12 Jan · Shift 2","tp":"pri","st":"Parallel and perpendicular axes","q":"The moment of inertia of a solid sphere, about an axis parallel to its diameter and at a distance of x from it, is I(x). Which one of the graphs represents the variation of I(x) with x correctly?","fig":{"w":340,"h":222,"alt":"Four graphs of I(x) against x: (a) straight line through the origin, (b) upward parabola starting above the origin, (c) upward parabola starting at the origin, (d) straight line with a positive intercept","d":[["l",20,80,140,80,"a"],["l",20,80,20,15,"a"],["t",26,18,"I(x)","s"],["t",142,92,"x","s"],["t",80,100,"(a)","ms"],["l",20,80,120,20],["l",190,80,310,80,"a"],["l",190,80,190,15,"a"],["t",196,18,"I(x)","s"],["t",312,92,"x","s"],["t",250,100,"(b)","ms"],["p","M190 60 Q245 60 290 18"],["l",20,190,140,190,"a"],["l",20,190,20,125,"a"],["t",26,128,"I(x)","s"],["t",142,202,"x","s"],["t",80,210,"(c)","ms"],["p","M20 190 Q75 190 120 138"],["l",190,190,310,190,"a"],["l",190,190,190,125,"a"],["t",196,128,"I(x)","s"],["t",312,202,"x","s"],["t",250,210,"(d)","ms"],["l",190,165,290,142]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":1,"s":"By the parallel axis theorem, I(x) = I_cm + Mx² = {2;5}MR² + Mx².\nAt x = 0, I is not zero: it equals {2;5}MR².\nSo the graph starts at a positive value on the I axis and rises as a parabola (curving upward).\nThis is graph (b). Graph (c) starts at the origin and graph (d) is a straight line, which are wrong."},
{"y":"JEE Main 2018","tp":"pri","st":"Parallel and perpendicular axes","q":"Seven identical circular planar disks, each of mass M and radius R are welded symmetrically as shown. The moment of inertia of the arrangement about the axis normal to the plane and passing through the point P is","fig":{"w":300,"h":180,"alt":"Seven equal discs in a hexagonal pattern with one at the centre O and the point P on the rim of an outer disc, on the line from O","d":[["c",150,90,22],["c",188.1,68,22],["c",150,46,22],["c",111.9,68,22],["c",111.9,112,22],["c",150,134,22],["c",188.1,112,22],["l",150,90,207.2,57,"d"],["c",150,90,2,"F"],["t",146,102,"O","e"],["c",207.2,57,2.5,"F"],["t",212.2,54,"P"]]},"o":["{19;2}MR²","{55;2}MR²","{73;2}MR²","{181;2}MR²"],"c":3,"s":"About the centre O: centre disc ½MR²; each of 6 outer discs ½MR² + M(2R)² = {9;2}MR².\nI_O = ½MR² + 6 · {9;2}MR² = {55;2}MR².\nP is on the rim of an outer disc, so OP = 3R. Total mass is 7M.\nI_P = I_O + 7M(3R)² = {55;2}MR² + 63MR² = {181;2}MR²."},
{"y":"JEE Main 2018","tp":"pri","st":"Radius of gyration and composite bodies","q":"From a uniform circular disc of radius R and mass 9M, a small disc of radius {R;3} is removed as shown in the figure. The moment of inertia of the remaining disc about an axis perpendicular to the plane of the disc and passing through centre of disc is","fig":{"w":340,"h":200,"alt":"Disc of radius R with a small disc of radius R/3 removed from the top so that its centre is 2R/3 above the centre O","d":[["c",150,100,75],["c",150,50,25],["l",65,100,235,100],["l",150,15,150,185],["c",150,100,2,"F"],["t",154,114,"O","s"],["l",150,100,97,153,"a"],["t",116,130,"R","e"],["l",260,100,260,50,"b"],["t",265,79,"2R/3","s"]]},"o":["4MR²","{40;9}MR²","10MR²","{37;9}MR²"],"c":0,"s":"Disc of radius R and mass 9M: I = ½(9M)R² = 4.5MR².\nThe removed disc has area 1/9, so its mass is M. Its centre is 2R/3 from O.\nI_removed = ½M(R/3)² + M(2R/3)² = {MR²;18} + {4MR²;9} = ½MR².\nRemaining I = 4.5MR² − 0.5MR² = 4MR²."},
{"y":"JEE Main 2018 · Online","tp":"pri","st":"Parallel and perpendicular axes","q":"A thin circular disc is in the xy plane as shown in the figure. The ratio of its moment of inertia about z and z′ axis will be","fig":{"w":320,"h":190,"alt":"Circular disc lying in the xy plane with the z axis vertical through its centre O and the z′ axis vertical through a point on its rim","d":[["p","M60 120 A90 28 0 0 1 240 120 A90 28 0 0 1 60 120"],["l",150,120,150,15,"a"],["t",156,18,"z"],["l",240,120,240,15,"a"],["t",246,18,"z′"],["l",150,120,300,120,"a"],["t",298,134,"y"],["l",150,120,100,162,"a"],["t",96,170,"x","e"],["c",150,120,2,"F"],["t",138,116,"O","e"]]},"o":["1 : 4","1 : 3","1 : 2","1 : 5"],"c":1,"s":"The z axis goes through the centre perpendicular to the disc: I_z = ½MR².\nThe z′ axis is parallel to it and passes through the rim, a distance R away.\nI_z′ = ½MR² + MR² = {3;2}MR².\nI_z : I_z′ = ½ : {3;2} = 1 : 3."},
{"y":"JEE Main 2017","tp":"pri","st":"Moment of inertia of bodies","q":"The moment of inertia of a uniform cylinder of length l and radius R about its perpendicular bisector is I. What is the ratio l/R such that the moment of inertia is minimum?","o":["√{3;2}","{√3;2}","1","{3;√2}"],"c":0,"s":"I = M(R²/4 + l²/12). The mass M is fixed, so the volume πR²l is fixed: R² = k/l.\nI/M = k/(4l) + l²/12.\nSet the derivative to zero: −k/(4l²) + l/6 = 0, so k = {2l³;3}.\nThen R² = {2l²;3}, so l²/R² = {3;2}.\nl/R = √{3;2}."},
{"y":"JEE Main 2017 · Online","tp":"pri","st":"Radius of gyration and composite bodies","q":"Moment of inertia of an equilateral triangular lamina ABC, about the axis passing through its center O and perpendicular to its plane is I₀ as shown in the figure. A cavity DEF is cut out from the lamina, where D, E, F are the mid points of the sides. Moment of inertia of the remaining part of lamina about the same axis is","fig":{"w":300,"h":195,"alt":"Equilateral triangular lamina ABC with C at the top, mid-points D, E, F of its sides joined by dashed lines, and the centre O","d":[["p","M170 14 L80 170 L260 170 Z"],["p","M125 92 L215 92 L170 170 Z","d"],["c",170,118,2,"F"],["t",176,114,"O","s"],["t",170,10,"C","m"],["t",70,178,"A"],["t",262,178,"B"],["t",112,96,"F","e"],["t",220,96,"E"],["t",170,186,"D","m"]]},"o":["{7I₀;8}","{31I₀;32}","{3I₀;4}","{15I₀;16}"],"c":3,"s":"I of a triangle about its centre is proportional to m a².\nThe cavity DEF has half the side, so a quarter of the area and mass, and its centre is also O.\nI_cavity = {1;4} · {1;4}I₀ = {I₀;16}.\nRemaining part: I₀ − {I₀;16} = {15I₀;16}."},
{"y":"JEE Main 2017 · Online","tp":"pri","st":"Radius of gyration and composite bodies","q":"A circular hole of radius {R;4} is made in a thin uniform disc having mass M and radius R, as shown in figure. The moment of inertia of the remaining portion of the disc about an axis passing through the point O and perpendicular to the plane of the disc is","fig":{"w":340,"h":190,"alt":"Disc of radius R with centre O and a hole of radius R/4 whose centre O′ is 3R/4 from O, touching the rim","d":[["c",150,95,80],["c",210,95,20],["l",65,95,235,95],["l",150,10,150,180],["c",150,95,2,"F"],["t",143,108,"O","e"],["t",210,91,"O′","ms"],["t",236,106,"R/4","s"],["l",150,95,96,38,"a"],["t",112,60,"R","e"],["l",150,128,210,128,"b"],["t",180,144,"3R/4","ms"]]},"o":["{219MR²;256}","{197MR²;256}","{19MR²;512}","{237MR²;512}"],"c":3,"s":"Area is proportional to r², so the hole (radius R/4) has 1/16 of the area. Its mass is M/16.\nWhole disc: ½MR².\nHole about O: ½ · {M;16} · (R/4)² + {M;16} · (3R/4)² = {MR²;512} + {9MR²;256} = {19MR²;512}.\nRemaining: ½MR² − {19MR²;512} = {237MR²;512}."},
{"y":"JEE Main 2015","tp":"pri","st":"Moment of inertia of bodies","q":"From a solid sphere of mass M and radius R a cube of maximum possible volume is cut. Moment of inertia of cube about an axis passing through its centre and perpendicular to one of its faces is","o":["{4MR²;9√3π}","{4MR²;3√3π}","{MR²;32√2π}","{MR²;16√2π}"],"c":0,"s":"The largest cube has its body diagonal equal to the diameter 2R. So √3 a = 2R and a = {2R;√3}.\nMass of the cube: m = M · a³/({4;3}πR³) = {2M;√3π}.\nI about an axis through the centre perpendicular to a face = {ma²;6}.\nI = {1;6} · {2M;√3π} · {4R²;3} = {4MR²;9√3π}."},
{"y":"JEE Main 2015 · Online","tp":"pri","st":"Parallel and perpendicular axes","q":"Consider a thin uniform square sheet made of a rigid material. If its side is a, mass m and moment of inertia I about one of its diagonals, then","o":["I > {ma²;12}","{ma²;24} < I < {ma²;12}","I = {ma²;12}","I = {ma²;24}"],"c":2,"s":"About an axis through the centre and perpendicular to the sheet, I_z = {ma²;6}.\nBy symmetry, any two perpendicular axes in the plane through the centre have equal I (the diagonals, or the lines parallel to the sides).\nPerpendicular axis theorem: I + I = I_z, so I = {ma²;12}."},
{"y":"AIEEE 2008","tp":"pri","st":"Parallel and perpendicular axes","q":"Consider a uniform square plate of side a and mass m. The moment of inertia of this plate about an axis perpendicular to its plane and passing through one of its corners is","o":["{2;3}ma²","{5;6}ma²","{1;12}ma²","{7;12}ma²"],"c":0,"s":"About the centre, perpendicular to the plate: I = {ma²;6}.\nThe corner is a distance a/√2 from the centre, so d² = a²/2.\nI = {ma²;6} + m · {a²;2} = {2;3}ma²."},
{"y":"AIEEE 2007","tp":"pri","st":"Parallel and perpendicular axes","q":"For the given uniform square lamina ABCD, whose centre is O,","fig":{"w":300,"h":185,"alt":"Square lamina ABCD with centre O, its diagonal AC dashed and a dashed line EF through the mid-points of the top and bottom sides","d":[["r",110,25,120,120],["l",110,145,230,25,"d"],["l",170,25,170,145,"d"],["c",170,85,2,"F"],["t",176,92,"O","s"],["t",104,22,"D","e"],["t",236,22,"C"],["t",104,158,"A","e"],["t",236,158,"B"],["t",170,18,"F","m"],["t",170,162,"E","m"]]},"o":["I_AC = √2 I_EF","√2 I_AC = I_EF","I_AD = 3I_EF","I_AC = I_EF"],"c":3,"s":"Both AC (a diagonal) and EF (a line through the mid-points of opposite sides) lie in the plane of the lamina and pass through the centre O.\nFor a square, I about any axis in its plane through the centre is the same, equal to {ma²;12}.\nSo I_AC = I_EF."},
{"y":"AIEEE 2006","tp":"pri","st":"Parallel and perpendicular axes","q":"Four point masses, each of value m, are placed at the corners of a square ABCD of side l. The moment of inertia of this system about an axis through A and parallel to BD is","o":["ml²","2ml²","√3ml²","3ml²"],"c":3,"s":"The diagonal BD has length l√2. The axis through A parallel to BD is at distance l/√2 from B and D, and l√2 from C.\nA is on the axis: 0.\nB and D: 2 · m(l/√2)² = ml².\nC: m(l√2)² = 2ml².\nI = ml² + 2ml² = 3ml²."},
{"y":"IIT-JEE 2006","tp":"pri","st":"Moment of inertia of bodies","q":"A solid sphere of mass M and radius R having moment of inertia I about its diameter is recast into a solid disc of radius r and thickness t. The moment of inertia of the disc about an axis passing through its edge and perpendicular to the plane remains I. Then R and r are related as","o":["r = √{2;15}R","r = {2;√15}R","r = {2;15}R","r = {√2;15}R"],"c":1,"s":"The mass is unchanged. Sphere: I = {2;5}MR².\nDisc about an axis through its edge, perpendicular to its plane: I = ½Mr² + Mr² = {3;2}Mr².\nEquate: {3;2}r² = {2;5}R², so r² = {4R²;15}.\nr = {2;√15}R."},
{"y":"IIT-JEE 2005","tp":"pri","st":"Moment of inertia of bodies","q":"The moment of inertia of a uniform semicircular disc of mass M and radius r about a line perpendicular to the plane of the disc through the center is","o":["Mr²","{1;2}Mr²","{1;4}Mr²","{2;5}Mr²"],"c":1,"s":"Two such semicircular discs make a full disc of mass 2M, with I = ½(2M)r² = Mr² about the centre.\nBy symmetry each half contributes equally, so the semicircle has I = ½Mr².\n(Every bit of mass is at the same distances from the centre as in the full disc, so only the mass changes.)"},
{"y":"IIT-JEE 2005","tp":"pri","st":"Radius of gyration and composite bodies","q":"From a circular disc of radius R and mass 9M, a small disc of radius R/3 is removed from the disc. The moment of inertia of the remaining disc about an axis perpendicular to the plane of the disc and passing through O is","fig":{"w":340,"h":200,"alt":"Disc of radius R with a small disc of radius R/3 removed from the top so that its centre is 2R/3 above the centre O","d":[["c",150,100,75],["c",150,50,25],["l",65,100,235,100],["l",150,15,150,185],["c",150,100,2,"F"],["t",154,114,"O","s"],["l",150,100,97,153,"a"],["t",116,130,"R","e"],["l",260,100,260,50,"b"],["t",265,79,"2R/3","s"]]},"o":["4MR²","{40;9}MR²","10MR²","{37;9}MR²"],"c":0,"s":"Disc of radius R and mass 9M: I = ½(9M)R² = 4.5MR².\nThe removed disc has mass M and its centre is 2R/3 from O.\nI_removed = ½M(R/3)² + M(2R/3)² = {MR²;18} + {4MR²;9} = ½MR².\nRemaining I = 4.5MR² − 0.5MR² = 4MR²."},
{"y":"AIEEE 2004","tp":"pri","st":"Moment of inertia of bodies","q":"One solid sphere A and another hollow sphere B are of same mass and same outer radii. Their moment of inertia about their diameters are respectively I_A and I_B such that","o":["I_A = I_B","I_A > I_B","I_A < I_B","I_A/I_B = d_A/d_B"],"c":2,"s":"Same mass and same outer radius: the hollow sphere has its mass farther from the axis.\nSolid sphere: I_A = {2;5}MR² = 0.4MR². Hollow sphere: I_B is larger (up to {2;3}MR² for a thin shell).\nSo I_A < I_B.\n(d_A and d_B are densities. Since masses are equal, d_A ≠ d_B in general, and the ratio of I is not d_A/d_B.)"},
{"y":"AIEEE 2003","tp":"pri","st":"Moment of inertia of bodies","q":"A circular disc X of radius R is made from an iron plate of thickness t, and another disc Y of radius 4R is made from an iron plate of thickness t/4. Then the relation between the moment of inertia I_X and I_Y is","o":["I_Y = 32I_X","I_Y = 16I_X","I_Y = I_X","I_Y = 64I_X"],"c":3,"s":"Mass = density × π r² × thickness. M_X ∝ R²t and M_Y ∝ 16R² · t/4 = 4R²t, so M_Y = 4M_X.\nI = ½MR². I_X = ½M_X R².\nI_Y = ½(4M_X)(4R)² = 64 · ½M_X R².\nI_Y = 64I_X."},
{"y":"AIEEE 2002","tp":"pri","st":"Moment of inertia of bodies","q":"Moment of inertia of a circular wire of mass M and radius R about its diameter is","o":["MR²/2","MR²","2MR²","MR²/4"],"c":0,"s":"About the axis through the centre perpendicular to the plane, I = MR².\nBy symmetry the two perpendicular diameters have equal I.\nPerpendicular axis theorem: 2I_d = MR², so I_d = MR²/2."},
{"y":"IIT-JEE 2001","tp":"pri","st":"Moment of inertia of bodies","q":"One quarter sector is cut from a uniform circular disc of radius R. This sector has mass M. It is made to rotate about a line perpendicular to its plane and passing through the center of the original disc. Its moment of inertia about the axis of rotation is","fig":{"w":300,"h":200,"alt":"A quarter sector of a disc with its apex at the centre of the original disc and a rotation axis perpendicular to the page through the apex","d":[["p","M110 100 L173.6 36.4 A90 90 0 0 1 173.6 163.6 Z","f"],["c",110,100,5],["c",110,100,1.5,"F"],["t",104,86,"axis","es"],["t",150,104,"R"],["p","M92 70 A28 28 0 0 1 128 70","a"]]},"o":["{1;2}MR²","{1;4}MR²","{1;8}MR²","√2MR²"],"c":0,"s":"A full disc of mass 4M and radius R has I = ½(4M)R² = 2MR² about its centre.\nBy symmetry, each quarter contributes equally: I = {2MR²;4} = ½MR².\nSo I = {1;2}MR²; the shape of the sector does not matter, only that every bit of mass is at the same distance from the axis as in the full disc."},
{"y":"IIT-JEE 2000","tp":"pri","st":"Parallel and perpendicular axes","q":"A thin wire of length L and uniform linear mass density ρ is bent into a circular loop with centre at O as shown. The moment of inertia of the loop about the axis XX′ is","fig":{"w":300,"h":170,"alt":"Circular loop with centre O and a tangent line XX′ touching the top of the loop at a right angle to the radius","d":[["c",150,95,60],["l",50,35,260,35],["l",150,35,150,95,"d"],["p","M150 45 H160 V35"],["c",150,95,2,"F"],["t",156,108,"O","s"],["t",44,32,"X","e"],["t",264,32,"X′"]]},"o":["{ρL³;8π²}","{ρL³;16π²}","{5ρL³;16π²}","{3ρL³;8π²}"],"c":3,"s":"Circumference L = 2πR, so R = {L;2π}, and the mass is M = ρL.\nXX′ is a tangent, a distance R from the centre and parallel to a diameter axis.\nI = {1;2}MR² (about a diameter) + MR² = {3;2}MR².\nI = {3;2}ρL · {L²;4π²} = {3ρL³;8π²}."},
{"y":"IIT-JEE 1995","tp":"pri","st":"Radius of gyration and composite bodies","q":"Two point masses of 0.3 kg and 0.7 kg are fixed at the ends of a rod of length 1.4 m and of negligible mass. The rod is set rotating about an axis perpendicular to its length with a uniform angular speed. The point on the rod through which the axis should pass in order that the work required for rotation of the rod is minimum, is located at a distance of","o":["0.42 m from mass of 0.3 kg","0.70 m from mass of 0.7 kg","0.98 m from mass of 0.3 kg","0.98 m from mass of 0.7 kg"],"c":2,"s":"Work needed for a given ω is ½Iω², so it is minimum when I is minimum.\nFor a fixed direction of the axis, I is smallest when the axis passes through the centre of mass.\nDistance of the CM from the 0.3 kg mass = (0.7 × 1.4)/(0.3 + 0.7) = 0.98 m.\nSo the axis passes 0.98 m from the 0.3 kg mass."},
{"y":"IIT-JEE 1998","tp":"pri","st":"Parallel and perpendicular axes","q":"Let I be the moment of inertia of a uniform square plate about an axis AB that passes through its centre and is parallel to two of its sides. CD is a line in the plane of the plate that passes through the centre of the plate and makes an angle θ with AB. The moment of inertia of the plate about the axis CD is then equal to","o":["I","I sin²θ","I cos²θ","I cos²(θ/2)"],"c":[0],"s":"For a square plate, the moment of inertia is the same about every axis in its plane through the centre.\nProof: the perpendicular axis theorem gives I_AB + I_perp = I_z, and symmetry gives I_AB = I_perp. For an axis at angle θ, the inertia tensor in the plane is a multiple of the identity, so I_CD = I_AB cos²θ + I_perp sin²θ = I.\nSo I_CD = I."},
{"y":"IIT-JEE 1992","tp":"pri","st":"Parallel and perpendicular axes","q":"The moment of inertia of a thin square plate ABCD, as shown in the figure, of uniform thickness about an axis passing through the centre O and perpendicular to the plane of the plate is (where I₁, I₂, I₃ and I₄ are respectively the moments of inertia about axis 1, 2, 3 and 4 which are in the plane of the plate)","fig":{"w":300,"h":190,"alt":"Square plate ABCD with centre O and four axes in its plane through O: axis 1 along the diagonal towards the top right, axis 2 along the other diagonal towards the bottom right, axis 3 horizontal and axis 4 vertical","d":[["r",110,30,120,120],["l",170,150,170,12,"a"],["t",176,12,"4"],["l",100,90,262,90,"a"],["t",266,94,"3"],["l",95,165,245,15,"a"],["t",250,16,"1"],["l",95,15,245,165,"a"],["t",250,172,"2"],["c",170,90,2,"F"],["t",162,104,"O","s"],["t",104,28,"A","e"],["t",236,28,"B"],["t",236,148,"C"],["t",104,150,"D","e"]]},"o":["I₁ + I₂","I₃ + I₄","I₁ + I₃","I₁ + I₂ + I₃ + I₄"],"c":[0,1,2],"s":"Perpendicular axis theorem: for any two perpendicular axes in the plane through O, I₁ + I₂ = I_z.\nAxes 1 and 2 are perpendicular (the diagonals), axes 3 and 4 are perpendicular (parallel to the sides).\nSo I_z = I₁ + I₂ = I₃ + I₄.\nBy symmetry I₁ = I₂ = I₃ = I₄, so I₁ + I₃ is also equal to I_z.\nOptions (a), (b) and (c) are correct; (d) gives 2I_z."},
{"y":"JEE Main 2025 · 7 Apr · Shift 1","tp":"pri","st":"Radius of gyration and composite bodies","q":"A, B and C are disc, solid sphere and spherical shell respectively with same radii and masses. These masses are placed as shown in figure.\nThe moment of inertia of the given system about PQ axis is {x;15}I, where I is the moment of inertia of the disc about its diameter. The value of x is ______.","fig":{"w":300,"h":190,"alt":"Disc A on top and solid sphere B and spherical shell C below it, all touching, with a vertical axis PQ through the centre of A and the contact point of B and C","d":[["c",150,58,28,"f"],["c",122,106.5,28],["c",178,106.5,28],["l",122,106.5,178,106.5,"d"],["l",150,58,122,106.5,"d"],["l",150,58,178,106.5,"d"],["c",150,58,2,"F"],["l",150,10,150,178],["t",156,16,"P"],["t",156,176,"Q"],["t",150,62,"A","ms"],["t",122,110,"B","ms"],["t",178,110,"C","ms"]]},"n":199,"s":"Let each have mass M and radius R. Disc about its diameter: I = {MR²;4}.\nThe axis PQ is a diameter of A: I_A = {MR²;4}.\nB and C have their centres a distance R from PQ (their centres are 2R apart and PQ passes between them).\nB (solid sphere): {2;5}MR² + MR² = {7;5}MR². C (shell): {2;3}MR² + MR² = {5;3}MR².\nTotal = MR²({1;4} + {7;5} + {5;3}) = {199;60}MR² = {199;15}I (since MR² = 4I).\nx = 199."},
{"y":"JEE Main 2025 · 7 Apr · Shift 2","tp":"pri","st":"Radius of gyration and composite bodies","q":"M and R be the mass and radius of a disc. A small disc of radius R/3 is removed from the bigger disc as shown in figure. The moment of inertia of remaining part of bigger disc about an axis AB passing through the centre O and perpendicular to the plane of disc is {4;x}MR². The value of x is ______.","fig":{"w":300,"h":205,"alt":"Disc of radius R with a small disc of radius R/3 removed at the left edge, centre O and a vertical line AB through O","d":[["c",150,100,80],["c",97,100,27],["l",60,100,235,100,"d"],["l",150,12,150,190],["t",150,8,"A","ms"],["t",150,200,"B","ms"],["c",150,100,2,"F"],["t",156,96,"O","s"],["t",97,88,"O′","ms"],["t",97,122,"R/3","ms"],["l",150,100,206,156,"a"],["t",184,142,"R"]]},"n":9,"s":"Mass of the removed disc: area ratio (1/3)² = 1/9, so its mass is {M;9}.\nIts centre O′ is at R − R/3 = 2R/3 from O.\nI_removed = ½ · {M;9} · (R/3)² + {M;9} · (2R/3)² = {MR²;162} + {4MR²;81} = {MR²;18}.\nRemaining: ½MR² − {MR²;18} = {4;9}MR².\nSo x = 9."},
{"y":"JEE Main 2025 · 28 Jan · Shift 1","tp":"pri","st":"Moment of inertia of bodies","q":"The moment of inertia of a solid disc rotating along its diameter is 2.5 times higher than the moment of inertia of a ring rotating in similar way. The moment of inertia of a solid sphere which has same radius as the disc and rotating in similar way, is n times higher than the moment of inertia of the given ring. Here, n = ______.\nConsider all the bodies have equal masses.","n":4,"s":"Disc about a diameter: {Mr₁²;4}. Ring about a diameter: {Mr₂²;2}.\nGiven: {r₁²;4} = 2.5 · {r₂²;2}, so r₁² = 5r₂².\nSolid sphere with the disc's radius: I = {2;5}Mr₁² = {2;5} · 5 · Mr₂² = 2Mr₂².\nn = I_sphere/I_ring = 2Mr₂² / ({Mr₂²;2}) = 4."},
{"y":"JEE Main 2025 · 28 Jan · Shift 2","tp":"pri","st":"Moment of inertia of bodies","q":"Two iron solid discs of negligible thickness have radii R₁ and R₂ and moment of inertia I₁ and I₂, respectively. For R₂ = 2R₁, the ratio of I₁ and I₂ would be 1/x, where x = ______.","n":16,"s":"Both discs are iron (same density) and, being thin, are taken to have the same thickness.\nThen mass is proportional to R², and I = ½MR² is proportional to R⁴.\nI₂/I₁ = (R₂/R₁)⁴ = 2⁴ = 16.\nSo I₁/I₂ = 1/16 and x = 16."},
{"y":"JEE Main 2024 · 6 Apr · Shift 2","tp":"pri","st":"Radius of gyration and composite bodies","q":"Three balls of masses 2 kg, 4 kg and 6 kg respectively are arranged at centre of the edges of an equilateral triangle of side 2 m. The moment of inertia of the system about an axis through the centroid and perpendicular to the plane of triangle, will be ______ kg m².","n":4,"s":"The centroid of an equilateral triangle is at distance (inradius) = side/(2√3) = 1/√3 m from the mid-point of each side.\nSo r² = {1;3} m² for all three balls.\nI = (2 + 4 + 6) × {1;3} = 12 × {1;3} = 4 kg m²."},
{"y":"JEE Main 2024 · 1 Feb · Shift 2","tp":"prd","st":"Torque and angular acceleration","q":"A uniform rod AB of mass 2 kg and length 30 cm at rest on a smooth horizontal surface. An impulse of force 0.2 Ns is applied to end B. The time taken by the rod to turn through at right angles will be {π;x} s, where x = ______.","n":4,"s":"Surface is smooth, so the impulse J acts perpendicular to the rod at B and gives angular momentum about the centre of mass.\nJ · (L/2) = I_cm ω with I_cm = {mL²;12}.\n0.2 × 0.15 = {2 × 0.09;12} ω, so 0.03 = 0.015ω and ω = 2 rad/s.\nAngle π/2 at constant ω: t = ({π;2})/2 = {π;4} s.\nx = 4."},
{"y":"JEE Main 2024 · 27 Jan · Shift 1","tp":"pri","st":"Parallel and perpendicular axes","q":"Four particles each of mass 1 kg are placed at four corners of a square of side 2 m. Moment of inertia of system about an axis perpendicular to its plane and passing through one of its vertex is ______ kgm².","n":16,"s":"Distances of the four particles from the axis through one vertex: 0, 2 m, 2 m and 2√2 m (the diagonal).\nI = Σ m r² = 1(0)² + 1(2)² + 1(2)² + 1(2√2)²\nI = 0 + 4 + 4 + 8 = 16 kg m².\nAnswer: 16."},
{"y":"JEE Main 2024 · 31 Jan · Shift 2","tp":"pri","st":"Parallel and perpendicular axes","q":"Two identical spheres each of mass 2 kg and radius 50 cm are fixed at the ends of a light rod so that the separation between the centers is 150 cm. Then, moment of inertia of the system about an axis perpendicular to the rod and passing through its middle point is {x;20} kg m², where the value of x is ______.","n":53,"s":"One sphere about its own diameter: {2;5}mr² = {2;5}(2)(0.5)² = 0.2 kg m².\nIts centre is 0.75 m from the middle point, so by the parallel axis theorem add md² = 2(0.75)² = 1.125 kg m².\nOne sphere: 0.2 + 1.125 = 1.325 kg m². Two spheres: 2.65 kg m².\n2.65 = x/20 gives x = 53.\nAnswer: 53."},
{"y":"JEE Main 2023 · 6 Apr · Shift 1","tp":"pri","st":"Parallel and perpendicular axes","q":"Two identical solid spheres each of mass 2 kg and radii 10 cm are fixed at the ends of a light rod. The separation between the centres of the spheres is 40 cm. The moment of inertia of the system about an axis perpendicular to the rod passing through its middle point is ______ × 10⁻³ kg-m².","n":176,"s":"One sphere about its own diameter: {2;5}mr² = {2;5}(2)(0.1)² = 0.008 kg m².\nEach centre is 0.2 m from the middle point: md² = 2(0.2)² = 0.08 kg m².\nOne sphere: 0.088 kg m². Two spheres: 0.176 kg m² = 176 × 10⁻³ kg m².\nAnswer: 176."},
{"y":"JEE Main 2023 · 6 Apr · Shift 2","tp":"pri","st":"Radius of gyration and composite bodies","q":"A ring and a solid sphere rotating about an axis passing through their centres have same radii of gyration. The axis of rotation is perpendicular to plane of ring. The ratio of radius of ring to that of sphere is √{2;x}. The value of x is ______.","n":5,"s":"Radius of gyration k is defined by I = Mk².\nRing about the axis through its centre perpendicular to its plane: I = MR₁², so k² = R₁².\nSolid sphere about a diameter: I = {2;5}MR₂², so k² = {2;5}R₂².\nEqual k gives R₁² = {2;5}R₂², so R₁/R₂ = √{2;5}.\nComparing with √{2;x}: x = 5.\nAnswer: 5."},
{"y":"JEE Main 2023 · 8 Apr · Shift 1","tp":"pri","st":"Moment of inertia of bodies","q":"The moment of inertia of a semicircular ring about an axis, passing through the center and perpendicular to the plane of the ring is {1;x}MR², where R is the radius and M is the mass of the semicircular ring. The value of x will be ______.","n":1,"s":"Every mass element of the semicircular ring is at the same distance R from the axis through the centre of the circle, perpendicular to its plane.\nSo I = ΣΔm R² = MR².\nComparing with {1;x}MR²: x = 1.\nAnswer: 1."},
{"y":"JEE Main 2023 · 15 Apr · Shift 1","tp":"pri","st":"Radius of gyration and composite bodies","q":"A solid sphere and a solid cylinder of same mass and radius are rolling on a horizontal surface without slipping. The ratio of their radius of gyrations respectively (k_sph : k_cyl) is 2 : √x. The value of x is ______.","n":5,"s":"Radius of gyration about the axis of rotation: k² = I/M.\nSolid sphere: k² = {2;5}R². Solid cylinder: k² = {1;2}R².\nk_sph/k_cyl = √({2;5} ÷ {1;2}) = √{4;5} = 2/√5.\nSo k_sph : k_cyl = 2 : √5 and x = 5.\nAnswer: 5."},
{"y":"JEE Main 2023 · 1 Feb · Shift 2","tp":"pri","st":"Parallel and perpendicular axes","q":"Moment of inertia of a disc of mass M and radius 'R' about any of its diameter is {MR²;4}. The moment of inertia of this disc about an axis normal to the disc and passing through a point on its edge will be, {x;2}MR². The value of x is ______.","n":3,"s":"Perpendicular axis theorem for the disc: I (normal, through centre) = I₁ + I₂ = {MR²;4} + {MR²;4} = {MR²;2}.\nParallel axis theorem to a point on the edge (distance R): I = {MR²;2} + MR² = {3;2}MR².\nComparing with {x;2}MR²: x = 3.\nAnswer: 3."},
{"y":"JEE Main 2023 · 24 Jan · Shift 1","tp":"pri","st":"Radius of gyration and composite bodies","q":"Solid sphere A is rotating about an axis PQ. If the radius of the sphere is 5 cm, then its radius of gyration about PQ will be √x cm. The value of x is ______.","fig":{"w":340,"h":175,"alt":"A solid sphere A of radius 5 cm whose centre is 10 cm from the vertical axis PQ about which it rotates","d":[["l",70,15,70,150],["t",78,22,"P",""],["t",78,150,"Q",""],["c",250,70,22],["c",250,70,2.5,"F"],["t",250,38,"A","m"],["l",250,92,250,135,"d"],["l",70,125,250,125,"b"],["t",160,119,"10 cm","ms"],["l",250,48,250,70,"d"],["l",250,70,272,70,"d"],["t",262,66,"5 cm","ms"]]},"n":110,"s":"The centre of the sphere is 10 cm from the axis PQ (see figure).\nI = {2;5}Mr² + Md² = {2;5}M(5)² + M(10)² = 10M + 100M = 110M (in cm² units).\nI = Mk², so k² = 110 and k = √110 cm.\nHence x = 110.\nAnswer: 110."},
{"y":"JEE Main 2023 · 24 Jan · Shift 2","tp":"pri","st":"Radius of gyration and composite bodies","q":"A uniform solid cylinder with radius R and length L has moment of inertia I₁, about the axis of the cylinder. A concentric solid cylinder of radius R′ = {R;2} and length L′ = {L;2} is carved out of the original cylinder. If I₂ is the moment of inertia of the carved out portion of the cylinder then {I₁;I₂} = ______.\n(Both I₁ and I₂ are about the axis of the cylinder)","n":32,"s":"Mass is proportional to volume. The carved part has volume (R/2)²(L/2) = {1;8} of the original, so its mass is M/8.\nI₁ = {1;2}MR².\nI₂ = {1;2}({M;8})({R;2})² = {MR²;64}.\nI₁/I₂ = (1/2)/(1/64) = 32.\nAnswer: 32."},
{"y":"JEE Main 2023 · 25 Jan · Shift 1","tp":"pri","st":"Parallel and perpendicular axes","q":"I_CM is the moment of inertia of a circular disc about an axis (CM) passing through its center and perpendicular to the plane of the disc. I_AB is it's moment of inertia about an axis AB perpendicular to plane and parallel to axis CM at a distance {2;3}R from center. Where R is the radius of the disc. The ratio of I_AB and I_CM is x : 9. The value of x is ______.","fig":{"w":300,"h":215,"alt":"A circular disc of radius R with a vertical axis CM through its centre and a parallel axis AB at a distance 2R/3 to the right of the centre","d":[["c",120,105,75],["c",120,105,2.5,"F"],["l",120,18,120,190,"d"],["l",170,18,170,190,"d"],["c",170,105,2.5,"F"],["l",120,105,45,105],["t",82,99,"R","ms"],["l",120,150,170,150,"b"],["t",145,168,"2R/3","ms"],["t",120,13,"C","m"],["t",170,13,"A","m"],["t",120,206,"M","m"],["t",170,206,"B","m"]]},"n":17,"s":"I_CM = {1;2}MR².\nParallel axis theorem with d = {2;3}R: I_AB = {1;2}MR² + M({2;3}R)² = ({1;2} + {4;9})MR² = {17;18}MR².\nI_AB / I_CM = {17;18} ÷ {1;2} = {17;9}.\nComparing with x : 9, x = 17.\nAnswer: 17."},
{"y":"JEE Main 2023 · 25 Jan · Shift 2","tp":"pri","st":"Parallel and perpendicular axes","q":"If a solid sphere of mass 5 kg and a disc of mass 4 kg have the same radius. Then the ratio of moment of inertia of the disc about a tangent in its plane to the moment of inertia of the sphere about its tangent will be {x;7}. Then the value of x is ______.","n":5,"s":"Disc about a tangent in its plane: I = {1;4}MR² + MR² = {5;4}MR² = {5;4}(4)R² = 5R².\nSolid sphere about a tangent: I = {2;5}MR² + MR² = {7;5}MR² = {7;5}(5)R² = 7R².\nRatio = 5R² / 7R² = {5;7}.\nComparing with {x;7}: x = 5.\nAnswer: 5."},
{"y":"JEE Main 2023 · 31 Jan · Shift 2","tp":"pri","st":"Moment of inertia of bodies","q":"Two discs of same mass and different radii are made of different materials such that their thicknesses are 1 cm and 0.5 cm respectively. The densities of materials are in the ratio 3 : 5. The moment of inertia of these discs respectively about their diameters will be in the ratio of x/6. The value of x is ______.","n":5,"s":"Mass m = ρ(πr²)t, so with equal masses r² = m/(πρt), i.e. r² ∝ 1/(ρt).\nρ₁t₁ : ρ₂t₂ = (3)(1) : (5)(0.5) = 3 : 2.5 = 6 : 5.\nSo r₁²/r₂² = 5/6.\nAbout a diameter I = {1;4}mr², so I₁/I₂ = r₁²/r₂² = 5/6.\nComparing with x/6: x = 5.\nAnswer: 5."},
{"y":"JEE Main 2022 · 26 Jul · Shift 2","tp":"pri","st":"Radius of gyration and composite bodies","q":"The radius of gyration of a cylindrical rod about an axis of rotation perpendicular to its length and passing through the center will be ______ m.\nGiven, the length of the rod is 10√3 m.","n":5,"s":"For a rod about a perpendicular axis through its centre, I = {ML²;12}.\nSince I = Mk², k² = {L²;12}, so k = L/(2√3).\nk = 10√3 / (2√3) = 5 m.\nAnswer: 5."},
{"y":"JEE Main 2022 · 28 Jul · Shift 1","tp":"pri","st":"Radius of gyration and composite bodies","q":"Four identical discs each of mass 'M' and diameter 'a' are arranged in a small plane as shown in figure. If the moment of inertia of the system about OO′ is {x;4}Ma². Then, the value of x will be ______.","fig":{"w":200,"h":260,"alt":"Four identical touching discs: one at the top and one at the bottom on the vertical axis OO', and two side by side in the middle, each half a diameter from the axis","d":[["l",100,18,100,242,"d"],["t",108,16,"O",""],["t",108,246,"O′",""],["c",100,70,28],["c",72,118.5,28],["c",128,118.5,28],["c",100,167,28]]},"n":3,"s":"From the figure the top and bottom discs have their centres on OO′. The two side discs touch each other on OO′, so their centres are a/2 from OO′.\nA disc about its diameter: {1;4}M({a;2})² = {Ma²;16}.\nTop and bottom discs: 2 × {Ma²;16} = {Ma²;8}.\nEach side disc (parallel axis, d = a/2): {Ma²;16} + M({a;2})² = {5Ma²;16}; two of them: {5Ma²;8}.\nTotal I = {Ma²;8} + {5Ma²;8} = {3;4}Ma², so x = 3.\nAnswer: 3."},
{"y":"JEE Main 2022 · 25 Jun · Shift 2","tp":"pri","st":"Moment of inertia of bodies","q":"Moment of Inertia (M.I.) of four bodies having same mass 'M' and radius '2R' are as follows\nI₁ = M.I. of solid sphere about its diameter\nI₂ = M.I. of solid cylinder about its axis\nI₃ = M.I. of solid circular disc about its diameter\nI₄ = M.I. of thin circular ring about its diameter\nIf 2(I₂ + I₃) + I₄ = x·I₁, then the value of x will be ______.","n":5,"s":"Let K = M(2R)². Then:\nI₁ = {2;5}K = 0.4K, I₂ = {1;2}K = 0.5K, I₃ = {1;4}K = 0.25K, I₄ = {1;2}K = 0.5K.\n2(I₂ + I₃) + I₄ = 2(0.75K) + 0.5K = 2K.\nx·I₁ = 0.4xK = 2K, so x = 5.\nAnswer: 5."},
{"y":"JEE Main 2022 · 29 Jun · Shift 2","tp":"pri","st":"Moment of inertia of bodies","q":"The moment of inertia of a uniform thin rod about a perpendicular axis passing through one end is I₁. The same rod is bent into a ring and its moment of inertia about a diameter is I₂. If {I₁;I₂} is {xπ²;3}, then the value of x will be ______.","n":8,"s":"Let the rod have mass m and length l. I₁ = {ml²;3}.\nBent into a ring: 2πr = l, so r = l/(2π).\nRing about a diameter: I₂ = {1;2}mr² = {ml²;8π²}.\nI₁/I₂ = {l²/3;l²/(8π²)} = {8π²;3}.\nComparing with {xπ²;3}: x = 8.\nAnswer: 8."},
{"y":"JEE Main 2021 · 26 Aug · Shift 1","tp":"pri","st":"Parallel and perpendicular axes","q":"Consider a badminton racket with length scales as shown in the figure.\nIf the mass of the linear and circular portions of the badminton racket are same (M) and the mass of the threads are negligible, the moment of inertia of the racket about an axis perpendicular to the handle and in the plane of the ring at, {r;2} distance from the end A of the handle will be ______ Mr².","fig":{"w":340,"h":150,"alt":"Badminton racket: a handle of length 6r from end A to a ring of diameter 2r, with a rotation axis marked at r/2 from A","d":[["l",20,12,20,138],["l",35,12,35,138,"d"],["l",20,66,200,66,"B"],["c",230,66,30],["c",230,66,24,"d"],["t",10,70,"A","e"],["t",230,28,"P","m"],["l",200,95,200,140,"d"],["l",260,95,260,140,"d"],["l",20,100,35,100,"b"],["t",27,116,"r/2","ms"],["l",20,134,200,134,"b"],["t",110,128,"6r","ms"],["l",200,100,260,100,"b"],["t",230,116,"2r","ms"]]},"n":52,"s":"Handle: rod of length 6r, mass M, centre at 3r from A, so 2.5r from the axis (which is r/2 from A).\nI(rod) = {M(6r)²;12} + M(2.5r)² = 3Mr² + 6.25Mr² = 9.25Mr².\nRing: radius r, centre at 6r + r = 7r from A, so d = 6.5r from the axis. The axis is in the plane of the ring, so about its own diameter I = {1;2}Mr².\nI(ring) = {1;2}Mr² + M(6.5r)² = 0.5Mr² + 42.25Mr² = 42.75Mr².\nTotal I = 9.25 + 42.75 = 52 Mr².\nAnswer: 52."},
{"y":"JEE Main 2021 · 24 Feb · Shift 2","tp":"pri","st":"Parallel and perpendicular axes","q":"A uniform thin bar of mass 6 kg and length 2.4 meter is bent to make an equilateral hexagon. The moment of inertia about an axis passing through the centre of mass and perpendicular to the plane of hexagon is ______ × 10⁻¹ kg m².","n":8,"s":"Each side has length 2.4/6 = 0.4 m and mass 1 kg.\nDistance of each side from the centre (apothem) = {√3;2}(0.4), so d² = 0.12 m².\nOne side: {ml²;12} + md² = {0.16;12} + 0.12 = 0.1333 kg m².\nSix sides: 6 × 0.1333 = 0.8 kg m² = 8 × 10⁻¹ kg m².\nAnswer: 8."},
{"y":"JEE Main 2020 · 3 Sep · Shift 2","tp":"pri","st":"Parallel and perpendicular axes","q":"An massless equilateral triangle EFG of side 'a' (As shown in figure) has three particles of mass m situated at its vertices. The moment of inertia of the system about the line EX perpendicular to EG in the plane of EFG is {N;20}ma² where N is an integer. The value of N is ______.","fig":{"w":220,"h":200,"alt":"Equilateral triangle EFG with side a, E at bottom left, G at bottom right, F at the apex, and a vertical line EX through E","d":[["l",40,170,40,18,"a"],["t",34,16,"X","e"],["l",40,170,180,170],["l",40,170,110,49],["l",110,49,180,170],["c",40,170,4,"F"],["c",180,170,4,"F"],["c",110,49,4,"F"],["t",30,184,"E","e"],["t",186,184,"G",""],["t",118,46,"F",""],["t",110,186,"a","m"]]},"n":25,"s":"Take EX as the vertical line through E. Distances of the particles from this line: E: 0; G: a; F: a/2 (F is above the midpoint of EG).\nI = m(0)² + m(a)² + m({a;2})² = {5;4}ma².\n{5;4} = {25;20}, so N = 25.\nAnswer: 25."},
{"y":"JEE Main 2020 · 4 Sep · Shift 1","tp":"pri","st":"Radius of gyration and composite bodies","q":"ABC is a plane lamina of the shape of an equilateral triangle. D, E are mid points of AB, AC and G is the centroid of the lamina. Moment of inertia of the lamina about an axis passing through G and perpendicular to the plane ABC is I₀. If part ADE is removed, the moment of inertia of the remaining part about the same axis is {NI₀;16} where N is an integer. Value of N is ______.","fig":{"w":220,"h":190,"alt":"Equilateral triangle ABC with D and E the midpoints of AB and AC, and the centroid G below the line DE","d":[["l",110,18,30,158],["l",110,18,190,158],["l",30,158,190,158],["l",70,88,150,88],["c",110,111,2.5,"F"],["t",110,18,"A","m"],["t",22,166,"B",""],["t",192,166,"C",""],["t",60,86,"D","e"],["t",156,86,"E",""],["t",118,114,"G",""]]},"n":11,"s":"Let the triangle have mass M and side s, so I₀ = {Ms²;12}.\nADE is a similar triangle with half the side: mass M/4, side s/2. About its own centroid I = (M/4)(s/2)²/12 = {I₀;16}.\nDistance from G to the centroid of ADE: altitude h = {√3;2}s; G is 2h/3 from A and ADE's centroid is h/3 from A, so d = h/3 and d² = {s²;12}.\nParallel axis: I(ADE about G) = {I₀;16} + {M;4}·{s²;12} = {I₀;16} + {I₀;4} = {5I₀;16}.\nRemaining part: I₀ − {5I₀;16} = {11I₀;16}, so N = 11.\nAnswer: 11."},
{"y":"JEE Advanced 2015","tp":"pri","st":"Moment of inertia of bodies","q":"The densities of two solid spheres A and B of the same radii R vary with radial distance r as ρ_A(r) = k({r;R}) and ρ_B(r) = k({r;R})⁵, respectively, where k is a constant. The moments of inertia of the individual spheres about axes passing through their centres are I_A and I_B respectively. If {I_B;I_A} = {n;10}, the value of n is ______.","n":6,"s":"Split the sphere into thin shells of radius r, thickness dr, mass dm = ρ·4πr²dr. A thin shell has I = {2;3}r²dm.\nSo I = {8π;3}∫ρ r⁴ dr from 0 to R.\nSphere A: ∫ k r⁵/R dr = kR⁵/6, so I_A ∝ 1/6.\nSphere B: ∫ k r⁹/R⁵ dr = kR⁵/10, so I_B ∝ 1/10.\nI_B/I_A = (1/10)/(1/6) = {6;10}, so n = 6.\nAnswer: 6."},
{"y":"IIT-JEE 2012","tp":"pri","st":"Radius of gyration and composite bodies","q":"A lamina is made by removing a small disc of diameter 2R from a bigger disc of uniform mass density and radius 2R, as shown in the figure. The moment of inertia of this lamina about axes passing through O and P is I_O and I_P respectively. Both these axis are perpendicular to the plane of the lamina. The ratio {I_P;I_O} to the nearest integer is ______.","fig":{"w":300,"h":225,"alt":"Big disc of radius 2R with centre O and a smaller disc of diameter 2R removed above O, touching the rim at the top; P is on the rim to the right of O","d":[["c",130,115,95],["c",130,67.5,47.5],["c",130,115,2.5,"F"],["l",130,20,130,115,"b"],["t",136,70,"2R",""],["l",130,115,225,115,"a"],["t",178,109,"2R","ms"],["t",116,130,"O","m"],["t",232,119,"P",""]]},"n":3,"s":"Let the removed disc (radius R) have mass m. Then the big disc (radius 2R) has mass 4m. O is the centre of the big disc; the small disc touches O and the rim, so its centre is R above O. P is on the rim, 2R from O.\nAbout O: I_O = {1;2}(4m)(2R)² − [{1;2}mR² + mR²] = 8mR² − 1.5mR² = 6.5mR².\nAbout P: big disc = 8mR² + 4m(2R)² = 24mR². Small disc = {1;2}mR² + m(√5R)² = 5.5mR². I_P = 24mR² − 5.5mR² = 18.5mR².\nI_P/I_O = 18.5/6.5 = 2.85, which is 3 to the nearest integer.\nAnswer: 3."},
{"y":"IIT-JEE 2011","tp":"pri","st":"Parallel and perpendicular axes","q":"Four solid spheres each of diameter √5 cm and mass 0.5 kg are placed with their centers at the corners of a square of side 4 cm. The moment of inertia of the system about the diagonal of the square is N × 10⁻⁴ kg-m², then N is ______.","n":9,"s":"Radius r = √5/2 cm, so r² = 1.25 × 10⁻⁴ m².\nA sphere about its own diameter: {2;5}(0.5)(1.25 × 10⁻⁴) = 0.25 × 10⁻⁴ kg m².\nTwo spheres have their centres on the diagonal, so only this term counts for them.\nThe other two centres are 2√2 cm from the diagonal: d² = 8 × 10⁻⁴ m², md² = 0.5(8 × 10⁻⁴) = 4 × 10⁻⁴.\nI = 4(0.25 × 10⁻⁴) + 2(4 × 10⁻⁴) = 1 × 10⁻⁴ + 8 × 10⁻⁴ = 9 × 10⁻⁴ kg m².\nAnswer: N = 9."},
{"y":"JEE Main 2022 · 28 Jun · Shift 1","tp":"pri","st":"Statements, matching and subjective","q":"Match List-I with List-II.\nList-I:\n(A) Moment of inertia of solid sphere of radius R about any tangent.\n(B) Moment of inertia of hollow sphere of radius (R) about any tangent.\n(C) Moment of inertia of circular ring of radius (R) about its diameter.\n(D) Moment of inertia of circular disc of radius (R) about any diameter.\nList-II:\n(i) {5;3}MR²\n(ii) {7;5}MR²\n(iii) {1;4}MR²\n(iv) {1;2}MR²\nChoose the correct answer from the options given below.","o":["(A)-(ii), (B)-(i), (C)-(iv), (D)-(iii)","(A)-(i), (B)-(ii), (C)-(iv), (D)-(iii)","(A)-(ii), (B)-(i), (C)-(iii), (D)-(iv)","(A)-(i), (B)-(ii), (C)-(iii), (D)-(iv)"],"c":0,"s":"Use the parallel axis theorem: I(tangent) = I(centre) + MR².\n(A) Solid sphere: {2;5}MR² + MR² = {7;5}MR², which is (ii).\n(B) Hollow sphere: {2;3}MR² + MR² = {5;3}MR², which is (i).\n(C) Ring about a diameter: {1;2}MR², which is (iv).\n(D) Disc about a diameter: {1;4}MR², which is (iii).\nSo A-(ii), B-(i), C-(iv), D-(iii)."},
{"y":"JEE Main 2021 · 27 Jul · Shift 1","tp":"pri","st":"Statements, matching and subjective","q":"Match List-I with List-II.\nList-I:\n(A) MI of the rod (length L, mass M, about an axis ⊥ to the rod passing through the midpoint)\n(B) MI of the rod (length L, mass 2M, about an axis ⊥ to the rod passing through one of its end)\n(C) MI of the rod (length 2L, mass M, about an axis ⊥ to the rod passing through one of its end)\n(D) MI of the rod (length 2L, mass 2M about an axis ⊥ to the rod passing through one of its end)\nList-II:\n(i) {8ML²;3}\n(ii) {ML²;3}\n(iii) {ML²;12}\n(iv) {2ML²;3}\nChoose the correct answer from the options given below.","o":["(A)-(iii), (B)-(iv), (C)-(ii), (D)-(i)","(A)-(ii), (B)-(iii), (C)-(i), (D)-(iv)","(A)-(iii), (B)-(iv), (C)-(i), (D)-(ii)","(A)-(ii), (B)-(i), (C)-(iii), (D)-(iv)"],"c":0,"s":"(A) About the midpoint: {ML²;12}, which is (iii).\n(B) About one end: {(2M)L²;3} = {2ML²;3}, which is (iv).\n(D) Length 2L, mass 2M, about one end: {(2M)(2L)²;3} = {8ML²;3}, which is (i).\n(C) As printed (length 2L, mass M) gives {4ML²;3}, which is not in List-II (probably a misprint in the paper); the only remaining match is (ii) {ML²;3}.\nSo A-(iii), B-(iv), C-(ii), D-(i)."},
{"y":"JEE Main 2021 · 25 Jul · Shift 1","tp":"pri","st":"Statements, matching and subjective","q":"Given below are two statements : one is labelled as Assertion and the other is labelled as Reason.\nAssertion : Moment of inertia of a circular disc of mass 'M' and radius 'R' about X, Y axis (passing through its diameter) and Z-axis which is perpendicular to its plane were found to be Iₓ, I_y and I_z respectively. The respective radii of gyration about all the three axis will be the same.\nReason : A rigid body making rotational motion has fixed mass and shape.\nIn the light of the above statements, choose the most appropriate answer from the options given below.","o":["Assertion is correct but Reason is not correct.","Both Assertion and Reason are correct but Reason is NOT the correct explanation of Assertion.","Assertion is not correct but Reason is correct.","Both Assertion and Reason are correct and Reason is the correct explanation of Assertion."],"c":2,"s":"For a disc, Iₓ = I_y = {1;4}MR² and I_z = {1;2}MR².\nRadius of gyration k = √(I/M): k = R/2 for X and Y axes but k = R/√2 for the Z axis, so they are not the same. The Assertion is wrong.\nThe Reason (a rigid body has fixed mass and shape) is a true statement.\nSo the Assertion is not correct but the Reason is correct."},
{"y":"IIT-JEE 2001","tp":"prd","st":"Statements, matching and subjective","q":"Two heavy metallic plates are joined together at 90° to each other. A laminar sheet of mass 30 kg is hinged at the line AB joining the two heavy metallic plates. The hinges are frictionless. The moment of inertia of the laminar sheet about an axis parallel to AB and passing through its center of mass is 1.2 kg-m². Two rubber obstacles P and Q are fixed, one on each metallic plate at a distance 0.5 m from the line AB.\nThis distance is chosen so that the reaction due to the hinges on the laminar sheet is zero during the impact. Initially the laminar sheet hits one of the obstacles with an angular velocity 1 rad/s and turns back. If the impulse on the sheet due to each obstacle is 6 N-s.\n(a) Find the location of the centre of mass of the laminar sheet from AB.\n(b) At what angular velocity does the laminar sheet come back after the first impact?\n(c) After how many impacts, does the laminar sheet come to rest?","fig":{"w":340,"h":240,"alt":"End view along the hinge line AB: two plates at 90 degrees meeting at the hinge, obstacle P on the vertical plate and Q on the horizontal plate, each 0.5 m from the hinge, and the laminar sheet between them with its centre of mass near the hinge","d":[["l",70,15,70,190,"B"],["l",70,190,330,190,"B"],["c",70,190,5,"F"],["t",62,206,"hinge AB","e"],["l",70,190,170,91],["t",178,86,"sheet","s"],["c",84,176,3,"F"],["t",92,182,"cm","s"],["c",70,90,5,"F"],["t",80,86,"P",""],["c",170,190,5,"F"],["t",170,178,"Q","m"],["p","M123.6 145 A70 70 0 0 0 93.9 124.2","a"],["t",130,128,"ω",""],["l",46,190,46,90,"b"],["t",40,144,"0.5 m","es"],["l",70,220,170,220,"b"],["t",120,234,"0.5 m","ms"]]},"a":"(a) 0.1 m   (b) 1 rad/s   (c) infinity (it never comes to rest)","s":"Let d = distance of the centre of mass from AB, J = 6 N s, ω = 1 rad/s before and ω′ after the impact. The sheet turns back, so its angular velocity changes by (ω + ω′).\nNo hinge reaction means the hinge gives no impulse, so J = M d (ω + ω′) and, about AB, J(0.5) = (I_cm + Md²)(ω + ω′).\nDividing: 0.5 M d = I_cm + M d² gives 15d = 1.2 + 30d², so d = 0.1 m or 0.4 m.\nUsing the given impulse: 6 = 30 d (1 + ω′). For d = 0.1 m this gives ω′ = 1 rad/s (the sheet turns back); d = 0.4 m would give ω′ = −0.5 rad/s (no turning back). So (a) d = 0.1 m, (b) ω′ = 1 rad/s.\n(c) Each impact only reverses the angular velocity, with the same size (1 rad/s), so the sheet bounces between the two obstacles for ever and never comes to rest: infinitely many impacts."},
{"y":"IIT-JEE 1997","tp":"pri","st":"Parallel and perpendicular axes","q":"A symmetric lamina of mass M consists of a square shape with a semicircular section over the edge of the square as shown in figure. The side of the square is 2a. The moment of inertia of the lamina about an axis through its centre of mass and perpendicular to the plane is 1.6 Ma². The moment of inertia of the lamina about the tangent AB in the plane of the lamina is ______.","fig":{"w":300,"h":250,"alt":"A square lamina of side 2a with a semicircle on each of its four edges, centre O, and the line AB tangent to the top semicircle","d":[["p","M110 100 A40 40 0 0 1 190 100 A40 40 0 0 1 190 180 A40 40 0 0 1 110 180 A40 40 0 0 1 110 100 Z"],["r",110,100,80,80,"d"],["c",150,140,2.5,"F"],["t",158,156,"O",""],["l",110,122,190,122,"b"],["t",150,116,"2a","ms"],["l",40,60,260,60],["t",30,57,"A","e"],["t",268,57,"B",""]]},"a":"4.8 Ma²","s":"The lamina is symmetric about O, so its moments about the two in-plane axes through O (one parallel to AB, one perpendicular to it) are equal: Iₓ = I_y.\nPerpendicular axis theorem: I_z = Iₓ + I_y, so Iₓ = 1.6Ma²/2 = 0.8Ma².\nAB touches the top semicircle, so its distance from O is a (half the square) + a (radius) = 2a.\nParallel axis theorem: I_AB = 0.8Ma² + M(2a)² = 4.8Ma².\nAnswer: 4.8 Ma²."},
{"y":"JEE Main 2025 · 2 Apr · Shift 1","tp":"prd","st":"Rotational kinetic energy and work","q":"A cord of negligible mass is wound around the rim of a wheel supported by spokes with negligible mass. The mass of wheel is 10 kg and radius is 10 cm and it can freely rotate without any friction. Initially the wheel is at rest. If a steady pull of 20 N is applied on the cord, the angular velocity of the wheel, after the cord is unwound by 1 m, would be","fig":{"w":280,"h":200,"alt":"A wheel of radius R with a cord wound on its rim, pulled downward with a steady force F = 20 N","d":[["c",110,80,55],["c",110,80,2.5,"F"],["l",110,80,75,40],["t",86,66,"R","ms"],["l",165,80,165,175,"a"],["t",175,172,"F = 20 N",""]]},"o":["30 rad/s","0 rad/s","10 rad/s","20 rad/s"],"c":3,"s":"All the mass is on the rim, so I = MR² = 10(0.1)² = 0.1 kg m².\nThe pull does work W = F × (length of cord unwound) = 20 × 1 = 20 J.\nThis becomes rotational kinetic energy: {1;2}Iω² = 20, so ω² = 40/0.1 = 400.\nω = 20 rad/s."},
{"y":"JEE Main 2025 · 23 Jan · Shift 2","tp":"prd","st":"Torque and angular acceleration","q":"A circular disk of radius R meter and mass M kg is rotating around the axis perpendicular to the disk. An external torque is applied to the disk such that θ(t) = 5t² − 8t, where θ(t) is the angular position of the rotating disc as a function of time t. How much power is delivered by the applied torque, when t = 2 s?","o":["72 MR²","8 MR²","108 MR²","60 MR²"],"c":3,"s":"ω = dθ/dt = 10t − 8, so at t = 2 s, ω = 12 rad/s.\nα = dω/dt = 10 rad/s², a constant.\nI = {1;2}MR², so torque τ = Iα = {1;2}MR²(10) = 5MR².\nPower P = τω = 5MR² × 12 = 60 MR²."},
{"y":"JEE Advanced 2023","tp":"pra","st":"Collisions with rotating bodies","q":"A bar of mass M = 1.00 kg and length L = 0.20 m is lying on a horizontal frictionless surface. One end of the bar is pivoted at a point about which it is free to rotate. A small mass m = 0.10 kg is moving on the same horizontal surface with 5.00 m s⁻¹ speed on a path perpendicular to the bar. It hits the bar at a distance L/2 from the pivoted end and returns back on the same path with speed v. After this elastic collision, the bar rotates with an angular velocity ω. Which of the following statement is correct?","o":["ω = 6.98 rad s⁻¹ and v = 4.30 m s⁻¹","ω = 3.75 rad s⁻¹ and v = 4.30 m s⁻¹","ω = 3.75 rad s⁻¹ and v = 10.0 m s⁻¹","ω = 6.80 rad s⁻¹ and v = 4.10 m s⁻¹"],"c":0,"s":"Take I = {ML²;3} = {1(0.2)²;3} = 0.01333 kg m² about the pivot. The pivot force acts at the pivot, so angular momentum about the pivot is conserved: m(5)({L;2}) = −m v({L;2}) + Iω, i.e. 0.05 = −0.01v + 0.01333ω, so ω = 3.75 + 0.75v.\nElastic collision: {1;2}m(5)² = {1;2}mv² + {1;2}Iω², i.e. 1.25 = 0.05v² + 0.006667ω².\nSubstitute ω: 0.05375v² + 0.0375v − 1.15625 = 0, which gives v = 4.30 m/s.\nThen ω = 3.75 + 0.75(4.30) = 6.98 rad/s.\nSo ω = 6.98 rad/s and v = 4.30 m/s."},
{"y":"JEE Main 2022 · 24 Jun · Shift 2","tp":"prd","st":"Rotational kinematics","q":"A flywheel is accelerated uniformly from rest and rotates through 5 rad in the first second. The angle rotated by the flywheel in the next second, will be","o":["7.5 rad","15 rad","20 rad","30 rad"],"c":1,"s":"From rest with constant α: θ = {1;2}αt².\nIn the first second: 5 = {1;2}α(1)², so α = 10 rad/s².\nIn the first 2 s: θ = {1;2}(10)(2)² = 20 rad.\nIn the next (second) second: 20 − 5 = 15 rad.\n(Angles in successive seconds are in the ratio 1 : 3, so 5 × 3 = 15 rad.)"},
{"y":"JEE Main 2022 · 28 Jun · Shift 2","tp":"prd","st":"Rotational kinematics","q":"A ball is spun with angular acceleration α = 6t² − 2t where t is in second and α is in rad s⁻². At t = 0, the ball has angular velocity of 10 rad s⁻¹ and angular position of 4 rad. The most appropriate expression for the angular position of the ball is","o":["{3;2}t⁴ − t² + 10t","{t⁴;2} − {t³;3} + 10t + 4","{2t⁴;3} − {t³;6} + 10t + 12","2t⁴ − {t³;2} + 5t + 4"],"c":1,"s":"Integrate α to get ω: ω = ∫(6t² − 2t)dt = 2t³ − t² + C. With ω = 10 at t = 0, C = 10.\nIntegrate ω to get θ: θ = {t⁴;2} − {t³;3} + 10t + C′. With θ = 4 at t = 0, C′ = 4.\nθ = {t⁴;2} − {t³;3} + 10t + 4."},
{"y":"JEE Main 2022 · 28 Jun · Shift 2","tp":"prt","st":"Ladder, beams and hinges","q":"A √34 m long ladder weighing 10 kg leans on a frictionless wall. Its feet rest on the floor 3 m away from the wall as shown in figure. If F_f and F_w are the reaction forces of the floor and the wall, then ratio of F_w/F_f will be (Use g = 10 m/s².)","fig":{"w":300,"h":215,"alt":"A ladder of length root 34 m leaning on a smooth vertical wall, its foot on the floor 3 m from the wall","d":[["l",240,20,240,170,"B"],["l",30,170,260,170],["l",156,170,240,30,"B"],["t",178,96,"√34 m","e"],["l",156,190,240,190,"b"],["t",198,206,"3 m","m"],["l",240,50,250,40],["l",240,80,250,70],["l",240,110,250,100],["l",240,140,250,130]]},"o":["{6;√110}","{3;√113}","{3;√109}","{2;√109}"],"c":2,"s":"Height reached on the wall = √(34 − 9) = 5 m. Weight W = 10 × 10 = 100 N acts at the middle, 1.5 m from the wall.\nTorque about the foot: F_w × 5 = W × 1.5, so F_w = 30 N.\nHorizontal balance: friction at the floor = F_w = 30 N. Vertical balance: normal reaction = 100 N.\nF_f is the total floor reaction = √(100² + 30²) = 10√109 N.\nF_w/F_f = 30/(10√109) = 3/√109."},
{"y":"JEE Main 2020 · 6 Sep · Shift 1","tp":"prd","st":"Rotational kinematics","q":"A clock has a continuously moving second's hand of 0.1 m length. The average acceleration of the tip of the hand (in units of m s⁻²) is of the order of","o":["10⁻³","10⁻⁴","10⁻²","10⁻¹"],"c":0,"s":"The second hand turns once in 60 s, so ω = 2π/60 = 0.105 rad/s.\nThe tip moves in a circle at constant speed, so its acceleration has constant size a = ω²r = (0.105)²(0.1) = 1.1 × 10⁻³ m/s².\n(Check: the speed v = ωr = 0.0105 m/s reverses direction in 30 s, so the average acceleration over half a turn is 2v/30 = 7 × 10⁻⁴ m/s², also of order 10⁻³.)\nSo the order is 10⁻³ m/s²."},
{"y":"JEE Main 2020 · 7 Jan · Shift 1","tp":"prd","st":"Pulleys and hinged rods","q":"As shown in the figure, a bob of mass m is tied by a massless string whose other end portion is wound on a fly wheel (disc) of radius r and mass m. When released from rest the bob starts falling vertically. When it has covered a distance of h, the angular speed of the wheel will be","fig":{"w":280,"h":225,"alt":"A fly wheel of mass m and radius r on a fixed axle with a string wound on it, carrying a hanging bob of mass m","d":[["l",75,12,145,12],["l",110,12,110,70],["c",110,70,40],["c",110,70,2.5,"F"],["t",110,66,"m, r","ms"],["l",150,70,150,170],["c",150,182,12,"F"],["t",170,186,"m",""]]},"o":["r√{3;2gh}","r√{3;4gh}","{1;r}√{4gh;3}","{1;r}√{2gh;3}"],"c":2,"s":"Energy conservation: the bob's loss of potential energy becomes kinetic energy of the bob and of the wheel.\nmgh = {1;2}mv² + {1;2}Iω², with I = {1;2}mr² and v = rω.\nmgh = {1;2}mv² + {1;4}mv² = {3;4}mv², so v = √{4gh;3}.\nω = v/r = {1;r}√{4gh;3}."},
{"y":"JEE Main 2020 · 9 Jan · Shift 1","tp":"prd","st":"Pulleys and hinged rods","q":"A uniformly thick wheel with moment of inertia I and radius R is free to rotate about its centre of mass (see figure). A massless string is wrapped over its rim and two blocks of masses m₁ and m₂ (m₁ > m₂) are attached to the ends of the string. The system is released from rest. The angular speed of the wheel when m₁ descents by a distance h is","fig":{"w":280,"h":245,"alt":"A wheel hung from a fixed support with a string over its rim carrying block m1 on the left and a lighter block m2 on the right","d":[["l",80,12,200,12],["l",140,12,140,70],["c",140,70,36],["c",140,70,2.5,"F"],["t",140,66,"I, R","ms"],["l",104,70,104,175],["r",90,175,28,26,"F"],["t",104,222,"m₁","m"],["l",176,70,176,150],["r",164,150,24,20,"F"],["t",176,190,"m₂","m"]]},"o":["[{2(m₁ − m₂)gh;(m₁ + m₂)R² + I}]^(1/2)","[{m₁ + m₂;(m₁ + m₂)R² + I}gh]^(1/2)","[{2(m₁ + m₂)gh;(m₁ + m₂)R² + I}]^(1/2)","[{m₁ − m₂;(m₁ + m₂)R² + I}gh]^(1/2)"],"c":0,"s":"Energy conservation: m₁ falls by h and m₂ rises by h, and the string does not slip so v = Rω for both blocks.\n(m₁ − m₂)gh = {1;2}(m₁ + m₂)v² + {1;2}Iω²\n(m₁ − m₂)gh = {1;2}[(m₁ + m₂)R² + I]ω²\nω = [{2(m₁ − m₂)gh;(m₁ + m₂)R² + I}]^(1/2)."},
{"y":"JEE Main 2019 · 8 Apr · Shift 2","tp":"prd","st":"Torque and angular acceleration","q":"A rectangular solid box of length 0.3 m is held horizontally, with one of its sides on the edge of a platform of height 5 m. When released, it slips off the table in a very short time τ = 0.01 s, remaining essentially horizontal. The angle by which it would rotate when it hits the ground will be (in radians) close to","fig":{"w":300,"h":200,"alt":"A box of length l held horizontally at the edge of a table of height h above the ground","d":[["r",20,100,110,80,"f"],["r",130,88,90,12,"f"],["l",130,100,130,88],["l",130,76,220,76,"b"],["t",175,70,"l","ms"],["l",260,100,260,180,"b"],["t",268,144,"h",""],["l",10,180,290,180],["l",150,180,160,190],["l",190,180,200,190],["l",230,180,240,190]]},"o":["0.5","0.28","0.3","0.02"],"c":0,"s":"While it slips off, the table edge acts as a pivot. Gravity gives a torque mg({l;2}) about the edge, and I = {ml²;3}.\nAngular impulse = change in angular momentum: mg({l;2})τ = Iω, so ω = {3gτ;2l} = {3(10)(0.01);2(0.3)} = 0.5 rad/s.\nTime to fall 5 m: t = √{2h;g} = √{2(5);10} = 1 s.\nAngle rotated = ωt = 0.5 × 1 = 0.5 rad."},
{"y":"JEE Main 2019 · 9 Apr · Shift 1","tp":"prd","st":"Torque and angular acceleration","q":"A stationary horizontal disc is free to rotate about its axis. When a torque is applied on it, its kinetic energy as a function of θ, where θ is the angle by which it has rotated, is given as kθ². If its moment of inertia is I then the angular acceleration of the disc is","o":["{k;I}θ","{k;2I}θ","{k;4I}θ","{2k;I}θ"],"c":3,"s":"Work done by the torque = gain in kinetic energy, so τ dθ = d(KE).\nτ = d(kθ²)/dθ = 2kθ.\nα = τ/I = {2kθ;I}."},
{"y":"JEE Main 2019 · 9 Apr · Shift 2","tp":"prd","st":"Rotational kinetic energy and work","q":"Moment of inertia of a body about a given axis is 1.5 kg m². Initially the body is at rest. In order to produce a rotational kinetic energy of 1200 J, the angular acceleration of 20 rad/s² must be applied about the axis for a duration of","o":["5 s","2 s","2.5 s","3 s"],"c":1,"s":"Rotational KE = {1;2}Iω², so 1200 = {1;2}(1.5)ω², giving ω² = 1600 and ω = 40 rad/s.\nStarting from rest with α = 20 rad/s²: ω = αt.\nt = 40/20 = 2 s."},
{"y":"JEE Main 2019 · 10 Apr · Shift 1","tp":"pri","st":"Moment of inertia of bodies","q":"A thin disc of mass M and radius R has mass per unit area σ(r) = kr² where r is the distance from its centre. Its moment of inertia about an axis going through its centre of mass and perpendicular to its plane is","o":["{MR²;6}","{2MR²;3}","{MR²;3}","{MR²;2}"],"c":1,"s":"Take a ring of radius r and width dr: dm = σ·2πr dr = 2πk r³ dr.\nM = ∫dm = 2πk ∫₀ᴿ r³dr = {πkR⁴;2}.\nI = ∫r²dm = 2πk ∫₀ᴿ r⁵dr = {πkR⁶;3}.\nI/M = {(1/3);(1/2)}R² = {2;3}R², so I = {2MR²;3}."},
{"y":"JEE Main 2019 · 10 Apr · Shift 2","tp":"prd","st":"Torque and angular acceleration","q":"A metal coin of mass 5 g and radius 1 cm is fixed to a thin stick AB of negligible mass as shown in the figure. The system is initially at rest. The constant torque, that will make the system rotate about AB at 25 rotations per second in 5 s, is close to","fig":{"w":240,"h":210,"alt":"A coin of radius 1 cm fixed beside a stick AB that touches its edge, with the 1 cm distance from the centre to the stick marked","d":[["c",150,100,50,"f"],["c",150,100,2.5,"F"],["l",100,18,100,185],["t",100,12,"A","m"],["t",100,200,"B","m"],["l",100,100,150,100,"d"],["t",125,94,"1 cm","ms"]]},"o":["4.0 × 10⁻⁶ N m","1.6 × 10⁻⁵ N m","2.0 × 10⁻⁵ N m","7.9 × 10⁻⁶ N m"],"c":2,"s":"AB is a tangent to the coin in its plane, 1 cm from the centre. I = {1;4}mr² + mr² = {5;4}mr² = {5;4}(5 × 10⁻³)(10⁻²)² = 6.25 × 10⁻⁷ kg m².\nFinal angular speed ω = 2π × 25 = 50π rad/s, reached in 5 s from rest: α = 10π = 31.4 rad/s².\nτ = Iα = 6.25 × 10⁻⁷ × 31.4 = 1.96 × 10⁻⁵ N m ≈ 2.0 × 10⁻⁵ N m."},
{"y":"JEE Main 2019 · 9 Jan · Shift 2","tp":"prd","st":"Pulleys and hinged rods","q":"A rod of length 50 cm is pivoted at one end. It is raised such that it makes an angle of 30° from the horizontal as shown and released from rest. Its angular speed when it passes through the horizontal (in rad s⁻¹) will be (g = 10 m s⁻²)","fig":{"w":300,"h":190,"alt":"A rod pivoted at its left end, raised 30 degrees above the horizontal dashed line","d":[["l",40,150,230,150,"d"],["l",40,150,204.5,55,"B"],["c",40,150,5],["p","M110 150 A70 70 0 0 0 100.6 115"],["t",122,140,"30°",""]]},"o":["{√30;2}","√{30;2}","√30","√20"],"c":2,"s":"The centre of mass falls by {L;2}sin 30° as the rod swings down to the horizontal.\nEnergy conservation: Mg{L;2}sin 30° = {1;2}({ML²;3})ω².\nω² = {3g sin 30°;L} = {3(10)(0.5);0.5} = 30.\nω = √30 rad/s."},
{"y":"JEE Main 2019 · 10 Jan · Shift 2","tp":"prd","st":"Pulleys and hinged rods","q":"A rigid massless rod of length 3l has two masses attached at each end as shown in the figure. The rod is pivoted at point P on the horizontal axis (see figure). When released from initial horizontal position, its instantaneous angular acceleration will be","fig":{"w":340,"h":115,"alt":"A horizontal rod of length 3l pivoted at P, with mass 5M0 at the left end, l from P, and mass 2M0 at the right end, 2l from P","d":[["l",40,55,300,55,"B"],["c",40,55,10,"F"],["c",300,55,7,"F"],["c",127,55,3,"F"],["l",127,55,127,75],["t",127,90,"P","m"],["t",40,92,"5M₀","m"],["t",300,92,"2M₀","m"],["l",40,26,127,26,"b"],["t",83,20,"l","ms"],["l",127,26,300,26,"b"],["t",213,20,"2l","ms"]]},"o":["{g;3l}","{g;2l}","{7g;3l}","{g;13l}"],"c":3,"s":"The pivot P is l from the 5M₀ mass and 2l from the 2M₀ mass.\nNet torque about P at release: τ = 5M₀g(l) − 2M₀g(2l) = M₀gl.\nMoment of inertia: I = 5M₀l² + 2M₀(2l)² = 13M₀l².\nα = τ/I = {M₀gl;13M₀l²} = {g;13l}."},
{"y":"JEE Main 2018 · Online","tp":"prd","st":"Pulleys and hinged rods","q":"A thin rod MN, free to rotate in the vertical plane about the fixed end N, is held horizontal. When the end M is released the speed of this end, when the rod makes an angle α with the horizontal, will be proportional to (see figure)","fig":{"w":300,"h":150,"alt":"Rod MN hinged at N, shown horizontal and then tilted down by angle alpha","d":[["l",60,30,250,30,"B"],["c",250,30,3,"F"],["t",50,26,"M","e"],["t",256,26,"N"],["l",250,30,86,125,"dB"],["p","M215 30 A35 35 0 0 0 219.7 47.5"],["t",196,48,"α","s"]]},"o":["cosα","sinα","√cosα","√sinα"],"c":3,"s":"Energy conservation about the hinge N: the centre of mass falls by (l/2) sinα.\n½ · (ml²/3) ω² = mg (l/2) sinα, so ω² = 3g sinα / l.\nSpeed of end M is v = ωl = √(3gl sinα).\nSo v is proportional to √sinα."},
{"y":"JEE Advanced 2017","tp":"prd","st":"Torque and angular acceleration","q":"A slender uniform rod of mass M and length l is pivoted at one end so that it can rotate in a vertical plane (see figure). There is negligible friction at the pivot. The free end is held vertically above the pivot and then released. The angular acceleration of the rod when it makes an angle θ with the vertical is","fig":{"w":260,"h":190,"alt":"Rod pivoted at the origin making angle theta with the vertical z axis, x axis horizontal","d":[["l",60,170,60,15,"a"],["l",60,170,235,170,"a"],["t",54,14,"z","e"],["t",238,174,"x"],["l",60,170,60,50,"d"],["l",60,170,131,86,"B"],["p","M60 130 A40 40 0 0 1 85.7 139.4"],["t",72,122,"θ","s"],["c",60,170,3,"F"],["t",136,84,"rod","s"]]},"o":["{3g;2l} sinθ","{2g;3l} sinθ","{3g;2l} cosθ","{2g;3l} cosθ"],"c":0,"s":"Torque about the pivot comes from the weight acting at the centre, a distance l/2 from the pivot.\nHorizontal distance of the centre from the pivot is (l/2) sinθ, so τ = Mg (l/2) sinθ.\nI = Ml²/3, so α = τ/I = (Mg l sinθ/2) / (Ml²/3) = 3g sinθ / 2l."},
{"y":"JEE Main 2017 · Online","tp":"prd","st":"Pulleys and hinged rods","q":"A uniform disc of radius R and mass M is free to rotate only about its axis. A string is wrapped over its rim and a body of mass m is tied to the free end of the string as shown in the figure. The body is released from rest. Then the acceleration of the body is","fig":{"w":320,"h":230,"alt":"Disc of mass M on a fixed axle attached to a wall, with a string from its rim carrying a block of mass m","d":[["r",290,15,14,130,"f"],["l",200,75,290,75],["c",200,75,40],["c",200,75,3,"F"],["t",200,62,"M","ms"],["l",160,75,160,165],["r",140,165,40,28,"f"],["t",160,184,"m","ms"],["l",100,120,100,160,"a"],["t",90,145,"g","e"]]},"o":["{2mg;2m+M}","{2Mg;2m+M}","{2Mg;2M+m}","{2mg;2M+m}"],"c":0,"s":"For the block: mg − T = ma. For the disc: TR = Iα = (½MR²)(a/R), so T = Ma/2.\nPut T into the first equation: mg = ma + Ma/2 = a (2m + M)/2.\nSo a = 2mg/(2m + M)."},
{"y":"JEE Main 2016 · Online","tp":"prd","st":"Rotational kinematics","q":"Concrete mixture is made by mixing cement, stone and sand in a rotating cylindrical drum. If the drum rotates too fast, the ingredients remain stuck to the wall of the drum and proper mixing of ingredients does not take place. The maximum rotational speed of the drum in revolutions per minute (rpm) to ensure proper mixing is close to (Take the radius of the drum to be 1.25 m and its axle to be horizontal)","o":["27.0","0.4","1.3","8.0"],"c":0,"s":"Mixing stops when the material sticks at the top of the drum, which happens when the needed centripetal force is more than the weight can give.\nThe limit is when mω²R = mg at the top, so ω = √(g/R) = √(10/1.25) = √8 = 2.83 rad/s.\nIn rpm: 2.83 × 60/(2π) ≈ 27 rpm."},
{"y":"JEE Main 2014","tp":"prd","st":"Pulleys and hinged rods","q":"A mass m is supported by a massless string wound around a uniform hollow cylinder of mass m and radius R. If the string does not slip on the cylinder, with what acceleration will the mass fall on release?","fig":{"w":300,"h":230,"alt":"Hollow cylinder on a fixed axle hung from a ceiling bracket, string from its rim carrying a mass m","d":[["r",105,10,90,8,"f"],["l",150,18,150,100],["c",150,100,48],["c",150,100,3,"F"],["l",150,100,198,100,"d"],["t",172,94,"R","ms"],["t",150,150,"mass m","ms"],["l",198,100,198,185],["r",183,185,30,26,"f"],["t",198,224,"m","ms"]]},"o":["g","{2g;3}","{g;2}","{5g;6}"],"c":2,"s":"Hollow cylinder: I = mR². Block: mg − T = ma. Cylinder: TR = Iα = mR² (a/R), so T = ma.\nThen mg = ma + ma = 2ma.\nSo a = g/2."},
{"y":"IIT-JEE 2012","tp":"prd","st":"Rotational kinematics","q":"Consider a disc rotating in the horizontal plane with a constant angular speed ω about its centre O. The disc has a shaded region on one side of the diameter and an unshaded region on the other side as shown in the figure. When the disc is in the orientation shown, two pebbles P and Q are simultaneously projected at an angle towards R. The velocity of projection is in the y-z plane and is same for both pebbles with respect to the disc. Assume that (i) they land back on the disc before the disc has completed {1;8} rotation, (ii) their range is less than half the disc radius, and (iii) ω remains constant throughout. Then","fig":{"w":340,"h":210,"alt":"Top view of a disc turning clockwise with a vertical diameter through P, Q, O and R; the right half is hatched (shaded) and the left half is plain","d":[["c",230,105,85],["l",230,20,230,190,"d"],["l",240,160,290,110],["l",240,130,300,70],["l",240,100,275,65],["l",240,70,255,55],["l",250,175,295,130],["c",230,20,3,"F"],["t",236,30,"R","s"],["c",230,80,3,"F"],["t",236,84,"Q","s"],["c",230,105,3,"F"],["t",224,109,"O","es"],["c",230,190,3,"F"],["t",236,186,"P","s"],["l",50,170,50,120,"a"],["l",50,170,100,170,"a"],["t",44,120,"y","es"],["t",104,174,"x","s"],["p","M254 15 A93 93 0 0 1 310.5 58.5","a"],["t",318,52,"ω"],["t",160,100,"unshaded","ms"],["t",270,195,"shaded","ms"]]},"o":["P lands in the shaded region and Q in the unshaded region","P lands in the unshaded region and Q in the shaded region","both P and Q land in the unshaded region","both P and Q land in the shaded region"],"c":0,"s":"Work in the frame of the disc. In this frame each pebble feels the Coriolis effect, which pushes a pebble moving along +y sideways to the left (the disc turns clockwise), the same for P and Q.\nQ starts close to the centre, where the sideways speed given by the rotation is small, so the Coriolis drift decides: Q lands on the left, the unshaded side.\nP starts on the rim, where the speed ωR of the rim is large. In the ground frame P moves in a straight line while the disc turns under it, and for a short flight this effect carries P to the right of the diameter, the shaded side.\nSo P lands in the shaded region and Q in the unshaded region (option a, as in the official key)."},
{"y":"IIT-JEE 2012","tp":"prd","st":"Rotational kinematics","q":"Two identical discs of same radius R are rotating about their axes in opposite directions with the same constant angular speed ω. The discs are in the same horizontal plane. At time t = 0, the points P and Q are facing each other as shown in the figure. The relative speed between the two points P and Q is vᵣ. In one time period (T) of rotation of the discs, vᵣ as a function of time is best represented by\n(In the figure the discs lie side by side. P is the right-hand end of a horizontal radius of the left disc, which turns clockwise. Q is the left-hand end of a horizontal radius of the right disc, which turns anticlockwise.)","fig":{"w":340,"h":262,"alt":"Four graphs of relative speed against time: (a) two humps starting from zero, (b) starts high with kinks, (c) four humps, (d) four humps starting high","d":[["l",40,110,160,110,"a"],["l",40,110,40,40,"a"],["t",162,114,"t","s"],["t",36,44,"vᵣ","es"],["t",36,121,"0","es"],["l",140,110,140,55,"d"],["t",140,122,"T","ms"],["t",18,28,"(a)","s"],["p","M40 110 Q65 20 90 110 Q115 20 140 110","B"],["l",210,110,330,110,"a"],["l",210,110,210,40,"a"],["t",332,114,"t","s"],["t",206,44,"vᵣ","es"],["t",206,121,"0","es"],["l",310,110,310,55,"d"],["t",310,122,"T","ms"],["t",188,28,"(b)","s"],["p","M210 55 Q230 60 235 110 Q260 20 285 110 Q290 60 310 55","B"],["l",40,235,160,235,"a"],["l",40,235,40,165,"a"],["t",162,239,"t","s"],["t",36,169,"vᵣ","es"],["t",36,246,"0","es"],["l",140,235,140,180,"d"],["t",140,247,"T","ms"],["t",18,153,"(c)","s"],["p","M40 235 Q52 145 65 235 Q77 145 90 235 Q102 145 115 235 Q127 145 140 235","B"],["l",210,235,330,235,"a"],["l",210,235,210,165,"a"],["t",332,239,"t","s"],["t",206,169,"vᵣ","es"],["t",206,246,"0","es"],["l",310,235,310,180,"d"],["t",310,247,"T","ms"],["t",188,153,"(d)","s"],["p","M210 180 Q218 185 222.5 235 Q235 145 247.5 235 Q260 145 272.5 235 Q285 145 297.5 235 Q302 185 310 180","B"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":0,"s":"Let each point have turned through angle θ = ωt. Both points move with speed ωR.\nThe left disc turns clockwise, so P has velocity ωR(−sinθ, −cosθ). The right disc turns anticlockwise, so Q has velocity ωR(+sinθ, −cosθ).\nRelative velocity = ωR(−2 sinθ, 0), so vᵣ = 2ωR |sin ωt|.\nThis is zero at t = 0, rises to 2ωR and falls back to zero at T/2, and repeats. In one period T there are two humps starting from zero: graph (a)."},
{"y":"AIEEE 2011","tp":"prd","st":"Torque and angular acceleration","q":"A pulley of radius 2 m is rotated about its axis by a force F = (20t − 5t²) newton (where t is measured in seconds) applied tangentially. If the moment of inertia of the pulley about its axis of rotation is 10 kg m², the number of rotations made by the pulley before its direction of motion is reversed, is","o":["less than 3","more than 3 but less than 6","more than 6 but less than 9","more than 9"],"c":1,"s":"Torque τ = F R = 2(20t − 5t²), so α = τ/I = 0.2(20t − 5t²) = 4t − t².\nStarting from rest, ω = 2t² − t³/3. It becomes zero again at t = 6 s, when the direction reverses.\nAngle turned θ = ∫ω dt = [2t³/3 − t⁴/12] from 0 to 6 = 144 − 108 = 36 rad.\nRotations = 36/2π ≈ 5.7, which is more than 3 but less than 6."},
{"y":"AIEEE 2011","tp":"prd","st":"Pulleys and hinged rods","q":"A mass m hangs with the help of a string wrapped around a pulley on a frictionless bearing. The pulley has mass m and radius R. Assuming pulley to be a perfect uniform circular disc, the acceleration of the mass m, if the string does not slip on the pulley, is","o":["{3;2}g","g","{2;3}g","{g;3}"],"c":2,"s":"Mass: mg − T = ma. Pulley (disc, I = ½mR²): TR = Iα = ½mR² (a/R), so T = ma/2.\nThen mg = ma + ma/2 = 3ma/2.\nSo a = 2g/3."},
{"y":"AIEEE 2009","tp":"prd","st":"Rotational kinetic energy and work","q":"A thin uniform rod of length l and mass m is swinging freely about a horizontal axis passing through its end. Its maximum angular speed is ω. Its centre of mass rises to a maximum height of","o":["{l²ω²;3g}","{lω;6g}","{l²ω²;2g}","{l²ω²;6g}"],"c":3,"s":"The angular speed is maximum at the lowest point. There the kinetic energy is ½Iω² with I = ml²/3.\nAt the highest point all of it has become potential energy of the centre of mass.\n½ (ml²/3) ω² = mgh, so h = l²ω²/(6g)."},
{"y":"IIT-JEE 2000","tp":"prd","st":"Torque and angular acceleration","q":"A long horizontal rod has a bead which can slide along its length and initially placed at a distance L from one end A of the rod. The rod is set in angular motion about A with constant angular acceleration α. If the coefficient of friction between the rod and the bead is μ, and gravity is neglected, then the time after which the bead starts slipping is","fig":{"w":320,"h":110,"alt":"Horizontal rod with end A on the left, a bead at distance L from A, and a curved arrow showing angular acceleration alpha","d":[["r",40,30,240,40],["r",116,33,8,34,"F"],["t",34,54,"A","es"],["l",40,88,120,88,"b"],["t",80,102,"L","ms"],["p","M284 28 Q310 50 284 72","a"],["t",292,24,"α","s"]]},"o":["√(μ/α)","μ/√α","1/√(μα)","infinitesimal"],"c":0,"s":"At time t the angular speed is ω = αt. With gravity neglected, the rod pushes the bead in two ways.\nAcross the rod (tangential): the normal force N = m α L gives the tangential acceleration αL.\nAlong the rod (towards A): friction must give the centripetal force f = mω²L = mα²t²L.\nSlipping starts when f = μN: mα²t²L = μ mαL, so t² = μ/α and t = √(μ/α)."},
{"y":"IIT-JEE 1992","tp":"prd","st":"Rotational kinematics","q":"A tube of length L is filled completely with an incompressible liquid of mass M and closed at both the ends. The tube is then rotated in a horizontal plane about one of its ends with a uniform angular velocity ω. The force exerted by the liquid at the other end is","o":["{Mω²L;2}","Mω²L","{Mω²L;4}","{Mω²L²;2}"],"c":[0],"s":"The liquid moves in a circle about the axis end, so it needs a net centripetal force.\nThe liquid behaves like all its mass M at the centre, a distance L/2 from the axis.\nNet force needed = M ω² (L/2). It is supplied by the far end of the tube, so the liquid pushes the far end with the same force.\nForce = Mω²L/2."},
{"y":"JEE Main 2025 · 2 Apr · Shift 2","tp":"prd","st":"Torque and angular acceleration","q":"A wheel of radius 0.2 m rotates freely about its center when a string that is wrapped over its rim is pulled by force of 10 N as shown in figure. The established torque produces an angular acceleration of 2 rad/s². Moment of inertia of the wheel is ______ kg m². (Acceleration due to gravity = 10 m/s²)","fig":{"w":220,"h":200,"alt":"Wheel on a fixed axle hung from a ceiling with a string from its rim pulled down by a 10 N force","d":[["r",60,8,100,8,"f"],["l",110,16,110,80],["c",110,80,40],["c",110,80,3,"F"],["l",150,80,150,165,"a"],["t",158,170,"10 N","s"]]},"n":1,"s":"Torque = F × R = 10 × 0.2 = 2 N m.\nτ = Iα, so I = τ/α = 2/2 = 1 kg m²."},
{"y":"JEE Main 2025 · 8 Apr · Shift 2","tp":"prd","st":"Torque and angular acceleration","q":"A thin solid disk of 1 kg is rotating along its diameter axis at the speed of 1800 rpm. By applying an external torque of 25π N m for 40 s, the speed increases to 2100 rpm. The diameter of the disk is ______ m.","n":40,"s":"ω₁ = 1800 rpm = 60π rad/s and ω₂ = 2100 rpm = 70π rad/s.\nα = (70π − 60π)/40 = π/4 rad/s².\nτ = Iα gives 25π = I (π/4), so I = 100 kg m².\nFor a disc about a diameter, I = mr²/4, so r² = 4I/m = 400 and r = 20 m.\nDiameter = 40 m."},
{"y":"JEE Main 2024 · 9 Apr · Shift 1","tp":"prd","st":"Torque and angular acceleration","q":"A string is wrapped around the rim of a wheel of moment of inertia 0.40 kg m² and radius 10 cm. The wheel is free to rotate about its axis. Initially the wheel is at rest. The string is now pulled by a force of 40 N. The angular velocity of the wheel after 10 s is x rad/s, where x is ______.","n":100,"s":"Torque = F R = 40 × 0.1 = 4 N m.\nα = τ/I = 4/0.40 = 10 rad/s².\nStarting from rest, ω = αt = 10 × 10 = 100 rad/s."},
{"y":"JEE Advanced 2024","tp":"pra","st":"Angular momentum of particles and bodies","q":"A thin uniform rod of length L and certain mass is kept on a frictionless horizontal table with a massless string of length L fixed to one end (top view is shown in the figure). The other end of the string is pivoted to a point O. If a horizontal impulse P is imparted to the rod at a distance x = L/n from the mid-point of the rod (see figure), then the rod and string revolve together around the point O, with the rod remaining aligned with the string. In such a case, the value of n is ______.","fig":{"w":340,"h":185,"alt":"Top view: rod of length L and string of length L in a line ending at pivot O, with an upward impulse P applied a distance x to the left of the rod midpoint","d":[["l",40,90,115,90,"B"],["l",115,90,190,90],["c",190,90,3,"F"],["t",196,86,"O"],["l",40,58,115,58,"b"],["t",77,52,"L","ms"],["l",115,58,190,58,"b"],["t",152,52,"L","ms"],["l",77,70,77,160,"d"],["l",115,70,115,100,"d"],["l",60,135,60,96,"a"],["t",66,132,"P","s"],["l",60,150,77,150,"b"],["t",68,164,"x","ms"],["l",77,172,115,172,"b"],["t",96,183,"L/2","ms"]]},"n":18,"s":"Let m be the mass of the rod. The rod lies from L to 2L from O, so its centre is 1.5L from O, and I about O = mL²/12 + m(1.5L)² = 7mL²/3.\nThe string is massless and can pull only along its own length, so it gives no sideways impulse. Hence P = m v_cm = m ω (1.5L).\nAngular momentum about O: P (1.5L + x) = I ω = (7mL²/3) ω.\nSubstitute P: 1.5L (1.5L + x) = 7L²/3, so 1.5L + x = 14L/9 and x = L/18.\nSo n = 18."},
{"y":"JEE Main 2023 · 13 Apr · Shift 2","tp":"prd","st":"Torque and angular acceleration","q":"A light rope is wound around a hollow cylinder of mass 5 kg and radius 70 cm. The rope is pulled with a force of 52.5 N. The angular acceleration of the cylinder will be ______ rad s⁻².","n":15,"s":"Hollow cylinder: I = MR² = 5 × 0.7² = 2.45 kg m².\nTorque = F R = 52.5 × 0.7 = 36.75 N m.\nα = τ/I = 36.75/2.45 = 15 rad/s²."},
{"y":"JEE Main 2022 · 27 Jul · Shift 1","tp":"prd","st":"Torque and angular acceleration","q":"A pulley of radius 1.5 m is rotated about its axis by a force F = (12t − 3t²) N applied tangentially (while t is measured in seconds). If moment of inertia of the pulley about its axis of rotation is 4.5 kg m², the number of rotations made by the pulley before its direction of motion is reversed, will be {K;π}. The value of K is ______.","n":18,"s":"Torque = 1.5 F, so α = 1.5(12t − 3t²)/4.5 = 4t − t².\nω = 2t² − t³/3. This is zero again at t = 6 s, when the direction reverses.\nAngle turned = ∫ω dt = [2t³/3 − t⁴/12] from 0 to 6 = 144 − 108 = 36 rad.\nRotations = 36/2π = 18/π, so K = 18."},
{"y":"JEE Main 2022 · 27 Jul · Shift 2","tp":"prd","st":"Rotational kinetic energy and work","q":"A solid cylinder length is suspended symmetrically through two massless strings as shown in the figure. The distance from the initial rest position, the cylinder should be unbinding the strings to achieve a speed of 4 m s⁻¹, is ______ cm. (Take g = 10 m s⁻²)","fig":{"w":300,"h":170,"alt":"Solid cylinder hung from a ceiling by two strings wound around it, with tension T upward in each string","d":[["r",55,10,190,8,"f"],["l",125,18,125,100],["l",175,18,175,100],["l",125,80,125,52,"a"],["l",175,80,175,52,"a"],["t",131,60,"T","s"],["t",181,60,"T","s"],["r",60,100,180,50],["l",118,100,118,150],["l",132,100,132,150],["l",168,100,168,150],["l",182,100,182,150]]},"n":120,"s":"The strings unwind without slipping. Energy conservation: mgh = ½mv² + ½Iω² with I = ½mR² and ω = v/R.\nSo mgh = ½mv² + ¼mv² = ¾mv², giving h = 3v²/(4g).\nh = 3 × 16/(4 × 10) = 1.2 m = 120 cm."},
{"y":"JEE Main 2022 · 24 Jun · Shift 1","tp":"prt","st":"Equilibrium of rigid bodies","q":"A metre scale is balanced on a knife edge at its centre. When two coins, each of mass 10 g are put one on the top of the other at the 10.0 cm mark the scale is found to be balanced at 40.0 cm mark. The mass of the metre scale is found to be x × 10⁻² kg. The value of x is ______.","n":6,"s":"The weight of the scale acts at its centre, the 50 cm mark. The knife edge is at 40 cm.\nCoins: 20 g at 10 cm, which is 30 cm to the left of the knife edge. Scale: mass M at 50 cm, which is 10 cm to the right.\nBalance of torques: 20 × 30 = M × 10, so M = 60 g = 6 × 10⁻² kg.\nSo x = 6."},
{"y":"JEE Main 2022 · 28 Jun · Shift 2","tp":"prd","st":"Pulleys and hinged rods","q":"A uniform disc with mass M = 4 kg and radius R = 10 cm is mounted on a fixed horizontal axle as shown in figure. A block with mass m = 2 kg hangs from a massless cord that is wrapped around the rim of the disc. During the fall of the block, the cord does not slip and there is no friction at the axle. The tension in the cord is ______ N. (Take g = 10 m s⁻²)","fig":{"w":260,"h":220,"alt":"Disc of mass M on a fixed horizontal axle below a support, with a cord from its rim carrying a block of mass m","d":[["r",60,8,160,8,"f"],["l",150,16,150,60],["c",150,60,36],["c",150,60,3,"F"],["t",150,52,"M","ms"],["l",114,60,114,150],["r",98,150,34,28,"f"],["t",115,169,"m","ms"]]},"n":10,"s":"Block: mg − T = ma. Disc: TR = ½MR² (a/R), so T = Ma/2 = 2a.\nThen 20 − 2a = 2a, so a = 5 m/s².\nT = 2a = 10 N."},
{"y":"JEE Main 2021 · 20 Jul · Shift 2","tp":"prd","st":"Rotational kinematics","q":"A body rotating with an angular speed of 600 rpm is uniformly accelerated to 1800 rpm in 10 sec. The number of rotations made in the process is ______.","n":200,"s":"Uniform acceleration, so use the average speed: (600 + 1800)/2 = 1200 rpm = 20 rev/s.\nRotations = 20 × 10 = 200."},
{"y":"JEE Main 2021 · 25 Jul · Shift 2","tp":"prd","st":"Torque and angular acceleration","q":"A solid disc of radius 20 cm and mass 10 kg is rotating with an angular velocity of 600 rpm, about an axis normal to its circular plane and passing through its centre of mass. The retarding torque required to bring the disc at rest in 10 s is ______ (π × 10⁻¹ N m).","n":4,"s":"ω = 600 rpm = 20π rad/s. Deceleration α = 20π/10 = 2π rad/s².\nI = ½MR² = ½ × 10 × 0.2² = 0.2 kg m².\nτ = Iα = 0.2 × 2π = 0.4π = 4 × (π × 10⁻¹) N m.\nThe value is 4."},
{"y":"JEE Main 2021 · 16 Mar · Shift 1","tp":"prd","st":"Torque and angular acceleration","q":"Consider a 20 kg uniform circular disk of radius 0.2 m. It is pin supported at its center and is at rest initially. The disk is acted upon by a constant force F = 20 N through a massless string wrapped around its periphery as shown in the figure. Suppose the disk makes n number of revolutions to attain an angular speed of 50 rad s⁻¹. The value of n, to the nearest integer, is ______.\n[Given: In one complete revolution, the disk rotates by 6.28 rad]","fig":{"w":240,"h":180,"alt":"Disc pinned at its centre C with a string around its rim pulled down by F = 20 N","d":[["c",110,70,45],["c",110,70,3,"F"],["t",100,62,"C","es"],["l",155,70,155,150,"a"],["t",163,150,"F = 20 N","s"]]},"n":20,"s":"τ = F R = 20 × 0.2 = 4 N m. I = ½MR² = ½ × 20 × 0.04 = 0.4 kg m².\nα = τ/I = 10 rad/s².\nω² = 2αθ gives θ = 50²/(2 × 10) = 125 rad.\nn = 125/6.28 ≈ 19.9, which is 20 to the nearest integer."},
{"y":"JEE Main 2021 · 17 Mar · Shift 1","tp":"prd","st":"Rotational kinematics","q":"The angular speed of truck wheel is increased from 900 rpm to 2460 rpm in 26 seconds. The number of revolutions by the truck engine during this time is ______. (Assuming the acceleration to be uniform)","n":728,"s":"Uniform acceleration, so use the average speed: (900 + 2460)/2 = 1680 rpm = 28 rev/s.\nRevolutions = 28 × 26 = 728."},
{"y":"JEE Main 2020 · 9 Jan · Shift 1","tp":"prd","st":"Pulleys and hinged rods","q":"One end of a straight uniform 1 m long bar is pivoted on horizontal table. It is released from rest when it makes an angle 30° from the horizontal (see figure). Its angular speed when it hits the table is given as √n s⁻¹, where n is an integer. The value of n is ______.","fig":{"w":240,"h":180,"alt":"Bar pivoted at the left end on a horizontal table, raised 30 degrees above the table, with an arrow showing it falls","d":[["l",20,140,225,140,"B"],["l",80,140,193,75,"B"],["c",80,140,3,"F"],["p","M120 140 A40 40 0 0 0 114.6 120"],["t",126,134,"30°","s"],["l",200,90,200,130,"da"]]},"n":15,"s":"The centre of mass falls by (l/2) sin30° = 0.25 m.\nEnergy: ½ (ml²/3) ω² = mg (l/2) sin30°, so ω² = 3g sin30°/l = 3 × 10 × 0.5/1 = 15.\nSo ω = √15 s⁻¹ and n = 15."},
{"y":"JEE Advanced 2014","tp":"prd","st":"Torque and angular acceleration","q":"A uniform circular disc of mass 1.5 kg and radius 0.5 m is initially at rest on a horizontal frictionless surface. Three forces of equal magnitude F = 0.5 N are applied simultaneously along the three sides of an equilateral triangle XYZ with its vertices on the perimeter of the disc (see figure). One second after applying the forces, the angular speed of the disc in rad s⁻¹ is ______.","fig":{"w":340,"h":210,"alt":"Disc with an inscribed equilateral triangle XYZ; three equal forces F act along its sides, one along each side in turn","d":[["c",170,100,70],["c",170,100,2,"F"],["t",176,96,"O","s"],["l",170,30,109.4,135],["l",109.4,135,230.6,135],["l",230.6,135,170,30],["l",109.4,135,97.4,155.8,"a"],["l",230.6,135,262,135,"a"],["l",170,30,182,9.2,"a"],["t",168,24,"X","es"],["t",104,132,"Y","es"],["t",236,150,"Z"],["t",186,12,"F","s"],["t",100,166,"F","s"],["t",266,130,"F","s"]]},"n":2,"s":"The three forces are equal and act around the triangle, so the net force is zero. Only torque acts.\nEach side of the inscribed triangle is at distance R/2 from the centre, so each force has torque F R/2.\nTotal torque = 3 × 0.5 × 0.25 = 0.375 N m. I = ½MR² = ½ × 1.5 × 0.25 = 0.1875 kg m².\nα = 0.375/0.1875 = 2 rad/s², so ω = αt = 2 rad/s after 1 s."},
{"y":"JEE Advanced 2016","tp":"prd","st":"Statements, matching and subjective","q":"A frame of reference that is accelerated with respect to an inertial frame of reference is called a non-inertial frame of reference. A coordinate system fixed on a circular disc rotating about a fixed axis with a constant angular velocity ω is an example of a non-inertial frame of reference. The relationship between the force F⃗ᵣₒₜ experienced by a particle of mass m moving on the rotating disc and the force F⃗ᵢₙ experienced by the particle in an inertial frame of reference is\nF⃗ᵣₒₜ = F⃗ᵢₙ + 2m(v⃗ᵣₒₜ × ω⃗) + m(ω⃗ × r⃗) × ω⃗,\nwhere v⃗ᵣₒₜ is the velocity of the particle in the rotating frame of reference and r⃗ is the position vector of the particle with respect to the centre of the disc.\nNow consider a smooth slot along a diameter of a disc of radius R rotating counter-clockwise with a constant angular speed ω about its vertical axis through its center. We assign a coordinate system with the origin at the center of the disc, the x-axis along the slot, the y-axis perpendicular to the slot and the z-axis along the rotation axis (ω⃗ = ωk̂). A small block of mass m is gently placed in the slot at r⃗ = (R/2)î at t = 0 and is constrained to move only along the slot.\nThe distance r of the block at time t is","fig":{"w":280,"h":190,"alt":"Top view of a disc rotating anticlockwise with a slot along the x axis; the block starts at R/2 from the centre; y axis perpendicular to the slot, z axis out of the page","d":[["c",140,100,80],["l",60,98,220,98],["l",60,102,220,102],["r",176,95,8,10,"F"],["l",140,100,240,100,"a"],["t",244,104,"x"],["l",140,100,140,30,"a"],["t",146,32,"y","s"],["c",140,100,3,"F"],["t",130,116,"O","es"],["l",140,125,180,125,"b"],["t",160,138,"R/2","ms"],["p","M200 24 Q140 2 82 32","a"],["t",140,14,"ω","ms"],["t",215,170,"z out of page","es"]]},"o":["{R;4}(e^(2ωt) + e^(−2ωt))","{R;4}(e^(ωt) + e^(−ωt))","{R;2} cos2ωt","{R;2} cosωt"],"c":1,"s":"Along the slot, the only force in the rotating frame is the centrifugal term mω²r (the slot is smooth).\nSo r̈ = ω²r, whose solution is r = A e^(ωt) + B e^(−ωt).\nConditions: r(0) = R/2 and ṙ(0) = 0 (placed gently), so A + B = R/2 and A − B = 0, giving A = B = R/4.\nr = (R/4)(e^(ωt) + e^(−ωt))."},
{"y":"JEE Advanced 2016","tp":"prd","st":"Statements, matching and subjective","q":"A frame of reference that is accelerated with respect to an inertial frame of reference is called a non-inertial frame of reference. A coordinate system fixed on a circular disc rotating about a fixed axis with a constant angular velocity ω is an example of a non-inertial frame of reference. The relationship between the force F⃗ᵣₒₜ experienced by a particle of mass m moving on the rotating disc and the force F⃗ᵢₙ experienced by the particle in an inertial frame of reference is\nF⃗ᵣₒₜ = F⃗ᵢₙ + 2m(v⃗ᵣₒₜ × ω⃗) + m(ω⃗ × r⃗) × ω⃗,\nwhere v⃗ᵣₒₜ is the velocity of the particle in the rotating frame of reference and r⃗ is the position vector of the particle with respect to the centre of the disc.\nNow consider a smooth slot along a diameter of a disc of radius R rotating counter-clockwise with a constant angular speed ω about its vertical axis through its center. We assign a coordinate system with the origin at the center of the disc, the x-axis along the slot, the y-axis perpendicular to the slot and the z-axis along the rotation axis (ω⃗ = ωk̂). A small block of mass m is gently placed in the slot at r⃗ = (R/2)î at t = 0 and is constrained to move only along the slot.\nThe net reaction of the disc on the block is","fig":{"w":280,"h":190,"alt":"Top view of a disc rotating anticlockwise with a slot along the x axis; the block starts at R/2 from the centre; y axis perpendicular to the slot, z axis out of the page","d":[["c",140,100,80],["l",60,98,220,98],["l",60,102,220,102],["r",176,95,8,10,"F"],["l",140,100,240,100,"a"],["t",244,104,"x"],["l",140,100,140,30,"a"],["t",146,32,"y","s"],["c",140,100,3,"F"],["t",130,116,"O","es"],["l",140,125,180,125,"b"],["t",160,138,"R/2","ms"],["p","M200 24 Q140 2 82 32","a"],["t",140,14,"ω","ms"],["t",215,170,"z out of page","es"]]},"o":["−mω²R cosωt ĵ − mg k̂","{1;2}mω²R(e^(2ωt) − e^(−2ωt)) ĵ + mg k̂","mω²R sinωt ĵ − mg k̂","{1;2}mω²R(e^(ωt) − e^(−ωt)) ĵ + mg k̂"],"c":3,"s":"The block moves only along the slot, so in the rotating frame the forces along y and z must balance. The disc reaction N has to cancel the Coriolis force and the weight.\nCoriolis force = 2m(v⃗ × ω⃗) = 2m ṙ ω (î × k̂) = −2mωṙ ĵ. So N has a y-part +2mωṙ.\nFrom r = (R/4)(e^(ωt) + e^(−ωt)): ṙ = (Rω/4)(e^(ωt) − e^(−ωt)).\nN_y = 2mω ṙ = ½mω²R(e^(ωt) − e^(−ωt)). Vertically N_z = mg.\nN = ½mω²R(e^(ωt) − e^(−ωt)) ĵ + mg k̂."},
{"y":"JEE Main 2023 · 10 Apr · Shift 2","tp":"pra","st":"Statements, matching and subjective","q":"Given below are two statements: one is labelled as Assertion A and the other is labelled as Reason R.\nAssertion A: An electric fan continues to rotate for some time after the current is switched off.\nReason R: Fan continues to rotate due to inertia of motion.\nIn the light of above statements, choose the most appropriate answer from the options given below.","o":["A is not correct but R is correct","Both A and R are correct and R is the correct explanation of A","A is correct but R is not correct","Both A and R are correct but R is NOT the correct explanation of A"],"c":1,"s":"Assertion A is true: a fan keeps turning for a while after switching off.\nReason R is true and is the cause: with no torque the fan keeps its rotational motion (inertia of motion), and friction slows it down only slowly.\nSo both are correct and R explains A."},
{"y":"IIT-JEE 1998","tp":"prd","st":"Statements, matching and subjective","q":"A uniform circular disc has radius R and mass m. A particle also of mass m, is fixed at a point A on the edge of the disc as shown in figure. The disc can rotate freely about a fixed horizontal chord PQ that is at a distance R/4 from the centre C of the disc. The line AC is perpendicular to PQ. Initially, the disc is held vertical with the point A at its highest position. It is then allowed to fall so that it starts rotating about PQ. Find the linear speed of the particle as it reaches its lowest position.","fig":{"w":300,"h":230,"alt":"Vertical disc with centre C, point A at the top, and a horizontal chord PQ a distance R/4 below the centre","d":[["c",140,115,80],["l",62.5,135,217.5,135,"B"],["t",56,140,"P","es"],["t",222,140,"Q"],["c",140,35,4,"F"],["t",146,30,"A","s"],["c",140,115,3,"F"],["t",132,111,"C","es"],["l",140,35,140,115,"d"],["t",146,78,"R","s"],["l",140,115,250,115,"d"],["l",244,115,244,135,"b"],["t",250,130,"R/4","s"]]},"a":"√(5gR)","s":"Distance of A from the axis PQ: R + R/4 = 5R/4 (above the axis at first, below it at the end).\nI about PQ: disc = mR²/4 + m(R/4)² = 5mR²/16; particle = m(5R/4)² = 25mR²/16. Total I = 15mR²/8.\nFall in height: the centre C falls by R/4 + R/4 = R/2; the particle falls by 5R/4 + 5R/4 = 5R/2. Loss of PE = mg(R/2) + mg(5R/2) = 3mgR.\n½Iω² = 3mgR gives ω² = 16g/(5R).\nSpeed of the particle v = ω (5R/4), so v² = (25R²/16)(16g/5R) = 5gR.\nv = √(5gR)."},
{"y":"IIT-JEE 1994","tp":"prd","st":"Statements, matching and subjective","q":"A block X of mass 0.5 kg is held by a long massless string on a frictionless inclined plane of inclination 30° to the horizontal. The string is wound on a uniform solid cylindrical drum Y of mass 2 kg and of radius 0.2 m as shown in figure. The drum is given an initial angular velocity such that the block X starts moving up the plane.\n(i) Find the tension in the string during the motion.\n(ii) At a certain instant of time the magnitude of the angular velocity of Y is 10 rad s⁻¹. Calculate the distance travelled by X from that instant of time until it comes to rest.","fig":{"w":320,"h":200,"alt":"Block X on a smooth incline of 30 degrees, with a string running up the slope to a drum Y at the top","d":[["l",40,170,280,31,"B"],["l",280,31,280,170],["l",40,170,280,170],["p","M133.3 116.1 L162.7 99.1 L145.7 69.7 L116.3 86.7 Z","f"],["t",134,100,"X","ms"],["l",154,84,268,19],["c",272,32,14],["c",272,32,2,"F"],["t",286,16,"Y","s"],["p","M85 170 A45 45 0 0 0 79 147.5"],["t",92,164,"30°","s"]]},"a":"(i) 1.63 N   (ii) 1.22 m","s":"Take g = 9.8 m/s². The block moves up but slows down, and so does the drum. Let a be the size of the deceleration.\nBlock (along the plane): mg sin30° − T = ma, so 0.5 × 9.8 × 0.5 − T = 0.5a, i.e. 2.45 − T = 0.5a.\nDrum: TR = ½MR² (a/R), so T = ½Ma = a (M = 2 kg).\nThen 2.45 = 1.5a, so a = 1.63 m/s² and T = 1.63 N.\n(ii) Speed of X when ω = 10 rad/s: v = ωR = 10 × 0.2 = 2 m/s.\nDistance until rest = v²/(2a) = 4/(2 × 1.633) = 1.22 m."},
{"y":"JEE Main 2025 · 4 Apr · Shift 1","tp":"pra","st":"Angular momentum of particles and bodies","q":"If L⃗ and P⃗ represent the angular momentum and linear momentum respectively of a particle of mass 'm' having position vector as r⃗ = a(î cosωt + ĵ sinωt). The direction of force is","o":["opposite to the direction of r⃗","opposite to the direction of L⃗ × P⃗","opposite to the direction of L⃗","opposite to the direction of P⃗"],"c":0,"s":"The position r⃗ = a(î cosωt + ĵ sinωt) describes uniform circular motion of radius a.\nThe velocity is v⃗ = aω(−î sinωt + ĵ cosωt) and the acceleration is a⃗ = −ω² r⃗.\nSo the force F⃗ = m a⃗ = −mω² r⃗ points opposite to r⃗ (towards the centre).\n(L⃗ × P⃗ itself points towards the centre, so the force is along it, not opposite to it.)"},
{"y":"JEE Main 2025 · 24 Jan · Shift 1","tp":"pra","st":"Angular momentum of particles and bodies","q":"An object of mass 'm' is projected from origin in a vertical xy plane at an angle 45° with the x-axis with an initial velocity v₀. The magnitude and direction of the angular momentum of the object with respect to origin, when it reaches at the maximum height, will be\n[g is acceleration due to gravity]","o":["{mv₀³;4√2 g} along positive z-axis","{mv₀³;2√2 g} along negative z-axis","{mv₀³;2√2 g} along positive z-axis","{mv₀³;4√2 g} along negative z-axis"],"c":3,"s":"At maximum height, t = v₀ sin45°/g. There x = v₀² sin45° cos45°/g = v₀²/(2g) and y = v₀² sin²45°/(2g) = v₀²/(4g).\nThe velocity there is horizontal: vₓ = v₀ cos45° = v₀/√2.\nL = m(x v_y − y vₓ) = −m y vₓ = −m (v₀²/4g)(v₀/√2) = −mv₀³/(4√2 g).\nThe negative sign means the direction is along the negative z-axis."},
{"y":"JEE Main 2024 · 8 Apr · Shift 2","tp":"pra","st":"Conservation of angular momentum","q":"A thin circular disc of mass M and radius R is rotating in a horizontal plane about an axis passing through its centre and perpendicular to its plane with angular velocity ω. If another disc of same dimensions but of mass M/2 is placed gently on the first disc co-axially, then the new angular velocity of the system is","o":["{3;2}ω","{2;3}ω","{4;5}ω","{5;4}ω"],"c":1,"s":"No external torque, so angular momentum is conserved.\nI₁ = ½MR² and I₂ = ½(M/2)R² = ¼MR².\nI₁ω = (I₁ + I₂)ω′ gives ω′ = (½M/(¾M)) ω = (2/3)ω."},
{"y":"JEE Main 2024 · 30 Jan · Shift 1","tp":"pra","st":"Angular momentum of particles and bodies","q":"A particle of mass m is projected with a velocity 'u' making an angle of 30° with the horizontal. The magnitude of angular momentum of the projectile about the point of projection when the particle is at its maximum height h is","o":["{√3 mu³;16 g}","{√3 mu²;2 g}","{mu³;√2 g}","zero"],"c":0,"s":"At the top the velocity is horizontal: v = u cos30° = u√3/2.\nMaximum height h = u² sin²30°/(2g) = u²/(8g).\nL = m v h (the velocity is perpendicular to the vertical distance h) = m (u√3/2)(u²/8g).\nL = √3 mu³/(16 g)."},
{"y":"JEE Main 2022 · 26 Jun · Shift 1","tp":"pra","st":"Conservation of angular momentum","q":"A thin circular ring of mass M and radius R is rotating with a constant angular velocity 2 rad s⁻¹ in a horizontal plane about an axis vertical to its plane and passing through the center of the ring. If two objects each of mass m be attached gently to the opposite ends of a diameter of ring, the ring will then rotate with an angular velocity (in rad s⁻¹).","o":["{M;M+m}","{M+2m;2M}","{2M;M+2m}","{2(M+2m);M}"],"c":2,"s":"No external torque, so angular momentum is conserved.\nBefore: I = MR², after: I′ = MR² + 2mR² = (M + 2m)R².\nMR² × 2 = (M + 2m)R² × ω′, so ω′ = 2M/(M + 2m) rad/s."},
{"y":"JEE Main 2021 · 27 Aug · Shift 2","tp":"pra","st":"Conservation of angular momentum","q":"Two discs have moments of inertia I₁ and I₂ about their respective axes perpendicular to the plane and passing through the centre. They are rotating with angular speeds ω₁ and ω₂ respectively and are brought into contact face to face with their axes of rotation coaxial. The loss in kinetic energy of the system in the process is given by","o":["{I₁I₂;I₁+I₂}(ω₁−ω₂)²","{(ω₁−ω₂)²;2(I₁+I₂)}","{I₁I₂;2(I₁+I₂)}(ω₁−ω₂)²","{(I₁−I₂)²ω₁ω₂;2(I₁+I₂)}"],"c":2,"s":"Angular momentum is conserved: ω = (I₁ω₁ + I₂ω₂)/(I₁ + I₂) (both turning the same way).\nLoss = ½I₁ω₁² + ½I₂ω₂² − ½(I₁ + I₂)ω².\nSimplifying gives the loss = I₁I₂(ω₁ − ω₂)² / [2(I₁ + I₂)]."},
{"y":"JEE Main 2021 · 31 Aug · Shift 1","tp":"pra","st":"Angular momentum of particles and bodies","q":"Angular momentum of a single particle moving with constant speed along circular path","o":["remains same in magnitude but changes in the direction","remains same in magnitude and direction","is zero","changes in magnitude but remains same in direction"],"c":1,"s":"About the centre of the circle, L = m v r, and its direction is along the axis, perpendicular to the plane of the circle.\nm, v and r are constant, and the axis direction does not change.\nSo L stays the same in magnitude and direction."},
{"y":"JEE Main 2021 · 17 Mar · Shift 1","tp":"pra","st":"Angular momentum of particles and bodies","q":"A mass M hangs on a massless rod of length l which rotates at a constant angular frequency. The mass M moves with steady speed in a circular path of constant radius. Assume that the system is in steady circular motion with constant angular velocity ω. The angular momentum of M about point A is L_A which lies in the positive z-direction and the angular momentum of M about point B is L_B. The correct statement for this system is","fig":{"w":280,"h":230,"alt":"Conical pendulum: point B on the vertical axis above, rod of length l at angle alpha carrying mass M on a horizontal circle with centre A on the axis","d":[["l",140,20,140,4,"a"],["t",146,10,"z","s"],["l",140,20,140,160,"d"],["l",140,20,200,160,"B"],["p","M80 160 A60 14 0 0 0 200 160 A60 14 0 0 0 80 160","d"],["l",140,160,194,160,"d"],["c",200,160,8,"F"],["c",140,20,3,"F"],["t",128,24,"B","es"],["t",128,166,"A","es"],["t",212,166,"M"],["t",146,62,"α","s"],["t",180,85,"l","s"],["t",166,152,"r","s"]]},"o":["L_B is constant in direction with varying magnitude","L_B is constant, both in magnitude and direction","L_A is constant, both in magnitude and direction","L_A and L_B are both constant in magnitude and direction"],"c":2,"s":"A is the centre of the circle, on the axis. About A, r⃗ and v⃗ are both in the horizontal plane, so L_A = M r v is along the z-axis and has a fixed size. So L_A is constant.\nB is the point of suspension, above the plane of the circle. The vector from B to M has a vertical part, so L_B has a horizontal part that turns with the mass.\nThe magnitude of L_B is constant but its direction keeps changing (it sweeps a cone).\nSo only L_A is constant in both magnitude and direction."},
{"y":"JEE Main 2021 · 18 Mar · Shift 1","tp":"pra","st":"Conservation of angular momentum","q":"A thin circular ring of mass M and radius r is rotating about its axis with an angular speed ω. Two particles having mass m each are now attached at diametrically opposite points. The angular speed of the ring will become","o":["ω {M;M+2m}","ω {M+2m;M}","ω {M−2m;M+2m}","ω {M;M+m}"],"c":0,"s":"No external torque, so angular momentum is conserved.\nMr²ω = (Mr² + 2mr²) ω′.\nω′ = ω M/(M + 2m)."},
{"y":"JEE Main 2021 · 26 Feb · Shift 2","tp":"prd","st":"Rotational kinetic energy and work","q":"A cord is wound round the circumference of wheel of radius r. The axis of the wheel is horizontal and the moment of inertia about it is I. A weight mg is attached to the cord at the end. The weight falls from rest. After falling through a distance 'h' the square of angular velocity of wheel will be","o":["2gh","{2gh;I+mr²}","{2mgh;I+mr²}","{2mgh;I+2mr²}"],"c":2,"s":"The cord does not slip, so the weight has speed v = ωr.\nEnergy: mgh = ½mv² + ½Iω² = ½mr²ω² + ½Iω² = ½(I + mr²)ω².\nω² = 2mgh/(I + mr²)."},
{"y":"JEE Main 2020 · 3 Sep · Shift 2","tp":"pra","st":"Angular momentum of particles and bodies","q":"A uniform rod of length 'l' is pivoted at one of its ends on a vertical shaft of negligible radius. When the shaft rotates at angular speed ω the rod makes an angle θ with it (see figure). To find θ equate the rate of change of angular momentum (direction going into the paper) {ml²;12} ω² sinθ cosθ about the centre of mass (CM) to the torque provided by the horizontal and vertical forces F_H and F_V about the CM. The value of θ is then such that","fig":{"w":260,"h":200,"alt":"Rod pivoted on a vertical rotating shaft making angle theta with it; vertical force F_V up and horizontal force F_H to the left at the pivot","d":[["l",100,25,100,190,"B"],["l",100,50,174.6,156.5,"B"],["p","M100 90 A40 40 0 0 0 123 82.8"],["t",112,104,"θ","s"],["l",90,50,90,18,"a"],["t",86,14,"F_V","es"],["l",90,50,48,50,"a"],["t",44,46,"F_H","es"],["t",150,24,"ω (shaft turns)","s"]]},"o":["cosθ = {2g;3lω²}","cosθ = {g;2lω²}","cosθ = {g;lω²}","cosθ = {3g;2lω²}"],"c":3,"s":"Forces at the pivot: F_V = mg (balances the weight) and F_H = mω²(l/2) sinθ (gives the circular motion of the CM).\nTorques about the CM: F_V acts at horizontal distance (l/2) sinθ, F_H at vertical distance (l/2) cosθ, and they act in opposite senses.\nSo (ml²/12) ω² sinθ cosθ = mg (l/2) sinθ − mω²(l/2) sinθ (l/2) cosθ.\nDivide by m l sinθ: (l/12) ω² cosθ + (l/4) ω² cosθ = g/2, so (l/3) ω² cosθ = g/2.\ncosθ = 3g/(2lω²)."},
{"y":"JEE Main 2020 · 6 Sep · Shift 1","tp":"pra","st":"Angular momentum of particles and bodies","q":"Four point masses, each of mass m, are fixed at the corners of a square of side l. The square is rotating with angular frequency ω, about an axis passing through one of the corners of the square and parallel to its diagonal, as shown in the figure. The angular momentum of the square about this axis is","fig":{"w":260,"h":220,"alt":"Square with an axis line through its top-left corner running parallel to the dashed diagonal from the bottom-left to the top-right corner","d":[["l",80,80,170,80],["l",170,80,170,170],["l",170,170,80,170],["l",80,170,80,80],["l",80,170,170,80,"d"],["l",40,120,130,30,"B"],["t",36,114,"Axis","es"],["c",80,80,3,"F"],["c",170,80,3,"F"],["c",170,170,3,"F"],["c",80,170,3,"F"],["t",125,190,"l","ms"]]},"o":["ml²ω","4 ml²ω","3 ml²ω","2 ml²ω"],"c":2,"s":"L = Iω, where I = Σ m r² with r the distance of each mass from the axis.\nThe axis passes through one corner (r = 0) and is parallel to the diagonal joining the two neighbouring corners. Each of these two corners is at distance l/√2 (half the other diagonal). The opposite corner is at distance √2 l.\nI = m[0 + (l²/2) + (l²/2) + 2l²] = 3ml².\nL = 3ml²ω."},
{"y":"JEE Main 2020 · 8 Jan · Shift 1","tp":"pra","st":"Collisions with rotating bodies","q":"Consider a uniform rod of mass M = 4m and length l pivoted about its centre. A mass m moving with velocity v making angle θ = π/4 to the rod's long axis collides with one end of the rod and sticks to it. The angular speed of the rod-mass system just after the collision is","fig":{"w":340,"h":140,"alt":"Rod pivoted at its centre; a mass m moving at 45 degrees to the rod hits its right end","d":[["l",70,80,270,80,"B"],["c",170,80,3,"F"],["c",270,80,5,"F"],["l",330,20,277,73,"a"],["t",318,18,"v"],["t",284,60,"45°","s"],["t",272,100,"m"],["t",170,66,"M = 4m","ms"],["l",70,118,270,118,"b"],["t",170,134,"l","ms"]]},"o":["{4v;7l}","{3√2 v;7l}","{3v;7√2 l}","{3v;7l}"],"c":1,"s":"No external torque about the pivot during the collision, so angular momentum about the pivot is conserved.\nBefore: L = m·v·sin45°·(l/2) = mvl/(2√2).\nAfter: I = (4m)l²/12 + m(l/2)² = ml²/3 + ml²/4 = 7ml²/12.\nω = L/I = [mvl/(2√2)]·[12/(7ml²)] = 6v/(7√2 l) = 3√2 v/(7l).\nAnswer: (b)."},
{"y":"JEE Main 2019 · 9 Apr · Shift 2","tp":"pra","st":"Conservation of angular momentum","q":"A thin smooth rod of length L and mass M is rotating freely with angular speed ω₀ about an axis perpendicular to the rod and passing through its center. Two beads of mass m and negligible size are at the center of the rod initially. The beads are free to slide along the rod. The angular speed of the system, when the beads reach the opposite ends of the rod, will be","o":["{Mω₀;M+3m}","{Mω₀;M+6m}","{Mω₀;M+m}","{Mω₀;M+2m}"],"c":1,"s":"The rod is smooth, so there is no external torque on the system about the axis: angular momentum is conserved.\nInitially I₁ = ML²/12.\nFinally the beads are at L/2 from the axis: I₂ = ML²/12 + 2m(L/2)² = ML²/12 + mL²/2 = L²(M + 6m)/12.\nI₁ω₀ = I₂ω gives ω = Mω₀/(M + 6m).\nAnswer: (b)."},
{"y":"JEE Main 2019 · 10 Apr · Shift 1","tp":"pra","st":"Conservation of angular momentum","q":"Two coaxial discs, having moments of inertia I₁ and {I₁;2}, are rotating with respective angular velocities ω₁ and {ω₁;2}, about their common axis. They are brought in contact with each other and thereafter they rotate with a common angular velocity. If E_f and E_i are the final and initial total energies, then (E_f − E_i) is","o":["−{I₁ω₁²;24}","{3;8} I₁ω₁²","{I₁ω₁²;6}","−{I₁ω₁²;12}"],"c":0,"s":"Angular momentum is conserved: I₁ω₁ + (I₁/2)(ω₁/2) = (3I₁/2)ω, so ω = 5ω₁/6.\nE_i = ½I₁ω₁² + ½(I₁/2)(ω₁/2)² = (9/16)I₁ω₁².\nE_f = ½(3I₁/2)(5ω₁/6)² = (25/48)I₁ω₁².\nE_f − E_i = (25/48 − 27/48)I₁ω₁² = −I₁ω₁²/24.\nAnswer: (a)."},
{"y":"JEE Main 2019 · 10 Apr · Shift 2","tp":"pra","st":"Angular momentum of particles and bodies","q":"The time dependence of the position of a particle of mass m = 2 is given by r⃗(t) = 2t î − 3t² ĵ. Its angular momentum, with respect to the origin, at time t = 2 s is","o":["−48k̂","−34(k̂ − î)","36 k̂","48(î + ĵ)"],"c":0,"s":"r = 2t î − 3t² ĵ, so v = dr/dt = 2 î − 6t ĵ.\nAt t = 2 s: r = 4 î − 12 ĵ and v = 2 î − 12 ĵ.\nL = m(r × v) = 2[(4)(−12) − (−12)(2)] k̂ = 2(−48 + 24) k̂ = −48 k̂.\nAnswer: (a)."},
{"y":"JEE Main 2019 · 12 Apr · Shift 1","tp":"pra","st":"Conservation of angular momentum","q":"A person of mass M, sitting on a swing of length L and swinging with an angular amplitude θ₀. If the person stands up when the swing passes through its lowest point, the work done by him, assuming that his centre of mass moves by a distance l (l << L), is close to","o":["Mgl(1 − θ₀²)","Mgl","Mgl(1 + θ₀²)","Mgl(1 + {θ₀²;2})"],"c":2,"s":"At the lowest point the kinetic energy is KE = MgL(1 − cosθ₀) ≈ MgLθ₀²/2.\nStanding up: angular momentum about the support is conserved, so with I = ML², KE = L²/(2I) and KE' = KE·L²/(L − l)² ≈ KE(1 + 2l/L).\nGain in KE = (MgLθ₀²/2)(2l/L) = Mglθ₀².\nThe centre of mass also rises by l, gaining PE = Mgl.\nWork done = Mglθ₀² + Mgl = Mgl(1 + θ₀²).\nAnswer: (c)."},
{"y":"JEE Main 2019 · 12 Jan · Shift 2","tp":"pra","st":"Angular momentum of particles and bodies","q":"A particle of mass 20 g is released with an initial velocity 5 m/s along the curve from the point A, as shown in the figure. The point A is at height h from point B. The particle slides along the frictionless surface. When the particle reaches point B, its angular momentum about O will be (Take g = 10 m/s²)","fig":{"w":340,"h":190,"alt":"Curved track with A on the left at the same level as a dotted line, B at the bottom, h = 10 m between them, and O a = 10 m above the dotted line","d":[["l",20,60,330,60,"d"],["p","M40 60 C70 130 130 150 190 150 C250 150 310 130 330 60"],["c",40,60,4,"F"],["t",30,52,"A","e"],["t",196,166,"B"],["l",190,12,190,150,"d"],["t",180,20,"O","e"],["l",208,14,208,58,"b"],["t",214,42,"a = 10 m","s"],["l",170,62,170,148,"b"],["t",164,108,"h = 10 m","es"]]},"o":["6 kg-m²/s","8 kg-m²/s","3 kg-m²/s","2 kg-m²/s"],"c":0,"s":"Energy conservation from A to B (h = 10 m): v² = 5² + 2gh = 25 + 200 = 225, so v = 15 m/s.\nAt B the velocity is horizontal. O is a = 10 m above the level of A, so it is a + h = 20 m vertically above B.\nL = m·v·(perpendicular distance) = 0.02 × 15 × 20 = 6 kg m²/s.\nAnswer: (a)."},
{"y":"JEE Main 2018 · Online","tp":"pra","st":"Collisions with rotating bodies","q":"A thin uniform bar of length L and mass 8m lies on a smooth horizontal table. Two point masses m and 2m are moving in the same horizontal plane from opposite sides of the bar with speeds 2v and v respectively. The masses stick to the bar after collision at a distance {L;3} and {L;6} respectively from the centre of the bar. If the bar starts rotating about its center of mass as a result of collision, the angular speed of the bar will be","fig":{"w":340,"h":150,"alt":"Bar with centre O; mass m with speed 2v hits from above at L/3 on the right, mass 2m with speed v hits from below at L/6 on the left","d":[["r",30,60,280,30,"f"],["c",170,75,2.5,"F"],["t",176,56,"O","s"],["c",263,75,5,"F"],["t",272,70,"m"],["l",263,8,263,64,"a"],["t",270,28,"2v"],["c",123,75,6,"F"],["t",113,70,"2m","e"],["l",123,145,123,86,"a"],["t",130,132,"v"],["l",123,40,170,40,"b"],["t",146,34,"L/6","ms"],["l",170,112,263,112,"b"],["t",216,128,"L/3","ms"]]},"o":["{6v;5L}","{v;6L}","{v;5L}","{3v;5L}"],"c":0,"s":"Linear momentum: m(2v) − 2m(v) = 0, so the centre of mass stays at the centre and the bar only rotates.\nAngular momentum about the centre (both impulses turn the bar the same way): m(2v)(L/3) + 2m(v)(L/6) = 2mvL/3 + mvL/3 = mvL.\nI = 8mL²/12 + m(L/3)² + 2m(L/6)² = (2/3 + 1/9 + 1/18)mL² = 5mL²/6.\nω = mvL ÷ (5mL²/6) = 6v/(5L).\nAnswer: (a)."},
{"y":"JEE Advanced 2017","tp":"prr","st":"Rolling and its energy","q":"Consider regular polygons with number of sides n = 3, 4, 5 … as shown in the figure. The centre of all polygons is at height h from the ground. They roll on a horizontal surface about the leading vertex without slipping and sliding as depicted. The maximum increase in height of the locus of the center of mass for each polygon is Δ. Then Δ depends on n and h as","fig":{"w":340,"h":165,"alt":"A triangle, a square and a pentagon each standing on a side with the centre at height h; each rolls forward about its leading vertex","d":[["l",10,140,330,140],["p","M20 140 L90 140 L55 79 Z"],["c",55,120,2.5,"F"],["l",40,140,40,120,"b"],["t",36,134,"h","e"],["r",130,90,50,50],["c",155,115,2.5,"F"],["l",143,140,143,115,"b"],["t",140,131,"h","e"],["p","M260 85.7 L231.5 106.4 L242.4 140 L277.6 140 L288.5 106.4 Z"],["c",260,115.7,2.5,"F"],["l",250,140,250,116,"b"],["t",247,132,"h","e"],["t",170,158,"each polygon rolls about its right-hand (leading) bottom vertex","ms"]]},"o":["Δ = h sin²(π/n)","Δ = h tan²(π/2n)","Δ = h({1;cos(π/n)} − 1)","Δ = h sin(2π/n)"],"c":2,"s":"Resting on a side, the centre is at height h, which is the distance from the centre to a side (apothem).\nThe distance from the centre to a vertex is R. In a regular n-gon the half-angle at the centre between a vertex and the adjacent side midpoint is π/n, so h = R cos(π/n).\nWhile the polygon pivots about a vertex, the centre moves on a circle of radius R about that vertex, and it is highest (height R) when it is directly above the vertex.\nΔ = R − h = h/cos(π/n) − h = h[1/cos(π/n) − 1].\nAnswer: (c)."},
{"y":"JEE Main 2016 · Online","tp":"pra","st":"Collisions with rotating bodies","q":"A cubical block of side 30 cm is moving with velocity 2 m s⁻¹ on a smooth horizontal surface. The surface has a bump at a point O as shown in figure. The angular velocity (in rad/s) of the block immediately after it hits the bump, is","fig":{"w":340,"h":150,"alt":"Cube of side a sliding to the right with speed v towards a small ridge at O on the ground","d":[["l",10,120,330,120],["r",40,60,60,60,"f"],["t",70,95,"M","m"],["l",40,48,100,48,"b"],["t",70,42,"a = 30 cm","ms"],["l",100,90,160,90,"a"],["t",130,82,"2 m/s","ms"],["p","M252 120 L260 108 L268 120 Z","F"],["t",260,138,"O","m"]]},"o":["13.3","5.0","9.4","6.7"],"c":1,"s":"The bump gives an impulse at O, so angular momentum about O is conserved.\nBefore: L = mv(a/2) (the centre of mass is a/2 above O's level).\nAfter: block rotates about its edge at O: I = ma²/6 + m(a/√2)² = 2ma²/3.\nω = mva/2 ÷ (2ma²/3) = 3v/(4a) = (3 × 2)/(4 × 0.3) = 5 rad/s.\nAnswer: (b)."},
{"y":"JEE Main 2015 · Online","tp":"pra","st":"Angular momentum of particles and bodies","q":"A particle of mass 2 kg is on a smooth horizontal table and moves in a circular path of radius 0.6 m. The height of the table from the ground is 0.8 m. If the angular speed of the particle is 12 rad s⁻¹, the magnitude of its angular momentum about a point on the ground right under the centre of the circle is","o":["8.64 kg m² s⁻¹","11.52 kg m² s⁻¹","14.4 kg m² s⁻¹","20.16 kg m² s⁻¹"],"c":2,"s":"Position vector from that point to the particle has a horizontal part 0.6 m and a vertical part 0.8 m, so |r| = √(0.36 + 0.64) = 1.0 m.\nThe velocity is horizontal and tangent to the circle, so it is perpendicular to r.\nSpeed v = ωr' = 12 × 0.6 = 7.2 m/s.\nL = m v |r| = 2 × 7.2 × 1.0 = 14.4 kg m² s⁻¹.\nAnswer: (c)."},
{"y":"JEE Main 2014","tp":"pra","st":"Angular momentum of particles and bodies","q":"A bob of mass m attached to an inextensible string of length l is suspended from a vertical support. The bob rotates in a horizontal circle with an angular speed ω rad s⁻¹ about the vertical. About the point of suspension","o":["angular momentum changes both in direction and magnitude.","angular momentum is conserved.","angular momentum changes in magnitude but not in direction.","angular momentum changes in direction but not in magnitude."],"c":3,"s":"Take the point of suspension as the reference point. The position vector from it to the bob has constant length and turns round as the bob moves, and the velocity is tangent to the circle.\nSo |L| = m v r (the angle between r and v stays 90°) is constant.\nThe vertical component of L is constant, but the horizontal component turns with the bob, so the direction of L keeps changing.\nL changes in direction but not in magnitude.\nAnswer: (d)."},
{"y":"JEE Main 2014 · Online","tp":"pra","st":"Angular momentum of particles and bodies","q":"A particle is moving in a circular path of radius a, with a constant velocity v as shown in the figure. The center of circle is marked by C. The angular momentum from the origin O can be written as","fig":{"w":340,"h":200,"alt":"Circle of radius a with centre C on the x axis passing through the origin O; a line from O at angle theta to the x axis meets the circle at the particle","d":[["c",150,100,90],["l",60,195,60,6,"a"],["l",60,100,330,100,"a"],["t",66,10,"y"],["t",324,116,"x"],["t",54,114,"O","e"],["c",150,100,2.5,"F"],["t",150,116,"C","m"],["l",60,100,195,22],["l",150,100,195,22],["c",195,22,4,"F"],["t",178,66,"a"],["p","M95 100 A35 35 0 0 0 90.3 82.5"],["t",99,96,"θ","s"],["l",195,22,169,7,"a"],["t",170,18,"v","s"]]},"o":["va(1 + cos2θ)","va(1 + cosθ)","va cos2θ","va"],"c":0,"s":"The book gives no mass, so L is taken per unit mass (m = 1).\nThe circle passes through O with centre C = (a, 0). The point P at angle θ from O on the chord subtends angle 2θ at the centre, so P = (a + a cos2θ, a sin2θ).\nVelocity is tangent: v = (−v sin2θ, v cos2θ).\nL = x·v_y − y·v_x = av(1 + cos2θ)cos2θ + av sin²2θ = av(1 + cos2θ).\nAnswer: (a)."},
{"y":"AIEEE 2012 · Online","tp":"pra","st":"Conservation of angular momentum","q":"A stone of mass m, tied to the end of a string, is whirled around in a circle on a horizontal frictionless table. The length of the string is reduced gradually keeping the angular momentum of the stone about the centre of the circle constant. Then, the tension in the string is given by T = Arⁿ, where A is a constant, r is the instantaneous radius of the circle. The value of n is equal to","o":["−1","−2","−4","−3"],"c":3,"s":"Angular momentum L = mvr is constant, so v = L/(mr).\nThe tension supplies the centripetal force: T = mv²/r = (m/r)·L²/(m²r²) = L²/(mr³).\nSo T ∝ r⁻³, giving n = −3.\nAnswer: (d)."},
{"y":"JEE Main 2013","tp":"prr","st":"Slipping and friction in rolling","q":"A hoop of radius r and mass m rotating with an angular velocity ω₀ is placed on a rough horizontal surface. The initial velocity of the centre of the hoop is zero. What will be the velocity of the centre of the hoop when it ceases to slip?","o":["rω₀","{rω₀;4}","{rω₀;3}","{rω₀;2}"],"c":3,"s":"Take torques about the contact point: gravity and the normal force both act along the vertical line through it, and friction acts at the point itself, so angular momentum about the contact point is conserved.\nInitially: L = mr²ω₀ (only spin).\nWhen slipping stops, v = rω: L = mvr + mr²(v/r) = 2mrv.\n2mrv = mr²ω₀, so v = rω₀/2.\nAnswer: (d)."},
{"y":"IIT-JEE 2012","tp":"pra","st":"Angular momentum of particles and bodies","q":"A thin uniform rod, pivoted at O, is rotating in the horizontal plane with constant angular speed ω, as shown in the figure. At time t = 0, a small insect starts from O and moves with constant speed v with respect to the rod towards other end. It reaches the end of the rod at t = T and stops. The angular speed of the system remains ω throughout. The magnitude of the torque (|τ⃗|) on the system about O, as a function of time is best represented by which plot?","fig":{"w":340,"h":252,"alt":"Rod with an insect moving from the pivot O, and four torque against time graphs (a) to (d)","d":[["l",30,16,250,16,"B"],["c",30,16,3,"F"],["t",24,34,"O","m"],["c",95,16,4,"F"],["t",95,36,"insect","ms"],["l",104,10,150,10,"a"],["t",156,14,"v","s"],["t",258,20,"rod (horizontal plane)","s"],["l",30,130,155,130,"a"],["l",30,130,30,70,"a"],["t",2,78,"(a)","s"],["t",36,74,"|τ|","s"],["t",155,143,"t","es"],["t",26,142,"0","es"],["l",100,130,100,125],["t",100,143,"T","ms"],["p","M 30 130 L 100 80 H 145","B"],["l",190,130,315,130,"a"],["l",190,130,190,70,"a"],["t",162,78,"(b)","s"],["t",196,74,"|τ|","s"],["t",315,143,"t","es"],["t",186,142,"0","es"],["l",260,130,260,125],["t",260,143,"T","ms"],["p","M 190 130 L 260 80","B"],["l",260,80,260,130,"d"],["l",30,230,155,230,"a"],["l",30,230,30,170,"a"],["t",2,178,"(c)","s"],["t",36,174,"|τ|","s"],["t",155,243,"t","es"],["t",26,242,"0","es"],["l",100,230,100,225],["t",100,243,"T","ms"],["p","M 30 230 Q 85 230 100 180 H 145","B"],["l",190,230,315,230,"a"],["l",190,230,190,170,"a"],["t",162,178,"(d)","s"],["t",196,174,"|τ|","s"],["t",315,243,"t","es"],["t",186,242,"0","es"],["l",260,230,260,225],["t",260,243,"T","ms"],["p","M 190 230 Q 245 230 260 180","B"],["l",260,180,260,230,"d"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":1,"s":"Since ω is constant, torque = dL/dt = ω·d(I)/dt.\nAt time t the insect is at x = vt, so I = I_rod + m v²t² and dI/dt = 2mv²t.\nSo τ = 2mv²ωt: a straight line through the origin, rising until t = T.\nAfter t = T the insect stops, I is constant and τ = 0, so the torque drops suddenly to zero.\nThis is graph (b)."},
{"y":"IIT-JEE 2012","tp":"pra","st":"Angular momentum of particles and bodies","q":"A small mass m is attached to a massless string whose other end is fixed at P as shown in the figure. The mass is undergoing circular motion in the x-y plane with centre at O and constant angular speed ω. If the angular momentum of the system, calculated about O and P are denoted by L⃗ₒ and L⃗ₚ respectively, then","fig":{"w":340,"h":170,"alt":"Conical pendulum: mass m on a string fixed at P moves in a horizontal circle centred at O below P, z axis vertical","d":[["l",170,25,170,5,"a"],["t",176,10,"z"],["l",170,25,170,130,"d"],["p","M170 110 A80 20 0 1 0 170 150 A80 20 0 1 0 170 110","d"],["l",170,25,240,140],["c",240,140,6,"F"],["t",250,134,"m"],["c",170,25,3,"F"],["t",178,28,"P","s"],["c",170,130,2.5,"F"],["t",176,150,"O"],["l",252,150,288,152,"a"],["t",292,154,"ω"]]},"o":["L⃗ₒ and L⃗ₚ do not vary with time.","L⃗ₒ varies with time while L⃗ₚ remains constant.","L⃗ₒ remains constant while L⃗ₚ varies with time.","L⃗ₒ and L⃗ₚ both vary with time."],"c":2,"s":"About O, the position vector is radial and the velocity is tangent, so L_O = mωr² along the z axis with constant magnitude and direction.\nAbout P, the position vector has a constant z-component and a horizontal component that turns with the mass.\nSo L_P has a constant z-component plus a horizontal part that rotates: its direction changes with time.\nL_O stays constant, while L_P varies with time.\nAnswer: (c)."},
{"y":"AIEEE 2011","tp":"pra","st":"Conservation of angular momentum","q":"A thin horizontal circular disc is rotating about a vertical axis passing through its centre. An insect is at rest at a point near the rim of the disc. The insect now moves along a diameter of the disc to reach its other end. During the journey of the insect, the angular speed of the disc","o":["remains unchanged","continuously decreases","continuously increases","first increases and then decreases."],"c":3,"s":"No external torque acts about the axis, so Iω is constant.\nI = I_disc + m r², where r is the insect's distance from the axis.\nAs the insect goes from the rim to the centre, r decreases, so I decreases and ω increases.\nFrom the centre to the other rim, r increases, so I increases and ω decreases.\nAnswer: (d)."},
{"y":"AIEEE 2010","tp":"pra","st":"Angular momentum of particles and bodies","q":"A small particle of mass m is projected at an angle θ with the x-axis with an initial velocity v₀ in the x-y plane as shown in the figure. At a time t < {v₀ sinθ;g}, the angular momentum of the particle is\n(î, ĵ and k̂ are unit vectors along x, y and z-axis respectively.)","fig":{"w":340,"h":185,"alt":"Projectile path in the x-y plane starting at the origin with speed v0 at angle theta to the x axis","d":[["l",40,170,320,170,"a"],["l",40,170,40,15,"a"],["t",326,174,"x"],["t",46,18,"y"],["t",30,184,"O"],["p","M40 170 Q170 -10 300 170"],["l",40,170,68,131,"a"],["t",74,132,"v₀"],["p","M70 170 A30 30 0 0 0 57.6 145.7"],["t",78,162,"θ","s"]]},"o":["½ mgv₀t² cosθ î","−mgv₀t² cosθ ĵ","mgv₀t cosθ k̂","−½ mgv₀t² cosθ k̂"],"c":3,"s":"x = v₀cosθ·t, y = v₀sinθ·t − ½gt²; vₓ = v₀cosθ, vᵧ = v₀sinθ − gt.\nL = m(x·vᵧ − y·vₓ) along z:\n= m v₀cosθ·t(v₀sinθ − gt) − m(v₀sinθ·t − ½gt²)v₀cosθ\n= m v₀cosθ(−gt² + ½gt²) = −½ m g v₀ t² cosθ.\nThe sign is negative, so it points along −z (clockwise motion).\nAnswer: (d)."},
{"y":"AIEEE 2007","tp":"pra","st":"Angular momentum of particles and bodies","q":"Angular momentum of the particle rotating with a central force is constant due to","o":["constant torque","constant force","constant linear momentum","zero torque."],"c":3,"s":"A central force always acts along the line joining the particle and the centre.\nTorque = r × F = 0 because r and F are parallel.\nSince τ = dL/dt, zero torque means L is constant.\nAnswer: (d)."},
{"y":"AIEEE 2006","tp":"pra","st":"Conservation of angular momentum","q":"A thin circular ring of mass m and radius R is rotating about its axis with a constant angular velocity ω. Two objects each of mass M are attached gently to the opposite ends of a diameter of the ring. The ring now rotates with an angular velocity, ω' is","o":["{ωm;m+2M}","{ω(m+2M);m}","{ω(m−2M);m+2M}","{ωm;m+M}"],"c":0,"s":"No external torque, so angular momentum is conserved.\nInitial: I = mR². Final: I' = mR² + 2MR² = (m + 2M)R².\nmR²ω = (m + 2M)R²ω', so ω' = ωm/(m + 2M).\nAnswer: (a)."},
{"y":"IIT-JEE 2005","tp":"pra","st":"Angular momentum of particles and bodies","q":"A particle is confined to rotate in a circular path with decreasing linear speed. Then which of the following is correct?","o":["L⃗ (angular momentum) is conserved about the centre","only direction of angular momentum L⃗ is conserved","it spirals towards the centre","its acceleration is towards the centre."],"c":1,"s":"The speed decreases, so there is a tangential force and a torque about the centre (along the axis). Hence L = mvr changes in magnitude: (a) is wrong.\nThe path is a circle, not a spiral: (c) is wrong.\nThe acceleration has a tangential part as well as a centripetal part, so it does not point to the centre: (d) is wrong.\nThe torque is along the axis, so the direction of L (along the axis) stays the same while its magnitude falls.\nAnswer: (b)."},
{"y":"AIEEE 2004","tp":"pra","st":"Conservation of angular momentum","q":"A solid sphere is rotating in free space. If the radius of the sphere is increased keeping mass same which one of the following will not be affected?","o":["Moment of inertia","Angular momentum","Angular velocity","Rotational kinetic energy"],"c":1,"s":"In free space there is no external torque, so the angular momentum stays constant.\nMoment of inertia (2/5)MR² increases, so ω = L/I decreases, and the kinetic energy L²/2I decreases.\nOnly the angular momentum is unaffected.\nAnswer: (b)."},
{"y":"IIT-JEE 2004","tp":"pra","st":"Conservation of angular momentum","q":"A child is standing with folded hands at the centre of a platform rotating about its central axis. The kinetic energy of the system is K. The child now stretches his arms so that the moment of inertia of the system doubles. The kinetic energy of the system now is","o":["2K","K/2","K/4","4K"],"c":1,"s":"No external torque, so L = Iω is constant.\nKinetic energy K = L²/(2I).\nWhen I doubles at constant L, the kinetic energy halves: K' = K/2.\nAnswer: (b)."},
{"y":"IIT-JEE 2004","tp":"pra","st":"Conservation of angular momentum","q":"A horizontal circular plate is rotating about a vertical axis passing through its centre with an angular velocity ω₀. A man sitting at the centre having two blocks in his hands stretches out his hands so that the moment of inertia of the system doubles. If the kinetic energy of the system is K initially, its final kinetic energy will be","o":["2K","K/2","K","K/4."],"c":1,"s":"The angular momentum Iω is conserved because there is no external torque.\nK = L²/(2I), so doubling I halves K.\nFinal kinetic energy = K/2.\nAnswer: (b)."},
{"y":"AIEEE 2003","tp":"pra","st":"Angular momentum of particles and bodies","q":"A particle performing uniform circular motion has angular momentum L. If its angular frequency is doubled and its kinetic energy halved, then the new angular momentum is","o":["L/4","2L","4L","L/2."],"c":0,"s":"L = mωr² and K = ½mω²r².\nω doubles and K halves, so r² changes by the factor (1/2)/4 = 1/8.\nNew L = m(2ω)(r²/8) = (1/4)mωr² = L/4.\nAnswer: (a)."},
{"y":"IIT-JEE 2003","tp":"pra","st":"Angular momentum of particles and bodies","q":"A particle undergoes uniform circular motion. About which point on the plane of the circle, will the angular momentum of the particle remain conserved?","o":["centre of the circle","on the circumference of the circle","inside the circle","outside the circle."],"c":0,"s":"In uniform circular motion the only force needed is centripetal and it always points towards the centre.\nAbout the centre, the torque r × F is zero, so L is conserved.\nAbout any other point in the plane, the force does not pass through the point, so there is a torque and L changes.\nAnswer: (a)."},
{"y":"IIT-JEE 2003","tp":"pra","st":"Collisions with rotating bodies","q":"Consider a body, shown in figure, consisting of two identical balls, each of mass M connected by a light rigid rod. If an impulse J = Mv is imparted to the body at one of its ends, what would be its angular velocity?","fig":{"w":340,"h":140,"alt":"Two balls of mass M joined by a light rod of length L; an impulse J = Mv acts upward on the right ball","d":[["l",60,70,280,70],["c",60,70,6,"F"],["c",280,70,6,"F"],["t",60,56,"M","m"],["t",288,60,"M"],["l",60,34,280,34,"b"],["t",170,28,"L","ms"],["l",280,118,280,80,"a"],["t",286,112,"J = Mv","s"]]},"o":["{v;L}","{2v;L}","{v;3L}","{v;4L}"],"c":0,"s":"The body is free, so it rotates about its centre of mass (the middle of the rod).\nAngular impulse about the centre: J·(L/2) = Iω, with I = 2M(L/2)² = ML²/2.\nMv·L/2 = (ML²/2)ω, so ω = v/L.\n(Check: centre moves at v/2, so the struck ball moves at v/2 + ωL/2 = v and the other at 0.)\nAnswer: (a)."},
{"y":"AIEEE 2002","tp":"pra","st":"Angular momentum of particles and bodies","q":"A particle of mass m moves along line PC with velocity v as shown. What is the angular momentum of the particle about P?","fig":{"w":340,"h":190,"alt":"Axes with origin O; a straight line through P on the vertical axis rises to C; the particle moves along it; l is the perpendicular from O to the line and r joins O to the particle","d":[["l",120,160,120,10,"a"],["l",120,160,330,160,"a"],["l",20,145,320,25,"a"],["t",324,22,"C","s"],["t",128,102,"P"],["t",108,176,"O","m"],["l",120,160,104.5,111.2],["l",110.1,109,112.3,114.6],["l",112.3,114.6,106.7,116.8],["t",94,140,"l","e"],["l",120,160,230,61],["t",182,122,"r"],["c",230,61,4,"F"],["t",236,74,"m","s"],["l",232,50,282,30,"a"],["t",284,40,"v","s"]]},"o":["mvL","mvl","mvr","zero."],"c":3,"s":"Angular momentum about a point is m·v·(perpendicular distance of the line of motion from that point).\nThe particle moves along the line PC, which passes through P, so the perpendicular distance is zero.\nSo the angular momentum about P is zero (mvl, mvL and mvr are the values about other points).\nAnswer: (d)."},
{"y":"AIEEE 2002","tp":"pra","st":"Conservation of angular momentum","q":"Initial angular velocity of a circular disc of mass M is ω₁. Then two small spheres of mass m are attached gently to two diametrically opposite points on the edge of the disc. What is the final angular velocity of the disc?","o":["({M+m;M})ω₁","({M+m;m})ω₁","({M;M+4m})ω₁","({M;M+2m})ω₁"],"c":2,"s":"No external torque, so angular momentum is conserved.\nInitial I = ½MR². Final I' = ½MR² + 2mR².\n½MR²ω₁ = (½M + 2m)R²ω', so ω' = Mω₁/(M + 4m).\nAnswer: (c)."},
{"y":"IIT-JEE 2002","tp":"pra","st":"Conservation of angular momentum","q":"A circular platform is free to rotate in a horizontal plane about a vertical axis passing through its centre. A tortoise is sitting at the edge of the platform. Now, the platform is given an angular velocity ω₀. When the tortoise moves along a chord of the platform with a constant velocity (with respect to the platform), the angular velocity of the platform ω(t) will vary with time t as","fig":{"w":340,"h":222,"alt":"Four graphs of angular velocity of the platform against time: (a) constant, (b) rises then falls smoothly, (c) falls then rises, (d) rises then falls linearly","d":[["l",30,100,155,100,"a"],["l",30,100,30,30,"a"],["t",2,38,"(a)","s"],["t",36,34,"ω(t)","s"],["t",155,113,"t","es"],["t",26,112,"0","es"],["p","M 30 55 H 145","B"],["l",27,55,33,55],["t",24,58,"ω₀","es"],["l",190,100,315,100,"a"],["l",190,100,190,30,"a"],["t",162,38,"(b)","s"],["t",196,34,"ω(t)","s"],["t",315,113,"t","es"],["t",186,112,"0","es"],["p","M 190 55 Q 247 25 305 55","B"],["l",187,55,193,55],["t",184,58,"ω₀","es"],["l",30,200,155,200,"a"],["l",30,200,30,130,"a"],["t",2,138,"(c)","s"],["t",36,134,"ω(t)","s"],["t",155,213,"t","es"],["t",26,212,"0","es"],["p","M 30 155 Q 87 185 145 155","B"],["l",27,155,33,155],["t",24,158,"ω₀","es"],["l",190,200,315,200,"a"],["l",190,200,190,130,"a"],["t",162,138,"(d)","s"],["t",196,134,"ω(t)","s"],["t",315,213,"t","es"],["t",186,212,"0","es"],["p","M 190 155 L 247 130 L 305 155","B"],["l",187,155,193,155],["t",184,158,"ω₀","es"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":1,"s":"There is no external torque, so L = Iω is constant.\nOn a chord, the tortoise's distance from the axis first decreases (to the foot of the perpendicular from the centre) and then increases back to the radius.\nSo I first decreases then increases, which makes ω first rise above ω₀ and then fall back, smoothly (distance² is a quadratic in t).\nThis is the arch-shaped graph (b)."},
{"y":"IIT-JEE 2000","tp":"pra","st":"Conservation of angular momentum","q":"An equilateral triangle ABC formed from a uniform wire has two small identical beads initially located at A. The triangle is set rotating about the vertical axis AO. Then the beads are released from rest simultaneously and allowed to slide down, one along AB and the other along AC as shown. Neglecting frictional effects, the quantities that are conserved as the beads slide down, are","fig":{"w":340,"h":200,"alt":"Equilateral triangle ABC with apex A at the top and base BC; two beads slide down along AB and AC; AO is the vertical axis of rotation and g points down","d":[["l",170,20,80,176],["l",170,20,260,176],["l",80,176,260,176],["l",170,6,170,176,"d"],["c",134,82,5,"F"],["c",206,82,5,"F"],["l",130,90,118,110,"a"],["l",210,90,222,110,"a"],["t",178,18,"A"],["t",62,180,"B"],["t",268,180,"C"],["t",176,192,"O","s"],["l",300,40,300,90,"a"],["t",306,70,"g"]]},"o":["angular velocity and total energy (kinetic and potential)","total angular momentum and total energy","angular velocity and moment of inertia about the axis of rotation","total angular momentum and moment of inertia about the axis of rotation."],"c":1,"s":"Normal forces from the wire do no work on frictionless beads, and gravity is conservative, so total mechanical energy is conserved.\nNo external torque about the vertical axis acts, so total angular momentum is conserved.\nThe beads move outward from the axis, so the moment of inertia increases and the angular velocity decreases, so these two are not conserved.\nAnswer: (b)."},
{"y":"IIT-JEE 2000","tp":"prt","st":"Equilibrium of rigid bodies","q":"A cubical block of side L rests on a rough horizontal surface with co-efficient of friction μ. A horizontal force F is applied on the block as shown. If the co-efficient of friction is sufficiently high so that the block does not slide before toppling, the minimum force required to topple the block is","fig":{"w":340,"h":160,"alt":"A cube of side L and mass M on the ground with a horizontal force F applied at its top left corner P","d":[["l",60,140,260,140],["r",120,60,80,80,"f"],["t",160,105,"M","m"],["l",60,60,120,60,"a"],["t",80,52,"F"],["t",122,54,"P","es"],["l",215,60,215,140,"b"],["t",222,104,"L"]]},"o":["infinitesimal","mg/4","mg/2","mg(1 − μ)"],"c":2,"s":"The block is about to topple when it just starts turning about its bottom edge on the side away from the force; then the normal force and friction act at that edge.\nTorque about that edge: F applied at the top (height L) must equal the torque of weight, whose line is L/2 from the edge.\nF·L = mg·(L/2), so F = mg/2.\nSince friction is large enough, the block does not slide first.\nAnswer: (c)."},
{"y":"IIT-JEE 1999","tp":"pra","st":"Collisions with rotating bodies","q":"A cubical block of side a is moving with velocity v on a horizontal smooth plane as shown in figure. It hits a ridge at point O. The angular speed of the block after it hits O is","fig":{"w":340,"h":150,"alt":"Cube of side a sliding to the right with speed v towards a ridge at O on the ground","d":[["l",10,120,330,120],["r",130,60,60,60,"f"],["t",160,95,"M","m"],["l",130,48,190,48,"b"],["t",160,42,"a","ms"],["l",190,90,240,90,"a"],["t",216,82,"v","ms"],["p","M262 120 L270 108 L278 120 Z","F"],["t",270,138,"O","m"]]},"o":["{3v;4a}","{3v;2a}","{√3 v;√2 a}","zero."],"c":0,"s":"The ridge exerts an impulse at O, so angular momentum about O is conserved (gravity and the normal force have no moment about O during the short impact).\nBefore: L = mv(a/2).\nAfter: the cube turns about its edge at O: I = ma²/6 + m(a/√2)² = 2ma²/3.\nω = (mva/2)/(2ma²/3) = 3v/(4a).\nAnswer: (a)."},
{"y":"IIT-JEE 1999","tp":"pra","st":"Angular momentum of particles and bodies","q":"A disc of mass M and radius R is rolling with angular speed ω on a horizontal plane as shown in figure. The magnitude of angular momentum of the disc about the origin O is","fig":{"w":340,"h":180,"alt":"A disc of radius R rolling clockwise with angular speed omega on the x axis, with the origin O at the left","d":[["l",40,150,320,150,"a"],["l",40,150,40,20,"a"],["t",34,16,"Y","e"],["t",324,166,"X"],["t",28,164,"O"],["c",180,110,40],["c",180,110,2.5,"F"],["l",180,110,180,150],["t",186,134,"R"],["t",170,104,"M","e"],["p","M150 75 A47 47 0 0 1 207 72","a"],["t",214,68,"ω"]]},"o":["½ MR²ω","MR²ω","{3;2} MR²ω","2MR²ω."],"c":2,"s":"For rolling without slipping the centre moves with v = ωR, at height R above the x axis.\nAngular momentum about O = (orbital part) + (spin part) = M·v·R + ½MR²ω.\n= MR²ω + ½MR²ω = (3/2)MR²ω (both parts have the same sense).\nAnswer: (c)."},
{"y":"IIT-JEE 1999","tp":"pra","st":"Collisions with rotating bodies","q":"A smooth sphere A is moving on a frictionless horizontal plane with angular speed ω and centre of mass velocity v. It collides elastically and head-on with an identical sphere B at rest. Neglect friction everywhere. After the collision, their angular speeds are ω_A and ω_B, respectively. Then","o":["ω_A < ω_B","ω_A = ω_B","ω_A = ω","ω_B = ω."],"c":2,"s":"With no friction the contact force at the collision passes through both centres, so it exerts no torque on either sphere.\nSo neither angular speed changes during the collision: sphere A keeps ω and sphere B keeps 0.\n(The centre of mass velocities are exchanged, since the spheres are identical and the collision is elastic and head-on.)\nSo ω_A = ω.\nAnswer: (c)."},
{"y":"IIT-JEE 1997","tp":"pra","st":"Angular momentum of particles and bodies","q":"A mass m is moving with a constant velocity along a line parallel to the x-axis, away from the origin. Its angular momentum with respect to the origin","o":["is zero","remains constant","goes on increasing","goes on decreasing."],"c":1,"s":"Angular momentum about the origin = m·v·(perpendicular distance of the line of motion from the origin).\nThe line is parallel to the x-axis, so this distance is constant (= y), and v is constant.\nSo L = mvy stays constant (it is also zero only if y = 0).\nAnswer: (b)."},
{"y":"IIT-JEE 1983","tp":"pra","st":"Conservation of angular momentum","q":"A thin circular ring of mass M and radius r is rotating about its axis with a constant angular velocity ω. Two objects each of mass m, are attached gently to the opposite ends of a diameter of the ring. The wheel now rotates with an angular velocity","o":["{ωM;M+m}","{ω(M−2m);M+2m}","{ωM;M+2m}","{ω(M+2m);M}."],"c":2,"s":"No external torque, so angular momentum is conserved.\nInitial I = Mr²; final I' = Mr² + 2mr² = (M + 2m)r².\nMr²ω = (M + 2m)r²ω', so ω' = ωM/(M + 2m).\nAnswer: (c)."},
{"y":"JEE Advanced 2020","tp":"pra","st":"Collisions with rotating bodies","q":"A rod of mass m and length L, pivoted at one of its ends, is hanging vertically. A bullet of the same mass moving at speed v strikes the rod horizontally at a distance x from its pivoted end and gets embedded in it. The combined system now rotates with angular speed ω about the pivot. The maximum angular speed ωₘ is achieved for x = xₘ. Then","fig":{"w":340,"h":185,"alt":"A vertical rod of length L hanging from a pivot at the top; a bullet with velocity v hits it horizontally at distance x below the pivot","d":[["r",90,20,24,140,"f"],["c",102,28,4],["c",102,100,4,"F"],["l",20,100,88,100,"a"],["t",50,92,"v"],["l",150,28,150,100,"b"],["t",156,66,"x"],["l",190,28,190,160,"b"],["t",196,96,"L"],["l",114,28,200,28,"d"],["l",114,100,160,100,"d"],["l",114,160,200,160,"d"]]},"o":["ω = {3vx;L²+3x²}","ω = {12vx;L²+12x²}","xₘ = {L;√3}","ωₘ = {v;2L}√3"],"c":[0,2,3],"s":"Angular momentum about the pivot is conserved (the pivot force has no moment about it): mvx = (mL²/3 + mx²)ω.\nSo ω = 3vx/(L² + 3x²): (a) is true, (b) is false.\nFor maximum, d/dx[x/(L² + 3x²)] = 0 gives L² + 3x² = 6x², so xₘ = L/√3: (c) is true.\nωₘ = 3v(L/√3)/(L² + L²) = √3 v/(2L): (d) is true.\nAnswer: (a), (c), (d)."},
{"y":"JEE Advanced 2016","tp":"pra","st":"Angular momentum of particles and bodies","q":"Two thin circular discs of mass m and 4m, having radii of a and 2a, respectively, are rigidly fixed by a massless, rigid rod of length l = √24 a through their centers. This assembly is laid on a firm and flat surface, and set rolling without slipping on the surface so that the angular speed about the axis of the rod is ω. The angular momentum of the entire assembly about the point O is L⃗ (see the figure). Which of the following statement(s) is (are) true?","fig":{"w":340,"h":180,"alt":"Two discs of radii a and 2a on a rod rising from the origin O on the ground, both resting on the ground, rolling about the rod axis with angular speed omega","d":[["l",20,150,320,150,"B"],["l",30,148,30,30,"da"],["t",36,34,"z"],["t",18,164,"O"],["l",30,148,137.8,126,"d"],["l",137.8,126,245.6,104,"B"],["p","M138 104 A6 22 0 1 0 138 148 A6 22 0 1 0 138 104"],["p","M246 59 A10 45 0 1 0 246 149 A10 45 0 1 0 246 59"],["t",138,98,"m","m"],["t",246,52,"4m","m"],["t",80,128,"l"],["t",190,106,"l"],["l",146,126,146,148,"b"],["t",152,142,"a","s"],["l",256,104,256,149,"b"],["t",262,130,"2a","s"],["p","M290 80 Q312 100 290 122","a"],["t",306,106,"ω"]]},"o":["The magnitude of angular momentum of the assembly about its center of mass is {17ma²ω;2}.","The center of mass of the assembly rotates about the z-axis with an angular speed of ω/5.","The magnitude of the z-component of L⃗ is 55ma²ω.","The magnitude of angular momentum of center of mass of the assembly about the point O is 81ma²ω."],"c":[0,1],"s":"Geometry: the discs touch the ground, so the assembly is a cone with apex O; the half-angle α satisfies sinα = a/√(l² + a²) = a/5a = 1/5, and the rod makes angle α with the ground.\nRolling without slipping: the total angular velocity lies along the ground line through O, so its vertical component is zero: ω sinα (spin) is cancelled by the rotation Ω of the axis about z. So Ω = ω sinα = ω/5: (b) is true.\n(a) Taking the angular momentum about the centre of mass as the spin about the rod: I = ½ma² + ½(4m)(2a)² = 17ma²/2, so L = 17ma²ω/2: (a) is true (this is the intended result).\n(c), (d): the book marks them false; they do not equal 55ma²ω and 81ma²ω.\nAnswer: (a), (b)."},
{"y":"JEE Advanced 2016","tp":"pra","st":"Angular momentum of particles and bodies","q":"The position vector r⃗ of a particle of mass m is given by the following equation, r⃗(t) = αt³ î + βt² ĵ, where α = 10/3 m s⁻³, β = 5 m s⁻² and m = 0.1 kg. At t = 1 s, which of the following statement(s) is (are) true about the particle?","o":["The velocity v⃗ is given by v⃗ = (10î + 10ĵ) m s⁻¹.","The angular momentum L⃗ with respect to the origin is given by L⃗ = −{5;3}k̂ N m s.","The force F⃗ is given by F⃗ = (î + 2ĵ) N.","The torque τ⃗ with respect to the origin is given by τ⃗ = −{20;3}k̂ N m."],"c":[0,1,3],"s":"v = dr/dt = 3αt² î + 2βt ĵ = (10 î + 10 ĵ) m/s at t = 1 s: (a) true.\nr = (10/3 î + 5 ĵ) m. L = m(r × v) = 0.1[(10/3)(10) − (5)(10)] k̂ = 0.1(−50/3) k̂ = −(5/3) k̂ N m s: (b) true.\na = 6αt î + 2β ĵ = (20 î + 10 ĵ), so F = ma = (2 î + ĵ) N, not (î + 2ĵ): (c) false.\nτ = r × F = [(10/3)(1) − (5)(2)] k̂ = −(20/3) k̂ N m: (d) true.\nAnswer: (a), (b), (d)."},
{"y":"JEE Advanced 2015","tp":"pra","st":"Conservation of angular momentum","q":"A ring of mass M and radius R is rotating with angular speed ω about a fixed vertical axis passing through its centre O with two point masses each of mass {M;8} at rest at O. These masses can move radially outwards along two massless rods fixed on the ring as shown in the figure. At some instant the angular speed of the system is {8;9}ω and one of the masses is at a distance of {3;5}R from O. At this instant the distance of the other mass from O is","fig":{"w":340,"h":200,"alt":"A ring seen obliquely rotating about a vertical axis through its centre O, with two rods running from O to the ring and a point mass on each rod","d":[["p","M170 45 A120 55 0 1 0 170 155 A120 55 0 1 0 170 45"],["l",170,10,170,190],["p","M155 22 Q175 8 198 20","a"],["t",204,20,"ω"],["c",170,100,2.5,"F"],["t",176,120,"O"],["l",170,100,95,57],["l",170,100,245,57],["c",150,89,4,"F"],["c",190,89,4,"F"],["l",146,86,126,75,"a"],["l",194,86,214,75,"a"]]},"o":["{2;3}R","{1;3}R","{3;5}R","{4;5}R"],"c":3,"s":"The rods are fixed to the ring and no external torque acts about the axis, so angular momentum is conserved.\nInitially: MR²ω. Later: [MR² + (M/8)(r₁² + r₂²)](8ω/9).\nMR² + (M/8)(r₁² + r₂²) = (9/8)MR², so r₁² + r₂² = R².\nWith r₁ = 3R/5: r₂² = R² − 9R²/25 = 16R²/25, so r₂ = 4R/5.\nAnswer: (d)."},
{"y":"IIT-JEE 1998","tp":"pra","st":"Angular momentum of particles and bodies","q":"The torque τ⃗ on a body about a given point is found to be equal to A⃗ × L⃗ where A⃗ is a constant vector, and L⃗ is the angular momentum of the body about that point. From this it follows that","o":["d L⃗/dt is perpendicular to L⃗ at all instants of time.","the component of L⃗ in the direction of A⃗ does not change with time.","the magnitude of L⃗ does not change with time.","L⃗ does not change with time."],"c":[0,1,2],"s":"We have τ = dL/dt = A × L.\n(a) A × L is perpendicular to L, so dL/dt ⊥ L: true.\n(c) L·dL/dt = 0, so |L|² is constant: the magnitude of L does not change: true.\n(b) A × L is also perpendicular to A, so d(A·L)/dt = A·dL/dt = 0: the component of L along A is constant: true.\n(d) dL/dt ≠ 0, so L (direction) does change: false.\nAnswer: (a), (b), (c)."},
{"y":"IIT-JEE 1991","tp":"pra","st":"Collisions with rotating bodies","q":"A uniform bar of length 6a and mass 8m lies on a smooth horizontal table. Two point masses m and 2m moving in the same horizontal plane with speed 2v and v respectively, strike the bar [as shown in the figure] and stick to it after collision. Denoting angular velocity (about the centre of mass), total energy and centre of mass velocity by ω, E and v_C respectively, we have after collision","fig":{"w":340,"h":205,"alt":"Bar of length 6a with centre C; mass 2m moving down with speed v hits above at distance a left of C; mass m moving up with speed 2v hits below at distance 2a right of C","d":[["r",20,70,300,40,"f"],["c",170,90,2.5,"F"],["t",178,86,"C","s"],["c",120,63,6,"F"],["t",108,60,"2m","e"],["l",120,6,120,52,"a"],["t",128,30,"v"],["c",270,117,6,"F"],["t",284,114,"m"],["l",270,195,270,126,"a"],["t",278,170,"2v"],["l",120,146,170,146,"b"],["l",170,146,270,146,"b"],["t",145,162,"a","ms"],["t",220,162,"2a","ms"],["l",320,70,320,110,"d"]]},"o":["v_C = 0","ω = {3v;5a}","ω = {v;5a}","E = {3mv²;5}"],"c":[0,2,3],"s":"From the figure: mass 2m (speed v) hits at a from the centre on one side, mass m (speed 2v) hits at 2a on the other side, moving in opposite directions.\nMomentum: m(2v) − 2m(v) = 0, so v_C = 0.\nAngular momentum about the centre (same sense): m(2v)(2a) + 2m(v)(a) = 6mva.\nI = 8m(6a)²/12 + m(2a)² + 2m(a)² = 24ma² + 4ma² + 2ma² = 30ma², so ω = 6mva/30ma² = v/(5a).\nE = ½Iω² = ½(30ma²)(v²/25a²) = 3mv²/5.\nAnswer: (a), (c), (d)."},
{"y":"IIT-JEE 1990","tp":"pra","st":"Angular momentum of particles and bodies","q":"A particle of mass m is projected with a velocity v making an angle of 45° with the horizontal. The magnitude of the angular momentum of the projectile about the point of projection, when the particle is at its maximum height h, is","o":["zero","{mv³;4√2 g}","{mv³;√2 g}","m√(2gh³)"],"c":[1,3],"s":"At the top the velocity is horizontal: vₓ = v cos45° = v/√2.\nMaximum height h = v² sin²45°/(2g) = v²/(4g).\nAngular momentum about the point of projection = m vₓ h = m (v/√2)(v²/4g) = mv³/(4√2 g).\nAlso h = v²/(4g), so m√(2gh³) = m√(2g·v⁶/(64g³)) = mv³√2/(8g) = mv³/(4√2 g). Both (b) and (d) are the same value.\nAnswer: (b) and (d)."},
{"y":"JEE Main 2025 · 4 Apr · Shift 2","tp":"pra","st":"Conservation of angular momentum","q":"A solid sphere of uniform density and radius R is rotating initially with constant angular velocity (ω₁) about its diameter. After some time during the rotation its starts loosing mass at a uniform rate, with no change in its shape. The angular velocity of the sphere when its radius become R/2 is xω₁. The value of x is ______.","n":32,"s":"Treat the angular momentum of the sphere as conserved (the book assumes the lost mass carries away no angular momentum).\nUniform density: mass M ∝ R³, and I = (2/5)MR² ∝ R⁵.\nWhen R becomes R/2, I becomes I/2⁵ = I/32.\nI₁ω₁ = I₂ω₂ gives ω₂ = 32ω₁.\nSo x = 32."},
{"y":"JEE Main 2025 · 22 Jan · Shift 2","tp":"pra","st":"Angular momentum of particles and bodies","q":"The position vectors of two 1 kg particles, (A) and (B) are given by r⃗_A = (α₁t² î + α₂t ĵ + α₃t k̂) m and r⃗_B = (β₁t î + β₂t² ĵ + β₃t k̂) m, respectively; (α₁ = 1 m/s², α₂ = 3n m/s, α₃ = 2 m/s, β₁ = 2 m/s, β₂ = −1 m/s², β₃ = 4p m/s, where t is time, n and p are constants. At t = 1 s, |v⃗_A| = |v⃗_B| and velocities v⃗_A and v⃗_B of the particles are orthogonal to each other. At t = 1 s, the magnitude of angular momentum of particle (A) with respect to the position of particle (B) is √L kg m² s⁻¹. The value of L is ______.","n":90,"s":"At t = 1 s: v_A = (2, 3n, 2) and v_B = (2, −2, 4p).\n|v_A| = |v_B| gives 8 + 9n² = 8 + 16p², so 3n = ±4p.\nv_A · v_B = 4 − 6n + 8p = 0. The case 3n = 4p gives 4 = 0, which is impossible, so 3n = −4p, which gives 4 + 8p + 8p = 0, p = −1/4 and n = 1/3.\nThen r_A = (1, 1, 2), r_B = (2, −1, −1), v_A = (2, 1, 2).\nr_A − r_B = (−1, 2, 3). L⃗ = m (r_A − r_B) × v_A = (2·2 − 3·1, 3·2 − (−1)·2, (−1)·1 − 2·2) = (1, 8, −5).\n|L⃗|² = 1 + 64 + 25 = 90, so L = 90."},
{"y":"JEE Main 2024 · 6 Apr · Shift 1","tp":"pra","st":"Conservation of angular momentum","q":"If the radius of earth is reduced to three-fourth of its present value without change in its mass then value of duration of the day of earth will be ______ hours 30 minutes.","n":13,"s":"No external torque, so angular momentum is conserved: Iω is constant, so I/T is constant, so T ∝ I ∝ R².\nT₂ = 24 × (3/4)² = 24 × 9/16 = 13.5 hours = 13 hours 30 minutes.\nSo the blank is 13."},
{"y":"JEE Main 2024 · 29 Jan · Shift 2","tp":"pra","st":"Angular momentum of particles and bodies","q":"A body of mass 5 kg moving with a uniform speed 3√2 m s⁻¹ in X-Y plane along the line y = x + 4. The angular momentum of the particle about the origin will be ______ kg m² s⁻¹.","n":60,"s":"For straight-line motion, L = m v d, where d is the perpendicular distance of the line from the origin.\nLine x − y + 4 = 0: d = 4/√2 = 2√2 m.\nL = 5 × 3√2 × 2√2 = 5 × 3 × 4 = 60 kg m² s⁻¹."},
{"y":"JEE Main 2024 · 30 Jan · Shift 1","tp":"pra","st":"Conservation of angular momentum","q":"Consider a disc of mass 5 kg, radius 2 m, rotating with angular velocity of 10 rad/s about an axis perpendicular to the plane of rotation. An identical disc is kept gently over the rotating disc along the same axis. The energy dissipated so that both the discs continue to rotate together without slipping is ______ J.","fig":{"w":340,"h":150,"alt":"A horizontal disc of mass 5 kg and radius 2 m rotating with angular velocity 10 rad/s about a vertical axis","d":[["p","M80 95 A90 22 0 1 0 260 95 A90 22 0 1 0 80 95 Z","f"],["l",170,95,170,35,"a"],["l",170,95,260,95,"d"],["t",215,90,"2 m","ms"],["t",182,32,"ω = 10 rad/s"],["t",170,140,"Mass = 5 kg","m"]]},"n":250,"s":"I of one disc = ½MR² = ½ × 5 × 4 = 10 kg m².\nAngular momentum is conserved: 10 × 10 = 20 × ω, so ω = 5 rad/s.\nInitial KE = ½ × 10 × 10² = 500 J. Final KE = ½ × 20 × 5² = 250 J.\nEnergy dissipated = 500 − 250 = 250 J."},
{"y":"JEE Main 2024 · 30 Jan · Shift 1","tp":"pra","st":"Conservation of angular momentum","q":"Two discs of moment of inertia I₁ = 4 kg m² and I₂ = 2 kg m², about their central axes and normal to their planes, rotating with angular speeds 10 rad/s and 4 rad/s are brought into contact face to face with their axes of rotation coincident. The loss in kinetic energy of the system in the process is ______ J.","n":24,"s":"Angular momentum is conserved: 4 × 10 + 2 × 4 = (4 + 2) ω, so ω = 48/6 = 8 rad/s.\nInitial KE = ½ × 4 × 100 + ½ × 2 × 16 = 200 + 16 = 216 J.\nFinal KE = ½ × 6 × 64 = 192 J.\nLoss = 216 − 192 = 24 J."},
{"y":"JEE Main 2024 · 31 Jan · Shift 2","tp":"pra","st":"Angular momentum of particles and bodies","q":"A body of mass 'm' is projected with a speed 'u' making an angle of 45° with the ground. The angular momentum of the body about the point of projection, at the highest point is expressed as {√2 mu³;Xg}. The value of 'X' is ______.","n":8,"s":"At the highest point the velocity is horizontal: u cos45° = u/√2.\nHeight H = u² sin²45°/(2g) = u²/(4g).\nL = m (u/√2) H = m u³/(4√2 g) = √2 m u³/(8g).\nComparing with √2 m u³/(Xg): X = 8."},
{"y":"JEE Advanced 2024","tp":"pra","st":"Conservation of angular momentum","q":"A disc of mass M and radius R is free to rotate about its vertical axis as shown in the figure. A battery operated motor of negligible mass is fixed to a point on its circumference. Another disc of the same mass M and radius R/2 is fixed to the motor's thin shaft. Initially, both the discs are at rest. The motor is switched on so that the smaller disc rotates at a uniform angular speed ω. If the angular speed at which the large disc rotates is ω/n, then the value of n is ______.","fig":{"w":340,"h":170,"alt":"Large horizontal disc free to turn about its vertical axis, with a small disc of half the radius mounted on a motor at its rim","d":[["p","M80 115 A120 34 0 1 0 320 115 A120 34 0 1 0 80 115 Z","f"],["l",200,60,200,160,"d"],["c",200,115,2,"F"],["l",200,115,320,115,"d"],["t",262,110,"R","m"],["p","M32 80 A48 14 0 1 0 128 80 A48 14 0 1 0 32 80 Z","f"],["l",80,80,80,115,"B"],["c",80,115,3,"F"],["l",80,80,128,80,"d"],["t",104,75,"R/2","ms"],["t",150,134,"M"],["t",38,66,"M"]]},"n":12,"s":"No external torque about the vertical axis, so the total angular momentum stays zero.\nLet the large disc turn with Ω. Its angular momentum is ½MR²Ω.\nThe small disc has its centre at distance R from the axis, so its orbital part is M R² Ω (same sense as Ω).\nIts own spin is ω in the opposite sense (ω taken as measured in the ground frame): ½M(R/2)² ω = MR²ω/8.\nZero total: (½ + 1) MR²Ω = MR²ω/8, so (3/2)Ω = ω/8, Ω = ω/12.\nSo n = 12."},
{"y":"JEE Main 2023 · 10 Apr · Shift 1","tp":"pra","st":"Conservation of angular momentum","q":"If the earth suddenly shrinks to {1;64}th of its original volume with its mass remaining the same, the period of rotation of earth becomes {24;x} h. The value of x will be ______.","n":16,"s":"Volume ∝ R³, so R becomes (1/64)^(1/3) = 1/4 of its value.\nI = (2/5)MR² becomes 1/16 of its value.\nAngular momentum is conserved, so ω becomes 16 times, and the period becomes 24/16 h.\nSo x = 16."},
{"y":"JEE Main 2023 · 11 Apr · Shift 1","tp":"pri","st":"Parallel and perpendicular axes","q":"A solid sphere of mass 500 g and radius 5 cm is rotated about one of its diameter with angular speed of 10 rad s⁻¹. If the moment of inertia of the sphere about its tangent is x × 10⁻² times its angular momentum about the diameter. Then the value of x will be ______.","n":35,"s":"M = 0.5 kg, R = 0.05 m, R² = 25 × 10⁻⁴ m².\nAbout a diameter: I = (2/5)MR² = 5 × 10⁻⁴ kg m². Angular momentum L = Iω = 5 × 10⁻³.\nAbout a tangent (parallel axis theorem): I_t = (2/5)MR² + MR² = (7/5)MR² = 1.75 × 10⁻³ kg m².\nI_t / L = 1.75 × 10⁻³ / 5 × 10⁻³ = 0.35 = 35 × 10⁻².\nSo x = 35."},
{"y":"JEE Main 2023 · 11 Apr · Shift 2","tp":"pra","st":"Conservation of angular momentum","q":"A circular plate is rotating in horizontal plane, about an axis passing through its center and perpendicular to the plate, with an angular velocity ω. A person sits at the center having two dumbbells in his hands. When he stretches out his hands, the moment of inertia of the system becomes triple. If E be the initial kinetic energy of the system, then final kinetic energy will be E/x. The value of x is ______.","n":3,"s":"Angular momentum is conserved: I ω = 3I ω′, so ω′ = ω/3.\nInitial KE: E = ½Iω².\nFinal KE = ½(3I)(ω/3)² = (1/3)(½Iω²) = E/3.\nSo x = 3."},
{"y":"JEE Main 2023 · 29 Jan · Shift 2","tp":"pra","st":"Angular momentum of particles and bodies","q":"A particle of mass 100 g is projected at time t = 0 with a speed 20 m s⁻¹ at an angle 45° to the horizontal as given in the figure. The magnitude of the angular momentum of the particle about the starting point at time t = 2 s is found to be √K kg m²/s. The value of K is ______. (Take g = 10 m s⁻²)","fig":{"w":260,"h":170,"alt":"Projectile launched from the origin O at 45 degrees to the horizontal X axis, with its dashed parabolic path","d":[["l",40,150,40,15,"a"],["l",40,150,235,150,"a"],["t",30,14,"Y","e"],["t",238,154,"X"],["t",30,162,"O","e"],["l",40,150,175,15],["p","M40 150 Q110 20 180 150","d"],["p","M75 150 A35 35 0 0 0 65 125","d"],["t",82,146,"45°","s"]]},"n":800,"s":"About the starting point, only gravity gives torque: τ = m g x, where x = vₓ t is the horizontal distance.\nvₓ = 20 cos45° = 10√2 m/s, so τ = m g vₓ t and L = ∫τ dt = m g vₓ t²/2.\nL = 0.1 × 10 × 10√2 × 4/2 = 20√2 kg m²/s.\n√K = 20√2, so K = 800."},
{"y":"JEE Main 2023 · 30 Jan · Shift 1","tp":"prd","st":"Rotational kinetic energy and work","q":"A thin uniform rod of length 2 m, cross sectional area 'A' and density 'd' is rotated about an axis passing through the centre and perpendicular to its length with angular velocity ω. If value of ω in terms of its rotational kinetic energy E is √{αE;Ad} then value of α is ______.","n":3,"s":"Mass M = A × 2 × d = 2Ad.\nI about the centre = ML²/12 = 2Ad × 4/12 = 2Ad/3.\nE = ½Iω², so ω = √(2E/I) = √(2E × 3/(2Ad)) = √(3E/(Ad)).\nComparing with √(αE/(Ad)): α = 3."},
{"y":"JEE Advanced 2023","tp":"prd","st":"Rotational kinematics","q":"A thin circular coin of mass 5 gm and radius 4/3 cm is initially in a horizontal xy-plane. The coin is tossed vertically up (+z direction) by applying an impulse of √{π;2} × 10⁻² N-s at a distance 2/3 cm from its center. The coin spins about its diameter and moves along the +z direction. By the time the coin reaches back to its initial position, it completes n rotations. The value of n is ______.\n[Given: The acceleration due to gravity g = 10 m s⁻²]","fig":{"w":340,"h":180,"alt":"Horizontal coin of radius 4/3 cm with an upward impulse applied 2/3 cm from its centre, and x, y, z axes with gravity downward","d":[["p","M60 95 A90 30 0 1 0 240 95 A90 30 0 1 0 60 95 Z","f"],["c",150,95,2,"F"],["l",60,95,150,95,"d"],["t",105,86,"4/3 cm","ms"],["l",150,95,105,95,"B"],["t",128,117,"2/3 cm","ms"],["l",105,155,105,100,"a"],["t",105,170,"Impulse","m"],["l",285,115,285,40,"a"],["t",291,40,"z"],["l",285,115,335,115,"a"],["t",330,108,"y"],["l",285,115,262,132,"a"],["t",252,138,"x"],["l",250,30,250,62,"a"],["t",256,30,"g"]]},"n":30,"s":"Linear impulse: m v = J, so v = √(π/2) × 10⁻² / (5 × 10⁻³) = 2√(π/2) = √(2π) m/s.\nTime to return: T = 2v/g = 2√(2π)/10 s.\nAngular impulse about the diameter = J × (2/3 × 10⁻² m) = I ω, with I = ¼mR² = ¼ × 5 × 10⁻³ × (16/9) × 10⁻⁴ = (20/9) × 10⁻⁷ kg m².\nω = (2/3)√(π/2) × 10⁻⁴ / ((20/9) × 10⁻⁷) = 300√(π/2) rad/s.\nAngle turned = ωT = 300√(π/2) × 2√(2π)/10 = 60π rad.\nRotations n = 60π/2π = 30."},
{"y":"JEE Main 2022 · 26 Jul · Shift 1","tp":"prd","st":"Rotational kinetic energy and work","q":"A disc of mass 1 kg and radius R is free to rotate about a horizontal axis passing through its centre and perpendicular to the plane of disc. A body of same mass as that of disc is fixed at the highest point of the disc. Now the system is released, when the body comes to the lowest position, its angular speed will be 4√{x;3R} rad s⁻¹, where x = ______ (g = 10 m s⁻²).","n":5,"s":"I of system about the axis = ½MR² + MR² = (3/2)MR².\nThe body falls through a height 2R, so energy conservation: M g (2R) = ½ I ω² = ½ (3/2) MR² ω² = (3/4) MR² ω².\nω² = 8g/(3R) = 80/(3R), so ω = √(80/(3R)) = 4√(5/(3R)).\nComparing with 4√(x/(3R)): x = 5."},
{"y":"JEE Main 2022 · 28 Jun · Shift 1","tp":"pra","st":"Angular momentum of particles and bodies","q":"The position vector of 1 kg object is r⃗ = (3î − ĵ) m and its velocity v⃗ = (3ĵ + k̂) m s⁻¹. The magnitude of its angular momentum is √x N m where x is ______.","n":91,"s":"L⃗ = m (r⃗ × v⃗) with r⃗ = (3, −1, 0), v⃗ = (0, 3, 1).\nr⃗ × v⃗ = ((−1)(1) − 0·3, 0·0 − 3·1, 3·3 − (−1)·0) = (−1, −3, 9).\n|L⃗| = √(1 + 9 + 81) = √91 N m.\nSo x = 91."},
{"y":"JEE Advanced 2022","tp":"pra","st":"Angular momentum of particles and bodies","q":"A particle of mass 1 kg is subjected to a force which depends on the position as F⃗ = −k(xî + yĵ) kg m s⁻² with k = 1 kg s⁻². At time t = 0, the particle's position r⃗ = ({1;√2}î + √2ĵ) m and its velocity v⃗ = (−√2î + √2ĵ + {2;π}k̂) m s⁻¹. Let vₓ and v_y denote the x and the y components of the particle's velocity, respectively. Ignore gravity. When z = 0.5 m, the value of (xv_y − yvₓ) is ______ m² s⁻¹.","n":3,"s":"The force F⃗ = −k(xî + yĵ) is central in the xy-plane (it points to the z-axis), so its torque about the z-axis is zero.\nHence L_z/m = x v_y − y vₓ stays constant (the z-motion does not matter, so the value is the same when z = 0.5 m).\nAt t = 0: x = 1/√2, y = √2, vₓ = −√2, v_y = √2.\nx v_y − y vₓ = (1/√2)(√2) − (√2)(−√2) = 1 + 2 = 3 m² s⁻¹."},
{"y":"JEE Main 2021 · 1 Sep · Shift 2","tp":"prd","st":"Pulleys and hinged rods","q":"A 2 kg steel rod of length 0.6 m is clamped on a table vertically at its lower end and is free to rotate in vertical plane. The upper end is pushed so that the rod falls under gravity. Ignoring the friction due to clamping at its lower end, the speed of the free end of rod when it passes through its lowest position is ______ m s⁻¹. (Take g = 10 m/s²)","n":6,"s":"Starting (almost) at rest from the vertical-up position, the centre of mass falls by L.\nEnergy: mgL = ½Iω² with I = mL²/3, so mgL = (1/6) mL²ω² and ω² = 6g/L.\nSpeed of free end v = ωL = √(6gL) = √(6 × 10 × 0.6) = √36 = 6 m/s."},
{"y":"JEE Main 2021 · 20 Jul · Shift 1","tp":"pra","st":"Collisions with rotating bodies","q":"A rod of mass M and length L is lying on a horizontal frictionless surface. A particle of mass 'm' travelling along the surface hits at one end of the rod with a velocity 'u' in a direction perpendicular to the rod. The collision is completely elastic. After collision, particle comes to rest. The ratio of masses ({m;M}) is {1;x}. The value of 'x' will be ______.","n":4,"s":"Linear momentum: mu = MV, so V = mu/M.\nAngular momentum about the centre: mu(L/2) = (ML²/12) ω, so ω = 6mu/(ML).\nElastic: ½mu² = ½MV² + ½(ML²/12)ω² = m²u²/(2M) + (3/2) m²u²/M = 2m²u²/M.\nSo ½ mu² = 2m²u²/M, which gives m/M = 1/4.\nSo x = 4."},
{"y":"JEE Main 2021 · 25 Jul · Shift 1","tp":"pra","st":"Angular momentum of particles and bodies","q":"A particle of mass 'm' is moving in time 't' on a trajectory given by r⃗ = 10αt² î + 5β(t − 5) ĵ where α and β are dimensional constants. The angular momentum of the particle becomes the same as it was for t = 0 at time t = ______ seconds.","n":10,"s":"x = 10αt², y = 5β(t − 5), so vₓ = 20αt, v_y = 5β.\nL = m(x v_y − y vₓ) = m[10αt² · 5β − 5β(t − 5) · 20αt] = 50mαβ[t² − 2t² + 10t] = 50mαβ(10t − t²).\nAt t = 0, L = 0.\nSet 10t − t² = 0, so t = 10 s (t = 0 is the starting value)."},
{"y":"JEE Main 2021 · 27 Jul · Shift 2","tp":"prd","st":"Rotational kinetic energy and work","q":"In the given figure, two wheels P and Q are connected by a belt B. The radius of P is three times as that of Q. In case of same rotational kinetic energy, the ratio of rotational inertias ({I₁;I₂}) will be x : 1. The value of x will be ______.","fig":{"w":340,"h":170,"alt":"Two wheels P (radius 3R) and Q (radius R) connected by a belt B","d":[["p","M101.4 27.2 L263.8 62.4 A18 18 0 0 1 263.8 97.6 L101.4 132.8 A54 54 0 1 1 101.4 27.2 Z"],["c",90,80,54],["c",260,80,18],["c",90,80,2,"F"],["c",260,80,2,"F"],["l",90,80,144,80,"d"],["t",117,74,"3R","ms"],["l",260,80,278,80,"d"],["t",269,74,"R","ms"],["t",70,22,"P","m"],["t",296,50,"Q"],["t",180,152,"B","m"]]},"n":9,"s":"The belt does not slip, so the rim speeds are equal: ω_P × 3R = ω_Q × R, so ω_Q = 3ω_P.\nSame rotational KE: ½I₁ω_P² = ½I₂ω_Q², so I₁/I₂ = (ω_Q/ω_P)² = 9.\nSo the ratio is 9 : 1 and x = 9."},
{"y":"JEE Advanced 2021","tp":"pra","st":"Angular momentum of particles and bodies","q":"A thin rod of mass M and length a is free to rotate in horizontal plane about a fixed vertical axis passing through point O. A thin circular disc of mass M and of radius a/4 is pivoted on this rod with its center at a distance a/4 from the free end so that it can rotate freely about its vertical axis, as shown in the figure. Assume that both the rod and the disc have uniform density and they remain horizontal during the motion. An outside stationary observer finds the rod rotating with an angular velocity Ω and the disc rotating about its vertical axis with angular velocity 4Ω. The total angular momentum of the system about the point O is ({Ma²Ω;48})n. The value of n is ______.","fig":{"w":340,"h":150,"alt":"Top view of a rod pivoted at its left end O carrying a small disc near its free end; rod length a and disc radius a/4","d":[["r",40,72,260,16,"f"],["c",40,80,3,"F"],["t",40,62,"O","m"],["p","M170 80 A65 20 0 1 0 300 80 A65 20 0 1 0 170 80 Z"],["c",235,80,2,"F"],["l",40,125,300,125,"b"],["t",170,142,"a","m"],["l",235,106,300,106,"b"],["t",267,102,"a/4","ms"],["t",40,42,"Ω","m"],["t",235,42,"4Ω","m"],["t",110,66,"M","m"],["t",205,76,"M","m"]]},"n":49,"s":"Take all angular momenta about the vertical axis through O.\nRod: (1/3)Ma²Ω = 16 Ma²Ω/48.\nDisc centre is at 3a/4 from O and moves with the rod: orbital part = M(3a/4)²Ω = 27 Ma²Ω/48.\nDisc spin about its own axis: ½M(a/4)²(4Ω) = Ma²Ω/8 = 6 Ma²Ω/48.\nTotal = (16 + 27 + 6) Ma²Ω/48 = 49 Ma²Ω/48.\nSo n = 49."},
{"y":"JEE Advanced 2021","tp":"pra","st":"Angular momentum of particles and bodies","q":"A pendulum consists of a bob of mass m = 0.1 kg and a massless inextensible string of length L = 1.0 m. It is suspended from a fixed point at height H = 0.9 m above a frictionless horizontal floor. Initially, the bob of the pendulum is lying on the floor at rest vertically below the point of suspension. A horizontal impulse P = 0.2 kg m s⁻¹ is imparted to the bob at some instant. After the bob slides for some distance, the string becomes taut and the bob lifts off the floor. The magnitude of the angular momentum of the pendulum about the point of suspension just before the bob lifts off is J kg m² s⁻¹. The kinetic energy of the pendulum just after the lift-off is K Joules.\nThe value of J is ______.","fig":{"w":340,"h":230,"alt":"Pendulum bob resting on a frictionless floor 0.9 m below the point of suspension, with a horizontal impulse P applied to the bob","d":[["l",120,25,220,25,"B"],["c",170,25,3,"F"],["t",178,20,"O"],["l",170,25,170,191],["t",178,110,"L = 1.0 m"],["c",170,198,7,"F"],["l",30,205,310,205,"B"],["l",60,25,60,205,"b"],["t",54,118,"H = 0.9 m","e"],["l",100,198,150,198,"a"],["t",100,188,"P = 0.2 kg m/s","s"]]},"n":0.18,"s":"The impulse is horizontal and the bob is on the floor, 0.9 m (= H) below the point of suspension.\nAngular momentum about the suspension point = P × H = 0.2 × 0.9 = 0.18 kg m² s⁻¹.\nWhile the bob slides on the frictionless floor no horizontal force acts on it, and when the string becomes taut the tension passes through the pivot, so this angular momentum is unchanged up to lift-off.\nSo J = 0.18."},
{"y":"JEE Advanced 2021","tp":"pra","st":"Angular momentum of particles and bodies","q":"A pendulum consists of a bob of mass m = 0.1 kg and a massless inextensible string of length L = 1.0 m. It is suspended from a fixed point at height H = 0.9 m above a frictionless horizontal floor. Initially, the bob of the pendulum is lying on the floor at rest vertically below the point of suspension. A horizontal impulse P = 0.2 kg m s⁻¹ is imparted to the bob at some instant. After the bob slides for some distance, the string becomes taut and the bob lifts off the floor. The magnitude of the angular momentum of the pendulum about the point of suspension just before the bob lifts off is J kg m² s⁻¹. The kinetic energy of the pendulum just after the lift-off is K Joules.\nThe value of K is ______.","fig":{"w":340,"h":230,"alt":"Pendulum bob resting on a frictionless floor 0.9 m below the point of suspension, with a horizontal impulse P applied to the bob","d":[["l",120,25,220,25,"B"],["c",170,25,3,"F"],["t",178,20,"O"],["l",170,25,170,191],["t",178,110,"L = 1.0 m"],["c",170,198,7,"F"],["l",30,205,310,205,"B"],["l",60,25,60,205,"b"],["t",54,118,"H = 0.9 m","e"],["l",100,198,150,198,"a"],["t",100,188,"P = 0.2 kg m/s","s"]]},"n":0.16,"s":"Angular momentum about the suspension point is conserved through the jerk of the string and the lift-off: J = 0.18 kg m² s⁻¹.\nJust after lift-off the bob moves on a circle of radius L = 1.0 m, so J = m v L and v = 0.18/(0.1 × 1.0) = 1.8 m/s.\nK = ½ m v² = ½ × 0.1 × 1.8² = 0.162 J ≈ 0.16 J.\nSo K = 0.16."},
{"y":"JEE Main 2020 · 3 Sep · Shift 1","tp":"pra","st":"Conservation of angular momentum","q":"A person of 80 kg mass is standing on the rim of a circular platform of mass 200 kg rotating about its axis at 5 revolutions per minute (rpm). The person now starts moving towards the center of the platform. What will be the rotational speed (in rpm) of the platform when the person reaches its centre ______ ?","n":9,"s":"Angular momentum of platform + person is conserved.\nInitially: I₁ = ½(200)R² + 80R² = 180R².\nFinally (person at the centre): I₂ = ½(200)R² = 100R².\n180R² × 5 = 100R² × ω₂, so ω₂ = 9 rpm."},
{"y":"JEE Main 2020 · 5 Sep · Shift 2","tp":"pra","st":"Collisions with rotating bodies","q":"A thin rod of mass 0.9 kg and length 1 m is suspended, at rest, from one end so that it can freely oscillate in the vertical plane. A particle of mass 0.1 kg moving in a straight line with velocity 80 m/s hits the rod at its bottom most point and sticks to it (see figure). The angular speed (in rad/s) of the rod immediately after the collision will be ______.","fig":{"w":240,"h":200,"alt":"A rod 1 m long hanging from a pivot at its top end, struck at its bottom end by a particle of mass 0.1 kg moving at 80 m/s","d":[["l",90,18,150,18,"B"],["c",120,22,3,"F"],["r",114,25,12,150,"f"],["l",150,25,150,175,"b"],["t",156,104,"1 m"],["c",30,175,5,"F"],["l",38,175,110,175,"a"],["t",20,160,"0.1 kg, 80 m/s","s"]]},"n":20,"s":"Take angular momentum about the pivot (the pivot force has no torque about it).\nBefore: m v L = 0.1 × 80 × 1 = 8 kg m²/s.\nAfter: I = (1/3)(0.9)(1)² + 0.1 × 1² = 0.3 + 0.1 = 0.4 kg m².\nω = 8/0.4 = 20 rad/s."},
{"y":"JEE Advanced 2014","tp":"pra","st":"Conservation of angular momentum","q":"A horizontal circular platform of radius 0.5 m and mass 0.45 kg is free to rotate about its axis. Two massless spring toy-guns, each carrying a steel ball of mass 0.05 kg are attached to the platform at a distance 0.25 m from the centre on its either sides along its diameter (see figure). Each gun simultaneously fires the balls horizontally and perpendicular to the diameter in opposite directions. After leaving the platform, the balls have horizontal speed of 9 m s⁻¹ with respect to the ground. The rotational speed of the platform in rad s⁻¹ after the balls leave the platform is ______.","fig":{"w":340,"h":190,"alt":"Top view of a circular platform of radius 0.5 m with two toy-guns at 0.25 m on either side of the centre firing balls in opposite directions perpendicular to the diameter","d":[["c",170,95,85],["l",85,95,255,95,"d"],["c",170,95,2,"F"],["c",127,95,5,"F"],["c",213,95,5,"F"],["l",127,90,127,40,"a"],["l",213,100,213,150,"a"],["t",120,34,"9 m/s","ms"],["t",220,164,"9 m/s","ms"],["t",191,86,"0.25 m","s"],["t",250,86,"R = 0.5 m","es"]]},"n":4,"s":"The platform starts at rest, so the total angular momentum about the axis is zero.\nBalls: each has angular momentum m v r = 0.05 × 9 × 0.25 = 0.1125, and both are in the same sense, so total = 0.225 kg m²/s.\nThe platform must get an equal and opposite angular momentum: I ω = 0.225 with I = ½MR² = ½ × 0.45 × 0.5² = 0.05625 kg m².\nω = 0.225/0.05625 = 4 rad/s."},
{"y":"JEE Advanced 2013","tp":"pra","st":"Conservation of angular momentum","q":"A uniform circular disc of mass 50 kg and radius 0.4 m is rotating with an angular velocity of 10 rad s⁻¹ about its own axis, which is vertical. Two uniform circular rings, each of mass 6.25 kg and radius 0.2 m, are gently placed symmetrically on the disc in such a manner that they are touching each other along the axis of the disc and are horizontal. Assume that the friction is large enough such that the rings are at rest relative to the disc and the system rotates about the original axis. The new angular velocity (in rad s⁻¹) of the system is ______.","n":8,"s":"Disc: I_d = ½MR² = ½ × 50 × 0.16 = 4 kg m².\nEach ring touches the axis, so its centre is 0.2 m from the axis. About the disc axis: I_r = mr² + md² = 6.25 × 0.04 + 6.25 × 0.04 = 0.5 kg m².\nTotal I = 4 + 2 × 0.5 = 5 kg m².\nAngular momentum is conserved: 4 × 10 = 5 ω, so ω = 8 rad/s."},
{"y":"JEE Advanced 2018","tp":"pra","st":"Statements, matching and subjective","q":"In the List-I below, four different paths of a particle are given as functions of time. In these functions, α and β are positive constants of appropriate dimensions and α ≠ β. In each case, the force acting on the particle is either zero or conservative. In List-II, five physical quantities of the particle are mentioned: p⃗ is the linear momentum, L⃗ is the angular momentum about the origin, K is the kinetic energy, U is the potential energy and E is the total energy. Match each path in List-I with those quantities in List-II, which are conserved for that path.\nList-I\nP. r⃗(t) = αt î + βt ĵ\nQ. r⃗(t) = α cos ωt î + β sin ωt ĵ\nR. r⃗(t) = α(cos ωt î + sin ωt ĵ)\nS. r⃗(t) = αt î + {β;2}t² ĵ\nList-II\n1. p⃗\n2. L⃗\n3. K\n4. U\n5. E","o":["P → 1, 2, 3, 4, 5; Q → 2, 5; R → 2, 3, 4, 5; S → 5","P → 1, 2, 3, 4, 5; Q → 3, 5; R → 2, 3, 4, 5; S → 2, 5","P → 2, 3, 4; Q → 5; R → 1, 2, 4; S → 2, 5","P → 1, 2, 3, 5; Q → 2, 5; R → 2, 3, 4, 5; S → 2, 5"],"c":0,"s":"P: straight line at constant velocity, so no force: p, L, K, U and E are all conserved (1, 2, 3, 4, 5).\nQ: ellipse. The force is central (−mω²r), so L and E are conserved. Since α ≠ β the speed changes, so p, K and U change (2, 5).\nR: circle. Speed and radius are constant, so L, K, U and E are conserved but p changes (2, 3, 4, 5).\nS: constant acceleration β in the y-direction. Only E is conserved; p, K, U and L change (5).\nSo P→1,2,3,4,5; Q→2,5; R→2,3,4,5; S→5, which is option (a)."},
{"y":"IIT-JEE 2007","tp":"pra","st":"Statements, matching and subjective","q":"Two discs A and B are mounted coaxially on a vertical axle. The discs have moments of inertia I and 2I respectively about the common axis. Disc A is imparted an initial angular velocity 2ω using the entire potential energy of a spring compressed by a distance x₁. Disc B is imparted an angular velocity ω by a spring having the same spring constant and compressed by a distance x₂. Both the discs rotate in the clockwise direction.\nThe ratio x₁/x₂ is","o":["2","1/2","√2","1/√2"],"c":2,"s":"Spring energy becomes rotational KE.\nDisc A: ½k x₁² = ½ I (2ω)² = 2Iω².\nDisc B: ½k x₂² = ½ (2I) ω² = Iω².\nDividing: x₁²/x₂² = 2, so x₁/x₂ = √2."},
{"y":"IIT-JEE 2007","tp":"pra","st":"Statements, matching and subjective","q":"Two discs A and B are mounted coaxially on a vertical axle. The discs have moments of inertia I and 2I respectively about the common axis. Disc A is imparted an initial angular velocity 2ω using the entire potential energy of a spring compressed by a distance x₁. Disc B is imparted an angular velocity ω by a spring having the same spring constant and compressed by a distance x₂. Both the discs rotate in the clockwise direction.\nWhen disc B is brought in contact with disc A, they acquire a common angular velocity in time t. The average frictional torque on one disc by the other during this period is","o":["{2Iω;3t}","{9Iω;2t}","{9Iω;4t}","{3Iω;2t}"],"c":0,"s":"Angular momentum is conserved: I(2ω) + 2I(ω) = 3I ω′, so ω′ = 4ω/3.\nFor disc A: change in angular momentum = I(2ω − 4ω/3) = 2Iω/3.\nAverage torque = change in angular momentum / time = 2Iω/(3t)."},
{"y":"IIT-JEE 2007","tp":"pra","st":"Statements, matching and subjective","q":"Two discs A and B are mounted coaxially on a vertical axle. The discs have moments of inertia I and 2I respectively about the common axis. Disc A is imparted an initial angular velocity 2ω using the entire potential energy of a spring compressed by a distance x₁. Disc B is imparted an angular velocity ω by a spring having the same spring constant and compressed by a distance x₂. Both the discs rotate in the clockwise direction.\nThe loss of kinetic energy during the above process is","o":["{Iω²;2}","{Iω²;3}","{Iω²;4}","{Iω²;6}"],"c":1,"s":"Initial KE = ½I(2ω)² + ½(2I)ω² = 2Iω² + Iω² = 3Iω².\nFinal KE = ½(3I)(4ω/3)² = 8Iω²/3.\nLoss = 3Iω² − 8Iω²/3 = Iω²/3."},
{"y":"IIT-JEE 2005","tp":"pra","st":"Collisions with rotating bodies","q":"A wooden log of mass M and length L is hinged by a frictionless nail at O. A bullet of mass m strikes with velocity v and sticks to it. Find the angular velocity of the system, immediately after the collision, about O.","fig":{"w":240,"h":200,"alt":"A vertical log of length L hinged at its top end O, struck at its lower end by a bullet of mass m moving horizontally with velocity v","d":[["l",85,28,145,28,"B"],["c",115,30,3,"F"],["t",122,22,"O"],["r",100,33,30,140,"f"],["t",92,106,"M","e"],["l",150,33,150,173,"b"],["t",158,108,"L"],["c",35,165,5,"F"],["l",44,165,98,165,"a"],["t",24,150,"m, v","s"]]},"a":"ω = 3mv/(L(M + 3m))","s":"The bullet hits the free (lower) end, at distance L from the hinge. The hinge force has no torque about O, so angular momentum about O is conserved.\nBefore: m v L.\nAfter: (ML²/3 + mL²) ω.\nω = m v L / (L²(M/3 + m)) = 3mv / (L(M + 3m))."},
{"y":"IIT-JEE 2003","tp":"pra","st":"Statements, matching and subjective","q":"A particle of mass m, moving in a circular path of radius R with a constant speed v₂ is located at point (2R, 0) at time t = 0 and a man starts moving with a velocity v₁ along the y-axis from origin at time t = 0. Calculate the linear momentum of the particle with respect to the man as a function of time.","fig":{"w":340,"h":200,"alt":"Circle of radius R through the origin with centre on the x axis; the particle at (2R, 0) moves with speed v2 upward and the man at the origin moves with v1 upward","d":[["l",30,100,325,100,"a"],["l",60,185,60,10,"a"],["t",328,104,"x"],["t",66,14,"y"],["c",130,100,70],["c",130,100,2,"F"],["l",130,100,180,50,"d"],["t",160,68,"R","s"],["c",200,100,5,"F"],["t",212,116,"m"],["t",200,134,"(2R, 0)","ms"],["l",200,92,200,48,"a"],["t",208,56,"v₂"],["l",60,92,60,48,"a"],["t",68,56,"v₁"],["t",22,116,"(0, 0)","s"]]},"a":"p⃗ = −m v₂ sin(ωt) î + m (v₂ cos(ωt) − v₁) ĵ, where ω = v₂/R","s":"The particle moves anticlockwise on a circle of centre (R, 0) with angular speed ω = v₂/R. Its velocity at time t is v⃗_p = −v₂ sin(ωt) î + v₂ cos(ωt) ĵ (at t = 0 it is v₂ ĵ).\nThe man moves with v⃗_m = v₁ ĵ.\nVelocity of the particle relative to the man: v⃗_p − v⃗_m = −v₂ sin(ωt) î + (v₂ cos(ωt) − v₁) ĵ.\nMomentum relative to the man = m × (relative velocity)."},
{"y":"IIT-JEE 2000","tp":"pra","st":"Collisions with rotating bodies","q":"A rod AB of mass M and length L is lying on a horizontal frictionless surface. A particle of mass m travelling along the surface hits the end A of the rod with a velocity v₀ in a direction perpendicular to AB. The collision is elastic. After the collision the particle comes to rest.\n(a) Find the ratio m/M.\n(b) A point P on the rod is at rest immediately after the collision. Find the distance AP.\n(c) Find the linear speed of the point P after a time {πL;3v₀} after the collision.","a":"(a) m/M = 1/4   (b) AP = 2L/3   (c) v = v₀/(2√2) = √2 v₀/4","s":"(a) Momentum: m v₀ = M V. Angular momentum about the centre: m v₀ (L/2) = (ML²/12) ω, so ω = 6mv₀/(ML). Elastic: ½mv₀² = ½MV² + ½(ML²/12)ω² = 2m²v₀²/M, so m/M = 1/4. Then V = v₀/4 and ω = 3v₀/(2L).\n(b) The end A moves forward, the far end moves backward. A point at distance y from the centre (on the far side) has speed V − ωy = 0 at y = V/ω = L/6. So AP = L/2 + L/6 = 2L/3.\n(c) V and ω stay constant. In time t = πL/(3v₀) the rod turns through ωt = (3v₀/2L)(πL/3v₀) = π/2. Now the velocity of P is V = v₀/4 along the original direction plus ωL/6 = v₀/4 at right angles to it.\nSpeed = √2 × v₀/4 = v₀/(2√2)."},
{"y":"IIT-JEE 1994","tp":"pra","st":"Collisions with rotating bodies","q":"Two uniform thin rods A and B of length 0.6 m each and of masses 0.01 kg and 0.02 kg respectively are rigidly joined end to end. The combination is pivoted at the lighter end, P as shown in fig. such that it can freely rotate about point P in a vertical plane. A small object of mass 0.05 kg, moving horizontally, hits the lower end of the combination and sticks to it. What should be the velocity of the object so that the system could just be raised to the horizontal position?","fig":{"w":240,"h":250,"alt":"Two rods A (upper, lighter) and B (lower, heavier), each 0.6 m long, joined end to end and pivoted at the top end P, with a small object about to hit the lower end horizontally","d":[["l",70,14,130,14,"B"],["c",100,18,3,"F"],["t",112,12,"P"],["r",94,21,12,95,"f"],["r",88,116,24,95,"f"],["t",70,72,"A","e"],["t",70,168,"B","e"],["l",160,21,160,116,"b"],["t",166,72,"0.6 m","s"],["l",160,116,160,211,"b"],["t",166,168,"0.6 m","s"],["c",25,208,6,"F"],["l",34,208,84,208,"a"],["t",14,192,"0.05 kg","s"]]},"a":"v ≈ 6.3 m/s","s":"I about P: rod A = (1/3)(0.01)(0.6)² = 0.0012; rod B = 0.02[(0.6)²/12 + 0.9²] = 0.0168; object = 0.05 × 1.2² = 0.072. Total I = 0.09 kg m².\nCollision (angular momentum about P): 0.05 × v × 1.2 = 0.09 ω, so ω = 2v/3.\nTo reach the horizontal the centre of mass of each part rises by its distance from P: PE gain = g(0.01 × 0.3 + 0.02 × 0.9 + 0.05 × 1.2) = 0.081g = 0.794 J (g = 9.8).\n½Iω² = 0.045 ω² = 0.794, so ω = 4.2 rad/s.\nv = 1.5 ω = 6.3 m/s."},
{"y":"IIT-JEE 1992","tp":"pra","st":"Statements, matching and subjective","q":"A homogeneous rod AB of length L = 1.8 m and mass M is pivoted at the centre O in such a way that it can rotate freely in the vertical plane (fig). The rod is initially in the horizontal position. An insect S of the same mass M falls vertically with speed v on the point C, midway between the points O and B. Immediately after falling, the insect moves towards the end B such that the rod rotates with a constant angular velocity ω.\n(a) Determine the angular velocity ω in terms of v and L.\n(b) If the insect reaches the end B when the rod has turned through an angle of 90°, determine v.","fig":{"w":340,"h":160,"alt":"Horizontal rod AB of length L pivoted at its centre O; point C is midway between O and B; an insect S above C falls vertically with speed v","d":[["r",40,85,240,14,"f"],["c",160,92,3,"F"],["c",220,30,6],["t",220,20,"S","m"],["l",220,40,220,82,"a"],["t",228,62,"v"],["t",40,118,"A","m"],["t",160,118,"O","m"],["t",220,118,"C","m"],["t",280,118,"B","m"],["l",40,132,160,132,"b"],["t",100,148,"L/2","ms"],["l",160,132,220,132,"b"],["t",190,148,"L/4","ms"],["l",220,132,280,132,"b"],["t",250,148,"L/4","ms"]]},"a":"(a) ω = 12v/(7L)   (b) v ≈ 3.5 m/s","s":"(a) Angular momentum about O is conserved during the landing: M v (L/4) = [ML²/12 + M(L/4)²] ω = (7/48) ML² ω.\nSo ω = 12v/(7L).\n(b) While the insect walks out at distance r, the only torque about O is the insect's weight: d/dt[(ML²/12 + Mr²)ω] = M g r cosθ with θ = ωt. For constant ω this gives 2Mrṙω = Mgr cosθ, so ṙ = g cos(ωt)/(2ω).\nIntegrating: r = L/4 + g sin(ωt)/(2ω²). At θ = 90° the insect is at B: L/2 = L/4 + g/(2ω²), so ω² = 2g/L = 2 × 9.8/1.8 = 10.89 and ω = 3.3 rad/s.\nv = 7Lω/12 = 7 × 1.8 × 3.3/12 ≈ 3.5 m/s."},
{"y":"IIT-JEE 1989","tp":"pra","st":"Collisions with rotating bodies","q":"A thin uniform bar lies on a frictionless horizontal surface and is free to move in any way on the surface. Its mass is 0.16 kg and length √3 metre. Two particles, each of mass 0.08 kg, are moving on the same surface and towards the bar in a direction perpendicular to the bar, one with a velocity of 10 m/s and other with 6 m/s as shown in fig. The first particle strikes the bar at point A and the other at point B. Points A and B are at a distance of 0.5 m from the centre of the bar. The particles strike the bar at the same instant of time and stick to the bar on collision. Calculate the loss of the kinetic energy of the system in the above collision process.","fig":{"w":340,"h":200,"alt":"Vertical bar of length root 3 metres; particle at A moving right at 10 m/s and particle at B moving right at 6 m/s, each 0.5 m from the centre of the bar","d":[["r",196,20,8,160,"f"],["c",200,100,2,"F"],["c",40,54,5,"F"],["l",48,54,190,54,"a"],["t",50,46,"10 m/s","s"],["c",40,146,5,"F"],["l",48,146,190,146,"a"],["t",50,138,"6 m/s","s"],["t",214,50,"A"],["t",214,152,"B"],["l",250,54,250,100,"b"],["t",256,80,"0.5 m","s"],["l",250,100,250,146,"b"],["t",256,126,"0.5 m","s"]]},"a":"2.72 J","s":"Momentum along the motion: 0.08(10 + 6) = (0.16 + 0.08 + 0.08)V, so V = 1.28/0.32 = 4 m/s.\nAngular momentum about the centre: 0.08 × 10 × 0.5 − 0.08 × 6 × 0.5 = 0.16.\nI = (0.16)(√3)²/12 + 2 × 0.08 × 0.5² = 0.04 + 0.04 = 0.08 kg m², so ω = 0.16/0.08 = 2 rad/s.\nInitial KE = ½(0.08)(10² + 6²) = 5.44 J.\nFinal KE = ½(0.32)(4²) + ½(0.08)(2²) = 2.56 + 0.16 = 2.72 J.\nLoss = 5.44 − 2.72 = 2.72 J."},
{"y":"IIT-JEE 1984","tp":"pra","st":"Angular momentum of particles and bodies","q":"A particle is projected at time t = 0 from a point P on the ground with a speed v₀, at an angle of 45° to the horizontal. Find the magnitude and direction of the angular momentum of the particle about P at time t = v₀/g.","a":"|L⃗| = m v₀³/(2√2 g), perpendicular to the plane of motion and directed away from the reader (−z)","s":"Take P as origin, x horizontal, y up. At t = v₀/g:\nx = (v₀/√2) t = v₀²/(√2 g); y = (v₀/√2) t − ½gt² = (v₀²/g)(1/√2 − 1/2).\nvₓ = v₀/√2; v_y = v₀/√2 − g t = v₀(1/√2 − 1).\nL_z = m(x v_y − y vₓ) = (m v₀³/g)(1/√2)[(1/√2 − 1) − (1/√2 − 1/2)] = −m v₀³/(2√2 g).\nThe negative sign means L⃗ points along −z. With x to the right and y up, +z is toward the reader, so L⃗ is perpendicular to the plane of motion and directed away from the reader (into the page)."},
{"y":"IIT-JEE 1986","tp":"pra","st":"Statements, matching and subjective","q":"A thin uniform circular disc of mass M and radius R is rotating in a horizontal plane about an axis passing through its centre and perpendicular to its plane with an angular velocity ω. Another disc of the same dimensions but of mass M/4 is placed gently on the first disc coaxially. The angular velocity of the system now is 2ω/√5.","o":["True","False"],"c":1,"s":"Angular momentum is conserved: ½MR² ω = (½MR² + ½(M/4)R²) ω′ = (5/8)MR² ω′.\nSo ω′ = (1/2)/(5/8) ω = 4ω/5, not 2ω/√5.\nThe statement is False."},
{"y":"IIT-JEE 1993","tp":"pra","st":"Conservation of angular momentum","q":"A stone of mass m, tied to the end of a string, is whirled around in a horizontal circle. (Neglect the force due to gravity). The length of the string is reduced gradually keeping the angular momentum of the stone about the centre of the circle constant. Then, the tension in the string is given by T = Arⁿ where A is a constant, r is the instantaneous radius of the circle and n = ______.","a":"n = −3","s":"Angular momentum L = m v r is constant, so v = L/(m r).\nThe tension supplies the centripetal force: T = m v²/r = m L²/(m² r² r) = L²/(m r³).\nSo T ∝ r⁻³ and n = −3."},
{"y":"IIT-JEE 1988","tp":"pra","st":"Conservation of angular momentum","q":"A smooth uniform rod of length L and mass M has two identical beads of negligible size, each of mass m, which can slide freely along the rod. Initially the two beads are at the centre of the rod and the system is rotating with an angular velocity ω₀ about an axis perpendicular to the rod and passing through the midpoint of the rod (see figure). There are no external forces. When the beads reach the ends of the rod, the angular velocity of the system is ______.","fig":{"w":340,"h":130,"alt":"Horizontal rod of length L with two beads at its centre, rotating with angular velocity omega-zero about a vertical axis through the midpoint","d":[["r",40,50,260,22,"f"],["l",170,30,170,90,"d"],["c",165,61,4,"F"],["c",175,61,4,"F"],["p","M140 28 Q170 8 200 28","a"],["t",206,22,"ω₀"],["l",40,100,170,100,"b"],["t",105,118,"L/2","ms"],["l",170,100,300,100,"b"],["t",235,118,"L/2","ms"]]},"a":"ω = Mω₀/(M + 6m)","s":"No external torque, so angular momentum is conserved.\nInitially the beads are on the axis: I₀ = ML²/12.\nWhen the beads are at the ends (L/2 from the axis): I = ML²/12 + 2m(L/2)² = ML²/12 + mL²/2 = (M + 6m)L²/12.\nI₀ω₀ = Iω gives ω = Mω₀/(M + 6m)."},
{"y":"JEE Main 2025 · 3 Apr · Shift 1","tp":"prr","st":"Rolling bodies with forces and plates","q":"A force of 49 N acts tangentially at the highest point of a sphere (solid) of mass 20 kg, kept on a rough horizontal plane. If the sphere rolls without slipping, then the acceleration of the center of the sphere is","fig":{"w":340,"h":130,"alt":"A solid sphere of radius r on a rough horizontal surface with a horizontal force F = 49 N applied at its highest point","d":[["c",170,64,24],["c",170,64,2,"F"],["l",170,64,188,50],["t",188,66,"r","s"],["l",100,40,168,40,"a"],["t",100,32,"F = 49 N"],["l",60,88,280,88,"B"],["l",70,88,62,98],["l",90,88,82,98],["l",110,88,102,98],["l",130,88,122,98],["l",150,88,142,98],["l",170,88,162,98],["l",190,88,182,98],["l",210,88,202,98],["l",230,88,222,98],["l",250,88,242,98],["l",270,88,262,98]]},"o":["3.5 m/s²","2.5 m/s²","0.35 m/s²","0.25 m/s²"],"c":0,"s":"Let friction f act forward at the bottom, and a be the acceleration of the centre.\nTranslation: F + f = m a.\nRotation about the centre: F R − f R = I α = (2/5) m R² (a/R), so F − f = (2/5) m a.\nAdding the two equations: 2F = (7/5) m a, so a = 10F/(7m) = 10 × 49/(7 × 20) = 3.5 m/s²."},
{"y":"JEE Main 2025 · 4 Apr · Shift 2","tp":"prr","st":"Rolling and its energy","q":"A wheel is rolling on a plane surface. The speed of a particle on the highest point of the rim is 8 m/s. The speed of the particle on the rim of the wheel at the same level as the centre of wheel, will be","o":["4√2 m/s","8 m/s","4 m/s","8√2 m/s"],"c":0,"s":"For rolling without slipping the top point moves at 2v, where v is the speed of the centre.\n2v = 8 m/s, so v = 4 m/s and ωR = 4 m/s.\nThe point level with the centre has velocity v forward (centre motion) plus ωR perpendicular to it (rotation).\nSpeed = √(4² + 4²) = 4√2 m/s."},
{"y":"JEE Main 2025 · 23 Jan · Shift 1","tp":"prr","st":"Rolling on an incline","q":"A solid sphere of mass 'm' and radius 'r' is allowed to roll without slipping from the highest point of an inclined plane of length 'L' and makes an angle 30° with the horizontal. The speed of the particle at the bottom of the plane is v₁. If the angle of inclination is increased to 45° while keeping L constant. Then the new speed of the sphere at the bottom of the plane is v₂. The ratio v₁² : v₂² is","o":["1 : √3","1 : 2","1 : 3","1 : √2"],"c":3,"s":"Rolling down a length L: ½mv²(1 + 2/5) = mgL sinθ.\nSo v² = (10/7) g L sinθ, which is proportional to sinθ.\nv₁² : v₂² = sin30° : sin45° = ½ : (1/√2).\nThis is 1 : √2."},
{"y":"JEE Main 2025 · 24 Jan · Shift 1","tp":"prr","st":"Rolling on an incline","q":"A uniform solid cylinder of mass 'm' and radius 'r' rolls along an inclined rough plane of inclination 45°. If it starts to roll from rest from the top of the plane then the linear acceleration of the cylinder's axis will be","o":["{1;√2}g","√2 g","{√2g;3}","{1;3√2}g"],"c":2,"s":"For a solid cylinder rolling down an incline, a = g sinθ / (1 + I/mr²) = g sinθ / (1 + ½) = (2/3) g sinθ.\nWith θ = 45°, sinθ = 1/√2.\na = (2/3) g /√2 = √2 g / 3."},
{"y":"JEE Main 2025 · 24 Jan · Shift 2","tp":"prr","st":"Rolling on an incline","q":"A solid sphere and hollow sphere of the same mass and of same radius are rolled on an inclined plane. Let the time taken to reach the bottom by the solid sphere and the hollow sphere be t₁ and t₂, respectively, then","o":["t₁ > t₂","t₁ = 2t₂","t₁ < t₂","t₁ = t₂"],"c":2,"s":"Acceleration down the incline is a = g sinθ / (1 + k), where k = I/mr².\nSolid sphere: k = 2/5, so a = (5/7) g sinθ.\nHollow sphere: k = 2/3, so a = (3/5) g sinθ.\nThe solid sphere has the larger acceleration, so it takes less time: t₁ < t₂."},
{"y":"JEE Main 2025 · 24 Jan · Shift 2","tp":"prr","st":"Rolling and its energy","q":"A solid sphere is rolling without slipping on a horizontal plane. The ratio of the linear kinetic energy of the centre of mass of the sphere and rotational kinetic energy is","o":["{2;5}","{3;4}","{4;3}","{5;2}"],"c":3,"s":"Translational KE = ½mv².\nRotational KE = ½Iω² = ½ (2/5 mr²)(v/r)² = (1/5)mv².\nRatio = (1/2) / (1/5) = 5/2."},
{"y":"JEE Main 2024 · 1 Feb · Shift 2","tp":"prr","st":"Rolling and its energy","q":"A disc of radius R and mass M is rolling horizontally without slipping with speed v. It then moves up an inclined smooth surface as shown in figure. The maximum height that the disc can go up the incline is","fig":{"w":340,"h":150,"alt":"A disc rolling with speed v on a horizontal surface towards a smooth incline; the maximum height h reached on the incline is marked with a dashed line.","d":[["l",10,110,150,110],["l",150,110,250,25],["c",70,88,22],["c",70,88,2,"F"],["l",96,66,140,66,"a"],["t",118,58,"v","m"],["l",250,25,250,110,"d"],["l",150,110,265,110,"d"],["t",256,72,"h"]]},"o":["{3v²;4g}","{v²;g}","{2v²;3g}","{v²;2g}"],"c":3,"s":"The incline is smooth, so there is no friction torque on the disc. Its spin ω stays constant and the rotational KE cannot be converted to height.\nOnly the translational KE changes: ½Mv² = Mgh.\nSo h = v²/(2g).\n(The printed key gives 3v²/4g, which would hold only if the incline were rough and the disc kept rolling; see notes.)"},
{"y":"JEE Main 2023 · 13 Apr · Shift 1","tp":"prr","st":"Rolling and its energy","q":"A disc is rolling without slipping on a surface. The radius of the disc is R. At t = 0, the top most point on the disc is A as shown in figure. When the disc completes half of its rotation, the displacement of point A from its initial position is","fig":{"w":340,"h":170,"alt":"A disc rolling on a horizontal surface with point A at its topmost point and radius R marked.","d":[["l",20,140,320,140],["c",170,80,60],["c",170,80,2,"F"],["c",170,20,3,"F"],["t",178,16,"A"],["l",170,80,212,38],["t",196,70,"R"],["p","M118 38 Q98 70 112 100","a"]]},"o":["R√(π² + 1)","2R","R√(π² + 4)","2R√(1 + 4π²)"],"c":2,"s":"In half a rotation the centre moves forward a distance πR (rolling without slipping).\nPoint A, initially at the top, ends at the bottom.\nHorizontal displacement of A = πR (same as the centre). Vertical displacement = 2R downward.\nDisplacement = √((πR)² + (2R)²) = R√(π² + 4)."},
{"y":"JEE Main 2022 · 25 Jul · Shift 1","tp":"prr","st":"Rolling on an incline","q":"A solid cylinder and a solid sphere, having same mass M and radius R, roll down the same inclined plane from top without slipping. They start from rest. The ratio of velocity of the solid cylinder and solid sphere, with which they reach the ground, will be","o":["√{5;3}","√{4;5}","√{3;5}","√{14;15}"],"c":3,"s":"v² = 2gh / (1 + k) for a body rolling from height h.\nSolid cylinder: k = ½, so v² = 4gh/3.\nSolid sphere: k = 2/5, so v² = 10gh/7.\nRatio of velocities = √[(4/3)/(10/7)] = √(28/30) = √(14/15)."},
{"y":"JEE Main 2022 · 26 Jun · Shift 2","tp":"prr","st":"Rolling and its energy","q":"A solid spherical ball is rolling on a frictionless horizontal plane surface about its axis of symmetry. The ratio of rotational kinetic energy of the ball to its total kinetic energy is","o":["2/5","2/7","1/5","7/10"],"c":1,"s":"Rotational KE = ½Iω² = (1/5)mv².\nTranslational KE = ½mv².\nTotal KE = (1/2 + 1/5)mv² = (7/10)mv².\nRatio = (1/5)/(7/10) = 2/7."},
{"y":"JEE Main 2022 · 29 Jun · Shift 1","tp":"pra","st":"Angular momentum of particles and bodies","q":"A spherical shell of 1 kg mass and radius R is rolling with angular speed ω on horizontal plane (as shown in figure). The magnitude of angular momentum of the shell about the origin O is {a;3}R²ω. The value of a will be","fig":{"w":340,"h":175,"alt":"A spherical shell of radius R rolling on a horizontal plane with angular speed omega; axes x and y with origin O on the plane to the left of the shell.","d":[["l",30,140,315,140,"a"],["l",30,140,30,15,"a"],["t",318,155,"x"],["t",38,22,"y"],["t",18,158,"O"],["c",170,100,40],["c",170,100,2,"F"],["l",170,100,198,72],["t",180,98,"R"],["p","M148 52 Q170 40 194 54","a"],["t",200,50,"ω"]]},"o":["2","3","5","4"],"c":2,"s":"Angular momentum about O = (orbital part of the centre of mass) + (spin about the centre).\nThe centre is at height R and moves with v = ωR, so orbital part = mvR = mR²ω.\nSpin part = Iω = (2/3)mR²ω for a thin shell.\nBoth act in the same sense, so L = (1 + 2/3)R²ω = (5/3)R²ω (m = 1 kg). Hence a = 5."},
{"y":"JEE Advanced 2022","tp":"pra","st":"Angular momentum of particles and bodies","q":"A flat surface of a thin uniform disk A of radius R is glued to a horizontal table. Another thin uniform disk B of mass M and with the same radius R rolls without slipping on the circumference of A, as shown in the figure. A flat surface of B also lies on the plane of the table. The center of mass of B has fixed angular speed ω about the vertical axis passing through the center of A. The angular momentum of B with respect to the center of A is nMωR². Which of the following is the value of n?","fig":{"w":340,"h":170,"alt":"Disc A glued to the table and a disc B of the same radius touching it externally; B rolls around the circumference of A.","d":[["c",110,95,40],["c",190,95,40],["t",110,99,"A","m"],["t",190,99,"B","m"],["p","M82 42 Q110 22 138 42","a"],["t",144,34,"ω"]]},"o":["2","5","7/2","9/2"],"c":1,"s":"The centre of B moves on a circle of radius 2R about the centre of A with angular speed ω, so its speed is 2Rω.\nOrbital angular momentum = M(2Rω)(2R) = 4MωR².\nB rolls on the fixed disc A, so its own spin ω_s satisfies ω_s R = 2Rω, so ω_s = 2ω, in the same sense as the orbital motion.\nSpin angular momentum = ½MR²(2ω) = MωR².\nTotal = 5MωR², so n = 5."},
{"y":"JEE Main 2021 · 20 Jul · Shift 2","tp":"prr","st":"Rolling and its energy","q":"A body rolls down an inclined plane without slipping. The kinetic energy of rotation is 50% of its translational kinetic energy. The body is","o":["solid sphere","hollow cylinder","ring","solid cylinder"],"c":3,"s":"Rotational KE = ½Iω² = ½(k mR²)(v/R)² = ½ k mv².\nTranslational KE = ½mv².\nGiven rotational = 50% of translational, so k = ½.\nI = ½mR² is the moment of inertia of a solid cylinder (solid sphere has 2/5, hollow cylinder and ring have 1)."},
{"y":"JEE Main 2021 · 22 Jul · Shift 2","tp":"prr","st":"Rolling on an incline","q":"Consider a situation in which a ring, a solid cylinder and a solid sphere roll down on the same inclined plane without slipping. Assume that they start rolling from rest and having identical diameter. The correct statement for this situation is","o":["The ring has the greatest and the cylinder has the least velocity of the centre of mass at the bottom of the inclined plane.","The cylinder has the greatest and the sphere has the least velocity of the centre of mass at the bottom of the inclined plane.","The sphere has the greatest and the ring has the least velocity of the centre of mass at the bottom of the inclined plane.","All of them will have same velocity."],"c":2,"s":"For rolling from height h, v² = 2gh / (1 + k), so a smaller k gives a larger speed.\nSolid sphere: k = 2/5, solid cylinder: k = 1/2, ring: k = 1.\nSo the sphere is fastest at the bottom and the ring is slowest."},
{"y":"JEE Main 2021 · 17 Mar · Shift 2","tp":"prr","st":"Rolling on an incline","q":"A sphere of mass 2 kg and radius 0.5 m is rolling with an initial speed of 1 m s⁻¹ goes up an inclined plane which makes an angle of 30° with the horizontal plane, without slipping. How long will the sphere take to return to the starting point A?","fig":{"w":340,"h":150,"alt":"A sphere at the bottom A of an incline of angle 30 degrees to the horizontal.","d":[["l",50,130,270,130],["l",50,130,250,15],["p","M90 130 A40 40 0 0 0 84.6 110"],["t",94,125,"30°","s"],["c",74,102,12],["t",36,146,"A"]]},"o":["0.60 s","0.52 s","0.57 s","0.80 s"],"c":2,"s":"Deceleration up the incline (rolling, solid sphere): a = g sinθ / (1 + 2/5) = (5/7) g sinθ.\nWith g = 9.8 m/s² and θ = 30°: a = (5/7)(4.9) = 3.5 m/s².\nThe motion up and back down is symmetric, so t = 2v/a = 2(1)/3.5 = 0.57 s."},
{"y":"JEE Main 2020 · 2 Sep · Shift 1","tp":"prd","st":"Torque and angular acceleration","q":"A bead of mass m stays at point P(a, b) on a wire bent in the shape of a parabola y = 4Cx² and rotating with angular speed ω (see figure). The value of ω is (neglect friction)","fig":{"w":340,"h":190,"alt":"A bead at point P(a, b) on a parabola y = 4Cx² that rotates about the vertical y axis with angular speed omega.","d":[["l",30,160,320,160,"a"],["l",170,172,170,20,"a"],["t",312,177,"x"],["t",177,28,"y"],["t",160,176,"O","e"],["p","M70 40 Q170 280 270 40"],["c",240,101,5,"F"],["l",170,101,240,101,"d"],["l",240,101,240,160,"d"],["t",250,96,"P(a, b)"],["p","M150 40 Q170 28 192 40","a"],["t",197,38,"ω"]]},"o":["2√(2gC)","2√(gC)","√{2gC;ab}","√{2g;C}"],"c":0,"s":"The slope of the wire at P is dy/dx = 8Ca, so the normal makes angle φ with the vertical where tanφ = 8Ca.\nVertical balance: N cosφ = mg. Horizontal (centripetal): N sinφ = mω²a.\nDividing: tanφ = ω²a/g, so 8Ca = ω²a/g.\nω² = 8gC, so ω = 2√(2gC)."},
{"y":"JEE Main 2020 · 2 Sep · Shift 2","tp":"pra","st":"Conservation of angular momentum","q":"Two uniform circular discs are rotating independently in the same direction around their common axis passing through their centres. The moment of inertia and angular velocity of the first disc are 0.1 kg m² and 10 rad s⁻¹ respectively while those for the second one are 0.2 kg m² and 5 rad s⁻¹ respectively. At some instant they get stuck together and start rotating as a single system about their common axis with some angular speed. The kinetic energy of the combined system is","o":["{2;3} J","{20;3} J","{10;3} J","{5;3} J"],"c":1,"s":"No external torque, so angular momentum is conserved.\n(0.1)(10) + (0.2)(5) = (0.1 + 0.2)ω, so ω = 2/0.3 = 20/3 rad/s.\nKE = ½(0.3)(20/3)² = ½(0.3)(400/9) = 20/3 J."},
{"y":"JEE Main 2020 · 5 Sep · Shift 1","tp":"pra","st":"Conservation of angular momentum","q":"A wheel is rotating freely with an angular speed ω on a shaft. The moment of inertia of the wheel is I and the moment of inertia of the shaft is negligible. Another wheel of moment of inertia 3I initially at rest is suddenly coupled to the same shaft. The resultant fractional loss in the kinetic energy of the system is","o":["{5;6}","{1;4}","0","{3;4}"],"c":3,"s":"Angular momentum is conserved: Iω = (I + 3I)ω', so ω' = ω/4.\nInitial KE = ½Iω². Final KE = ½(4I)(ω/4)² = ⅛Iω².\nFinal/initial = (1/8)/(1/2) = 1/4.\nFractional loss = 1 − 1/4 = 3/4."},
{"y":"JEE Main 2020 · 8 Jan","tp":"prr","st":"Rolling and its energy","q":"A uniform sphere of mass 500 g rolls without slipping on a plane horizontal surface with its centre moving at a speed of 5.00 cm/s. Its kinetic energy is","o":["6.25 × 10⁻⁴ J","1.13 × 10⁻³ J","8.75 × 10⁻⁴ J","8.75 × 10⁻³ J"],"c":2,"s":"Total KE of a rolling solid sphere = ½mv²(1 + 2/5) = (7/10)mv².\nm = 0.5 kg, v = 0.05 m/s, so mv² = 0.5 × 0.0025 = 1.25 × 10⁻³.\nKE = 0.7 × 1.25 × 10⁻³ = 8.75 × 10⁻⁴ J."},
{"y":"JEE Advanced 2020","tp":"prr","st":"Slipping and friction in rolling","q":"A small roller of diameter 20 cm has an axle of diameter 10 cm. It is on a horizontal floor and a meter scale is positioned horizontally on its axle with one edge of the scale on top of the axle. The scale is now pushed slowly on the axle so that it moves without slipping on the axle, and the roller starts rolling without slipping. After the roller has moved 50 cm, the position of the scale will look like (Figures are schematic and not drawn to scale.)","fig":{"w":340,"h":250,"alt":"Four sketches of the roller after it has moved 50 cm; in each the scale edge is at x = 0 and the axle centre is at x = 50, 75, 25 and 100 cm for (a), (b), (c) and (d).","d":[["t",38,12,"x=0","ms"],["t",73,12,"x=50 cm","ms"],["l",38,17,38,66,"d"],["l",73,17,73,66,"d"],["l",38,66,113,66],["c",73,84,24],["c",73,84,11,"f"],["t",2,104,"(a)","s"],["t",208,12,"x=0","ms"],["t",260.5,12,"x=75 cm","ms"],["l",208,17,208,66,"d"],["l",260.5,17,260.5,66,"d"],["l",208,66,300.5,66],["c",260.5,84,24],["c",260.5,84,11,"f"],["t",172,104,"(b)","s"],["t",38,137,"x=0","ms"],["t",55.5,137,"x=25 cm","ms"],["l",38,142,38,191,"d"],["l",55.5,142,55.5,191,"d"],["l",38,191,95.5,191],["c",55.5,209,24],["c",55.5,209,11,"f"],["t",2,229,"(c)","s"],["t",208,137,"x=0","ms"],["t",278,137,"x=100 cm","ms"],["l",208,142,208,191,"d"],["l",278,142,278,191,"d"],["l",208,191,318,191],["c",278,209,24],["c",278,209,11,"f"],["t",172,229,"(d)","s"]]},"o":["Figure (a)","Figure (b)","Figure (c)","Figure (d)"],"c":1,"s":"The roller (radius 10 cm) rolls 50 cm on the floor, so it turns through θ = 50/10 = 5 rad.\nThe scale rests on top of the axle (radius 5 cm), and the top of the axle moves at ω(R + r) relative to the floor, where R = 10 cm and r = 5 cm (centre speed plus rim speed of the axle).\nNo slipping between scale and axle, so the scale moves (R + r)θ = 15 × 5 = 75 cm.\nThis matches x = 75 cm, figure (b)."},
{"y":"JEE Advanced 2020","tp":"prt","st":"Equilibrium of rigid bodies","q":"A football of radius R is kept on a hole of radius r (r < R) made on a plank kept horizontally. One end of the plank is now lifted so that it gets tilted making an angle θ from the horizontal as shown in the figure below. The maximum value of θ so that the football does not start rolling down the plank satisfies (Figure is schematic and not drawn to scale.)","fig":{"w":340,"h":190,"alt":"A football of radius R resting on a hole of width 2r in a plank that is tilted at angle theta to the horizontal.","d":[["l",40,60,129,91],["l",171,105,300,150],["c",163,61,45],["l",163,61,190,25,"d"],["t",179,40,"R"],["l",123,108,165,122,"b"],["t",134,138,"2r"],["t",30,52,"Plank"],["l",150,150,300,150,"d"],["t",236,146,"θ"]]},"o":["sinθ = r/R","tanθ = r/R","sinθ = r/(2R)","cosθ = r/(2R)"],"c":0,"s":"The ball touches the hole along its rim, a circle of radius r. Its centre is at distance d = √(R² − r²) from the plane of the hole, along the normal to the plank.\nThe ball is on the verge of rolling about the lower edge of the hole when the vertical through its centre passes through that edge.\nHorizontally, the centre is d sinθ from the hole's centre, and the lower edge is r cosθ from it.\nd sinθ = r cosθ gives tanθ = r/√(R² − r²), which means sinθ = r/R."},
{"y":"JEE Main 2019 · 8 Apr · Shift 2","tp":"prr","st":"Rolling on an incline","q":"A solid sphere and solid cylinder of identical radii approach an incline with the same linear velocity (see figure). Both roll without slipping all throughout. The two climb maximum heights h_sph and h_cyl on the incline. The ratio h_sph / h_cyl is given by","fig":{"w":340,"h":130,"alt":"A sphere or cylinder rolling with velocity v on a horizontal floor towards an incline.","d":[["l",20,108,200,108],["p","M200 108 Q270 100 300 30"],["c",60,90,18],["c",60,90,2,"F"],["l",84,90,130,90,"a"],["t",106,82,"v","m"]]},"o":["1","{14;15}","{2;√5}","{4;5}"],"c":1,"s":"Energy conservation while rolling up: ½mv²(1 + k) = mgh, so h = v²(1 + k)/(2g).\nSolid sphere: 1 + k = 7/5. Solid cylinder: 1 + k = 3/2.\nh_sph / h_cyl = (7/5)/(3/2) = 14/15."},
{"y":"JEE Main 2019 · 9 Apr · Shift 1","tp":"prr","st":"Rolling on an incline","q":"The following bodies are made to roll up (without slipping) the same inclined plane from a horizontal plane : (i) a ring of radius R, (ii) a solid cylinder of radius R/2 and (iii) a solid sphere of radius R/4. If, in each case, the speed of the center of mass at the bottom of the incline is same, the ratio of the maximum heights they climb is","o":["14 : 15 : 20","2 : 3 : 4","4 : 3 : 2","10 : 15 : 7"],"c":0,"s":"With the same speed v, h = v²(1 + k)/(2g), and the radius does not matter.\nRing: 1 + k = 2. Solid cylinder: 3/2. Solid sphere: 7/5.\nHeights are in the ratio 2 : 3/2 : 7/5 = 20 : 15 : 14 for (ring : cylinder : sphere).\nThe book's option (a) lists the same three numbers, 14 : 15 : 20, in the order sphere : cylinder : ring; this is the answer given in the key."},
{"y":"JEE Main 2019 · 10 Jan · Shift 1","tp":"prr","st":"Rolling bodies with forces and plates","q":"A homogeneous solid cylindrical roller of radius R and mass M is pulled on a cricket pitch by a horizontal force. Assuming rolling without slipping, angular acceleration of the cylinder is","o":["{F;2MR}","{F;3MR}","{2F;3MR}","{3F;2MR}"],"c":2,"s":"The force F acts horizontally at the centre of the cylinder (as in the standard problem).\nF − f = Ma and f R = ½MR²α, with a = αR.\nFrom the second: f = ½Ma. Then F = Ma + ½Ma = (3/2)Ma, so a = 2F/(3M).\nα = a/R = 2F/(3MR)."},
{"y":"JEE Main 2019 · 11 Jan · Shift 2","tp":"prr","st":"Rolling bodies with forces and plates","q":"A string is wound around a hollow cylinder of mass 5 kg and radius 0.5 m. If the string is now pulled with a horizontal force of 40 N, and the cylinder is rolling without slipping on a horizontal surface (see figure), then the angular acceleration of the cylinder will be (Neglect the mass and thickness of the string)","fig":{"w":340,"h":140,"alt":"A hollow cylinder on a horizontal surface with a string wound round it; the top of the string is pulled horizontally with a force of 40 N.","d":[["c",110,80,30],["l",110,50,230,50,"a"],["t",238,54,"40 N"],["l",30,110,300,110]]},"o":["10 rad/s²","20 rad/s²","12 rad/s²","16 rad/s²"],"c":3,"s":"The string leaves from the top of the cylinder, at distance 2R from the contact point.\nTake torque about the contact point: F(2R) = I_contact α.\nI_contact = MR² + MR² = 2MR² = 2(5)(0.25) = 2.5 kg m².\nα = 40 × 1.0 / 2.5 = 16 rad/s²."},
{"y":"JEE Advanced 2016","tp":"prr","st":"Rolling and its energy","q":"A roller is made by joining together two cones at their vertices O. It is kept on two rails AB and CD which are placed asymmetrically (see figure), with its axis perpendicular to CD and its centre O at the centre of line joining AB and CD (see figure). It is given a light push so that it starts rolling with its centre O moving parallel to CD in the direction shown. As it moves, the roller will tend to","fig":{"w":340,"h":200,"alt":"Top view of a double-cone roller with centre O resting on two rails: rail AB is slanted and rail CD is straight; the roller's motion is parallel to CD, upwards.","d":[["l",98.25,185,140.75,20.5],["l",225.75,20.5,225.75,185],["l",83.8,78.6,83.8,125.49999999999999],["l",259.75,76.5,259.75,127.6],["l",83.8,78.6,174.75,101],["l",83.8,125.49999999999999,174.75,101],["l",259.75,76.5,174.75,101],["l",259.75,127.6,174.75,101],["l",43,101,289.5,101,"d"],["l",174.75,101,174.75,73,"a"],["t",178.75,115,"O"],["t",140.75,16.5,"B","m"],["t",225.75,16.5,"D","m"],["t",98.25,199,"A","m"],["t",225.75,199,"C","m"]]},"o":["turn left","turn right","go straight","turn left and right alternately"],"c":0,"s":"Each cone touches a rail at a distance from O that sets its rolling radius (radius is proportional to distance from the apex O).\nAt the start the two contact radii are equal, so the roller goes straight.\nRail CD is straight, so its contact radius stays the same. Rail AB slants towards CD in the direction of motion, so the contact point on that cone moves closer to O and its rolling radius decreases.\nThe side with the smaller radius covers less distance, so the roller turns towards that side, to the left."},
{"y":"JEE Main 2015 · Online","tp":"prr","st":"Rolling bodies with forces and plates","q":"A uniform solid cylindrical roller of mass m is being pulled on a horizontal surface with force F parallel to the surface and applied at its centre. If the acceleration of the cylinder is a and it is rolling without slipping then the value of F is","o":["ma","2ma","{3;2}ma","{5;3}ma"],"c":2,"s":"Let friction f act backwards. Then F − f = ma.\nTorque about the centre: f R = ½mR²α = ½mR(a/R)R, so f = ½ma.\nF = ma + ½ma = (3/2)ma."},
{"y":"JEE Main 2014 · Online","tp":"prr","st":"Rolling bodies with forces and plates","q":"Consider a cylinder of mass M resting on a rough horizontal rug that is pulled out from under it with acceleration 'a' perpendicular to the axis of the cylinder. What is F_friction at point P? It is assumed that the cylinder does not slip.","fig":{"w":340,"h":170,"alt":"A cylinder resting on a rug that is pulled to the left with acceleration a; P is the point of contact and friction acts there.","d":[["r",60,110,200,18,"f"],["c",160,80,30],["c",160,80,2,"F"],["t",166,76,"O"],["c",160,110,3,"F"],["t",168,108,"P","s"],["p","M130 60 Q160 40 190 58","a"],["t",196,54,"ω"],["l",120,142,60,142,"a"],["t",90,156,"a","m"],["t",150,124,"F friction","s"]]},"o":["Mg","Ma","{Ma;2}","{Ma;3}"],"c":3,"s":"Let the cylinder's own acceleration be a₁ and friction f (in the direction of the rug's motion): Ma₁ = f.\nTorque about the axis: f R = ½MR²α, so α R = 2f/M.\nNo slipping at P: the rug's acceleration equals the acceleration of the contact point of the cylinder, a = a₁ + αR = f/M + 2f/M = 3f/M.\nSo f = Ma/3."},
{"y":"JEE Main 2013 · Online","tp":"prr","st":"Rolling on an incline","q":"A tennis ball (treated as hollow spherical shell) starting from O rolls down a hill. At point A the ball becomes air borne leaving at an angle of 30° with the horizontal. The ball strikes the ground at B. What is the value of the distance AB?\n(Moment of inertia of a spherical shell of mass m and radius R about its diameter = {2;3}mR²)","fig":{"w":340,"h":200,"alt":"A ball starts from O at height 2.0 m above the lowest point of a dip in the track, rolls down and leaves at point A, which is 0.2 m above the lowest point, at 30 degrees above the horizontal; it lands at B on the same level as A.","d":[["c",62,32,11],["t",50,14,"O","e"],["l",36,22,36,170,"b"],["t",30,100,"2.0 m","e"],["p","M72 44 L122 135 Q140 174 162 160 Q176 150 190 152"],["l",40,152,320,152],["l",40,170,150,170,"d"],["l",140,152,140,170,"b"],["t",100,186,"0.2 m"],["c",188,142,9],["p","M196 152 A18 18 0 0 0 203 140","d"],["t",208,136,"30°","s"],["t",186,168,"A"],["t",246,168,"B"]]},"o":["1.87 m","2.08 m","1.57 m","1.77 m"],"c":0,"s":"From the figure, O is 2.0 m above the lowest point of the dip and A is 0.2 m above that point, so the ball falls through h = 2.0 − 0.2 = 1.8 m by the time it reaches A.\nRolling shell: mgh = ½mv²(1 + 2/3) = (5/6)mv², so v² = 6gh/5 = 6(9.8)(1.8)/5 = 21.2 m²/s².\nRange of the projectile at 30° (A and B at the same level): AB = v² sin60°/g = (6h/5)(0.866) = 2.16 × 0.866.\nAB = 1.87 m."},
{"y":"AIEEE 2012 · Online","tp":"prr","st":"Rolling on an incline","q":"A solid sphere is rolling on a surface as shown in figure, with a translational velocity v m s⁻¹. If it is to climb the inclined surface continuing to roll without slipping, then minimum v for this to happen is","fig":{"w":340,"h":190,"alt":"A solid sphere rolling with velocity v along a surface that curves up to a horizontal level at height h.","d":[["p","M30 168 C100 170 120 150 140 110 C160 70 170 45 230 42"],["c",50,152,14],["l",70,140,90,126,"a"],["t",96,132,"v"],["l",230,42,262,42,"d"],["l",30,168,262,168,"d"],["l",250,42,250,168,"b"],["t",256,108,"h"]]},"o":["√(2gh)","√({7;5}gh)","√({7;2}gh)","√({10;7}gh)"],"c":3,"s":"Rolling without slipping needs friction but it does no net work, so mechanical energy is conserved.\nTo just reach the top: ½mv² + ½(2/5 mr²)(v/r)² = mgh.\n(7/10)v² = gh, so v² = (10/7)gh.\nv = √((10/7)gh)."},
{"y":"AIEEE 2007","tp":"prr","st":"Rolling on an incline","q":"A round uniform body of radius R, mass M and moment of inertia I rolls down (without slipping) an inclined plane making an angle θ with the horizontal. Then its acceleration is","o":["{g sinθ;1 − MR²/I}","{g sinθ;1 + I/MR²}","{g sinθ;1 + MR²/I}","{g sinθ;1 − I/MR²}"],"c":1,"s":"Along the incline: Mg sinθ − f = Ma.\nTorque about the centre: f R = Iα = I a/R, so f = Ia/R².\nMg sinθ = Ma + Ia/R² = Ma(1 + I/MR²).\na = g sinθ / (1 + I/MR²)."},
{"y":"IIT-JEE 2007","tp":"prr","st":"Rolling on an incline","q":"A small object of uniform density rolls up a curved surface with an initial velocity 'v'. It reaches up to a maximum height of {3v²;4g} with respect to the initial position. The object is","fig":{"w":340,"h":130,"alt":"A small object rolling with velocity v along a horizontal floor towards a curved surface that rises on the right.","d":[["l",20,112,185,112],["p","M185 112 Q250 105 285 20"],["c",50,100,12],["l",68,100,104,100,"a"],["t",84,92,"v"],["l",285,20,285,112,"d"]]},"o":["ring","solid sphere","hollow sphere","disc"],"c":3,"s":"Energy conservation: ½mv²(1 + k) = mgh with h = 3v²/(4g).\nSo ½(1 + k) = 3/4, which gives k = ½.\nI = ½mR² corresponds to a disc (solid cylinder)."},
{"y":"AIEEE 2005","tp":"prr","st":"Rolling on an incline","q":"A spherical ball of mass 20 kg is stationary at the top of a hill of height 100 m. It rolls down a smooth surface to the ground, then climbs up another hill of height 30 m and finally rolls down to a horizontal base at a height of 20 m above the ground. The velocity attained by the ball is","o":["10 m/s","34 m/s","40 m/s","20 m/s"],"c":1,"s":"The net fall in height is 100 − 20 = 80 m.\nThe key treats the ball as a solid sphere that rolls without slipping, so its energy is shared between translation and rotation.\nmg(80) = ½mv²(1 + 2/5) = (7/10)mv², so v² = (10/7)(10)(80) ≈ 1143 (g = 10 m/s²).\nv ≈ 34 m/s."},
{"y":"IIT-JEE 2004","tp":"prr","st":"Rolling and its energy","q":"A disc is rolling without slipping with angular velocity ω. P and Q are two points equidistant from the centre C. The order of magnitude of velocity is","fig":{"w":340,"h":170,"alt":"A disc rolling on a horizontal surface with its centre C and two points P and Q at equal distances from C: P to the right of C and Q below and to the left of C.","d":[["l",70,145,230,145],["c",150,85,60],["c",150,85,2,"F"],["t",146,76,"C","e"],["c",172,85,3,"F"],["t",178,89,"P"],["c",137,103,3,"F"],["t",126,116,"Q"]]},"o":["vQ > vC > vP","vP > vC > vQ","vP = vC, vQ = vC/2","vP < vC > vQ"],"c":1,"s":"In rolling without slipping the contact point is instantaneously at rest, and every point moves with speed ω × (its distance from the contact point).\nC is at distance R from the contact point. P is farther from the contact point than C, so vP > vC.\nQ is nearer to the contact point than C, so vQ < vC.\nOrder: vP > vC > vQ."},
{"y":"AIEEE 2002","tp":"prr","st":"Rolling on an incline","q":"A solid sphere, a hollow sphere and a ring are released from top of an inclined plane (frictionless) so that they slide down the plane. Then maximum acceleration down the plane is for (no rolling)","o":["solid sphere","hollow sphere","ring","all same"],"c":3,"s":"The plane is frictionless, so there is no torque and the bodies only slide.\nAlong the plane: ma = mg sinθ, so a = g sinθ for every body, independent of mass, shape or radius.\nAll have the same acceleration."},
{"y":"IIT-JEE 2002","tp":"prr","st":"Slipping and friction in rolling","q":"A cylinder rolls up an inclined plane, reaches some height, and then rolls down (without slipping throughout these motions). The directions of the frictional force acting on the cylinder are","o":["up the incline while ascending and down the incline while descending","up the incline while ascending as well as descending","down the incline while ascending and up the incline while descending","down the incline while ascending as well as descending."],"c":1,"s":"Gravity alone would accelerate the centre down the incline and gives no torque about the centre.\nRolling without slipping needs a = αR, which needs a torque, and only friction can supply it.\nFor a solid cylinder a = (2/3)g sinθ, which is less than g sinθ, so friction must pull up the incline to reduce the acceleration.\nThe centre accelerates down the incline both when going up (slowing down) and when coming down (speeding up), so friction acts up the incline in both cases."},
{"y":"JEE Advanced 2023","tp":"prr","st":"Slipping and friction in rolling","q":"An annular disk of mass M, inner radius a and outer radius b is placed on a horizontal surface with coefficient of friction μ, as shown in the figure. At some time, an impulse J₀x̂ is applied at a height h above the center of the disk. If h = hₘ then the disk rolls without slipping along the x-axis. Which of the following statement(s) is (are) correct?","fig":{"w":340,"h":200,"alt":"An annular disk with inner radius a and outer radius b standing on a horizontal surface; an impulse J0 acts in the x direction at height h above the centre. Axes z (up) and x (right).","d":[["l",20,170,320,170],["c",130,110,60],["c",130,110,38],["c",130,110,2,"F"],["l",130,110,157,83],["t",134,96,"a","s"],["l",130,110,172,152],["t",158,140,"b"],["l",15,80,70,80,"a"],["t",22,72,"J₀"],["l",40,80,40,110,"b"],["t",26,98,"h"],["l",40,110,130,110,"d"],["l",270,150,270,100,"a"],["t",277,106,"z"],["l",270,150,320,150,"a"],["t",312,166,"x"]]},"o":["For μ ≠ 0 and a → 0, hₘ = b/2.","For μ ≠ 0 and a → b, hₘ = b.","For h = hₘ, the initial angular velocity does not depend on the inner radius a.","For μ = 0 and h = 0, the wheel always slides without rolling."],"c":[0,1,2,3],"s":"I = ½M(a² + b²). With the impulse at height hₘ the disk rolls from the start, so no friction impulse is needed.\nJ₀ = Mv and J₀hₘ = Iω (about the centre), with v = ωb.\nSo hₘ = I/(Mb) = (a² + b²)/(2b). For a → 0 this is b/2 (a), and for a → b it is b (b).\nω = v/b = J₀/(Mb) has no a in it (c).\nIf μ = 0 and h = 0, the impulse gives translation with no torque and no friction, so the disk only slides (d).\nAll four are correct."},
{"y":"JEE Advanced 2018","tp":"pra","st":"Angular momentum of particles and bodies","q":"The potential energy of a particle of mass m at a distance r from a fixed point O is given by V(r) = kr²/2, where k is a positive constant of appropriate dimensions. This particle is moving in a circular orbit of radius R about the point O. If v is the speed of the particle and L is the magnitude of its angular momentum about O, which of the following statements is (are) true?","o":["v = √{k;2m} R","v = √{k;m} R","L = √(mk) R²","L = √{mk;2} R²"],"c":[1,2],"s":"Force F = −dV/dr = −kr, directed towards O.\nThis supplies the centripetal force: mv²/R = kR, so v = √(k/m) R. Hence (b).\nL = mvR = m√(k/m) R² = √(mk) R². Hence (c).\nOptions (b) and (c) are correct."},
{"y":"IIT-JEE 2012","tp":"prr","st":"Rolling and its energy","q":"The figure shows a system consisting of (i) a ring of outer radius 3R rolling clockwise without slipping on a horizontal surface with angular speed ω and (ii) an inner disc of radius 2R rotating anti-clockwise with angular speed ω/2. The ring and disc are separated by frictionless ball bearings. The system is in the x-z plane. The point P on the inner disc is at a distance R from the origin, where OP makes an angle of 30° with the horizontal. Then with respect to the horizontal surface,","fig":{"w":340,"h":230,"alt":"A ring of outer radius 3R rolling clockwise with angular speed omega on a horizontal surface; inside it a disc of radius 2R rotates anticlockwise with omega/2, separated by ball bearings. P is at distance R from the centre O at 30 degrees to the horizontal. Axes z up and x right.","d":[["l",20,215,330,215],["c",150,125,90],["c",150,125,60],["c",150,125,2,"F"],["c",187,60,6],["c",112,60,6],["c",112,190,6],["c",188,190,6],["c",225,125,6],["l",150,125,61,125,"a"],["t",92,119,"3R","ms"],["l",150,125,108,167,"a"],["t",104,148,"2R","s"],["l",150,125,176,110],["c",176,110,3,"F"],["t",182,108,"P"],["t",156,138,"O","s"],["l",150,125,215,125,"d"],["t",200,121,"30°","s"],["p","M172 82 Q150 74 128 88","a"],["t",128,76,"ω/2","s"],["p","M215 40 Q250 60 262 100","a"],["t",264,96,"ω"],["l",300,170,300,120,"a"],["t",306,126,"z"],["l",300,170,335,170,"a"],["t",328,186,"x"]]},"o":["the point O has a linear velocity 3Rω î","the point P has a linear velocity {11;4}Rω î + {√3;4}Rω k̂","the point P has a linear velocity {13;4}Rω î − {√3;4}Rω k̂","the point P has a linear velocity (3 − {√3;4})Rω î + {1;4}Rω k̂"],"c":[0,1],"s":"The ring rolls without slipping, so its centre O moves with v = ω(3R) = 3Rω î. (a) is correct.\nThe bearings are frictionless, so the inner disc spins at ω/2 anticlockwise about O while O moves at 3Rω î.\nP is at R(cos30° î + sin30° k̂). Anticlockwise rotation gives velocity (ω/2)R(−sin30° î + cos30° k̂) = Rω(−¼ î + (√3/4) k̂).\nv_P = (3 − ¼)Rω î + (√3/4)Rω k̂ = (11/4)Rω î + (√3/4)Rω k̂. (b) is correct, (c) and (d) are not."},
{"y":"IIT-JEE 2012","tp":"prr","st":"Rolling on an incline","q":"Two solid cylinders P and Q of same mass and same radius start rolling down a fixed inclined plane from the same height at the same time. Cylinder P has most of its mass concentrated near its surface, while Q has most of its mass concentrated near the axis. Which statement(s) is(are) correct?","o":["Both cylinders P and Q reach the ground at the same time.","Cylinder P has larger linear acceleration than cylinder Q.","Both cylinders reach the ground with same translational kinetic energy.","Cylinder Q reaches the ground with larger angular speed."],"c":3,"s":"P has most mass at the rim, so its I is larger; Q has most mass near the axis, so its I is smaller.\nAcceleration a = g sinθ/(1 + I/mR²) is larger for Q, so Q reaches the ground first and P does not have the larger acceleration.\nAt the bottom v² = 2gh/(1 + I/mR²), so Q has larger v and larger translational KE. Both have the same total KE, but P puts more of it into rotation.\nω = v/R is therefore larger for Q. Only (d) is correct."},
{"y":"IIT-JEE 2009","tp":"prr","st":"Rolling and its energy","q":"A sphere is rolling without slipping on a fixed horizontal plane surface. In the figure, A is the point of contact, B is the centre of the sphere and C is its topmost point. Then","fig":{"w":340,"h":170,"alt":"A sphere rolling on a horizontal plane with its centre B, topmost point C and point of contact A; velocity arrow to the right.","d":[["l",70,130,230,130],["c",150,85,45],["c",150,85,2,"F"],["t",158,89,"B"],["c",150,40,3,"F"],["t",156,34,"C"],["l",168,32,208,32,"a"],["c",150,130,3,"F"],["t",150,148,"A","m"]]},"o":["V⃗C − V⃗A = 2(V⃗B − V⃗C)","V⃗C − V⃗B = V⃗B − V⃗A","|V⃗C − V⃗A| = 2|V⃗B − V⃗C|","|V⃗C − V⃗A| = 4|V⃗B|"],"c":[1,2],"s":"For rolling without slipping: V⃗A = 0, V⃗B = v (forward), V⃗C = 2v (forward).\n(a) LHS = 2v, RHS = 2(v − 2v) = −2v. Not equal.\n(b) LHS = 2v − v = v, RHS = v − 0 = v. Correct.\n(c) LHS = 2v, RHS = 2|v − 2v| = 2v. Correct.\n(d) LHS = 2v, RHS = 4v. Not equal.\nCorrect options: (b) and (c)."},
{"y":"IIT-JEE 2006","tp":"prr","st":"Slipping and friction in rolling","q":"A solid cylinder is rolling down a rough inclined plane of inclination θ. Then","o":["The friction force is dissipative","The friction force is necessarily changing","The friction force will aid rotation but hinder translation","The friction force is reduced if θ is reduced."],"c":[2,3],"s":"In rolling without slipping the contact point is at rest, so static friction does no net work. It is not dissipative, so (a) is false.\nMg sinθ − f = Ma and f R = ½MR²(a/R) give f = (1/3)Mg sinθ, which is constant for a given θ. So (b) is false.\nFriction acts up the incline: it opposes the translation down the incline and gives the torque that spins the cylinder. (c) is true.\nf = (1/3)Mg sinθ decreases when θ decreases. (d) is true."},
{"y":"JEE Main 2025 · 4 Apr · Shift 1","tp":"prr","st":"Rolling on an incline","q":"A circular ring and a solid sphere having same radius roll down on an inclined plane from rest without slipping. The ratio of their velocities when reached at the bottom of the plane is √{x;5} where x = ______.","n":3.5,"s":"At the bottom, v² = 2gh/(1 + k).\nRing: k = 1, so v² = gh. Solid sphere: k = 2/5, so v² = 10gh/7.\nv_ring / v_sphere = √(7/10) = √(3.5/5).\nHence x = 3.5."},
{"y":"JEE Main 2024 · 4 Apr · Shift 1","tp":"prr","st":"Rolling and its energy","q":"A solid sphere and a hollow cylinder roll up without slipping on same inclined plane with same initial speed v. The sphere and the cylinder reaches upto maximum heights h₁ and h₂ respectively, above the initial level. The ratio h₁ : h₂ is {n;10}. The value of n is ______.","n":7,"s":"Rolling without slipping means no energy is lost, so the initial kinetic energy turns into mgh.\nKE = ½mv²(1 + k²/R²), so h = v²(1 + k²/R²)/(2g).\nSolid sphere: k²/R² = 2/5, so h₁ = 7v²/(10g).\nHollow cylinder: k²/R² = 1, so h₂ = v²/g.\nh₁ : h₂ = 7/10, so n = 7."},
{"y":"JEE Main 2024 · 5 Apr · Shift 2","tp":"prr","st":"Rolling and its energy","q":"A hollow sphere is rolling on a plane surface about its axis of symmetry. The ratio of rotational kinetic energy to its total kinetic energy is {x;5}. The value of x is ______.","n":2,"s":"For a hollow sphere I = (2/3)mR² and v = ωR.\nRotational KE = ½Iω² = (1/3)mv².\nTranslational KE = ½mv².\nTotal KE = (1/3 + 1/2)mv² = (5/6)mv².\nRatio = (1/3)/(5/6) = 2/5, so x = 2."},
{"y":"JEE Main 2024 · 9 Apr · Shift 2","tp":"prr","st":"Rolling on an incline","q":"A circular disc reaches from top to bottom of an inclined plane of length l. When it slips down the plane, it takes t s. When it rolls down the plane then it takes √{α;2} t s, where α is ______.","n":3,"s":"Starting from rest, l = ½at², so t ∝ 1/√a.\nSlipping (smooth plane): a₁ = g sinθ.\nRolling disc: a₂ = g sinθ/(1 + ½) = (2/3)g sinθ.\nt₂/t₁ = √(a₁/a₂) = √(3/2).\nSo √(α/2) = √(3/2), which gives α = 3."},
{"y":"JEE Main 2024 · 27 Jan · Shift 2","tp":"prr","st":"Rolling and its energy","q":"A ring and a solid sphere roll down the same incline plane without slipping. They start from rest. The radii of both bodies are identical and the ratio of their kinetic energies is {7;x}, where x is ______.","n":10,"s":"For a body of mass m rolling at speed v, KE = ½mv²(1 + k²/R²).\nRing: KE = ½mv²(1 + 1) = mv².\nSolid sphere: KE = ½mv²(1 + 2/5) = (7/10)mv².\nRatio (sphere : ring) at the same mass and speed = 7/10.\nSo 7/x = 7/10 and x = 10.\n(Note: the wording of the question does not state the common speed; the book answer 10 follows this reading.)"},
{"y":"JEE Main 2024 · 29 Jan · Shift 1","tp":"prr","st":"Rolling on an incline","q":"A cylinder is rolling down on an inclined plane of inclination 60°. Its acceleration during rolling down will be {x;√3} m/s², where x = ______ (Use g = 10 m/s²).","n":10,"s":"For a solid cylinder rolling without slipping, a = g sinθ/(1 + ½) = (2/3)g sinθ.\na = (2/3)(10)(sin 60°) = (2/3)(10)(√3/2) = 10/√3 m/s².\nSo x = 10."},
{"y":"JEE Main 2024 · 31 Jan · Shift 1","tp":"prr","st":"Rolling and its energy","q":"A solid circular disc of mass 50 kg rolls along a horizontal floor so that its center of mass has a speed of 0.4 m/s. The absolute value of work done on the disc to stop it is ______ J.","n":6,"s":"Work done to stop the disc = its total kinetic energy (work–energy theorem).\nFor a rolling solid disc, KE = ½mv² + ½Iω² = ½mv²(1 + ½) = (3/4)mv².\nKE = (3/4)(50)(0.4)² = (3/4)(50)(0.16) = 6 J."},
{"y":"JEE Main 2023 · 8 Apr · Shift 2","tp":"prr","st":"Rolling and its energy","q":"A hollow spherical ball of uniform density rolls up a curved surface with an initial velocity 3 m/s. Maximum height with respect to the initial position covered by it will be ______ cm.","n":75,"s":"No slipping, so mechanical energy is conserved.\nHollow sphere: I = (2/3)mR², so KE = ½mv²(1 + 2/3) = (5/6)mv².\n(5/6)mv² = mgh gives h = 5v²/(6g).\nh = 5 × 9/(6 × 10) = 0.75 m = 75 cm."},
{"y":"JEE Main 2023 · 12 Apr · Shift 1","tp":"prr","st":"Rolling and its energy","q":"For a rolling spherical shell, the ratio of rotational kinetic energy and total kinetic energy is {x;5}. The value of x is ______.","n":2,"s":"Spherical shell: I = (2/3)mR² and v = ωR.\nRotational KE = ½Iω² = (1/3)mv².\nTotal KE = ½mv² + (1/3)mv² = (5/6)mv².\nRatio = (1/3)/(5/6) = 2/5, so x = 2."},
{"y":"JEE Main 2023 · 13 Apr · Shift 1","tp":"prr","st":"Rolling and its energy","q":"A solid sphere is rolling on a horizontal plane without slipping. If the ratio of angular momentum about axis of rotation of the sphere to the total energy of moving sphere is π : 22 then, the value of angular speed of the sphere will be ______ rad/s.","n":4,"s":"Angular momentum about the axis: L = Iω = (2/5)mR²ω.\nTotal energy: E = ½mv²(1 + 2/5) = (7/10)mR²ω².\nL/E = (2/5)/((7/10)ω) = 4/(7ω).\nGiven L/E = π/22, so 4/(7ω) = π/22, hence ω = 88/(7π).\nTaking π = 22/7: ω = 88/22 = 4 rad/s."},
{"y":"JEE Main 2023 · 1 Feb · Shift 1","tp":"prr","st":"Rolling on an incline","q":"A solid cylinder is released from rest from the top of an inclined plane of inclination 30° and length 60 cm. If the cylinder rolls without slipping, its speed upon reaching the bottom of the inclined plane is ______ m s⁻¹. (Given, g = 10 m s⁻²)","n":2,"s":"Height of the incline: h = 0.6 sin 30° = 0.3 m.\nEnergy conservation for a solid cylinder: mgh = (3/4)mv².\nv² = 4gh/3 = 4 × 10 × 0.3/3 = 4.\nv = 2 m/s."},
{"y":"JEE Main 2023 · 30 Jan · Shift 2","tp":"prr","st":"Slipping and friction in rolling","q":"A uniform disc of mass 0.5 kg and radius r is projected with velocity 18 m/s at t = 0 s on a rough horizontal surface. It starts off with a purely sliding motion at t = 0 s. After 2 s it acquires a purely rolling motion. The total kinetic energy of the disc after 2 s will be ______ J. (Given, coefficient of friction is 0.3 and g = 10 m/s²).","n":54,"s":"Friction decelerates the centre of mass: a = μg = 3 m/s².\nSpeed after 2 s: v = 18 − 3 × 2 = 12 m/s.\n(Check: friction torque gives α = 2μg/r, so ω r = 6 × 2 = 12 m/s, which equals v. So the disc is rolling at t = 2 s.)\nTotal KE of a rolling disc = (3/4)mv² = (3/4)(0.5)(144) = 54 J."},
{"y":"JEE Main 2022 · 27 Jun · Shift 2","tp":"prr","st":"Rolling bodies with forces and plates","q":"A rolling wheel of 12 kg is on an inclined plane at position P and connected to a mass of 3 kg through a string of fixed length and pulley as shown in figure.\nConsider PR as friction free surface. The velocity of centre of mass of the wheel when it reaches at the bottom Q of the inclined plane PQ will be ½√(xgh) m/s. The value of x is ______.","fig":{"w":340,"h":200,"alt":"Triangle QPR with Q and R at the base, both base angles alpha and height h at P. A 12 kg wheel sits at P on side PQ and a 3 kg block sits at R on side PR, joined by a string over a pulley at P.","d":[["l",20,170,320,170],["l",20,170,170,60],["l",170,60,320,170,"B"],["c",166,50,9,"f"],["t",112,40,"12 kg"],["l",172,56,290,141,"d"],["r",286,138,20,13,"F"],["t",250,122,"3 kg"],["l",170,60,170,170,"d"],["t",176,120,"h"],["t",50,164,"α"],["t",286,164,"α"],["t",14,186,"Q"],["t",318,186,"R"],["t",178,72,"P"]]},"n":3,"s":"The wheel rolls down PQ, dropping a height h. The 3 kg block slides up the smooth plane PR, rising the same h (both planes have angle α and the same length).\nBoth move with the same speed v, and the wheel rolls without slipping.\nEnergy: 12gh − 3gh = KE of wheel + ½(3)v².\nSolid disc: 9gh = (3/4)(12)v² + 1.5v² = 10.5v², so v = ½√(24gh/7) = ½√(3.4gh).\n(If the wheel is taken as a ring, v = ½√(8gh/3) = ½√(2.7gh).)\nBoth readings round to x = 3, the book answer."},
{"y":"JEE Advanced 2022","tp":"prr","st":"Rolling and its energy","q":"At time t = 0, a disk of radius 1 m starts to roll without slipping on a horizontal plane with an angular acceleration of α = 2/3 rad s⁻². A small stone is stuck to the disk. At t = 0, it is at the contact point of the disk and the plane. Later, at time t = √π s, the stone detaches itself and flies off tangentially from the disk. The maximum height (in m) reached by the stone measured from the plane is ½ + {x;10}. The value of x is ______.\n[Take g = 10 m s⁻²]","n":0.52,"s":"Angle turned by t = √π: θ = ½αt² = ½(2/3)π = π/3. Angular speed ω = αt = (2/3)√π, so v_cm = ωR = (2/3)√π m/s.\nThe stone started at the bottom, so now it is at height R(1 − cosθ) = 1 − ½ = ½ m.\nIts velocity (centre velocity plus rotation) has vertical part v_y = ωR sinθ = (2/3)√π × (√3/2).\nv_y² = (4π/9)(3/4) = π/3.\nExtra height = v_y²/(2g) = π/60 = 0.0524 m.\nSo ½ + x/10 = ½ + 0.0524 and x = 0.52."},
{"y":"JEE Advanced 2022","tp":"prr","st":"Rolling bodies with forces and plates","q":"A solid sphere of mass 1 kg and radius 1 m rolls without slipping on a fixed inclined plane with an angle of inclination θ = 30° from the horizontal. Two forces of magnitude 1 N each, parallel to the incline, act on the sphere, both at distance r = 0.5 m from the center of the sphere, as shown in the figure. The acceleration of the sphere down the plane is ______ m s⁻². (Take g = 10 m s⁻².)","fig":{"w":340,"h":200,"alt":"A sphere on a 30 degree incline. A dashed diameter perpendicular to the incline shows two points at distance r from the centre. A 1 N force acts down the slope at the lower point and a 1 N force acts up the slope at the upper point.","d":[["l",30,20,30,176],["l",30,176,300,176],["l",30,20,300,176],["c",154,45,40],["l",144,63,164,28,"d"],["l",88,31,114,46,"a"],["l",220,60,194,45,"a"],["t",60,26,"1 N","s"],["t",222,70,"1 N","s"],["t",167,44,"r","s"],["t",131,62,"r","s"],["t",258,170,"θ"]]},"n":2.86,"s":"From the figure: one 1 N force acts down the slope at a point 0.5 m below the centre (height 0.5 m above the plane). The other acts up the slope at a point 0.5 m above the centre (height 1.5 m above the plane).\nTake torques about the contact point (rolling without slipping), I = (7/5)mR² = 1.4 kg m².\nTorque down the slope: mg sinθ × R + 1 × 0.5 − 1 × 1.5 = 5 + 0.5 − 1.5 = 4 N m.\nα = 4/1.4 = 20/7 rad/s², so a = αR = 20/7 ≈ 2.86 m/s²."},
{"y":"JEE Main 2021 · 20 Jul · Shift 1","tp":"prr","st":"Rolling on an incline","q":"A circular disc reaches from top to bottom of an inclined plane of length 'L'. When it slips down the plane, it takes time t₁. When it rolls down the plane, it takes time t₂. The value of t₂/t₁ is √{3;x}. The value of x will be ______.","n":2,"s":"From rest, L = ½at², so t ∝ 1/√a.\nSlipping: a₁ = g sinθ. Rolling disc: a₂ = (2/3)g sinθ.\nt₂/t₁ = √(a₁/a₂) = √(3/2).\nComparing with √(3/x): x = 2."},
{"y":"JEE Main 2021 · 20 Jul · Shift 2","tp":"prr","st":"Rolling on an incline","q":"Two bodies a ring and a solid cylinder of same material are rolling down without slipping an inclined plane. The radii of the bodies are same. The ratio of velocity of the centre of mass at the bottom of the inclined plane of the ring to that of the cylinder is {√x;2}. Then, the value of x is ______.","n":3,"s":"Energy: mgh = ½mv²(1 + k²/R²), so v = √(2gh/(1 + k²/R²)).\nRing: k²/R² = 1, so v₁ = √(gh).\nSolid cylinder: k²/R² = ½, so v₂ = √(4gh/3).\nv₁/v₂ = √(3/4) = √3/2.\nComparing with √x/2: x = 3."},
{"y":"JEE Main 2021 · 22 Jul · Shift 2","tp":"prr","st":"Rolling and its energy","q":"The centre of a wheel rolling on a plane surface moves with a speed v₀. A particle on the rim of the wheel at the same level as the centre will be moving at speed √x v₀. Then the value of x is ______.","n":2,"s":"The velocity of a rim point is v₀ (forward, from the motion of the centre) plus ωR = v₀ (tangential).\nAt the level of the centre the tangential part is vertical, so the two parts are at 90°.\nSpeed = √(v₀² + v₀²) = √2 v₀.\nSo x = 2."},
{"y":"JEE Main 2021 · 16 Mar · Shift 2","tp":"prr","st":"Rolling on an incline","q":"A solid disc of radius 'a' and mass 'm' rolls down without slipping on an inclined plane making an angle θ with the horizontal. The acceleration of the disc will be {2;b} g sinθ, where b is ______.\n(Round off to nearest integer)\n(g = acceleration due to gravity)","n":3,"s":"For a solid disc rolling without slipping: a = g sinθ/(1 + ½) = (2/3)g sinθ.\nComparing with (2/b) g sinθ gives b = 3."},
{"y":"JEE Main 2021 · 17 Mar · Shift 1","tp":"prr","st":"Rolling on an incline","q":"The following bodies,\n(1) a ring\n(2) a disc\n(3) a solid cylinder\n(4) a solid sphere\nof same mass m and radius R are allowed to roll down without slipping simultaneously from the top of the inclined plane. The body which will reach first at the bottom of the inclined plane is ______.\n[Mark the body as per their respective numbering given in the question]","n":4,"s":"Acceleration down the plane: a = g sinθ/(1 + k²/R²). The body with the smallest k²/R² has the largest a and reaches first.\nRing: 1. Disc and solid cylinder: ½. Solid sphere: 2/5.\nThe solid sphere has the smallest value, so it wins.\nAnswer: body number 4."},
{"y":"JEE Main 2020 · 4 Sep · Shift 1","tp":"pra","st":"Conservation of angular momentum","q":"A circular disc of mass M and radius R is rotating about its axis with angular speed ω₁. If another stationary disc having radius {R;2} and same mass M is dropped coaxially on to the rotating disc. Gradually both discs attain constant angular speed ω₂. The energy lost in the process is p% of the initial energy. Value of p is ______.","n":20,"s":"No external torque, so angular momentum is conserved.\nI₁ = ½MR², I₂ = ½M(R/2)² = MR²/8.\nI₁ω₁ = (I₁ + I₂)ω₂ gives ω₂ = (1/2)/(1/2 + 1/8) ω₁ = (4/5)ω₁.\nFinal KE / initial KE = (I₁ + I₂)ω₂²/(I₁ω₁²) = (5/4)(16/25) = 4/5.\nEnergy lost = 1/5 of the initial energy = 20%, so p = 20."},
{"y":"JEE Advanced 2018","tp":"prr","st":"Rolling on an incline","q":"A ring and a disc are initially at rest, side by side, at the top of an inclined plane which makes an angle 60° with the horizontal. They start to roll without slipping at the same instant of time along the shortest path. If the time difference between their reaching the ground is (2 − √3)/√10 s, then the height of the top of the inclined plane, in metres, is ______. (Take g = 10 m s⁻²)","n":0.75,"s":"Let the height be h, so the path length is L = h/sinθ.\nRing: a = ½g sinθ, so t₁ = √(2L/a) = (2/sinθ)√(h/g).\nDisc: a = (2/3)g sinθ, so t₂ = (√3/sinθ)√(h/g).\nΔt = (2 − √3)√(h/g)/sinθ = (2 − √3)(2/√3)√(h/10).\nSet equal to (2 − √3)/√10: (2/√3)√h = 1, so h = 3/4 = 0.75 m."},
{"y":"JEE Advanced 2015","tp":"prr","st":"Rolling and its energy","q":"Two identical uniform discs roll without slipping on two different surfaces AB and CD (see figure) starting at A and C with linear speeds v₁ and v₂, respectively, and always remain in contact with the surfaces. If they reach B and D with the same linear speed and v₁ = 3 m/s, then v₂ in m/s is ______. (g = 10 m/s²)","fig":{"w":340,"h":200,"alt":"Two surface profiles. Top: disc at A with speed v1 = 3 m/s on a level, then a slope dropping 30 m to level B. Bottom: disc at C with speed v2 on a level, then a slope dropping 27 m to level D.","d":[["p","M20 30 H100 L160 66 H320"],["c",45,22,8],["l",58,22,92,22,"a"],["t",96,16,"v₁ = 3 m/s","s"],["l",200,30,258,30,"d"],["l",250,30,250,66,"b"],["t",258,52,"30 m","s"],["t",8,34,"A","s"],["t",300,82,"B"],["p","M20 120 H100 L160 152 H320"],["c",45,112,8],["l",58,112,92,112,"a"],["t",96,106,"v₂","s"],["l",200,120,258,120,"d"],["l",250,120,250,152,"b"],["t",258,142,"27 m","s"],["t",8,124,"C","s"],["t",300,170,"D"]]},"n":7,"s":"A rolling disc has KE = (3/4)mv², and mechanical energy is conserved.\nDisc 1: (3/4)v₁² + g(30) = (3/4)v_f² (per unit mass).\nDisc 2: (3/4)v₂² + g(27) = (3/4)v_f².\nSo (3/4)(9) + 300 = (3/4)v₂² + 270.\n(3/4)v₂² = 36.75, so v₂² = 49 and v₂ = 7 m/s."},
{"y":"IIT-JEE 2011","tp":"prr","st":"Slipping and friction in rolling","q":"A boy is pushing a ring of mass 2 kg and radius 0.5 m with a stick as shown in the figure. The stick applies a force of 2 N on the ring and rolls it without slipping with an acceleration of 0.3 m/s². The coefficient of friction between the ground and the ring is large enough that rolling always occurs and the coefficient of friction between the stick and the ring is (P/10). The value of P is ______.","fig":{"w":300,"h":190,"alt":"A ring standing on the ground with a vertical stick touching its right side.","d":[["c",130,100,50],["l",20,150,260,150,"B"],["l",180,20,180,130],["t",180,14,"Stick","m"],["t",130,170,"Ground","m"]]},"n":4,"s":"The stick pushes the ring forward with normal force N = 2 N. It also exerts a friction force f_s along the stick (vertical). Let f be the ground friction (horizontal).\nHorizontal: N − f = ma = 2 × 0.3 = 0.6, so f = 1.4 N (backwards).\nTorque about the centre (I = mR²): (f + f_s)R acts in the rolling sense, but with the signs of the forces f gives rolling torque fR and stick friction f_s (taken in the rolling sense) gives f_sR.\n(f + f_s)R = mR²(a/R), so f + f_s = ma = 0.6.\nThus f_s = 0.6 − 1.4 = −0.8 N: the stick friction is 0.8 N and acts against the rolling torque.\nμ = f_s/N = 0.8/2 = 0.4 = P/10, so P = 4."},
{"y":"JEE Advanced 2017","tp":"prr","st":"Statements, matching and subjective","q":"Comprehension-1\nOne twirls a circular ring (of mass M and radius R) near the tip of one's finger as shown in figure 1. In the process the finger never loses contact with the inner rim of the ring. The finger traces out the surface of a cone, shown by the dotted line. The radius of the path traced out by the point where the ring and the finger is in contact is r. The finger rotates with an angular velocity ω₀. The rotating ring rolls without slipping on the outside of a smaller circle described by the point where the ring and the finger is in contact (figure 2). The coefficient of friction between the ring and the finger is μ and the acceleration due to gravity is g.\nThe minimum value of ω₀ below which the ring will drop down is","fig":{"w":340,"h":170,"alt":"Figure 2: a large circle of radius R (the ring) with a small circle of radius r, traced by the contact point, touching it from inside on the left.","d":[["c",230,80,65],["c",230,80,2,"F"],["l",230,80,295,80,"d"],["t",262,74,"R","ms"],["c",183,80,18],["l",183,80,165,80,"d"],["t",183,66,"r","ms"],["t",230,160,"Figure 2 (top view)","ms"]]},"o":["√{3g;2μ(R−r)}","√{g;μ(R−r)}","√{g;2μ(R−r)}","√{2g;μ(R−r)}"],"c":1,"s":"The centre of the ring moves in a circle of radius (R − r) with angular speed ω₀.\nThe finger must supply the centripetal force as a normal force: N = Mω₀²(R − r).\nFriction at the finger must hold up the weight: μN ≥ Mg.\nμω₀²(R − r) ≥ g, so ω₀ ≥ √{g/(μ(R − r))}.\nMinimum value: ω₀ = √(g/(μ(R−r))). Answer (b)."},
{"y":"IIT-JEE 2012","tp":"prr","st":"Statements, matching and subjective","q":"Comprehension-2\nThe general motion of a rigid body can be considered to be a combination of (i) motion of its centre of mass about an axis, and (ii) its motion about an instantaneous axis passing through the centre of mass. These axes need not be stationary. Consider, for example, a thin uniform disc welded (rigidly fixed) horizontally at its rim to a massless stick, as shown in the figure. When the disc-stick system is rotated about the origin on a horizontal frictionless plane with angular speed ω, the motion at any instant can be taken as a combination of (i) a rotation of the centre of mass of the disc about the z-axis, and (ii) a rotation of the disc through an instantaneous vertical axis passing through its centre of mass (as is seen from the changed orientation of points P and Q of the disc). Both these motions have the same angular speed ω in this case.\nNow consider two similar systems as shown in the figure: Case (a) the disc with its face vertical and parallel to x-z plane; Case (b) the disc with its face making an angle of 45° with x-y plane and its horizontal diameter parallel to x-axis. In both the cases, the disc is welded at point P, and the systems are rotated with constant angular speed ω about the z-axis.\nWhich of the following statements about the instantaneous axis (passing through the same centre of mass) is correct?","fig":{"w":340,"h":170,"alt":"Two systems, case (a) and case (b): a stick along the y-axis from the origin to point P at the rim of a disc. In case (a) the disc is vertical, with its face parallel to the x-z plane. In case (b) the disc is tilted 45 degrees. The z-axis points up and the system rotates with angular speed omega about it.","d":[["l",50,120,50,28,"a"],["t",56,34,"z"],["l",50,120,170,120,"a"],["t",166,134,"y"],["l",50,120,24,142,"a"],["t",12,150,"x"],["t",58,52,"ω"],["p","M110 120 A 8 35 0 0 1 110 50 A 8 35 0 0 1 110 120"],["t",110,42,"Q","m"],["t",110,136,"P","m"],["t",110,164,"Case (a)","ms"],["l",210,120,210,28,"a"],["t",216,34,"z"],["l",210,120,335,120,"a"],["t",330,134,"y"],["l",210,120,184,142,"a"],["t",172,150,"x"],["t",218,52,"ω"],["p","M270 120 A 8 35 45 0 1 320 70 A 8 35 45 0 1 270 120"],["t",326,66,"Q"],["t",270,136,"P","m"],["t",280,164,"Case (b)","ms"]]},"o":["It is vertical for both the cases (a) and (b).","It is vertical for case (a); and is at 45° to the x-z plane and lies in the plane of the disc for case (b).","It is horizontal for case (a); and is at 45° to the x-z plane and is normal to the plane of the disc for case (b).","It is vertical for case (a); and is at 45° to the x-z plane and is normal to the plane of the disc for case (b)."],"c":0,"s":"In both cases the whole rigid body is turned about the vertical z-axis with angular velocity ω ẑ.\nThe instantaneous rotation of the body about its own centre of mass is therefore the same rotation, about a vertical axis through the centre of mass.\nThe tilt of the disc (45° in case b) only changes the orientation of the body, not the direction of its angular velocity.\nSo the instantaneous axis through the centre of mass is vertical for both cases. Answer (a)."},
{"y":"IIT-JEE 2012","tp":"prr","st":"Statements, matching and subjective","q":"Comprehension-2\nThe general motion of a rigid body can be considered to be a combination of (i) motion of its centre of mass about an axis, and (ii) its motion about an instantaneous axis passing through the centre of mass. These axes need not be stationary. Consider, for example, a thin uniform disc welded (rigidly fixed) horizontally at its rim to a massless stick, as shown in the figure. When the disc-stick system is rotated about the origin on a horizontal frictionless plane with angular speed ω, the motion at any instant can be taken as a combination of (i) a rotation of the centre of mass of the disc about the z-axis, and (ii) a rotation of the disc through an instantaneous vertical axis passing through its centre of mass (as is seen from the changed orientation of points P and Q of the disc). Both these motions have the same angular speed ω in this case.\nNow consider two similar systems as shown in the figure: Case (a) the disc with its face vertical and parallel to x-z plane; Case (b) the disc with its face making an angle of 45° with x-y plane and its horizontal diameter parallel to x-axis. In both the cases, the disc is welded at point P, and the systems are rotated with constant angular speed ω about the z-axis.\nWhich of the following statements regarding the angular speed about the instantaneous axis (passing through the centre of mass) is correct?","fig":{"w":340,"h":170,"alt":"Two systems, case (a) and case (b): a stick along the y-axis from the origin to point P at the rim of a disc. In case (a) the disc is vertical, with its face parallel to the x-z plane. In case (b) the disc is tilted 45 degrees. The z-axis points up and the system rotates with angular speed omega about it.","d":[["l",50,120,50,28,"a"],["t",56,34,"z"],["l",50,120,170,120,"a"],["t",166,134,"y"],["l",50,120,24,142,"a"],["t",12,150,"x"],["t",58,52,"ω"],["p","M110 120 A 8 35 0 0 1 110 50 A 8 35 0 0 1 110 120"],["t",110,42,"Q","m"],["t",110,136,"P","m"],["t",110,164,"Case (a)","ms"],["l",210,120,210,28,"a"],["t",216,34,"z"],["l",210,120,335,120,"a"],["t",330,134,"y"],["l",210,120,184,142,"a"],["t",172,150,"x"],["t",218,52,"ω"],["p","M270 120 A 8 35 45 0 1 320 70 A 8 35 45 0 1 270 120"],["t",326,66,"Q"],["t",270,136,"P","m"],["t",280,164,"Case (b)","ms"]]},"o":["It is √2 ω for both the cases.","It is ω for case (a); and ω/√2 for case (b).","It is ω for case (a); and √2 ω for case (b).","It is ω for both the cases."],"c":3,"s":"A rigid body has a single angular velocity vector at any instant, the same for every reference point.\nHere the body is rotated about the z-axis with angular speed ω, so its angular velocity is ω ẑ in both cases.\nThe angular speed about the instantaneous axis through the centre of mass is therefore ω for both cases. Answer (d)."},
{"y":"IIT-JEE 2008","tp":"prd","st":"Statements, matching and subjective","q":"Comprehension-3\nA uniform thin cylindrical disk of mass M and radius R is attached to two identical massless springs of spring constant k which are fixed to the wall as shown in the figure. The springs are attached to the axle of the disk symmetrically on either side at a distance d from its centre. The axle is massless and both the springs and the axle are in a horizontal plane. The unstretched length of each spring is L. The disk is initially at its equilibrium position with its centre of mass (CM) at a distance L from the wall. The disk rolls without slipping with velocity V⃗₀ = V₀ î. The coefficient of friction is μ.\nThe net external force acting on the disk when its centre of mass is at displacement x with respect to its equilibrium position is","fig":{"w":340,"h":170,"alt":"Top view: a wall on the left, two springs of constant k attached to the two ends of the axle of a disc that rolls to the right with velocity V0. The axle ends are 2d apart.","d":[["r",20,20,8,130,"f"],["p","M28 55 H40 L46 45 L58 65 L70 45 L82 65 L94 45 L106 65 L112 55 H190"],["p","M28 115 H40 L46 105 L58 125 L70 105 L82 125 L94 105 L106 125 L112 115 H190"],["l",190,50,190,120],["r",160,81,60,8,"F"],["t",90,40,"k","ms"],["t",90,102,"k","ms"],["l",205,55,205,115,"b"],["t",212,89,"2d","s"],["l",250,85,310,85,"a"],["t",250,75,"V₀"],["t",30,12,"wall","s"]]},"o":["−kx","−2kx","−{2kx;3}","−{4kx;3}"],"c":3,"s":"Let the centre be displaced by x with acceleration a. Spring force on the disk = −2kx. Let f be the friction at the ground.\nTranslation: Ma = −2kx + f.\nRolling without slipping: the torque of friction gives Iα = ½MR²(a/R) with the opposite sign, so f = −Ma/2.\nThen Ma = −2kx − Ma/2, so (3/2)Ma = −2kx and Ma = −4kx/3.\nThe net external force on the disk is −4kx/3. Answer (d)."},
{"y":"IIT-JEE 2008","tp":"prd","st":"Statements, matching and subjective","q":"Comprehension-3\nA uniform thin cylindrical disk of mass M and radius R is attached to two identical massless springs of spring constant k which are fixed to the wall as shown in the figure. The springs are attached to the axle of the disk symmetrically on either side at a distance d from its centre. The axle is massless and both the springs and the axle are in a horizontal plane. The unstretched length of each spring is L. The disk is initially at its equilibrium position with its centre of mass (CM) at a distance L from the wall. The disk rolls without slipping with velocity V⃗₀ = V₀ î. The coefficient of friction is μ.\nThe centre of mass of the disk undergoes simple harmonic motion with angular frequency ω equal to","fig":{"w":340,"h":170,"alt":"Top view: a wall on the left, two springs of constant k attached to the two ends of the axle of a disc that rolls to the right with velocity V0. The axle ends are 2d apart.","d":[["r",20,20,8,130,"f"],["p","M28 55 H40 L46 45 L58 65 L70 45 L82 65 L94 45 L106 65 L112 55 H190"],["p","M28 115 H40 L46 105 L58 125 L70 105 L82 125 L94 105 L106 125 L112 115 H190"],["l",190,50,190,120],["r",160,81,60,8,"F"],["t",90,40,"k","ms"],["t",90,102,"k","ms"],["l",205,55,205,115,"b"],["t",212,89,"2d","s"],["l",250,85,310,85,"a"],["t",250,75,"V₀"],["t",30,12,"wall","s"]]},"o":["√{k;M}","√{2k;M}","√{2k;3M}","√{4k;3M}"],"c":3,"s":"From the previous question, Ma = −(4k/3)x.\nSo a = −(4k/(3M))x, which is SHM with ω² = 4k/(3M).\nω = √(4k/3M). Answer (d)."},
{"y":"IIT-JEE 2008","tp":"prd","st":"Statements, matching and subjective","q":"Comprehension-3\nA uniform thin cylindrical disk of mass M and radius R is attached to two identical massless springs of spring constant k which are fixed to the wall as shown in the figure. The springs are attached to the axle of the disk symmetrically on either side at a distance d from its centre. The axle is massless and both the springs and the axle are in a horizontal plane. The unstretched length of each spring is L. The disk is initially at its equilibrium position with its centre of mass (CM) at a distance L from the wall. The disk rolls without slipping with velocity V⃗₀ = V₀ î. The coefficient of friction is μ.\nThe maximum value of V₀ for which the disk will roll without slipping is","fig":{"w":340,"h":170,"alt":"Top view: a wall on the left, two springs of constant k attached to the two ends of the axle of a disc that rolls to the right with velocity V0. The axle ends are 2d apart.","d":[["r",20,20,8,130,"f"],["p","M28 55 H40 L46 45 L58 65 L70 45 L82 65 L94 45 L106 65 L112 55 H190"],["p","M28 115 H40 L46 105 L58 125 L70 105 L82 125 L94 105 L106 125 L112 115 H190"],["l",190,50,190,120],["r",160,81,60,8,"F"],["t",90,40,"k","ms"],["t",90,102,"k","ms"],["l",205,55,205,115,"b"],["t",212,89,"2d","s"],["l",250,85,310,85,"a"],["t",250,75,"V₀"],["t",30,12,"wall","s"]]},"o":["μg√{M;k}","μg√{M;2k}","μg√{3M;k}","μg√{5M;2k}"],"c":2,"s":"The disk starts at the equilibrium position with speed V₀, so the amplitude is A = V₀/ω with ω = √(4k/3M).\nFriction needed: |f| = Ma/2 = (2k/3)|x|, largest at x = A, where it is (2k/3)A.\nNo slipping needs (2k/3)A ≤ μMg, so A ≤ 3μMg/(2k).\nV₀ = ωA ≤ √(4k/3M) × 3μMg/(2k) = μg√(3M/k).\nAnswer (c)."},
{"y":"IIT-JEE 2008","tp":"prr","st":"Statements, matching and subjective","q":"Statement-1 : Two cylinders, one hollow (metal) and the other solid (wood) with the same mass and identical dimensions are simultaneously allowed to roll without slipping down an inclined plane from the same height. The hollow cylinder will reach the bottom of the inclined plane first.\nStatement-2 : By the principle of conservation of energy, the total kinetic energies of both the cylinders are identical when they reach the bottom of the incline.","o":["Statements-1 and 2 are true and statement-2 is a correct explanation for statement-1","Statements-1 and 2 are true and statement-2 is not a correct explanation for statement-1","Statement-1 is true, statement-2 is false","Statement-1 is false, statement-2 is true."],"c":3,"s":"Acceleration down the plane: a = g sinθ/(1 + k²/R²). The solid cylinder has the smaller k²/R² (½ against 1), so it has the larger a and reaches the bottom first. Statement-1 is false.\nBoth start from the same height with the same mass, and no energy is lost in rolling without slipping, so both have KE = mgh at the bottom. Statement-2 is true.\nAnswer (d)."},
{"y":"IIT-JEE 2005","tp":"prr","st":"Statements, matching and subjective","q":"A cylinder of mass m and radius R rolls down an inclined plane of inclination θ. Calculate the linear acceleration of the axis of cylinder.","a":"a = (2/3) g sinθ","s":"Take the cylinder as solid, I = ½mR². Down the slope: mg sinθ − f = ma.\nTorque about the axis: fR = Iα = ½mR²(a/R), so f = ½ma.\nThen mg sinθ = ma + ½ma = (3/2)ma.\na = (2/3)g sinθ."},
{"y":"IIT-JEE 1999","tp":"prr","st":"Statements, matching and subjective","q":"A man pushes a cylinder of mass m₁ with the help of a plank of mass m₂ as shown in figure. There is no slipping at any contact. The horizontal component of the force applied by the man is F. Find\n(a) the acceleration of the plank and the centre of mass of cylinder, and\n(b) the magnitudes and directions of frictional forces at contact points.","fig":{"w":340,"h":170,"alt":"A force F pushes a plank of mass m2 to the right. The plank rests on top of a cylinder of mass m1, which stands on the ground.","d":[["r",110,43,150,12,"f"],["l",40,49,108,49,"a"],["t",36,42,"F","e"],["t",266,52,"m₂"],["c",185,95,40],["c",185,95,2,"F"],["t",185,100,"m₁","m"],["l",60,135,300,135,"B"]]},"a":"(a) Acceleration of the plank = 8F/(3m₁ + 8m₂); acceleration of the centre of the cylinder = 4F/(3m₁ + 8m₂).\n(b) Friction between cylinder and plank = 3m₁F/(3m₁ + 8m₂), to the right on the top of the cylinder and to the left on the plank. Friction between cylinder and ground = m₁F/(3m₁ + 8m₂), to the right at the bottom of the cylinder.","s":"Take a solid cylinder. No slipping at the plank means the top point of the cylinder moves with the plank. Since the bottom point is at rest, the plank acceleration is twice the centre acceleration: a₂ = 2a₁.\nLet f₁ be the friction between plank and cylinder (to the right on the cylinder top) and f₂ the ground friction at the bottom.\nPlank: F − f₁ = m₂a₂. Cylinder translation: f₁ + f₂ = m₁a₁. Torque: (f₁ − f₂)R = ½m₁R²(a₁/R), so f₁ − f₂ = ½m₁a₁.\nSo f₁ = ¾m₁a₁ and f₂ = ¼m₁a₁. With a₁ = a₂/2: F = m₂a₂ + (3/8)m₁a₂, so a₂ = 8F/(3m₁ + 8m₂), a₁ = 4F/(3m₁ + 8m₂).\nf₁ = 3m₁F/(3m₁ + 8m₂) and f₂ = m₁F/(3m₁ + 8m₂)."},
{"y":"IIT-JEE 1997","tp":"prr","st":"Statements, matching and subjective","q":"A uniform disc of mass m and radius R is projected horizontally with velocity v₀ on a rough horizontal floor so that it starts off with a purely sliding motion at t = 0. After t₀ seconds, it acquires a purely rolling motion as shown in figure.\n(i) Calculate the velocity of the centre of mass of the disc at t₀.\n(ii) Assuming the coefficient of friction to be μ, calculate t₀. Also calculate the work done by the frictional force as a function of time and the total work done by it over a time t much longer than t₀.","fig":{"w":340,"h":150,"alt":"A disc projected with velocity v0 sliding on a rough floor at t = 0, and the same disc rolling at t = t0.","d":[["l",20,95,320,95,"B"],["c",70,70,25],["c",70,70,2,"F"],["l",100,62,140,62,"a"],["t",118,56,"v₀","m"],["t",70,118,"t = 0","ms"],["c",230,70,25],["c",230,70,2,"F"],["p","M212 40 A 25 25 0 0 1 248 40","a"],["l",260,70,300,70,"a"],["t",230,118,"t = t₀","ms"]]},"a":"(i) 2v₀/3\n(ii) t₀ = v₀/(3μg); W = (μmgt/2)(3μgt − 2v₀) for t < t₀; total work W = −mv₀²/6","s":"(i) Take angular momentum about a point on the floor: friction passes through it, so L is conserved.\nInitially L = mv₀R. Finally (rolling) L = mvR + ½mR²(v/R) = (3/2)mvR. So v = 2v₀/3.\n(ii) Friction f = μmg: v = v₀ − μgt and α = 2μg/R, so ωR = 2μgt. Rolling starts when v = ωR: v₀ − μgt₀ = 2μgt₀, so t₀ = v₀/(3μg).\nFor t < t₀ the work of friction equals the change of KE: W = ½m[(v₀ − μgt)² − v₀²] + ½(½mR²)(2μgt/R)² = (μmgt/2)(3μgt − 2v₀).\nFor t ≫ t₀ the disc rolls with v = 2v₀/3, so W = ¾m(2v₀/3)² − ½mv₀² = −mv₀²/6."},
{"y":"IIT-JEE 1997","tp":"prr","st":"Statements, matching and subjective","q":"Two thin circular discs of mass 2 kg and radius 10 cm each are joined by a rigid massless rod of length 20 cm. The axis of the rod is along the perpendicular to the planes of the two discs through their centres. This object is kept on a truck in such a way that the axis of the object is horizontal and perpendicular to the direction of the motion of the truck. Its friction with the floor of the truck is large enough so that the object can roll on the truck without slipping. Take x-axis as the direction of motion of the truck and z-axis as the vertically upward direction. If the truck has an acceleration of 9 m/s², calculate:\n(i) the force of friction on each disc.\n(ii) the magnitude and the direction of the frictional torques acting on each disc about the centre of mass O of the object. Express the torque in the vector form in terms of unit vectors î, ĵ and k̂ in the x, y and z directions.","fig":{"w":340,"h":170,"alt":"Two thin discs seen edge-on from the side as tall ellipses, joined by a horizontal rod through their centres with the midpoint O. The discs are 20 cm apart and stand on the truck floor.","d":[["p","M90 25 A 18 45 0 0 1 90 115 A 18 45 0 0 1 90 25"],["p","M250 25 A 18 45 0 0 1 250 115 A 18 45 0 0 1 250 25"],["l",90,70,250,70],["c",170,70,3,"F"],["t",170,62,"O","ms"],["l",50,115,290,115,"B"],["l",90,138,250,138,"b"],["t",170,154,"20 cm","ms"],["t",300,112,"floor","s"]]},"a":"(i) 6 N on each disc (forward, along x; total 12 N)\n(ii) 0.6(k̂ − ĵ) N m on one disc (at y = −0.1 m) and 0.6(−ĵ − k̂) N m on the other (at y = +0.1 m)","s":"Work in the truck frame. Mass M = 4 kg, and the moment of inertia about the axis is I = 2 × ½(2)(0.1)² = 0.02 kg m², so I/R² = 2 kg.\nLet the object's acceleration relative to the truck be a′ (backwards, negative x). The pseudo force is −Ma. Total friction f (along +x).\nM a′ = f − Ma, and rolling gives f R = −I a′/R, so f = −2a′.\n4a′ = −2a′ − 36 gives a′ = −6 m/s². So f = 12 N in total, 6 N on each disc, along +x (the direction of the truck's acceleration), acting at the bottom contact.\n(Ground-frame check: the object's acceleration is 9 − 6 = 3 m/s², and 4 × 3 = 12 N.)\n(ii) For each disc, the friction point is r = (0, ±0.1, −0.1) m from O, F = 6 î N. τ = r × F = (0, −0.6, ∓0.6) N m.\nSo the disc at y = +0.1 m has τ = 0.6(−ĵ − k̂) N m and the disc at y = −0.1 m has τ = 0.6(k̂ − ĵ) N m. Each has magnitude 0.6√2 ≈ 0.85 N m."},
{"y":"IIT-JEE 1995","tp":"prr","st":"Statements, matching and subjective","q":"A rectangular rigid fixed block has a long horizontal edge. A solid homogeneous cylinder of radius R is placed horizontally at rest, with its length parallel to the edge such that the axis of the cylinder and the edge of the block are in the same vertical plane as shown in the figure below. There is sufficient friction present at the edge so that a very small displacement causes the cylinder to roll off the edge without slipping. Determine\n(a) the angle θc through which the cylinder rotates before it leaves contact with the edge,\n(b) the speed of the centre of the cylinder before leaving contact with the edge, and\n(c) the ratio of the translational to rotational kinetic energies of the cylinder when its centre of mass is in horizontal line with the edge.","fig":{"w":340,"h":170,"alt":"A fixed rectangular block with a horizontal edge on the right. A cylinder of radius R rests on the edge with its axis directly above the edge.","d":[["r",20,100,180,60,"f"],["c",200,70,30],["c",200,70,2,"F"],["l",200,70,225,83,"d"],["t",216,70,"R","s"]]},"a":"(a) θc = cos⁻¹(4/7)\n(b) v = √(4gR/7)\n(c) 6","s":"The cylinder rolls about the edge, so its centre moves on a circle of radius R about the edge, and ω = v/R.\n(a) At angle θ the centre has fallen R(1 − cosθ). Energy: mgR(1 − cosθ) = ½mv² + ½(½mR²)(v/R)² = (3/4)mv², so v² = (4/3)gR(1 − cosθ).\nIt leaves contact when N = 0: mg cosθ = mv²/R, so v² = gR cosθ.\nEquating: cosθ = (4/3)(1 − cosθ), so cosθ_c = 4/7 and θ_c = cos⁻¹(4/7).\n(b) v² = gR cosθ_c = 4gR/7, so v = √(4gR/7).\n(c) After leaving, the spin stays ω = v/R, so rotational KE stays ½(½mR²)ω² = ¼mv² = mgR/7.\nThe centre falls a further R cosθ_c = 4R/7 before it is level with the edge. Translational KE = ½m(4gR/7) + mg(4R/7) = 6mgR/7.\nRatio = (6mgR/7)/(mgR/7) = 6."},
{"y":"IIT-JEE 1990","tp":"prr","st":"Statements, matching and subjective","q":"A carpet of mass M, made of inextensible material is rolled along its length in the form of a cylinder of radius R and is kept on a rough floor. The carpet starts unrolling without sliding on the floor when a negligibly small push is given to it. Calculate the horizontal velocity of the axis of the cylindrical part of the carpet when its radius reduces to R/2.","a":"v = √(14Rg/3)","s":"The unrolled part lies at rest on the floor. The rolled part is a cylinder that rolls without slipping, so its KE = (3/4)m′v² (m′ is its mass).\nThe carpet is uniform, so the mass is proportional to the area: when the radius is R/2 the rolled mass is M/4.\nPE released: initially the centre of mass of the cylinder is at height R, so PE = MgR. At the end, the rolled part (M/4) has its centre at R/2, so PE = (M/4)g(R/2) = MgR/8, and the flat part has none.\nLoss of PE = MgR − MgR/8 = 7MgR/8.\n7MgR/8 = (3/4)(M/4)v² = (3/16)Mv², so v² = 14gR/3."},
{"y":"IIT-JEE 1990","tp":"prc","st":"Motion of the centre of mass and collisions","q":"An object of mass 5 kg is projected with a velocity of 20 m/s at an angle of 60° to the horizontal. At the highest point of its path, the projectile explodes and breaks up into two fragments of masses 1 kg and 4 kg. The fragments separate horizontally after the explosion. The explosion releases internal energy such that the kinetic energy of the system at the highest point is doubled. Calculate the separation between the two fragments when they reach the ground.","a":"≈ 44.25 m (about 44 m)","s":"At the top the speed is 20 cos60° = 10 m/s (horizontal). Initial KE = ½(5)(10²) = 250 J, so after the explosion KE = 500 J.\nMomentum along x: 1·v₁ + 4·v₂ = 5 × 10 = 50.\nEnergy: ½(1)v₁² + ½(4)v₂² = 500, so v₁² + 4v₂² = 1000.\nPut v₁ = 50 − 4v₂: 20v₂² − 400v₂ + 1500 = 0, so v₂ = 15 or 5 m/s, giving v₁ = −10 or 30 m/s. Either way the relative speed is 25 m/s.\nTime to fall from the top = time to rise = 20 sin60°/g = 17.32/9.8 = 1.77 s (g = 9.8 m/s²).\nSeparation = 25 × 1.77 ≈ 44 m (book value 44.25 m; with g = 10 it is 25√3 = 43.3 m)."},
{"y":"IIT-JEE 1987","tp":"prr","st":"Statements, matching and subjective","q":"A small sphere rolls down without slipping from the top of a track in a vertical plane. The track has an elevated section and a horizontal part. The horizontal part is 1.0 metre above the ground level and the top of the track is 2.4 metre above the ground. Find the distance on the ground with respect to the point B (which is vertically below the end of the track as shown in fig.) where the sphere lands. During its flight as a projectile, does the sphere continue to rotate about its centre of mass? Explain.","fig":{"w":340,"h":215,"alt":"A track in a vertical plane. A sphere sits at the top, 2.4 m above the ground. The track curves down to a horizontal part 1.0 m above the ground, ending above point B. A dashed path shows the projectile motion to the ground.","d":[["l",20,190,335,190,"B"],["c",40,62,8],["p","M40 70 C 60 125, 100 140, 150 140 H 230","B"],["l",230,140,230,190,"d"],["t",230,206,"B","ms"],["l",14,70,14,190,"b"],["t",20,134,"2.4 m","s"],["l",252,140,252,190,"b"],["t",258,168,"1.0 m","s"],["p","M230 140 Q 280 140 330 190","d"]]},"a":"Lands 2.0 m from B. Yes, the sphere keeps rotating about its centre of mass at constant angular speed, because gravity gives no torque about the centre of mass.","s":"The sphere drops 2.4 − 1.0 = 1.4 m while rolling, so mg(1.4) = ½mv² + ½(2/5)mR²(v/R)² = (7/10)mv².\nv² = (10/7)g(1.4) = 2g, so v = √(2g).\nThen it falls 1.0 m as a projectile: t = √(2 × 1/g).\nHorizontal distance = vt = √(2g) × √(2/g) = 2 m.\nIn flight the only force is gravity, which acts at the centre of mass and gives no torque about it. So the angular momentum is constant and the sphere keeps rotating about its centre at the same angular speed."},
{"y":"IIT-JEE 1989","tp":"prr","st":"Statements, matching and subjective","q":"A ring of mass 0.3 kg and radius 0.1 m and a solid cylinder of mass 0.4 kg and of the same radius are given the same kinetic energy and released simultaneously on a flat horizontal surface such that they begin to roll as soon as released towards a wall which is at the same distance from the ring and the cylinder. The rolling friction in both cases is negligible. The cylinder will reach the wall first.","o":["True","False"],"c":1,"s":"Both bodies roll at constant speed (no rolling friction), so the one with the larger speed arrives first.\nRing: KE = mv² gives v = √(KE/m) = √(KE/0.3).\nSolid cylinder: KE = (3/4)mv² gives v = √(4KE/(3m)) = √(4KE/1.2) = √(KE/0.3).\nThe speeds are equal, so both reach the wall at the same time. The statement is false."}
];
